-- Private Supabase schema for the Commerce integration.
-- Browsers never access these objects directly. The cms-commerce Edge Function
-- is the authorization boundary and critical writes use the RPCs below.

begin;

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

create schema if not exists commerce;

revoke all on schema commerce from public;
revoke all on schema commerce from anon;
revoke all on schema commerce from authenticated;

create table if not exists commerce.fee_policies (
    id bigint generated by default as identity primary key,
    policy_key text not null,
    version integer not null,
    name text not null,
    status text not null default 'draft',
    currency text not null default 'eur',
    shipping_beneficiary text not null default 'platform',
    estimated_stripe_cost_amount bigint not null default 0,
    estimated_carrier_cost_amount bigint not null default 0,
    platform_risk_reserve_contribution_amount bigint not null default 0,
    configured_minimum_margin_amount bigint not null default 0,
    cost_estimates_configured boolean not null default false,
    subsidy_override boolean not null default false,
    subsidy_reason text,
    published_at timestamptz,
    created_by text not null,
    created_at timestamptz not null default now(),
    constraint fee_policies_key_format check (policy_key ~ '^[a-z][a-z0-9_-]{0,63}$'),
    constraint fee_policies_version_positive check (version > 0),
    constraint fee_policies_name_not_blank check (length(btrim(name)) > 0),
    constraint fee_policies_status check (status in ('draft', 'published', 'retired')),
    constraint fee_policies_currency check (currency = 'eur'),
    constraint fee_policies_shipping_beneficiary check (shipping_beneficiary in ('platform', 'seller')),
    constraint fee_policies_amounts check (
        estimated_stripe_cost_amount between 0 and 9007199254740991
        and estimated_carrier_cost_amount between 0 and 9007199254740991
        and platform_risk_reserve_contribution_amount between 0 and 9007199254740991
        and configured_minimum_margin_amount between 0 and 9007199254740991
    ),
    constraint fee_policies_subsidy_reason check (not subsidy_override or length(btrim(subsidy_reason)) > 0),
    constraint fee_policies_publication check (
        (status = 'draft' and published_at is null) or (status <> 'draft' and published_at is not null)
    ),
    constraint fee_policies_key_version_unique unique (policy_key, version)
);

create table if not exists commerce.fee_policy_components (
    id bigint generated by default as identity primary key,
    fee_policy_id bigint not null references commerce.fee_policies(id) on delete restrict,
    component_key text not null,
    payer text not null,
    basis text not null,
    rate_bps integer not null default 0,
    fixed_amount bigint not null default 0,
    minimum_amount bigint,
    maximum_amount bigint,
    rounding_mode text not null default 'round_half_up',
    refund_policy text not null default 'proportional',
    position integer not null default 0,
    created_at timestamptz not null default now(),
    constraint fee_policy_components_key check (component_key in ('buyer_protection', 'seller_commission')),
    constraint fee_policy_components_payer check (payer in ('buyer', 'seller')),
    constraint fee_policy_components_key_payer check (
        (component_key = 'buyer_protection' and payer = 'buyer')
        or (component_key = 'seller_commission' and payer = 'seller')
    ),
    constraint fee_policy_components_basis check (basis in ('merchandise', 'merchandise_and_shipping')),
    constraint fee_policy_components_rate check (rate_bps between 0 and 10000),
    constraint fee_policy_components_amounts check (
        fixed_amount between 0 and 9007199254740991
        and (minimum_amount is null or minimum_amount between 0 and 9007199254740991)
        and (maximum_amount is null or maximum_amount between 0 and 9007199254740991)
        and (minimum_amount is null or maximum_amount is null or minimum_amount <= maximum_amount)
        and (maximum_amount is null or fixed_amount <= maximum_amount)
    ),
    constraint fee_policy_components_rounding check (rounding_mode = 'round_half_up'),
    constraint fee_policy_components_refund check (refund_policy in ('always', 'never', 'proportional', 'resolution_defined')),
    constraint fee_policy_components_policy_key_unique unique (fee_policy_id, component_key)
);

alter table commerce.fee_policy_components
    drop constraint if exists fee_policy_components_amounts;
alter table commerce.fee_policy_components
    add constraint fee_policy_components_amounts check (
        fixed_amount between 0 and 9007199254740991
        and (minimum_amount is null or minimum_amount between 0 and 9007199254740991)
        and (maximum_amount is null or maximum_amount between 0 and 9007199254740991)
        and (minimum_amount is null or maximum_amount is null or minimum_amount <= maximum_amount)
        and (maximum_amount is null or fixed_amount <= maximum_amount)
    );

create index if not exists fee_policy_components_policy_idx
    on commerce.fee_policy_components(fee_policy_id);

create table if not exists commerce.protection_policies (
    id bigint generated by default as identity primary key,
    policy_key text not null,
    version integer not null,
    name text not null,
    status text not null default 'draft',
    currency text not null default 'eur',
    payment_window_minutes integer not null default 30,
    seller_handoff_hours integer not null default 72,
    scan_grace_hours integer not null default 48,
    claim_window_hours integer not null default 48,
    seller_response_hours integer not null default 72,
    return_ship_hours integer not null default 168,
    finance_review_threshold_amount bigint not null default 50000,
    dual_approval_threshold_amount bigint not null default 100000,
    published_at timestamptz,
    created_by text not null,
    created_at timestamptz not null default now(),
    constraint protection_policies_key_format check (policy_key ~ '^[a-z][a-z0-9_-]{0,63}$'),
    constraint protection_policies_version_positive check (version > 0),
    constraint protection_policies_name_not_blank check (length(btrim(name)) > 0),
    constraint protection_policies_status check (status in ('draft', 'published', 'retired')),
    constraint protection_policies_currency check (currency = 'eur'),
    constraint protection_policies_durations check (
        payment_window_minutes between 1 and 1440
        and seller_handoff_hours between 1 and 720
        and scan_grace_hours between 1 and 720
        and claim_window_hours between 1 and 720
        and seller_response_hours between 1 and 720
        and return_ship_hours between 1 and 2160
    ),
    constraint protection_policies_thresholds check (
        finance_review_threshold_amount between 0 and 9007199254740991
        and dual_approval_threshold_amount between finance_review_threshold_amount and 9007199254740991
    ),
    constraint protection_policies_publication check (
        (status = 'draft' and published_at is null) or (status <> 'draft' and published_at is not null)
    ),
    constraint protection_policies_key_version_unique unique (policy_key, version)
);

create table if not exists commerce.seller_risk_policies (
    id bigint generated by default as identity primary key,
    policy_key text not null,
    version integer not null,
    name text not null,
    status text not null default 'draft',
    currency text not null default 'eur',
    reserve_rate_bps integer not null default 0,
    payout_delay_days integer not null default 7,
    reserve_liability_days integer not null default 120,
    order_transfer_limit_amount bigint not null default 500000,
    velocity_limit_amount bigint not null default 1000000,
    high_value_review_amount bigint not null default 50000,
    claim_ratio_review_bps integer not null default 1000,
    chargeback_ratio_review_bps integer not null default 200,
    published_at timestamptz,
    created_by text not null,
    created_at timestamptz not null default now(),
    constraint seller_risk_policies_key_format check (policy_key ~ '^[a-z][a-z0-9_-]{0,63}$'),
    constraint seller_risk_policies_version_positive check (version > 0),
    constraint seller_risk_policies_name_not_blank check (length(btrim(name)) > 0),
    constraint seller_risk_policies_status check (status in ('draft', 'published', 'retired')),
    constraint seller_risk_policies_currency check (currency = 'eur'),
    constraint seller_risk_policies_rates check (
        reserve_rate_bps between 0 and 9999
        and claim_ratio_review_bps between 0 and 10000
        and chargeback_ratio_review_bps between 0 and 10000
    ),
    constraint seller_risk_policies_delay check (
        payout_delay_days between 0 and 31 and reserve_liability_days between 1 and 180
    ),
    constraint seller_risk_policies_amounts check (
        order_transfer_limit_amount between 1 and 9007199254740991
        and velocity_limit_amount between order_transfer_limit_amount and 9007199254740991
        and high_value_review_amount between 0 and 9007199254740991
    ),
    constraint seller_risk_policies_publication check (
        (status = 'draft' and published_at is null) or (status <> 'draft' and published_at is not null)
    ),
    constraint seller_risk_policies_key_version_unique unique (policy_key, version)
);

insert into commerce.fee_policies (
    policy_key, version, name, status, currency, shipping_beneficiary,
    cost_estimates_configured, subsidy_override, subsidy_reason, published_at, created_by
) values (
    'c2c-default', 1, 'Protected C2C configuration required', 'draft', 'eur', 'platform',
    false, false, null, null, 'system'
) on conflict (policy_key, version) do nothing;

insert into commerce.fee_policy_components (
    fee_policy_id, component_key, payer, basis, rate_bps, fixed_amount, refund_policy, position
)
select id, 'buyer_protection', 'buyer', 'merchandise', 0, 0, 'resolution_defined', 10
from commerce.fee_policies where policy_key = 'c2c-default' and version = 1
on conflict (fee_policy_id, component_key) do nothing;

insert into commerce.fee_policies (
    policy_key, version, name, status, currency, shipping_beneficiary,
    cost_estimates_configured, subsidy_override, subsidy_reason, published_at, created_by
) values (
    'c2c-default', 2, 'Protected C2C configuration required', 'draft', 'eur', 'platform',
    false, false, null, null, 'system'
) on conflict (policy_key, version) do nothing;

insert into commerce.fee_policy_components (
    fee_policy_id, component_key, payer, basis, rate_bps, fixed_amount, refund_policy, position
)
select id, 'buyer_protection', 'buyer', 'merchandise', 0, 0, 'resolution_defined', 10
from commerce.fee_policies where policy_key = 'c2c-default' and version = 2
on conflict (fee_policy_id, component_key) do nothing;

insert into commerce.fee_policy_components (
    fee_policy_id, component_key, payer, basis, rate_bps, fixed_amount, refund_policy, position
)
select id, 'seller_commission', 'seller', 'merchandise', 0, 0, 'never', 20
from commerce.fee_policies where policy_key = 'c2c-default' and version = 2
on conflict (fee_policy_id, component_key) do nothing;

insert into commerce.fee_policy_components (
    fee_policy_id, component_key, payer, basis, rate_bps, fixed_amount, refund_policy, position
)
select id, 'seller_commission', 'seller', 'merchandise', 0, 0, 'never', 20
from commerce.fee_policies where policy_key = 'c2c-default' and version = 1
on conflict (fee_policy_id, component_key) do nothing;

insert into commerce.protection_policies (
    policy_key, version, name, status, currency, published_at, created_by
) values (
    'c2c-default', 1, 'Protected C2C default', 'published', 'eur', now(), 'system'
) on conflict (policy_key, version) do nothing;

insert into commerce.seller_risk_policies (
    policy_key, version, name, status, currency, reserve_rate_bps,
    payout_delay_days, reserve_liability_days, published_at, created_by
) values (
    'c2c-default', 1, 'Protected C2C default', 'published', 'eur', 1000,
    14, 120, now(), 'system'
) on conflict (policy_key, version) do nothing;

alter table commerce.seller_risk_policies
    add column if not exists reserve_liability_days integer not null default 120;
alter table commerce.seller_risk_policies
    drop constraint if exists seller_risk_policies_delay;
alter table commerce.seller_risk_policies
    add constraint seller_risk_policies_delay check (
        payout_delay_days between 0 and 31 and reserve_liability_days between 1 and 180
    );

insert into commerce.seller_risk_policies (
    policy_key, version, name, status, currency, reserve_rate_bps,
    payout_delay_days, reserve_liability_days, published_at, created_by
) values (
    'c2c-default', 2, 'Protected C2C prudent default', 'published', 'eur', 1000,
    14, 120, now(), 'system'
) on conflict (policy_key, version) do nothing;

create table if not exists commerce.settings (
    id text primary key default 'default',
    mode text not null default 'marketplace',
    default_currency text not null default 'eur',
    require_verified_seller boolean not null default true,
    offer_moderation text not null default 'always',
    price_policy text not null default 'admin_range',
    auto_approve_price_in_range boolean not null default false,
    require_final_price_approval boolean not null default true,
    seller_can_publish boolean not null default false,
    active_c2c_fee_policy_id bigint not null references commerce.fee_policies(id) on delete restrict,
    active_c2c_protection_policy_id bigint not null references commerce.protection_policies(id) on delete restrict,
    active_c2c_seller_risk_policy_id bigint not null references commerce.seller_risk_policies(id) on delete restrict,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint settings_singleton check (id = 'default'),
    constraint settings_mode check (mode in ('ecommerce', 'marketplace', 'hybrid')),
    constraint settings_currency check (default_currency ~ '^[a-z]{3}$'),
    constraint settings_offer_moderation check (offer_moderation in ('none', 'always')),
    constraint settings_price_policy check (price_policy in ('free', 'admin_range')),
    constraint settings_version_positive check (version > 0)
);

alter table commerce.settings
    add column if not exists active_c2c_fee_policy_id bigint references commerce.fee_policies(id) on delete restrict;
alter table commerce.settings
    add column if not exists active_c2c_protection_policy_id bigint references commerce.protection_policies(id) on delete restrict;
alter table commerce.settings
    add column if not exists active_c2c_seller_risk_policy_id bigint references commerce.seller_risk_policies(id) on delete restrict;

create table if not exists commerce.brands (
    id bigint generated by default as identity primary key,
    slug text not null unique,
    name text not null,
    description text,
    status text not null default 'active',
    position integer not null default 0,
    metadata jsonb not null default '{}'::jsonb,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint brands_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
    constraint brands_slug_length check (length(slug) <= 120),
    constraint brands_name_not_blank check (length(btrim(name)) > 0),
    constraint brands_name_length check (length(name) <= 200),
    constraint brands_description_length check (description is null or length(description) <= 10000),
    constraint brands_status check (status in ('active', 'inactive', 'archived')),
    constraint brands_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint brands_metadata_size check (pg_column_size(metadata) <= 32768),
    constraint brands_version_positive check (version > 0)
);

alter table commerce.brands add column if not exists position integer not null default 0;

create table if not exists commerce.categories (
    id bigint generated by default as identity primary key,
    parent_id bigint references commerce.categories(id) on delete restrict,
    slug text not null,
    full_slug text not null,
    label text not null,
    description text,
    status text not null default 'active',
    position integer not null default 0,
    metadata jsonb not null default '{}'::jsonb,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint categories_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
    constraint categories_slug_length check (length(slug) <= 120),
    constraint categories_full_slug_unique unique (full_slug),
    constraint categories_parent_slug_unique unique nulls not distinct (parent_id, slug),
    constraint categories_label_not_blank check (length(btrim(label)) > 0),
    constraint categories_label_length check (length(label) <= 200),
    constraint categories_description_length check (description is null or length(description) <= 10000),
    constraint categories_status check (status in ('active', 'inactive', 'archived')),
    constraint categories_no_self_parent check (parent_id is null or parent_id <> id),
    constraint categories_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint categories_metadata_size check (pg_column_size(metadata) <= 32768),
    constraint categories_version_positive check (version > 0)
);

create table if not exists commerce.products (
    id bigint generated by default as identity primary key,
    slug text not null unique,
    title text not null,
    description text,
    brand_id bigint references commerce.brands(id) on delete restrict,
    status text not null default 'draft',
    visibility text not null default 'public',
    metadata jsonb not null default '{}'::jsonb,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint products_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
    constraint products_slug_length check (length(slug) <= 160),
    constraint products_title_not_blank check (length(btrim(title)) > 0),
    constraint products_title_length check (length(title) <= 300),
    constraint products_description_length check (description is null or length(description) <= 20000),
    constraint products_status check (status in ('draft', 'active', 'archived')),
    constraint products_visibility check (visibility in ('public', 'hidden')),
    constraint products_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint products_metadata_size check (pg_column_size(metadata) <= 65536),
    constraint products_version_positive check (version > 0)
);

alter table commerce.products add column if not exists brand_id bigint references commerce.brands(id) on delete restrict;

create table if not exists commerce.product_categories (
    product_id bigint not null references commerce.products(id) on delete cascade,
    category_id bigint not null references commerce.categories(id) on delete restrict,
    is_primary boolean not null default false,
    position integer not null default 0,
    created_at timestamptz not null default now(),
    primary key (product_id, category_id)
);

create unique index if not exists product_categories_primary_unique
    on commerce.product_categories(product_id) where is_primary;

create table if not exists commerce.product_variants (
    id bigint generated by default as identity primary key,
    product_id bigint not null references commerce.products(id) on delete restrict,
    sku text,
    title text not null,
    status text not null default 'active',
    position integer not null default 0,
    combination_key text,
    generated_from_axes boolean not null default false,
    metadata jsonb not null default '{}'::jsonb,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint product_variants_product_id_id_unique unique (product_id, id),
    constraint product_variants_sku_not_blank check (sku is null or length(btrim(sku)) > 0),
    constraint product_variants_sku_length check (sku is null or length(sku) <= 160),
    constraint product_variants_title_not_blank check (length(btrim(title)) > 0),
    constraint product_variants_title_length check (length(title) <= 300),
    constraint product_variants_status check (status in ('draft', 'active', 'archived')),
    constraint product_variants_combination_key check (
        combination_key is null or length(combination_key) between 1 and 1000
    ),
    constraint product_variants_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint product_variants_metadata_size check (pg_column_size(metadata) <= 65536),
    constraint product_variants_version_positive check (version > 0)
);

alter table commerce.product_variants alter column sku drop not null;
alter table commerce.product_variants add column if not exists combination_key text;
alter table commerce.product_variants
    add column if not exists generated_from_axes boolean not null default false;

create unique index if not exists product_variants_sku_unique
    on commerce.product_variants(sku) where sku is not null;
create unique index if not exists product_variants_combination_unique
    on commerce.product_variants(product_id, combination_key) where combination_key is not null;

create table if not exists commerce.product_variant_axes (
    id bigint generated by default as identity primary key,
    product_id bigint not null references commerce.products(id) on delete restrict,
    key text not null,
    field_key text,
    label text not null,
    position integer not null default 0,
    created_at timestamptz not null default now(),
    constraint product_variant_axes_product_id_id_unique unique (product_id, id),
    constraint product_variant_axes_key_format check (key ~ '^[a-z][a-z0-9_-]{0,47}$'),
    constraint product_variant_axes_label_not_blank check (length(btrim(label)) > 0),
    constraint product_variant_axes_label_length check (length(label) <= 120),
    constraint product_variant_axes_product_key_unique unique (product_id, key)
);

create table if not exists commerce.product_variant_axis_values (
    id bigint generated by default as identity primary key,
    product_id bigint not null,
    axis_id bigint not null,
    key text not null,
    label text not null,
    value jsonb,
    position integer not null default 0,
    created_at timestamptz not null default now(),
    constraint product_variant_axis_values_axis_fk foreign key (product_id, axis_id)
        references commerce.product_variant_axes(product_id, id) on delete cascade,
    constraint product_variant_axis_values_product_axis_id_unique unique (product_id, axis_id, id),
    constraint product_variant_axis_values_key_format check (key ~ '^[a-z0-9][a-z0-9_-]{0,63}$'),
    constraint product_variant_axis_values_label_not_blank check (length(btrim(label)) > 0),
    constraint product_variant_axis_values_label_length check (length(label) <= 160),
    constraint product_variant_axis_values_axis_key_unique unique (axis_id, key)
);

alter table commerce.product_variant_axes add column if not exists field_key text;
alter table commerce.product_variant_axis_values add column if not exists value jsonb;
update commerce.product_variant_axis_values set value = to_jsonb(label) where value is null;

create table if not exists commerce.product_variant_selections (
    product_id bigint not null,
    variant_id bigint not null,
    axis_id bigint not null,
    value_id bigint not null,
    created_at timestamptz not null default now(),
    primary key (variant_id, axis_id),
    constraint product_variant_selections_variant_fk foreign key (product_id, variant_id)
        references commerce.product_variants(product_id, id) on delete cascade,
    constraint product_variant_selections_axis_fk foreign key (product_id, axis_id)
        references commerce.product_variant_axes(product_id, id) on delete cascade,
    constraint product_variant_selections_value_fk foreign key (product_id, axis_id, value_id)
        references commerce.product_variant_axis_values(product_id, axis_id, id) on delete restrict
);

create table if not exists commerce.media (
    id bigint generated by default as identity primary key,
    storage_bucket text not null,
    storage_path text not null,
    mime_type text not null,
    file_size bigint not null,
    original_filename text not null,
    alt text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint media_storage_path_unique unique (storage_bucket, storage_path),
    constraint media_file_size_valid check (file_size between 1 and 10485760),
    constraint media_mime_type_valid check (
        mime_type in ('image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif')
    ),
    constraint media_original_filename_not_blank check (length(btrim(original_filename)) > 0),
    constraint media_alt_length check (alt is null or length(alt) <= 500)
);

create table if not exists commerce.product_media (
    id bigint generated by default as identity primary key,
    product_id bigint not null references commerce.products(id) on delete restrict,
    media_id bigint not null references commerce.media(id) on delete restrict,
    sort_order integer not null default 0,
    is_main boolean not null default false,
    created_at timestamptz not null default now(),
    constraint product_media_product_media_unique unique (product_id, media_id)
);

create unique index if not exists product_media_main_unique
    on commerce.product_media(product_id) where is_main;

do $commerce_storage_bucket$
begin
    if to_regclass('storage.buckets') is not null then
        execute $sql$
            insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
            values (
                'commerce-media', 'commerce-media', false, 10485760,
                array['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif']::text[]
            )
            on conflict (id) do update set
                public = false,
                file_size_limit = excluded.file_size_limit,
                allowed_mime_types = excluded.allowed_mime_types
        $sql$;
    end if;
end;
$commerce_storage_bucket$;

create table if not exists commerce.sellers (
    id bigint generated by default as identity primary key,
    kind text not null,
    cms_user_id text,
    slug text not null unique,
    display_name text not null,
    verification_status text not null default 'pending',
    verified_at timestamptz,
    verified_by text,
    metadata jsonb not null default '{}'::jsonb,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint sellers_kind check (kind in ('merchant', 'user', 'external')),
    constraint sellers_user_identity check (
        (kind = 'user' and cms_user_id is not null and length(btrim(cms_user_id)) > 0)
        or (kind <> 'user' and cms_user_id is null)
    ),
    constraint sellers_cms_user_id_length check (cms_user_id is null or length(cms_user_id) <= 512),
    constraint sellers_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
    constraint sellers_slug_length check (length(slug) <= 160),
    constraint sellers_display_name_not_blank check (length(btrim(display_name)) > 0),
    constraint sellers_display_name_length check (length(display_name) <= 200),
    constraint sellers_verification_status check (
        verification_status in ('pending', 'verified', 'rejected', 'suspended')
    ),
    constraint sellers_verification_audit check (
        (verification_status = 'verified' and verified_at is not null and verified_by is not null)
        or verification_status <> 'verified'
    ),
    constraint sellers_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint sellers_metadata_size check (pg_column_size(metadata) <= 65536),
    constraint sellers_version_positive check (version > 0)
);

create unique index if not exists sellers_cms_user_id_unique
    on commerce.sellers(cms_user_id)
    where cms_user_id is not null;

create table if not exists commerce.seller_verification_events (
    id bigint generated by default as identity primary key,
    seller_id bigint not null references commerce.sellers(id) on delete restrict,
    previous_status text,
    next_status text not null,
    actor_id text not null,
    reason text,
    data jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now(),
    constraint seller_verification_events_previous_status check (
        previous_status is null or previous_status in ('pending', 'verified', 'rejected', 'suspended')
    ),
    constraint seller_verification_events_next_status check (
        next_status in ('pending', 'verified', 'rejected', 'suspended')
    ),
    constraint seller_verification_events_data_object check (jsonb_typeof(data) = 'object')
);

create table if not exists commerce.offer_conditions (
    code text primary key,
    label text not null,
    description text,
    position integer not null default 0,
    enabled boolean not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint offer_conditions_code_format check (code ~ '^[a-z][a-z0-9_]{0,47}$'),
    constraint offer_conditions_label_not_blank check (length(btrim(label)) > 0),
    constraint offer_conditions_label_length check (length(label) <= 200),
    constraint offer_conditions_description_length check (description is null or length(description) <= 2000)
);

create table if not exists commerce.offer_workflow_states (
    code text primary key,
    label text not null,
    phase text not null,
    position integer not null default 0,
    enabled boolean not null default true,
    terminal boolean not null default false,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint offer_workflow_states_code_format check (code ~ '^[a-z][a-z0-9_]{0,47}$'),
    constraint offer_workflow_states_label_not_blank check (length(btrim(label)) > 0),
    constraint offer_workflow_states_label_length check (length(label) <= 200),
    constraint offer_workflow_states_phase check (
        phase in ('draft', 'seller_input', 'admin_review', 'ready', 'terminal')
    ),
    constraint offer_workflow_states_terminal_phase check (
        not terminal or phase = 'terminal'
    )
);

create table if not exists commerce.offer_workflow_transitions (
    from_state text not null references commerce.offer_workflow_states(code) on delete restrict,
    action text not null,
    actor_kind text not null,
    to_state text not null references commerce.offer_workflow_states(code) on delete restrict,
    created_at timestamptz not null default now(),
    primary key (from_state, action, actor_kind),
    constraint offer_workflow_transitions_action_format check (action ~ '^[a-z][a-z0-9_]{0,47}$'),
    constraint offer_workflow_transitions_actor check (actor_kind in ('seller', 'admin', 'system')),
    constraint offer_workflow_transitions_changes_state check (from_state <> to_state)
);

create table if not exists commerce.offers (
    id bigint generated by default as identity primary key,
    seller_id bigint not null references commerce.sellers(id) on delete restrict,
    product_id bigint not null references commerce.products(id) on delete restrict,
    variant_id bigint,
    slug text not null unique,
    title text not null,
    description text,
    condition_code text not null references commerce.offer_conditions(code) on delete restrict,
    publication_status text not null default 'draft',
    workflow_state text not null default 'draft' references commerce.offer_workflow_states(code) on delete restrict,
    accepted_price_amount bigint,
    currency text not null,
    availability text not null default 'available',
    quantity_available integer,
    inventory_revision integer not null default 1,
    metadata jsonb not null default '{}'::jsonb,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint offers_product_variant_fk foreign key (product_id, variant_id)
        references commerce.product_variants(product_id, id) on delete restrict,
    constraint offers_seller_id_id_unique unique (seller_id, id),
    constraint offers_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
    constraint offers_slug_length check (length(slug) <= 160),
    constraint offers_title_not_blank check (length(btrim(title)) > 0),
    constraint offers_title_length check (length(title) <= 300),
    constraint offers_description_length check (description is null or length(description) <= 20000),
    constraint offers_publication_status check (
        publication_status in ('draft', 'active', 'paused', 'archived')
    ),
    constraint offers_currency check (currency ~ '^[a-z]{3}$'),
    constraint offers_accepted_price_non_negative check (
        accepted_price_amount is null or accepted_price_amount between 0 and 9007199254740991
    ),
    constraint offers_active_has_price check (
        publication_status <> 'active' or accepted_price_amount is not null
    ),
    constraint offers_availability check (availability in ('available', 'unavailable', 'preorder')),
    constraint offers_quantity_non_negative check (quantity_available is null or quantity_available between 0 and 1000),
    constraint offers_inventory_revision_positive check (inventory_revision > 0),
    constraint offers_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint offers_metadata_size check (pg_column_size(metadata) <= 65536),
    constraint offers_version_positive check (version > 0)
);

create table if not exists commerce.offer_media (
    id bigint generated by default as identity primary key,
    offer_id bigint not null references commerce.offers(id) on delete restrict,
    media_id bigint not null references commerce.media(id) on delete restrict,
    sort_order integer not null default 0,
    is_main boolean not null default false,
    created_at timestamptz not null default now(),
    constraint offer_media_offer_media_unique unique (offer_id, media_id)
);

create unique index if not exists offer_media_main_unique
    on commerce.offer_media(offer_id) where is_main;

create table if not exists commerce.offer_price_rules (
    offer_id bigint primary key references commerce.offers(id) on delete restrict,
    minimum_amount bigint not null,
    maximum_amount bigint not null,
    currency text not null,
    configured_by text not null,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint offer_price_rules_range check (
        minimum_amount >= 0 and maximum_amount >= minimum_amount
        and maximum_amount <= 9007199254740991
    ),
    constraint offer_price_rules_currency check (currency ~ '^[a-z]{3}$'),
    constraint offer_price_rules_version_positive check (version > 0)
);

create table if not exists commerce.offer_price_proposals (
    id bigint generated by default as identity primary key,
    offer_id bigint not null references commerce.offers(id) on delete restrict,
    amount bigint not null,
    currency text not null,
    status text not null default 'pending',
    proposed_by text not null,
    decided_by text,
    decision_reason text,
    decided_at timestamptz,
    created_at timestamptz not null default now(),
    constraint offer_price_proposals_offer_id_id_unique unique (offer_id, id),
    constraint offer_price_proposals_amount_non_negative check (amount between 0 and 9007199254740991),
    constraint offer_price_proposals_currency check (currency ~ '^[a-z]{3}$'),
    constraint offer_price_proposals_status check (
        status in ('pending', 'accepted', 'rejected', 'withdrawn', 'superseded')
    ),
    constraint offer_price_proposals_decision_audit check (
        (status in ('accepted', 'rejected') and decided_by is not null and decided_at is not null)
        or status not in ('accepted', 'rejected')
    )
);

create unique index if not exists offer_price_proposals_one_pending
    on commerce.offer_price_proposals(offer_id)
    where status = 'pending';

create unique index if not exists offer_price_proposals_one_accepted
    on commerce.offer_price_proposals(offer_id)
    where status = 'accepted';

create table if not exists commerce.offer_events (
    id bigint generated by default as identity primary key,
    offer_id bigint not null references commerce.offers(id) on delete restrict,
    event_type text not null,
    actor_kind text not null,
    actor_id text not null,
    previous_workflow_state text,
    next_workflow_state text,
    data jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now(),
    constraint offer_events_actor_kind check (actor_kind in ('seller', 'admin', 'system')),
    constraint offer_events_data_object check (jsonb_typeof(data) = 'object')
);

create table if not exists commerce.carts (
    id bigint generated by default as identity primary key,
    public_id uuid not null default gen_random_uuid() unique,
    buyer_cms_user_id text not null,
    status text not null default 'open',
    currency text,
    version integer not null default 1,
    converted_at timestamptz,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint carts_buyer_not_blank check (length(btrim(buyer_cms_user_id)) > 0),
    constraint carts_buyer_length check (length(buyer_cms_user_id) <= 512),
    constraint carts_status check (status in ('open', 'converted', 'abandoned', 'expired')),
    constraint carts_currency check (currency is null or currency ~ '^[a-z]{3}$'),
    constraint carts_conversion_consistent check (
        (status = 'converted' and converted_at is not null)
        or (status <> 'converted' and converted_at is null)
    ),
    constraint carts_version_positive check (version > 0)
);

create unique index if not exists carts_one_open_per_buyer
    on commerce.carts(buyer_cms_user_id) where status = 'open';

create table if not exists commerce.cart_items (
    id bigint generated by default as identity primary key,
    cart_id bigint not null references commerce.carts(id) on delete cascade,
    offer_id bigint not null references commerce.offers(id) on delete restrict,
    quantity integer not null,
    unit_amount_at_add bigint not null,
    offer_version_at_add integer not null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint cart_items_cart_offer_unique unique (cart_id, offer_id),
    constraint cart_items_quantity check (quantity between 1 and 1000),
    constraint cart_items_unit_amount check (unit_amount_at_add between 0 and 9007199254740991),
    constraint cart_items_offer_version_positive check (offer_version_at_add > 0)
);

create table if not exists commerce.checkout_groups (
    id uuid primary key default gen_random_uuid(),
    buyer_cms_user_id text not null,
    source_cart_id bigint references commerce.carts(id) on delete restrict,
    idempotency_key text not null,
    request_hash text not null,
    created_at timestamptz not null default now(),
    constraint checkout_groups_buyer_not_blank check (length(btrim(buyer_cms_user_id)) > 0),
    constraint checkout_groups_buyer_length check (length(buyer_cms_user_id) <= 512),
    constraint checkout_groups_idempotency_not_blank check (length(btrim(idempotency_key)) > 0),
    constraint checkout_groups_idempotency_length check (length(idempotency_key) <= 200),
    constraint checkout_groups_request_hash_format check (request_hash ~ '^[a-f0-9]{32}$'),
    constraint checkout_groups_buyer_idempotency_unique unique (buyer_cms_user_id, idempotency_key),
    constraint checkout_groups_source_cart_unique unique (source_cart_id)
);

create table if not exists commerce.orders (
    id bigint generated by default as identity primary key,
    public_id uuid not null default gen_random_uuid() unique,
    order_number text not null unique,
    checkout_group_id uuid not null default gen_random_uuid()
        references commerce.checkout_groups(id) on delete restrict,
    seller_id bigint not null references commerce.sellers(id) on delete restrict,
    buyer_cms_user_id text not null,
    status text not null default 'awaiting_quote',
    currency text not null,
    subtotal_amount bigint not null,
    shipping_amount bigint not null default 0,
    delivery_quoted_at timestamptz,
    total_amount bigint not null,
    shipping_address jsonb not null default '{}'::jsonb,
    billing_address jsonb not null default '{}'::jsonb,
    metadata jsonb not null default '{}'::jsonb,
    idempotency_key text not null,
    request_hash text not null,
    archived_at timestamptz,
    version integer not null default 1,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint orders_buyer_not_blank check (length(btrim(buyer_cms_user_id)) > 0),
    constraint orders_buyer_length check (length(buyer_cms_user_id) <= 512),
    constraint orders_status check (status in (
        'awaiting_quote', 'awaiting_payment', 'active', 'completed',
        'expired', 'cancellation_pending', 'cancelled'
    )),
    constraint orders_currency check (currency ~ '^[a-z]{3}$'),
    constraint orders_amounts_non_negative check (
        subtotal_amount >= 0 and shipping_amount >= 0
        and total_amount >= subtotal_amount + shipping_amount
        and total_amount <= 9007199254740991
    ),
    constraint orders_shipping_address_object check (jsonb_typeof(shipping_address) = 'object'),
    constraint orders_shipping_address_size check (pg_column_size(shipping_address) <= 65536),
    constraint orders_billing_address_object check (jsonb_typeof(billing_address) = 'object'),
    constraint orders_billing_address_size check (pg_column_size(billing_address) <= 65536),
    constraint orders_metadata_object check (jsonb_typeof(metadata) = 'object'),
    constraint orders_metadata_size check (pg_column_size(metadata) <= 65536),
    constraint orders_idempotency_not_blank check (length(btrim(idempotency_key)) > 0),
    constraint orders_idempotency_length check (length(idempotency_key) <= 200),
    constraint orders_request_hash_format check (request_hash ~ '^[a-f0-9]{32}$'),
    constraint orders_seller_id_id_unique unique (seller_id, id),
    constraint orders_version_positive check (version > 0)
);

alter table commerce.orders
    add column if not exists shipping_amount bigint not null default 0;
alter table commerce.orders
    add column if not exists delivery_quoted_at timestamptz;
alter table commerce.orders
    add column if not exists archived_at timestamptz;

alter table commerce.orders drop constraint if exists orders_status;
update commerce.orders set status = 'awaiting_quote' where status = 'placed';
update commerce.orders set status = 'completed', archived_at = coalesce(archived_at, now())
where status = 'archived';
alter table commerce.orders add constraint orders_status check (status in (
    'awaiting_quote', 'awaiting_payment', 'active', 'completed',
    'expired', 'cancellation_pending', 'cancelled'
));
alter table commerce.orders drop constraint if exists orders_amounts_non_negative;
alter table commerce.orders add constraint orders_amounts_non_negative check (
    subtotal_amount >= 0 and shipping_amount >= 0
    and total_amount >= subtotal_amount + shipping_amount
    and total_amount <= 9007199254740991
);

alter table commerce.orders drop constraint if exists orders_buyer_idempotency_unique;
alter table commerce.orders alter column checkout_group_id set default gen_random_uuid();

insert into commerce.checkout_groups (
    id, buyer_cms_user_id, idempotency_key, request_hash, created_at
)
select
    checkout_group_id, buyer_cms_user_id, idempotency_key, request_hash, created_at
from commerce.orders
on conflict do nothing;

do $$
begin
    if not exists (
        select 1 from pg_constraint
        where conname = 'orders_checkout_group_id_fkey'
          and conrelid = 'commerce.orders'::regclass
    ) then
        alter table commerce.orders
            add constraint orders_checkout_group_id_fkey
            foreign key (checkout_group_id) references commerce.checkout_groups(id) on delete restrict;
    end if;
end $$;

create table if not exists commerce.order_lines (
    id bigint generated by default as identity primary key,
    order_id bigint not null references commerce.orders(id) on delete restrict,
    seller_id bigint not null references commerce.sellers(id) on delete restrict,
    offer_id bigint not null references commerce.offers(id) on delete restrict,
    product_id bigint not null references commerce.products(id) on delete restrict,
    variant_id bigint references commerce.product_variants(id) on delete restrict,
    accepted_proposal_id bigint references commerce.offer_price_proposals(id) on delete restrict,
    title text not null,
    sku text,
    quantity integer not null,
    inventory_reserved integer not null default 0,
    availability_before text,
    inventory_revision_before integer,
    unit_amount bigint not null,
    total_amount bigint not null,
    product_snapshot jsonb not null,
    variant_snapshot jsonb,
    offer_snapshot jsonb not null,
    seller_snapshot jsonb not null,
    created_at timestamptz not null default now(),
    constraint order_lines_order_seller_fk foreign key (seller_id, order_id)
        references commerce.orders(seller_id, id) on delete restrict,
    constraint order_lines_offer_seller_fk foreign key (seller_id, offer_id)
        references commerce.offers(seller_id, id) on delete restrict,
    constraint order_lines_product_variant_fk foreign key (product_id, variant_id)
        references commerce.product_variants(product_id, id) on delete restrict,
    constraint order_lines_offer_proposal_fk foreign key (offer_id, accepted_proposal_id)
        references commerce.offer_price_proposals(offer_id, id) on delete restrict,
    constraint order_lines_title_not_blank check (length(btrim(title)) > 0),
    constraint order_lines_title_length check (length(title) <= 300),
    constraint order_lines_sku_length check (sku is null or length(sku) <= 160),
    constraint order_lines_quantity_positive check (quantity between 1 and 1000),
    constraint order_lines_inventory_reserved check (
        inventory_reserved between 0 and quantity
        and ((inventory_reserved = 0 and availability_before is null and inventory_revision_before is null)
            or (inventory_reserved > 0
                and availability_before in ('available', 'unavailable', 'preorder')
                and inventory_revision_before > 0))
    ),
    constraint order_lines_amounts_non_negative check (
        unit_amount between 0 and 9007199254740991
        and total_amount between 0 and 9007199254740991
    ),
    constraint order_lines_total_matches check (total_amount = unit_amount * quantity),
    constraint order_lines_product_snapshot_object check (jsonb_typeof(product_snapshot) = 'object'),
    constraint order_lines_variant_snapshot_object check (
        variant_snapshot is null or jsonb_typeof(variant_snapshot) = 'object'
    ),
    constraint order_lines_offer_snapshot_object check (jsonb_typeof(offer_snapshot) = 'object'),
    constraint order_lines_seller_snapshot_object check (jsonb_typeof(seller_snapshot) = 'object')
);

alter table commerce.offers
    add column if not exists inventory_revision integer not null default 1;
alter table commerce.order_lines
    add column if not exists inventory_revision_before integer;

create table if not exists commerce.order_events (
    id bigint generated by default as identity primary key,
    order_id bigint not null references commerce.orders(id) on delete restrict,
    event_type text not null,
    actor_kind text not null,
    actor_id text not null,
    previous_status text,
    next_status text,
    message text,
    data jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now(),
    constraint order_events_actor_kind check (actor_kind in ('buyer', 'seller', 'admin', 'system')),
    constraint order_events_data_object check (jsonb_typeof(data) = 'object')
);

create table if not exists commerce.financial_subsidy_overrides (
    id bigint generated by default as identity primary key,
    fee_policy_id bigint not null references commerce.fee_policies(id) on delete restrict,
    maximum_deficit_amount bigint not null,
    reason text not null,
    approved_by text not null,
    expires_at timestamptz,
    created_at timestamptz not null default now(),
    constraint financial_subsidy_overrides_amount check (
        maximum_deficit_amount between 0 and 9007199254740991
    ),
    constraint financial_subsidy_overrides_reason check (length(btrim(reason)) > 0),
    constraint financial_subsidy_overrides_approver check (length(btrim(approved_by)) > 0)
);

create index if not exists financial_subsidy_overrides_policy_idx
    on commerce.financial_subsidy_overrides(fee_policy_id, expires_at);

create table if not exists commerce.order_financial_terms (
    order_id bigint primary key references commerce.orders(id) on delete restrict,
    fee_policy_id bigint not null references commerce.fee_policies(id) on delete restrict,
    fee_policy_version integer not null,
    fee_policy_snapshot jsonb not null,
    protection_policy_id bigint not null references commerce.protection_policies(id) on delete restrict,
    protection_policy_version integer not null,
    protection_policy_snapshot jsonb not null,
    seller_risk_policy_id bigint not null references commerce.seller_risk_policies(id) on delete restrict,
    seller_risk_policy_version integer not null,
    seller_risk_policy_snapshot jsonb not null,
    delivery_quote_id text not null,
    merchandise_subtotal_amount bigint not null,
    shipping_amount bigint not null,
    buyer_protection_fee_amount bigint not null,
    seller_commission_amount bigint not null,
    platform_shipping_share_amount bigint not null,
    seller_shipping_share_amount bigint not null,
    buyer_total_amount bigint not null,
    seller_proceeds_amount bigint not null,
    seller_transfer_release_amount bigint not null,
    seller_reserve_liability_amount bigint not null,
    platform_retained_amount bigint not null,
    estimated_stripe_cost_amount bigint not null,
    estimated_carrier_cost_amount bigint not null,
    platform_risk_reserve_contribution_amount bigint not null,
    configured_minimum_margin_amount bigint not null,
    expected_platform_margin_amount bigint not null,
    subsidy_override_id bigint references commerce.financial_subsidy_overrides(id) on delete restrict,
    currency text not null,
    financial_terms_hash text not null,
    pricing_locked_at timestamptz not null default now(),
    pay_by_at timestamptz not null,
    financial_revision integer not null default 1,
    constraint order_financial_terms_quote check (length(btrim(delivery_quote_id)) > 0),
    constraint order_financial_terms_currency check (currency = 'eur'),
    constraint order_financial_terms_snapshots check (
        jsonb_typeof(fee_policy_snapshot) = 'object'
        and jsonb_typeof(protection_policy_snapshot) = 'object'
        and jsonb_typeof(seller_risk_policy_snapshot) = 'object'
    ),
    constraint order_financial_terms_hash check (financial_terms_hash ~ '^[a-f0-9]{64}$'),
    constraint order_financial_terms_revision check (financial_revision > 0),
    constraint order_financial_terms_payment_window check (pay_by_at > pricing_locked_at),
    constraint order_financial_terms_non_negative check (
        merchandise_subtotal_amount between 0 and 9007199254740991
        and shipping_amount between 0 and 9007199254740991
        and buyer_protection_fee_amount between 0 and 9007199254740991
        and seller_commission_amount between 0 and 9007199254740991
        and platform_shipping_share_amount between 0 and 9007199254740991
        and seller_shipping_share_amount between 0 and 9007199254740991
        and buyer_total_amount between 0 and 9007199254740991
        and seller_proceeds_amount between 0 and 9007199254740991
        and seller_transfer_release_amount between 0 and 9007199254740991
        and seller_reserve_liability_amount between 0 and 9007199254740991
        and platform_retained_amount between 0 and 9007199254740991
        and estimated_stripe_cost_amount between 0 and 9007199254740991
        and estimated_carrier_cost_amount between 0 and 9007199254740991
        and platform_risk_reserve_contribution_amount between 0 and 9007199254740991
        and configured_minimum_margin_amount between 0 and 9007199254740991
    ),
    constraint order_financial_terms_shipping_identity check (
        shipping_amount = platform_shipping_share_amount + seller_shipping_share_amount
    ),
    constraint order_financial_terms_seller_commission_limit check (
        seller_commission_amount <= merchandise_subtotal_amount + seller_shipping_share_amount
    ),
    constraint order_financial_terms_seller_identity check (
        seller_proceeds_amount = merchandise_subtotal_amount + seller_shipping_share_amount - seller_commission_amount
        and seller_proceeds_amount = seller_transfer_release_amount + seller_reserve_liability_amount
    ),
    constraint order_financial_terms_platform_identity check (
        platform_retained_amount = buyer_protection_fee_amount + seller_commission_amount + platform_shipping_share_amount
        and buyer_total_amount = seller_proceeds_amount + platform_retained_amount
    ),
    constraint order_financial_terms_margin_identity check (
        expected_platform_margin_amount = platform_retained_amount
            - estimated_stripe_cost_amount - estimated_carrier_cost_amount
            - platform_risk_reserve_contribution_amount
    )
