create or replace function commerce.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    new.updated_at = now();
    return new;
end;
$$;

create or replace function commerce.set_updated_at_and_version()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    new.updated_at = now();
    if new.version = old.version then
        new.version = old.version + 1;
    end if;
    return new;
end;
$$;

create or replace function commerce.category_full_slug(p_parent_id bigint, p_slug text)
returns text
language sql
stable
set search_path = ''
as $$
    select case
        when p_parent_id is null then p_slug
        else (select category.full_slug from commerce.categories category where category.id = p_parent_id) || '/' || p_slug
    end;
$$;

create or replace function commerce.set_category_full_slug()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    new.full_slug := commerce.category_full_slug(new.parent_id, new.slug);
    if new.full_slug is null then raise exception 'validation: category parent does not exist'; end if;
    return new;
end;
$$;

create or replace function commerce.cascade_category_full_slug()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    if new.full_slug is distinct from old.full_slug then
        update commerce.categories
        set full_slug = commerce.category_full_slug(new.id, slug)
        where parent_id = new.id;
    end if;
    return null;
end;
$$;

create or replace function commerce.ensure_order_checkout_group()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
    v_group commerce.checkout_groups%rowtype;
begin
    select * into v_group
    from commerce.checkout_groups
    where id = new.checkout_group_id;
    if found then
        if v_group.buyer_cms_user_id <> new.buyer_cms_user_id
            or v_group.idempotency_key <> new.idempotency_key
            or v_group.request_hash <> new.request_hash then
            raise exception 'conflict: checkout group does not match order';
        end if;
        return new;
    end if;
    insert into commerce.checkout_groups (
        id, buyer_cms_user_id, idempotency_key, request_hash, created_at
    ) values (
        new.checkout_group_id, new.buyer_cms_user_id,
        new.idempotency_key, new.request_hash, new.created_at
    );
    return new;
end;
$$;

create or replace function commerce.assert_custom_field_patch(
    p_entity_type text,
    p_values jsonb,
    p_actor_kind text
)
returns void
language plpgsql
set search_path = ''
as $$
declare
    v_key text;
    v_value jsonb;
    v_definition commerce.custom_field_definitions%rowtype;
begin
    p_values := coalesce(p_values, '{}'::jsonb);
    perform pg_advisory_xact_lock_shared(hashtextextended('commerce-custom-fields:' || p_entity_type, 0));
    if jsonb_typeof(p_values) <> 'object' then
        raise exception 'validation: custom fields must be an object';
    end if;
    if pg_column_size(p_values) > 65536 then
        raise exception 'validation: custom fields exceed 64 KiB';
    end if;
    if p_actor_kind not in ('self', 'admin', 'system') then
        raise exception 'forbidden: invalid custom field actor';
    end if;

    for v_key, v_value in select key, value from jsonb_each(p_values)
    loop
        select * into v_definition
        from commerce.custom_field_definitions
        where entity_type = p_entity_type
          and key = v_key
          and (enabled or p_actor_kind = 'system');

        if not found then
            raise exception 'validation: unknown custom field % for %', v_key, p_entity_type;
        end if;
        if p_actor_kind = 'self' and not v_definition.self_editable then
            raise exception 'forbidden: custom field % is not self editable', v_key;
        end if;
        if p_actor_kind = 'admin' and not v_definition.admin_editable then
            raise exception 'forbidden: custom field % is not admin editable', v_key;
        end if;
        if v_definition.field_type in ('string', 'enum') and jsonb_typeof(v_value) <> 'string' then
            raise exception 'validation: custom field % must be a string', v_key;
        elsif v_definition.field_type = 'number' and jsonb_typeof(v_value) <> 'number' then
            raise exception 'validation: custom field % must be a number', v_key;
        elsif v_definition.field_type = 'boolean' and jsonb_typeof(v_value) <> 'boolean' then
            raise exception 'validation: custom field % must be a boolean', v_key;
        end if;
        if v_definition.field_type = 'enum'
            and not (v_definition.options @> jsonb_build_array(v_value)) then
            raise exception 'validation: custom field % has an unsupported value', v_key;
        end if;
    end loop;

end;
$$;

drop function if exists commerce.upsert_custom_field(
    text, text, text, text, jsonb, boolean, boolean, boolean,
    boolean, boolean, integer, boolean
);

create or replace function commerce.upsert_custom_field(
    p_entity_type text,
    p_key text,
    p_label text,
    p_field_type text,
    p_options jsonb default '[]'::jsonb,
    p_required boolean default false,
    p_self_editable boolean default false,
    p_admin_editable boolean default true,
    p_public_readable boolean default false,
    p_show_in_dashboard_table boolean default false,
    p_position integer default 0,
    p_enabled boolean default true,
    p_unit text default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_definition commerce.custom_field_definitions%rowtype;
begin
    if p_entity_type not in ('product', 'variant', 'seller', 'offer', 'order') then
        raise exception 'validation: unsupported custom field entity type';
    end if;
    if p_field_type not in ('string', 'number', 'boolean', 'enum') then
        raise exception 'validation: unsupported custom field type';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('commerce-custom-fields:' || p_entity_type, 0));
    if not exists (
        select 1 from commerce.custom_field_definitions
        where entity_type = p_entity_type and key = p_key
    ) and (
        select count(*) from commerce.custom_field_definitions where entity_type = p_entity_type
    ) >= 128 then
        raise exception 'validation: at most 128 custom fields are allowed per entity';
    end if;

    if exists (
        select 1
        from (
            select metadata from commerce.products where p_entity_type = 'product'
            union all select metadata from commerce.product_variants where p_entity_type = 'variant'
            union all select metadata from commerce.sellers where p_entity_type = 'seller'
            union all select metadata from commerce.offers where p_entity_type = 'offer'
            union all select metadata from commerce.orders where p_entity_type = 'order'
        ) entity
        where entity.metadata ? p_key
          and (
              (p_field_type in ('string', 'enum') and jsonb_typeof(entity.metadata->p_key) <> 'string')
              or (p_field_type = 'number' and jsonb_typeof(entity.metadata->p_key) <> 'number')
              or (p_field_type = 'boolean' and jsonb_typeof(entity.metadata->p_key) <> 'boolean')
              or (p_field_type = 'enum' and not (p_options @> jsonb_build_array(entity.metadata->p_key)))
          )
    ) then raise exception 'conflict: existing metadata values are incompatible with this definition'; end if;

    if p_enabled and p_required and exists (
        select 1
        from (
            select metadata from commerce.products where p_entity_type = 'product'
            union all select metadata from commerce.product_variants where p_entity_type = 'variant'
            union all select metadata from commerce.sellers where p_entity_type = 'seller'
            union all select metadata from commerce.offers where p_entity_type = 'offer'
            union all select metadata from commerce.orders where p_entity_type = 'order'
        ) entity
        where not (entity.metadata ? p_key)
    ) then raise exception 'conflict: existing entities are missing this required custom field'; end if;

    insert into commerce.custom_field_definitions (
        entity_type, key, label, field_type, options, unit, required,
        self_editable, admin_editable, public_readable,
        show_in_dashboard_table, position, enabled
    ) values (
        p_entity_type, p_key, p_label, p_field_type, coalesce(p_options, '[]'::jsonb), nullif(btrim(p_unit), ''), p_required,
        p_self_editable, p_admin_editable, p_public_readable,
        p_show_in_dashboard_table, p_position, p_enabled
    ) on conflict (entity_type, key) do update
    set label = excluded.label,
        field_type = excluded.field_type,
        options = excluded.options,
        unit = excluded.unit,
        required = excluded.required,
        self_editable = excluded.self_editable,
        admin_editable = excluded.admin_editable,
        public_readable = excluded.public_readable,
        show_in_dashboard_table = excluded.show_in_dashboard_table,
        position = excluded.position,
        enabled = excluded.enabled
    returning * into v_definition;
    return to_jsonb(v_definition);
end;
$$;

create or replace function commerce.delete_custom_field(
    p_entity_type text,
    p_key text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_definition commerce.custom_field_definitions%rowtype;
begin
    select * into v_definition
    from commerce.custom_field_definitions
    where entity_type = p_entity_type and key = p_key
    for update;
    if not found then raise exception 'not_found: custom field not found'; end if;

    if exists (
        select 1 from commerce.category_custom_fields
        where entity_type = p_entity_type and field_key = p_key
    ) then raise exception 'conflict: metadata is assigned to at least one category'; end if;

    if p_entity_type = 'product' and exists (
        select 1 from commerce.product_variant_axes where field_key = p_key
    ) then raise exception 'conflict: metadata is used as a product variant axis'; end if;

    if exists (
        select 1
        from (
            select metadata from commerce.products where p_entity_type = 'product'
            union all select metadata from commerce.product_variants where p_entity_type = 'variant'
            union all select metadata from commerce.sellers where p_entity_type = 'seller'
            union all select metadata from commerce.offers where p_entity_type = 'offer'
            union all select metadata from commerce.orders where p_entity_type = 'order'
        ) entity
        where entity.metadata ? p_key
    ) then raise exception 'conflict: metadata has existing values'; end if;

    delete from commerce.custom_field_definitions
    where entity_type = p_entity_type and key = p_key;
    return jsonb_build_object('entityType', p_entity_type, 'key', p_key, 'deleted', true);
end;
$$;

create or replace function commerce.assert_custom_fields(
    p_entity_type text,
    p_values jsonb,
    p_actor_kind text
)
returns void
language plpgsql
set search_path = ''
as $$
begin
    p_values := coalesce(p_values, '{}'::jsonb);
    perform commerce.assert_custom_field_patch(p_entity_type, p_values, p_actor_kind);
    if exists (
        select 1
        from commerce.custom_field_definitions definition
        where definition.entity_type = p_entity_type
          and definition.enabled
          and definition.required
          and not (p_values ? definition.key)
    ) then
        raise exception 'validation: required custom fields are missing for %', p_entity_type;
    end if;
end;
$$;

create or replace function commerce.assert_product_custom_fields(
    p_category_id bigint,
    p_values jsonb,
    p_actor_kind text
)
returns void
language plpgsql
set search_path = ''
as $$
begin
    if p_category_id is null then
        perform commerce.assert_custom_fields('product', p_values, p_actor_kind);
        return;
    end if;
    if not exists (select 1 from commerce.categories where id = p_category_id) then
        raise exception 'validation: primary category does not exist';
    end if;
    perform commerce.assert_custom_field_patch('product', p_values, p_actor_kind);

    if exists (
        with recursive ancestry as (
            select id, parent_id from commerce.categories where id = p_category_id
            union all
            select parent.id, parent.parent_id
            from commerce.categories parent join ancestry child on child.parent_id = parent.id
        )
        select 1 from jsonb_object_keys(coalesce(p_values, '{}'::jsonb)) key
        where not exists (
            select 1 from ancestry
            join commerce.category_custom_fields field on field.category_id = ancestry.id
            join commerce.custom_field_definitions definition
              on definition.entity_type = field.entity_type and definition.key = field.field_key
            where definition.enabled and field.field_key = key
        )
    ) then raise exception 'validation: product metadata contains a field outside its category schema'; end if;

    if exists (
        with recursive ancestry as (
            select id, parent_id from commerce.categories where id = p_category_id
            union all
            select parent.id, parent.parent_id
            from commerce.categories parent join ancestry child on child.parent_id = parent.id
        )
        select 1 from ancestry
        join commerce.category_custom_fields field on field.category_id = ancestry.id
        join commerce.custom_field_definitions definition
          on definition.entity_type = field.entity_type and definition.key = field.field_key
        where definition.enabled and field.required and not (coalesce(p_values, '{}'::jsonb) ? field.field_key)
    ) then raise exception 'validation: required category fields are missing for product'; end if;
end;
$$;

create or replace function commerce.assert_product_custom_fields_with_axes(
    p_category_id bigint,
    p_values jsonb,
    p_actor_kind text,
    p_axis_field_keys jsonb
)
returns void
language plpgsql
set search_path = ''
as $$
begin
    if p_category_id is null then
        perform commerce.assert_custom_fields('product', p_values, p_actor_kind);
        return;
    end if;
    if not exists (select 1 from commerce.categories where id = p_category_id) then
        raise exception 'validation: primary category does not exist';
    end if;
    if jsonb_typeof(coalesce(p_axis_field_keys, '[]'::jsonb)) <> 'array' then
        raise exception 'validation: variant axis field keys must be an array';
    end if;
    perform commerce.assert_custom_field_patch('product', p_values, p_actor_kind);

    if exists (
        with recursive ancestry as (
            select id, parent_id from commerce.categories where id = p_category_id
            union all
            select parent.id, parent.parent_id
            from commerce.categories parent join ancestry child on child.parent_id = parent.id
        )
        select 1 from jsonb_object_keys(coalesce(p_values, '{}'::jsonb)) key
        where not exists (
            select 1 from ancestry
            join commerce.category_custom_fields field on field.category_id = ancestry.id
            join commerce.custom_field_definitions definition
              on definition.entity_type = field.entity_type and definition.key = field.field_key
            where definition.enabled and field.field_key = key
        )
    ) then raise exception 'validation: product metadata contains a field outside its category schema'; end if;

    if exists (
        with recursive ancestry as (
            select id, parent_id from commerce.categories where id = p_category_id
            union all
            select parent.id, parent.parent_id
            from commerce.categories parent join ancestry child on child.parent_id = parent.id
        )
        select 1 from ancestry
        join commerce.category_custom_fields field on field.category_id = ancestry.id
        join commerce.custom_field_definitions definition
          on definition.entity_type = field.entity_type and definition.key = field.field_key
        where definition.enabled and field.required
          and not (coalesce(p_values, '{}'::jsonb) ? field.field_key)
          and not (coalesce(p_axis_field_keys, '[]'::jsonb) ? field.field_key)
    ) then raise exception 'validation: required category fields are missing for product or variants'; end if;
end;
$$;

create or replace function commerce.assert_product_variant_ready(
    p_product_id bigint,
    p_variant_id bigint
)
returns void
language plpgsql
set search_path = ''
as $$
declare
    v_axis_count integer;
begin
    select count(*) into v_axis_count
    from commerce.product_variant_axes
    where product_id = p_product_id;

    if v_axis_count > 0 and p_variant_id is null then
        raise exception 'validation: a product variant is required when the product has variant axes';
    end if;
    if p_variant_id is null then return; end if;
    if not exists (
        select 1
        from commerce.product_variants variant
        where variant.id = p_variant_id
          and variant.product_id = p_product_id
          and variant.status = 'active'
          and (v_axis_count = 0 or variant.combination_key is not null)
    ) then
        raise exception 'validation: an active product variant is required';
    end if;
    if v_axis_count > 0 and (
        select count(distinct selection.axis_id)
        from commerce.product_variant_selections selection
        where selection.product_id = p_product_id
          and selection.variant_id = p_variant_id
    ) <> v_axis_count then
        raise exception 'validation: the product variant does not select every variant axis';
    end if;
end;
$$;

create or replace function commerce.assert_offer_publication_ready(
    p_seller_id bigint,
    p_product_id bigint,
    p_variant_id bigint,
    p_workflow_state text,
    p_price_amount bigint
)
returns void
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_seller commerce.sellers%rowtype;
begin
    if p_price_amount is null or p_price_amount < 0 then
        raise exception 'validation: a non-negative accepted price is required for publication';
    end if;
    select * into v_settings from commerce.settings where id = 'default';
    select * into v_seller from commerce.sellers where id = p_seller_id;
    if not found then raise exception 'not_found: seller'; end if;
    if v_seller.verification_status in ('rejected', 'suspended') then
        raise exception 'forbidden: seller is not allowed to publish';
    end if;
    if v_settings.mode = 'ecommerce' and v_seller.kind = 'user' then
        raise exception 'forbidden: marketplace offers are disabled';
    end if;
    if not exists (
        select 1 from commerce.products
        where id = p_product_id and status = 'active' and visibility = 'public'
    ) then raise exception 'validation: an active public product is required for publication'; end if;
    perform commerce.assert_product_variant_ready(p_product_id, p_variant_id);
    if not exists (
        select 1 from commerce.offer_workflow_states
        where code = p_workflow_state and phase = 'ready' and enabled
    ) then raise exception 'validation: a ready workflow state is required for publication'; end if;
end;
$$;

create or replace function commerce.update_settings(
    p_payload jsonb,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
begin
    select * into v_settings from commerce.settings where id = 'default' for update;
    if v_settings.version is distinct from p_expected_version then
        raise exception 'conflict: stale settings version';
    end if;
    update commerce.settings
    set mode = coalesce(nullif(p_payload->>'mode', ''), mode),
        default_currency = coalesce(nullif(lower(p_payload->>'defaultCurrency'), ''), default_currency),
        require_verified_seller = coalesce((p_payload->>'requireVerifiedSeller')::boolean, require_verified_seller),
        offer_moderation = coalesce(nullif(p_payload->>'offerModeration', ''), offer_moderation),
        price_policy = coalesce(nullif(p_payload->>'pricePolicy', ''), price_policy),
        auto_approve_price_in_range = coalesce((p_payload->>'autoApprovePriceInRange')::boolean, auto_approve_price_in_range),
        require_final_price_approval = coalesce((p_payload->>'requireFinalPriceApproval')::boolean, require_final_price_approval),
        seller_can_publish = coalesce((p_payload->>'sellerCanPublish')::boolean, seller_can_publish)
    where id = 'default'
    returning * into v_settings;

    if v_settings.mode = 'ecommerce' then
        update commerce.offers offer
        set publication_status = 'paused'
        from commerce.sellers seller
        where seller.id = offer.seller_id
          and seller.kind = 'user'
          and offer.publication_status = 'active';
    end if;
    return to_jsonb(v_settings);
end;
$$;

create or replace function commerce.register_my_seller(
    p_cms_user_id text,
    p_display_name text,
    p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_seller commerce.sellers%rowtype;
    v_slug text;
begin
    if p_cms_user_id is null or length(btrim(p_cms_user_id)) = 0 then
        raise exception 'forbidden: missing CMS user id';
    end if;
    select * into v_settings from commerce.settings where id = 'default' for share;
    if v_settings.mode = 'ecommerce' then
        raise exception 'forbidden: marketplace sellers are disabled';
    end if;

    perform pg_advisory_xact_lock(hashtextextended('commerce-seller:' || p_cms_user_id, 0));
    select * into v_seller from commerce.sellers where cms_user_id = p_cms_user_id;
    if found then
        return to_jsonb(v_seller);
    end if;
    perform commerce.assert_custom_fields('seller', coalesce(p_metadata, '{}'::jsonb), 'self');

    v_slug := 'user-' || substr(md5(p_cms_user_id), 1, 16);
    insert into commerce.sellers (kind, cms_user_id, slug, display_name, metadata)
    values (
        'user',
        p_cms_user_id,
        v_slug,
        coalesce(nullif(btrim(p_display_name), ''), 'Marketplace seller'),
        coalesce(p_metadata, '{}'::jsonb)
    )
    returning * into v_seller;

    insert into commerce.seller_verification_events (
        seller_id, previous_status, next_status, actor_id, data
    ) values (v_seller.id, null, 'pending', p_cms_user_id, '{}'::jsonb);

    return to_jsonb(v_seller);
end;
$$;

create or replace function commerce.update_my_seller(
    p_cms_user_id text,
    p_expected_version integer,
    p_display_name text default null,
    p_metadata_patch jsonb default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_seller commerce.sellers%rowtype;
    v_metadata jsonb;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    if v_settings.mode = 'ecommerce' then raise exception 'forbidden: marketplace sellers are disabled'; end if;
    select * into v_seller from commerce.sellers where cms_user_id = p_cms_user_id for update;
    if not found then raise exception 'not_found: seller'; end if;
    if v_seller.version is distinct from p_expected_version then
        raise exception 'conflict: stale seller version';
    end if;
    if p_metadata_patch is not null then
        perform commerce.assert_custom_field_patch('seller', p_metadata_patch, 'self');
        v_metadata := v_seller.metadata || p_metadata_patch;
    else
        v_metadata := v_seller.metadata;
    end if;
    perform commerce.assert_custom_fields('seller', v_metadata, 'system');
    update commerce.sellers
    set display_name = coalesce(nullif(btrim(p_display_name), ''), display_name),
        metadata = v_metadata
    where id = v_seller.id
    returning * into v_seller;
    return to_jsonb(v_seller);
end;
$$;

create or replace function commerce.verify_pending_seller_payout_eligibility(
    p_cms_user_id text,
    p_seller_id bigint,
    p_expected_version integer,
    p_provider text,
    p_provider_account_id text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_seller commerce.sellers%rowtype;
    v_provider text := lower(btrim(coalesce(p_provider, '')));
    v_provider_account_id text := btrim(coalesce(p_provider_account_id, ''));
    v_actor constant text := 'system:payout-eligibility';
begin
    if p_cms_user_id is null or length(btrim(p_cms_user_id)) = 0 then
        raise exception 'forbidden: missing CMS user id';
    end if;
    if v_provider !~ '^[a-z][a-z0-9_-]{0,31}$' then
        raise exception 'validation: invalid payout provider';
    end if;
    if length(v_provider_account_id) = 0 or length(v_provider_account_id) > 255 then
        raise exception 'validation: invalid payout provider account id';
    end if;

    select * into v_seller
    from commerce.sellers
    where id = p_seller_id
    for update;
    if not found or v_seller.kind <> 'user' or v_seller.cms_user_id is distinct from p_cms_user_id then
        raise exception 'not_found: seller';
    end if;

    if v_seller.verification_status = 'verified' then
        return jsonb_build_object(
            'seller', to_jsonb(v_seller),
            'transitioned', false,
            'idempotentReplay', true
        );
    end if;
    if v_seller.verification_status in ('rejected', 'suspended') then
        raise exception 'forbidden: seller payout eligibility cannot override marketplace review';
    end if;
    if v_seller.verification_status <> 'pending' then
        raise exception 'conflict: seller is not pending verification';
    end if;
    if p_expected_version is null or v_seller.version is distinct from p_expected_version then
        raise exception 'conflict: stale seller version';
    end if;

    update commerce.sellers
    set verification_status = 'verified',
        verified_at = now(),
        verified_by = v_actor
    where id = v_seller.id
    returning * into v_seller;

    insert into commerce.seller_verification_events (
        seller_id, previous_status, next_status, actor_id, reason, data
    ) values (
        v_seller.id,
        'pending',
        'verified',
        v_actor,
        'Payout provider eligibility verified server-side',
        jsonb_build_object(
            'provider', v_provider,
            'providerAccountId', v_provider_account_id,
            'eligibility', 'can_receive_protected_payments'
        )
    );

    return jsonb_build_object(
        'seller', to_jsonb(v_seller),
        'transitioned', true,
        'idempotentReplay', false
    );
end;
$$;

create or replace function commerce.review_seller(
    p_seller_id bigint,
    p_status text,
    p_admin_id text,
    p_reason text default null,
    p_expected_version integer default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
    v_previous text;
begin
    if p_status not in ('pending', 'verified', 'rejected', 'suspended') then
        raise exception 'validation: unsupported seller status';
    end if;
    select * into v_settings from commerce.settings where id = 'default' for share;
    select * into v_seller from commerce.sellers where id = p_seller_id for update;
    if not found then raise exception 'not_found: seller'; end if;
    if p_expected_version is null then raise exception 'validation: expected seller version is required'; end if;
    if v_seller.version is distinct from p_expected_version then
        raise exception 'conflict: stale seller version';
    end if;
    perform id from commerce.offers
    where seller_id = v_seller.id
    order by id
    for update;
    v_previous := v_seller.verification_status;

    update commerce.sellers
    set verification_status = p_status,
        verified_at = case when p_status = 'verified' then now() else null end,
        verified_by = case when p_status = 'verified' then coalesce(nullif(p_admin_id, ''), 'cms-admin') else null end
    where id = p_seller_id
    returning * into v_seller;

    insert into commerce.seller_verification_events (
        seller_id, previous_status, next_status, actor_id, reason
    ) values (
        v_seller.id, v_previous, p_status, coalesce(nullif(p_admin_id, ''), 'cms-admin'), p_reason
    );
    if p_status in ('rejected', 'suspended')
        or (v_settings.mode = 'ecommerce' and v_seller.kind = 'user') then
        update commerce.offers
        set publication_status = 'paused'
        where seller_id = v_seller.id and publication_status = 'active';
    end if;
    return to_jsonb(v_seller);
end;
$$;

create or replace function commerce.sync_product_variant_matrix(
    p_product_id bigint,
    p_axes jsonb,
    p_matrix jsonb
)
returns void
language plpgsql
set search_path = ''
as $$
declare
    v_axis jsonb;
    v_value jsonb;
    v_row jsonb;
    v_choice jsonb;
    v_axis_id bigint;
    v_category_id bigint;
    v_definition commerce.custom_field_definitions%rowtype;
    v_typed_value jsonb;
    v_variant commerce.product_variants%rowtype;
    v_expected integer := 1;
    v_axis_count integer;
begin
    p_axes := coalesce(p_axes, '[]'::jsonb);
    p_matrix := coalesce(p_matrix, '[]'::jsonb);
    if jsonb_typeof(p_axes) <> 'array' or jsonb_array_length(p_axes) > 4 then
        raise exception 'validation: variant axes must be an array with at most four axes';
    end if;
    if jsonb_typeof(p_matrix) <> 'array' then
        raise exception 'validation: variant matrix must be an array';
    end if;
    v_axis_count := jsonb_array_length(p_axes);
    if exists (
        select 1 from jsonb_array_elements(p_axes) axis
        where jsonb_typeof(axis) <> 'object'
           or coalesce(axis->>'key', '') !~ '^[a-z][a-z0-9_-]{0,47}$'
           or (axis ? 'fieldKey' and coalesce(axis->>'fieldKey', '') !~ '^[A-Za-z][A-Za-z0-9_]{0,63}$')
           or length(btrim(coalesce(axis->>'label', ''))) = 0
           or jsonb_typeof(axis->'values') <> 'array'
           or jsonb_array_length(axis->'values') not between 1 and 20
    ) then raise exception 'validation: every variant axis needs a key, label, and one to twenty values'; end if;
    if (select count(*) from jsonb_array_elements(p_axes)) <> (
        select count(distinct axis->>'key') from jsonb_array_elements(p_axes) axis
    ) then raise exception 'validation: variant axis keys must be unique'; end if;

    for v_axis in select value from jsonb_array_elements(p_axes)
    loop
        v_expected := v_expected * jsonb_array_length(v_axis->'values');
        if v_expected > 100 then raise exception 'validation: variant matrix cannot exceed 100 combinations'; end if;
        if (select count(*) from jsonb_array_elements(v_axis->'values')) <> (
            select count(distinct item->>'key') from jsonb_array_elements(v_axis->'values') item
        ) then raise exception 'validation: variant value keys must be unique inside an axis'; end if;
    end loop;
    if v_axis_count = 0 then v_expected := 0; end if;
    if jsonb_array_length(p_matrix) <> v_expected then
        raise exception 'validation: variant matrix does not match the cartesian product';
    end if;
    if (select count(*) from jsonb_array_elements(p_matrix)) <> (
        select count(distinct row->>'key') from jsonb_array_elements(p_matrix) row
    ) then raise exception 'validation: variant combination keys must be unique'; end if;

    delete from commerce.product_variant_selections where product_id = p_product_id;
    delete from commerce.product_variant_axes where product_id = p_product_id;
    select category_id into v_category_id from commerce.product_categories
    where product_id = p_product_id and is_primary;
    for v_axis in select value from jsonb_array_elements(p_axes) order by (value->>'position')::integer
    loop
        v_definition := null;
        if nullif(v_axis->>'fieldKey', '') is not null then
            with recursive ancestry as (
                select id, parent_id from commerce.categories where id = v_category_id
                union all
                select parent.id, parent.parent_id
                from commerce.categories parent join ancestry child on child.parent_id = parent.id
            )
            select definition.* into v_definition
            from ancestry
            join commerce.category_custom_fields field on field.category_id = ancestry.id
            join commerce.custom_field_definitions definition
              on definition.entity_type = field.entity_type and definition.key = field.field_key
            where definition.enabled and definition.entity_type = 'product'
              and definition.key = v_axis->>'fieldKey'
            limit 1;
            if not found then raise exception 'validation: variant axis metadata is not applicable to the primary category'; end if;
            if exists (select 1 from commerce.products where id = p_product_id and metadata ? (v_axis->>'fieldKey')) then
                raise exception 'validation: variant axis metadata cannot also be stored on the Product';
            end if;
        end if;
        insert into commerce.product_variant_axes (product_id, key, field_key, label, position)
        values (
            p_product_id, v_axis->>'key', nullif(v_axis->>'fieldKey', ''),
            coalesce(v_definition.label, btrim(v_axis->>'label')),
            coalesce(nullif(v_axis->>'position', '')::integer, 0)
        ) returning id into v_axis_id;
        for v_value in select value from jsonb_array_elements(v_axis->'values') order by (value->>'position')::integer
        loop
            v_typed_value := case v_definition.field_type
                when 'number' then to_jsonb((v_value->>'value')::numeric)
                when 'boolean' then to_jsonb((v_value->>'value')::boolean)
                else to_jsonb(v_value->>'value')
            end;
            if v_definition.field_type = 'enum' and not (v_definition.options @> jsonb_build_array(v_value->>'value')) then
                raise exception 'validation: variant axis value is not allowed by its metadata definition';
            end if;
            insert into commerce.product_variant_axis_values (product_id, axis_id, key, label, value, position)
            values (
                p_product_id, v_axis_id, v_value->>'key', btrim(v_value->>'label'),
                coalesce(v_typed_value, to_jsonb(v_value->>'label')),
                coalesce(nullif(v_value->>'position', '')::integer, 0)
            );
        end loop;
    end loop;

    if exists (
        select 1 from commerce.product_variants variant
        join commerce.product_variant_axes axis on axis.product_id = variant.product_id
        where variant.product_id = p_product_id
          and axis.field_key is not null
          and variant.metadata ? axis.field_key
    ) then raise exception 'validation: variant axis metadata cannot also be overridden on a Variant'; end if;

    for v_row in select value from jsonb_array_elements(p_matrix) order by (value->>'position')::integer
    loop
        if jsonb_typeof(v_row->'choices') <> 'array'
            or jsonb_array_length(v_row->'choices') <> v_axis_count then
            raise exception 'validation: every variant combination must select one value per axis';
        end if;
        if (
            select count(distinct choice->>'axisKey')
            from jsonb_array_elements(v_row->'choices') choice
        ) <> v_axis_count then
            raise exception 'validation: every variant combination must select each axis exactly once';
        end if;
        insert into commerce.product_variants (
            product_id, sku, title, status, position, combination_key, generated_from_axes
        ) values (
            p_product_id, null, btrim(v_row->>'title'),
            coalesce(nullif(v_row->>'status', ''), 'active'),
            coalesce(nullif(v_row->>'position', '')::integer, 0),
            v_row->>'key', true
        ) on conflict (product_id, combination_key) where combination_key is not null do update
        set title = excluded.title,
            status = excluded.status,
            position = excluded.position,
            generated_from_axes = true
        returning * into v_variant;

        for v_choice in select value from jsonb_array_elements(v_row->'choices')
        loop
            insert into commerce.product_variant_selections (product_id, variant_id, axis_id, value_id)
            select p_product_id, v_variant.id, axis.id, axis_value.id
            from commerce.product_variant_axes axis
            join commerce.product_variant_axis_values axis_value
              on axis_value.product_id = axis.product_id and axis_value.axis_id = axis.id
            where axis.product_id = p_product_id
              and axis.key = v_choice->>'axisKey'
              and axis_value.key = v_choice->>'valueKey';
            if not found then raise exception 'validation: variant choice is not part of the product axes'; end if;
        end loop;
    end loop;

    update commerce.product_variants variant
    set status = 'archived'
    where variant.product_id = p_product_id
      and variant.generated_from_axes
      and not exists (
          select 1 from jsonb_array_elements(p_matrix) row
          where row->>'key' = variant.combination_key
      );
    update commerce.offers offer
    set publication_status = 'paused'
    where offer.product_id = p_product_id
      and offer.publication_status = 'active'
      and not exists (
          select 1
          from commerce.product_variants variant
          where variant.id = offer.variant_id
            and variant.product_id = offer.product_id
            and variant.status = 'active'
            and (
                v_axis_count = 0
                or (
                    variant.combination_key is not null
                    and (
                        select count(distinct selection.axis_id)
                        from commerce.product_variant_selections selection
                        where selection.product_id = offer.product_id
                          and selection.variant_id = variant.id
                    ) = v_axis_count
                )
            )
      )
      and (v_axis_count > 0 or offer.variant_id is not null);
end;
$$;

create or replace function commerce.upsert_product(
    p_product_id bigint,
    p_payload jsonb,
    p_expected_version integer default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_product commerce.products%rowtype;
    v_metadata jsonb;
    v_metadata_patch jsonb;
    v_primary_category_id bigint;
    v_axis_field_keys jsonb;
begin
    if p_payload ? 'variantAxes' then
        select coalesce(jsonb_agg(axis->>'fieldKey'), '[]'::jsonb) into v_axis_field_keys
        from jsonb_array_elements(coalesce(p_payload->'variantAxes', '[]'::jsonb)) axis
        where nullif(axis->>'fieldKey', '') is not null;
    end if;
    if p_product_id is null then
        v_primary_category_id := nullif(p_payload->>'primaryCategoryId', '')::bigint;
        v_metadata := coalesce(p_payload->'metadata', '{}'::jsonb);
        perform commerce.assert_product_custom_fields_with_axes(
            v_primary_category_id, v_metadata, 'admin', coalesce(v_axis_field_keys, '[]'::jsonb)
        );
        insert into commerce.products (slug, title, description, brand_id, status, visibility, metadata)
        values (
            lower(btrim(p_payload->>'slug')),
            btrim(p_payload->>'title'),
            nullif(btrim(p_payload->>'description'), ''),
            nullif(p_payload->>'brandId', '')::bigint,
            coalesce(nullif(p_payload->>'status', ''), 'draft'),
            coalesce(nullif(p_payload->>'visibility', ''), 'public'),
            v_metadata
        ) returning * into v_product;
        if v_primary_category_id is not null then
            insert into commerce.product_categories (product_id, category_id, is_primary)
            values (v_product.id, v_primary_category_id, true);
        end if;
        if p_payload ? 'variantAxes' then
            perform commerce.sync_product_variant_matrix(
                v_product.id, p_payload->'variantAxes', p_payload->'variantMatrix'
            );
        end if;
    else
        if p_expected_version is null then raise exception 'validation: expected product version is required'; end if;
        select * into v_product from commerce.products where id = p_product_id for update;
        if not found then raise exception 'not_found: product'; end if;
        if v_product.version is distinct from p_expected_version then
            raise exception 'conflict: stale product version';
        end if;
        select category_id into v_primary_category_id
        from commerce.product_categories where product_id = p_product_id and is_primary;
        if p_payload ? 'primaryCategoryId' then
            v_primary_category_id := nullif(p_payload->>'primaryCategoryId', '')::bigint;
        end if;
        if not (p_payload ? 'variantAxes') then
            select coalesce(jsonb_agg(field_key), '[]'::jsonb) into v_axis_field_keys
            from commerce.product_variant_axes
            where product_id = p_product_id and field_key is not null;
        end if;
        perform id from commerce.product_variants
        where product_id = v_product.id
        order by id
        for update;
        perform id from commerce.offers
        where product_id = v_product.id
        order by id
        for update;
        if p_payload ? 'metadata' then
            v_metadata_patch := p_payload->'metadata';
            perform commerce.assert_custom_field_patch('product', v_metadata_patch, 'admin');
            v_metadata := coalesce(v_metadata_patch, '{}'::jsonb);
        else
            v_metadata := v_product.metadata;
        end if;
        perform commerce.assert_product_custom_fields_with_axes(
            v_primary_category_id, v_metadata, 'system', coalesce(v_axis_field_keys, '[]'::jsonb)
        );
        update commerce.products
        set slug = coalesce(nullif(lower(btrim(p_payload->>'slug')), ''), slug),
            title = coalesce(nullif(btrim(p_payload->>'title'), ''), title),
            description = case when p_payload ? 'description' then nullif(btrim(p_payload->>'description'), '') else description end,
            brand_id = case when p_payload ? 'brandId' then nullif(p_payload->>'brandId', '')::bigint else brand_id end,
            status = coalesce(nullif(p_payload->>'status', ''), status),
            visibility = coalesce(nullif(p_payload->>'visibility', ''), visibility),
            metadata = case when p_payload ? 'metadata' then v_metadata else metadata end
        where id = p_product_id
        returning * into v_product;
        if p_payload ? 'primaryCategoryId' then
            delete from commerce.product_categories where product_id = v_product.id and is_primary;
            if v_primary_category_id is not null then
                insert into commerce.product_categories (product_id, category_id, is_primary)
                values (v_product.id, v_primary_category_id, true)
                on conflict (product_id, category_id) do update set is_primary = true;
            end if;
        end if;
        if p_payload ? 'variantAxes' then
            perform commerce.sync_product_variant_matrix(
                v_product.id, p_payload->'variantAxes', p_payload->'variantMatrix'
            );
        end if;
        if v_product.status <> 'active' or v_product.visibility <> 'public' then
            update commerce.offers
            set publication_status = 'paused'
            where product_id = v_product.id and publication_status = 'active';
        end if;
    end if;
    return to_jsonb(v_product);
end;
$$;

drop function if exists commerce.product_read_bundle(bigint, boolean);

create or replace function commerce.product_read_bundle(
    p_product_id bigint,
    p_slug text default null,
    p_include_public_metadata_keys boolean default false,
    p_require_public boolean default false
)
returns jsonb
language sql
volatile
security invoker
set search_path = ''
as $$
    select jsonb_build_object(
        'product', jsonb_build_object(
            'id', product.id,
            'slug', product.slug,
            'title', product.title,
            'description', product.description,
            'brand_id', product.brand_id,
            'status', product.status,
            'visibility', product.visibility,
            'metadata', product.metadata,
            'version', product.version,
            'created_at', product.created_at,
            'updated_at', product.updated_at
        ),
        'public_metadata_keys', case when p_include_public_metadata_keys then coalesce((
            select jsonb_agg(definition.key order by definition.key)
            from commerce.custom_field_definitions definition
            where definition.entity_type = 'product'
              and definition.public_readable
              and definition.enabled
        ), '[]'::jsonb) else '[]'::jsonb end,
        'axes', coalesce((
            select jsonb_agg(to_jsonb(axis_row) order by axis_row.position, axis_row.id)
            from (
                select axis.id, axis.key, axis.field_key, axis.label, axis.position
                from commerce.product_variant_axes axis
                where axis.product_id = product.id
            ) axis_row
        ), '[]'::jsonb),
        'values', coalesce((
            select jsonb_agg(to_jsonb(value_row) order by value_row.position, value_row.id)
            from (
                select axis_value.id, axis_value.axis_id, axis_value.key,
                       axis_value.label, axis_value.value, axis_value.position
                from commerce.product_variant_axis_values axis_value
                where axis_value.product_id = product.id
            ) value_row
        ), '[]'::jsonb),
        'variants', coalesce((
            select jsonb_agg(to_jsonb(variant_row) order by variant_row.position, variant_row.id)
            from (
                select variant.id, variant.product_id, variant.sku, variant.title,
                       variant.status, variant.position, variant.combination_key,
                       variant.generated_from_axes, variant.metadata, variant.version,
                       variant.created_at, variant.updated_at
                from commerce.product_variants variant
                where variant.product_id = product.id
            ) variant_row
        ), '[]'::jsonb),
        'selections', coalesce((
            select jsonb_agg(to_jsonb(selection_row))
            from (
                select selection.variant_id, selection.axis_id, selection.value_id
                from commerce.product_variant_selections selection
                where selection.product_id = product.id
            ) selection_row
        ), '[]'::jsonb),
        'media', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', link.id,
                'media_id', link.media_id,
                'sort_order', link.sort_order,
                'is_main', link.is_main,
                'media', case when stored.id is null then null else jsonb_build_object(
                    'id', stored.id,
                    'storage_bucket', stored.storage_bucket,
                    'storage_path', stored.storage_path,
                    'mime_type', stored.mime_type,
                    'file_size', stored.file_size,
                    'original_filename', stored.original_filename,
                    'alt', stored.alt,
                    'created_at', stored.created_at,
                    'updated_at', stored.updated_at
                ) end
            ) order by link.sort_order, link.id)
            from commerce.product_media link
            left join commerce.media stored on stored.id = link.media_id
            where link.product_id = product.id
        ), '[]'::jsonb),
        'brand', case when product.brand_id is null or product.brand_id = 0 then null else (
            select jsonb_build_object(
                'id', brand.id,
                'slug', brand.slug,
                'name', brand.name,
                'status', brand.status
            )
            from commerce.brands brand
            where brand.id = product.brand_id
            limit 1
        ) end,
        'categories', coalesce((
            select jsonb_agg(jsonb_build_object(
                'product_id', link.product_id,
                'category_id', link.category_id,
                'is_primary', link.is_primary,
                'position', link.position,
                'category', case when category.id is null then null else jsonb_build_object(
                    'id', category.id,
                    'parent_id', category.parent_id,
                    'slug', category.slug,
                    'full_slug', category.full_slug,
                    'label', category.label,
                    'status', category.status,
                    'position', category.position
                ) end
            ) order by link.is_primary desc, link.position, link.category_id)
            from commerce.product_categories link
            left join commerce.categories category on category.id = link.category_id
            where link.product_id = product.id
        ), '[]'::jsonb)
    )
    from commerce.products product
    where ((p_product_id is not null and product.id = p_product_id)
        or (p_product_id is null and p_slug is not null and product.slug = p_slug))
      and (not p_require_public
        or (product.status = 'active' and product.visibility = 'public'))
    limit 1;
$$;

create or replace function commerce.get_product_read_model(
    p_scope text,
    p_product_id bigint default null,
    p_slug text default null
)
returns jsonb
language sql
volatile
security invoker
set search_path = ''
as $$
    select case
        when p_scope is null or p_scope not in ('public', 'admin')
            then jsonb_build_object('state', 'invalid_scope')
        else coalesce(
            jsonb_build_object('state', 'ok') || commerce.product_read_bundle(
                p_product_id,
                p_slug,
                p_scope = 'public',
                p_scope = 'public'
            ),
            jsonb_build_object('state', 'not_found')
        )
    end;
$$;

create or replace function commerce.upsert_product_read_model(
    p_product_id bigint,
    p_payload jsonb,
    p_expected_version integer default null
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
    v_product jsonb;
    v_bundle jsonb;
begin
    v_product := commerce.upsert_product(p_product_id, p_payload, p_expected_version);
    v_bundle := commerce.product_read_bundle((v_product->>'id')::bigint, null, false, false);
    if v_bundle is null then
        raise exception 'not_found: product';
    end if;
    return jsonb_build_object('state', 'ok') || v_bundle;
end;
$$;

revoke execute on function commerce.product_read_bundle(bigint, text, boolean, boolean)
    from public, anon, authenticated;
revoke execute on function commerce.get_product_read_model(text, bigint, text)
    from public, anon, authenticated;
revoke execute on function commerce.upsert_product_read_model(bigint, jsonb, integer)
    from public, anon, authenticated;
grant execute on function commerce.product_read_bundle(bigint, text, boolean, boolean)
    to service_role;
grant execute on function commerce.get_product_read_model(text, bigint, text) to service_role;
grant execute on function commerce.upsert_product_read_model(bigint, jsonb, integer)
    to service_role;

create or replace function commerce.upsert_brand(
    p_brand_id bigint,
    p_payload jsonb,
    p_expected_version integer default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_brand commerce.brands%rowtype;
begin
    if p_brand_id is null then
        insert into commerce.brands (slug, name, description, status, metadata)
        values (
            lower(btrim(p_payload->>'slug')),
            btrim(p_payload->>'name'),
            nullif(btrim(p_payload->>'description'), ''),
            coalesce(nullif(p_payload->>'status', ''), 'active'),
            coalesce(p_payload->'metadata', '{}'::jsonb)
        ) returning * into v_brand;
    else
        if p_expected_version is null then raise exception 'validation: expected brand version is required'; end if;
        select * into v_brand from commerce.brands where id = p_brand_id for update;
        if not found then raise exception 'not_found: brand'; end if;
        if v_brand.version is distinct from p_expected_version then raise exception 'conflict: stale brand version'; end if;
        update commerce.brands
        set slug = coalesce(nullif(lower(btrim(p_payload->>'slug')), ''), slug),
            name = coalesce(nullif(btrim(p_payload->>'name'), ''), name),
            description = case when p_payload ? 'description' then nullif(btrim(p_payload->>'description'), '') else description end,
            status = coalesce(nullif(p_payload->>'status', ''), status),
            metadata = case when p_payload ? 'metadata' then p_payload->'metadata' else metadata end
        where id = p_brand_id
        returning * into v_brand;
    end if;
    return to_jsonb(v_brand);
end;
$$;

create or replace function commerce.delete_brand(p_brand_id bigint)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_brand commerce.brands%rowtype;
begin
    select * into v_brand from commerce.brands where id = p_brand_id for update;
    if not found then raise exception 'not_found: brand not found'; end if;
    if exists (select 1 from commerce.products where brand_id = p_brand_id) then
        raise exception 'conflict: brand is used by at least one product';
    end if;
    delete from commerce.brands where id = p_brand_id;
    return jsonb_build_object('id', p_brand_id, 'deleted', true);
end;
$$;

create or replace function commerce.upsert_category(
    p_category_id bigint,
    p_payload jsonb,
    p_expected_version integer default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_category commerce.categories%rowtype;
    v_parent_id bigint := nullif(p_payload->>'parentId', '')::bigint;
begin
    if p_category_id is not null and v_parent_id is not null and exists (
        with recursive descendants as (
            select id from commerce.categories where parent_id = p_category_id
            union all
            select child.id from commerce.categories child join descendants parent on child.parent_id = parent.id
        )
        select 1 from descendants where id = v_parent_id
    ) then raise exception 'validation: category parent cannot be a descendant'; end if;

    if p_category_id is null then
        insert into commerce.categories (parent_id, slug, full_slug, label, description, status, position, metadata)
        values (
            v_parent_id,
            lower(btrim(p_payload->>'slug')),
            lower(btrim(p_payload->>'slug')),
            btrim(p_payload->>'label'),
            nullif(btrim(p_payload->>'description'), ''),
            coalesce(nullif(p_payload->>'status', ''), 'active'),
            coalesce(nullif(p_payload->>'position', '')::integer, 0),
            coalesce(p_payload->'metadata', '{}'::jsonb)
        ) returning * into v_category;
    else
        if p_expected_version is null then raise exception 'validation: expected category version is required'; end if;
        select * into v_category from commerce.categories where id = p_category_id for update;
        if not found then raise exception 'not_found: category'; end if;
        if v_category.version is distinct from p_expected_version then raise exception 'conflict: stale category version'; end if;
        update commerce.categories
        set parent_id = case when p_payload ? 'parentId' then v_parent_id else parent_id end,
            slug = coalesce(nullif(lower(btrim(p_payload->>'slug')), ''), slug),
            label = coalesce(nullif(btrim(p_payload->>'label'), ''), label),
            description = case when p_payload ? 'description' then nullif(btrim(p_payload->>'description'), '') else description end,
            status = coalesce(nullif(p_payload->>'status', ''), status),
            position = case when p_payload ? 'position' then coalesce(nullif(p_payload->>'position', '')::integer, 0) else position end,
            metadata = case when p_payload ? 'metadata' then p_payload->'metadata' else metadata end
        where id = p_category_id
        returning * into v_category;
    end if;
    return to_jsonb(v_category);
end;
$$;

create or replace function commerce.get_category_read_model(
    p_scope text,
    p_category_id bigint default null,
    p_full_slug text default null
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    select case
        when p_scope is null or p_scope not in ('public', 'admin')
            then jsonb_build_object('state', 'invalid_scope')
        else coalesce((
            select jsonb_build_object(
                'state', 'ok',
                'category', jsonb_build_object(
                    'id', category.id,
                    'parent_id', category.parent_id,
                    'slug', category.slug,
                    'full_slug', category.full_slug,
                    'label', category.label,
                    'description', category.description,
                    'status', category.status,
                    'position', category.position,
                    'metadata', category.metadata,
                    'version', category.version,
                    'created_at', category.created_at,
                    'updated_at', category.updated_at
                ),
                'parent', case
                    when category.parent_id is null or category.parent_id = 0 or parent.id is null
                        then null
                    else jsonb_build_object(
                        'id', parent.id,
                        'slug', parent.slug,
                        'full_slug', parent.full_slug,
                        'label', parent.label,
                        'status', parent.status
                    )
                end,
                'category_fields', case when p_scope = 'admin' then coalesce((
                    select jsonb_agg(jsonb_build_object(
                        'category_id', field.category_id,
                        'field_key', field.field_key,
                        'required', field.required,
                        'filterable', field.filterable,
                        'position', field.position,
                        'definition', case when definition.key is null then null else jsonb_build_object(
                            'label', definition.label,
                            'field_type', definition.field_type,
                            'options', definition.options,
                            'unit', definition.unit,
                            'public_readable', definition.public_readable,
                            'enabled', definition.enabled
                        ) end
                    ) order by field.position, field.field_key)
                    from commerce.category_custom_fields field
                    left join commerce.custom_field_definitions definition
                      on definition.entity_type = field.entity_type
                     and definition.key = field.field_key
                    where field.category_id = category.id
                ), '[]'::jsonb) else '[]'::jsonb end
            )
            from commerce.categories category
            left join commerce.categories parent
              on category.parent_id <> 0 and parent.id = category.parent_id
            where ((p_category_id is not null and category.id = p_category_id)
                or (p_category_id is null and p_full_slug is not null
                    and category.full_slug = p_full_slug))
              and (p_scope = 'admin' or category.status = 'active')
            limit 1
        ), jsonb_build_object('state', 'not_found'))
    end;
$$;

revoke execute on function commerce.get_category_read_model(text, bigint, text)
    from public, anon, authenticated;
grant execute on function commerce.get_category_read_model(text, bigint, text)
    to service_role;

create or replace function commerce.delete_category(p_category_id bigint)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_category commerce.categories%rowtype;
begin
    select * into v_category from commerce.categories where id = p_category_id for update;
    if not found then raise exception 'not_found: category not found'; end if;
    if exists (select 1 from commerce.categories where parent_id = p_category_id) then
        raise exception 'conflict: category has child categories';
    end if;
    if exists (
        select 1 from commerce.product_categories where category_id = p_category_id
    ) then raise exception 'conflict: category is used by at least one product'; end if;
    delete from commerce.categories where id = p_category_id;
    return jsonb_build_object('id', p_category_id, 'deleted', true);
end;
$$;

create or replace function commerce.reorder_brands(p_ids jsonb)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_count integer;
begin
    if jsonb_typeof(p_ids) <> 'array' then raise exception 'validation: ids must be an array'; end if;
    if jsonb_array_length(p_ids) > 200 then raise exception 'validation: too many brand ids'; end if;
    with ordered as (
        select value::bigint id, ordinality::integer - 1 position
        from jsonb_array_elements_text(p_ids) with ordinality
    ), updated as (
        update commerce.brands brand set position = ordered.position
        from ordered where brand.id = ordered.id returning brand.id
    ) select count(*) into v_count from updated;
    if v_count <> jsonb_array_length(p_ids) then raise exception 'validation: unknown or duplicate brand id'; end if;
    return jsonb_build_object('ids', p_ids);
end;
$$;

create or replace function commerce.reorder_categories(p_ids jsonb)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_count integer;
begin
    if jsonb_typeof(p_ids) <> 'array' then raise exception 'validation: ids must be an array'; end if;
    if jsonb_array_length(p_ids) > 200 then raise exception 'validation: too many category ids'; end if;
    with ordered as (
        select value::bigint id, ordinality::integer - 1 position
        from jsonb_array_elements_text(p_ids) with ordinality
    ), updated as (
        update commerce.categories category set position = ordered.position
        from ordered where category.id = ordered.id returning category.id
    ) select count(*) into v_count from updated;
    if v_count <> jsonb_array_length(p_ids) then raise exception 'validation: unknown or duplicate category id'; end if;
    return jsonb_build_object('ids', p_ids);
end;
$$;

create or replace function commerce.upsert_category_custom_field(
    p_category_id bigint,
    p_field_key text,
    p_required boolean default false,
    p_filterable boolean default false,
    p_position integer default 0,
    p_unit text default null,
    p_operators jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_definition commerce.custom_field_definitions%rowtype;
    v_field commerce.category_custom_fields%rowtype;
begin
    select * into v_definition from commerce.custom_field_definitions
    where entity_type = 'product' and key = p_field_key and enabled;
    if not found then raise exception 'validation: enabled Product custom field does not exist'; end if;
    if not exists (select 1 from commerce.categories where id = p_category_id) then
        raise exception 'validation: category does not exist';
    end if;
    if jsonb_typeof(coalesce(p_operators, '[]'::jsonb)) <> 'array' then
        raise exception 'validation: filter operators must be an array';
    end if;
    if exists (
        select 1 from jsonb_array_elements_text(coalesce(p_operators, '[]'::jsonb)) operator
        where operator not in ('eq', 'in', 'gte', 'lte')
           or (v_definition.field_type <> 'number' and operator in ('gte', 'lte'))
           or (v_definition.field_type not in ('enum', 'string') and operator = 'in')
    ) then raise exception 'validation: unsupported filter operator for custom field'; end if;

    insert into commerce.category_custom_fields (
        category_id, entity_type, field_key, required, filterable, position, unit, operators
    ) values (
        p_category_id, 'product', p_field_key, coalesce(p_required, false), coalesce(p_filterable, false),
        coalesce(p_position, 0), null, '[]'::jsonb
    ) on conflict (category_id, field_key) do update
    set required = excluded.required,
        filterable = excluded.filterable,
        position = excluded.position,
        unit = null,
        operators = '[]'::jsonb
    returning * into v_field;
    return to_jsonb(v_field);
end;
$$;

create or replace function commerce.sync_category_custom_fields(
    p_category_id bigint,
    p_fields jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_field jsonb;
begin
    if jsonb_typeof(coalesce(p_fields, '[]'::jsonb)) <> 'array' then
        raise exception 'validation: category fields must be an array';
    end if;
    if jsonb_array_length(coalesce(p_fields, '[]'::jsonb)) > 100 then
        raise exception 'validation: too many category fields';
    end if;
    if (select count(*) from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)))
       <> (select count(distinct field->>'fieldKey') from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) field) then
        raise exception 'validation: category field keys must be unique';
    end if;
    for v_field in select value from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) loop
        perform commerce.upsert_category_custom_field(
            p_category_id,
            v_field->>'fieldKey',
            coalesce((v_field->>'required')::boolean, false),
            coalesce((v_field->>'filterable')::boolean, false),
            coalesce(nullif(v_field->>'position', '')::integer, 0),
            null,
            '[]'::jsonb
        );
    end loop;
    delete from commerce.category_custom_fields existing
    where existing.category_id = p_category_id
      and not exists (
          select 1 from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) field
          where field->>'fieldKey' = existing.field_key
      );
    return commerce.category_custom_field_schema(p_category_id);
end;
$$;

create or replace function commerce.category_custom_field_schema(p_category_id bigint)
returns jsonb
language sql
stable
set search_path = ''
as $$
    with recursive ancestry as (
        select id, parent_id, 0 depth from commerce.categories where id = p_category_id
        union all
        select parent.id, parent.parent_id, child.depth + 1
        from commerce.categories parent join ancestry child on child.parent_id = parent.id
    ), resolved as (
        select distinct on (field.field_key)
            field.*, definition.label, definition.field_type, definition.options,
            definition.admin_editable, definition.public_readable, definition.unit definition_unit,
            definition.show_in_dashboard_table, ancestry.depth
        from ancestry
        join commerce.category_custom_fields field on field.category_id = ancestry.id
        join commerce.custom_field_definitions definition
          on definition.entity_type = field.entity_type and definition.key = field.field_key
        where definition.enabled
        order by field.field_key, ancestry.depth asc
    )
    select jsonb_build_object('fields', coalesce(jsonb_agg(jsonb_build_object(
        'id', field_key, 'fieldKey', field_key, 'label', label,
        'type', case when field_type = 'enum' then 'string' else field_type end,
        'fieldType', field_type, 'path', 'metadata.' || field_key,
        'section', 'categoryMetadata', 'options', case when field_type = 'enum' then (
            select coalesce(jsonb_agg(jsonb_build_object('value', value, 'label', value)), '[]'::jsonb)
            from jsonb_array_elements_text(options) value
        ) else '[]'::jsonb end,
        'required', required, 'adminEditable', admin_editable,
        'selfEditable', false, 'exposeToEditorSources', public_readable,
        'showInDashboardTable', show_in_dashboard_table,
        'filterable', filterable, 'position', position, 'unit', definition_unit,
        'operators', case field_type
            when 'number' then '["eq","gte","lte"]'::jsonb
            when 'boolean' then '["eq"]'::jsonb
            else '["eq","in"]'::jsonb
        end, 'inherited', category_id <> p_category_id,
        'definedByCategoryId', category_id
    ) order by position, field_key), '[]'::jsonb)) from resolved;
$$;

create or replace function commerce.offer_filter_schema(p_category_full_slug text)
returns jsonb
language sql
stable
set search_path = ''
as $$
    with recursive selected as (
        select * from commerce.categories
        where full_slug = p_category_full_slug and status = 'active'
    ), ancestry as (
        select id, parent_id, 0 depth from selected
        union all
        select parent.id, parent.parent_id, child.depth + 1
        from commerce.categories parent join ancestry child on child.parent_id = parent.id
    ), resolved as (
        select distinct on (field.field_key)
            field.field_key, field.required, field.filterable, field.position,
            definition.unit, definition.label, definition.field_type,
            definition.options, definition.public_readable, ancestry.depth
        from ancestry
        join commerce.category_custom_fields field on field.category_id = ancestry.id
        join commerce.custom_field_definitions definition
          on definition.entity_type = field.entity_type and definition.key = field.field_key
        where definition.enabled
          and definition.public_readable
        order by field.field_key, ancestry.depth asc
    )
    select case when not exists (select 1 from selected) then null else jsonb_build_object(
        'category', (select jsonb_build_object(
            'id', id, 'parentId', parent_id, 'slug', slug, 'fullSlug', full_slug, 'label', label
        ) from selected),
        'fields', coalesce((select jsonb_agg(jsonb_build_object(
            'key', field_key, 'label', label, 'type', field_type, 'options', options,
            'required', required, 'filterable', filterable, 'position', position,
            'unit', unit, 'operators', case field_type
                when 'number' then '["eq","gte","lte"]'::jsonb
                when 'boolean' then '["eq"]'::jsonb
                else '["eq","in"]'::jsonb
            end
        ) order by position, field_key) from resolved), '[]'::jsonb)
    ) end;
$$;

create or replace function commerce.get_offer_filter_schema_read_model(
    p_category_full_slug text
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with filter_schema as materialized (
        select commerce.offer_filter_schema(p_category_full_slug) value
    )
    select case when filter_schema.value is null then null else
        filter_schema.value || jsonb_build_object(
            'brands', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', brand.id,
                    'slug', brand.slug,
                    'name', brand.name
                ) order by brand.name, brand.id)
                from (
                    select listed.id, listed.slug, listed.name
                    from commerce.brands listed
                    where listed.status = 'active'
                    order by listed.name, listed.id
                    limit 200
                ) brand
            ), '[]'::jsonb)
        )
    end
    from filter_schema;
$$;

revoke execute on function commerce.get_offer_filter_schema_read_model(text)
    from public, anon, authenticated;
grant execute on function commerce.get_offer_filter_schema_read_model(text)
    to service_role;

create or replace function commerce.public_metadata_subset(
    p_metadata jsonb,
    p_keys text[]
)
returns jsonb
language sql
immutable
security invoker
set search_path = ''
as $$
    select coalesce(jsonb_object_agg(entry.key, entry.value), '{}'::jsonb)
    from jsonb_each(coalesce(p_metadata, '{}'::jsonb)) entry
    where entry.key = any(coalesce(p_keys, array[]::text[]));
$$;

create or replace function commerce.public_offer_items_read_model(
    p_offer_ids bigint[],
    p_include_inventory_revision boolean default false
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with requested as materialized (
        select requested.id, requested.ordinality
        from unnest(coalesce(p_offer_ids, array[]::bigint[]))
            with ordinality as requested(id, ordinality)
    ), offer_keys as materialized (
        select coalesce(array_agg(definition.key order by definition.key), array[]::text[]) keys
        from commerce.custom_field_definitions definition
        where definition.entity_type = 'offer'
          and definition.public_readable
          and definition.enabled
    ), product_keys as materialized (
        select coalesce(array_agg(definition.key order by definition.key), array[]::text[]) keys
        from commerce.custom_field_definitions definition
        where definition.entity_type = 'product'
          and definition.public_readable
          and definition.enabled
    ), page as materialized (
        select offer.*, requested.ordinality as read_ordinal
        from requested
        join commerce.offers offer on offer.id = requested.id
    ), page_variants as (
        select distinct page.product_id, page.variant_id
        from page
        where page.variant_id is not null
    ), axis_metadata as (
        select selection.variant_id,
               jsonb_object_agg(axis.field_key, axis_value.value order by selection.axis_id) metadata
        from page_variants page_variant
        join commerce.product_variant_selections selection
          on selection.product_id = page_variant.product_id
         and selection.variant_id = page_variant.variant_id
        join commerce.product_variant_axes axis
          on axis.product_id = selection.product_id
         and axis.id = selection.axis_id
        join commerce.product_variant_axis_values axis_value
          on axis_value.product_id = selection.product_id
         and axis_value.axis_id = selection.axis_id
         and axis_value.id = selection.value_id
        cross join product_keys
        where axis.field_key is not null
          and axis.field_key = any(product_keys.keys)
        group by selection.variant_id
    ), media_rollup as (
        select link.offer_id,
               jsonb_agg(jsonb_build_object(
                   'id', link.id,
                   'offer_id', link.offer_id,
                   'media_id', link.media_id,
                   'sort_order', link.sort_order,
                   'is_main', link.is_main,
                   'media', jsonb_build_object(
                       'id', media.id,
                       'storage_bucket', media.storage_bucket,
                       'storage_path', media.storage_path,
                       'mime_type', media.mime_type,
                       'file_size', media.file_size,
                       'original_filename', media.original_filename,
                       'alt', media.alt,
                       'created_at', media.created_at,
                       'updated_at', media.updated_at,
                       'url', ''
                   )
               ) order by link.sort_order, link.id) media,
               (array_agg(link.media_id order by link.is_main desc, link.sort_order, link.id))[1]::text
                   main_image_media_id
        from page
        join commerce.offer_media link on link.offer_id = page.id
        join commerce.media media on media.id = link.media_id
        group by link.offer_id
    ), items as (
        select page.read_ordinal,
               (case when p_include_inventory_revision
                   then to_jsonb(page) - 'read_ordinal' - 'seller_id'
                   else to_jsonb(page) - 'read_ordinal' - 'seller_id' - 'inventory_revision'
               end) || jsonb_build_object(
                   'metadata', commerce.public_metadata_subset(page.metadata, offer_keys.keys),
                   'product', case when product.id is null then null else jsonb_build_object(
                       'id', product.id,
                       'slug', product.slug,
                       'title', product.title,
                       'brand_id', product.brand_id,
                       'status', product.status,
                       'visibility', product.visibility,
                       'metadata', effective_metadata.value,
                       'brand', case when brand.id is null then null else jsonb_build_object(
                           'id', brand.id,
                           'slug', brand.slug,
                           'name', brand.name,
                           'status', brand.status
                       ) end,
                       'primary_category_id', primary_link.category_id,
                       'primary_category', case when category.id is null then null else jsonb_build_object(
                           'id', category.id,
                           'parent_id', category.parent_id,
                           'slug', category.slug,
                           'full_slug', category.full_slug,
                           'label', category.label,
                           'status', category.status,
                           'position', category.position
                       ) end,
                       'effective_metadata', effective_metadata.value
                   ) end,
                   'variant', case when variant.id is null then null else jsonb_build_object(
                       'id', variant.id,
                       'product_id', variant.product_id,
                       'sku', variant.sku,
                       'title', variant.title,
                       'status', variant.status,
                       'metadata', commerce.public_metadata_subset(variant.metadata, product_keys.keys),
                       'effective_metadata', effective_metadata.value
                   ) end,
                   'media', coalesce(media_rollup.media, '[]'::jsonb),
                   'main_image_media_id', media_rollup.main_image_media_id
               ) value
        from page
        cross join offer_keys
        cross join product_keys
        left join commerce.products product on product.id = page.product_id
        left join commerce.product_variants variant
          on variant.product_id = page.product_id
         and variant.id = page.variant_id
        left join axis_metadata on axis_metadata.variant_id = variant.id
        left join commerce.brands brand on brand.id = product.brand_id
        left join commerce.product_categories primary_link
          on primary_link.product_id = product.id
         and primary_link.is_primary
        left join commerce.categories category on category.id = primary_link.category_id
        left join media_rollup on media_rollup.offer_id = page.id
        cross join lateral (
            select commerce.public_metadata_subset(product.metadata, product_keys.keys)
                || commerce.public_metadata_subset(variant.metadata, product_keys.keys)
                || coalesce(axis_metadata.metadata, '{}'::jsonb) value
        ) effective_metadata
    )
    select coalesce(jsonb_agg(items.value order by items.read_ordinal), '[]'::jsonb)
    from items;
$$;

create or replace function commerce.list_public_offers_read_model(
    p_workflow_state text default null,
    p_condition_code text default null,
    p_product_id text default null,
    p_variant_id text default null,
    p_seller_id text default null,
    p_price_min bigint default null,
    p_price_max bigint default null,
    p_query text default null,
    p_sort text default null,
    p_limit integer default 50,
    p_offset integer default 0
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with settings_state as materialized (
        select settings.require_verified_seller
        from commerce.settings settings
        where settings.id = 'default'
    ), filtered as materialized (
        select offer.id, offer.accepted_price_amount, offer.updated_at
        from commerce.offers offer
        join commerce.sellers seller on seller.id = offer.seller_id
        cross join settings_state settings
        where offer.publication_status = 'active'
          and offer.availability = 'available'
          and seller.verification_status in ('pending', 'verified')
          and (not settings.require_verified_seller or seller.verification_status = 'verified')
          and (p_workflow_state is null or offer.workflow_state = p_workflow_state)
          and (p_condition_code is null or offer.condition_code = p_condition_code)
          and (p_product_id is null or offer.product_id = p_product_id::bigint)
          and (p_variant_id is null or offer.variant_id = p_variant_id::bigint)
          and (p_seller_id is null or offer.seller_id = p_seller_id::bigint)
          and (p_price_min is null or offer.accepted_price_amount >= p_price_min)
          and (p_price_max is null or offer.accepted_price_amount <= p_price_max)
          and (p_query is null or offer.title ilike '%' || p_query || '%'
               or offer.slug ilike '%' || p_query || '%')
    ), page_ids as materialized (
        select filtered.*
        from filtered
        order by
            case when p_sort = 'price-asc' then filtered.accepted_price_amount end asc nulls last,
            case when p_sort = 'price-desc' then filtered.accepted_price_amount end desc nulls last,
            filtered.updated_at desc,
            filtered.id desc
        limit least(greatest(coalesce(p_limit, 50), 1), 100)
        offset greatest(coalesce(p_offset, 0), 0)
    )
    select jsonb_build_object(
        'settings_available', (select count(*) = 1 from settings_state),
        'items', commerce.public_offer_items_read_model(coalesce((select array_agg(page_ids.id order by
            case when p_sort = 'price-asc' then page_ids.accepted_price_amount end asc nulls last,
            case when p_sort = 'price-desc' then page_ids.accepted_price_amount end desc nulls last,
            page_ids.updated_at desc,
            page_ids.id desc
        ) from page_ids), array[]::bigint[])),
        'total', (select count(*) from filtered)
    );
$$;

create or replace function commerce.list_seller_offers_read_model(
    p_cms_user_id text,
    p_status text default null,
    p_publication_status text default null,
    p_workflow_state text default null,
    p_condition_code text default null,
    p_product_id text default null,
    p_variant_id text default null,
    p_query text default null,
    p_limit integer default 50,
    p_offset bigint default 0
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
    v_seller_id bigint;
    v_status text := coalesce(p_status, 'all');
    v_product_id bigint;
    v_variant_id bigint;
    v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
    v_offset bigint := greatest(coalesce(p_offset, 0), 0);
    v_workflow_states jsonb := '[]'::jsonb;
    v_archived_codes text[] := array[]::text[];
    v_rejected_codes text[] := array[]::text[];
    v_action_required_codes text[] := array[]::text[];
    v_under_review_codes text[] := array[]::text[];
    v_draft_codes text[] := array[]::text[];
    v_status_codes text[] := array[]::text[];
    v_result jsonb;
begin
    if nullif(btrim(p_cms_user_id), '') is null then
        raise exception 'forbidden: CMS user id is required' using errcode = '42501';
    end if;

    select seller.id
    into v_seller_id
    from commerce.sellers seller
    where seller.cms_user_id = p_cms_user_id
    limit 1;

    if v_seller_id is null then
        return jsonb_build_object(
            'seller_exists', false,
            'status_valid', true,
            'rows', '[]'::jsonb,
            'total', 0,
            'workflow_states', '[]'::jsonb,
            'media', '[]'::jsonb,
            'active_price_proposals', '[]'::jsonb
        );
    end if;

    select
        coalesce(jsonb_agg(jsonb_build_object(
            'code', state.code,
            'label', state.label,
            'phase', state.phase,
            'terminal', state.terminal
        ) order by state.position, state.code), '[]'::jsonb),
        coalesce(array_agg(state.code order by state.position, state.code)
            filter (where state.code = 'archived'), array[]::text[]),
        coalesce(array_agg(state.code order by state.position, state.code)
            filter (where state.terminal and state.code <> 'archived'), array[]::text[]),
        coalesce(array_agg(state.code order by state.position, state.code)
            filter (where state.phase = 'seller_input'), array[]::text[]),
        coalesce(array_agg(state.code order by state.position, state.code)
            filter (where state.phase = 'admin_review'), array[]::text[]),
        coalesce(array_agg(state.code order by state.position, state.code)
            filter (where state.phase in ('draft', 'ready')), array[]::text[])
    into
        v_workflow_states,
        v_archived_codes,
        v_rejected_codes,
        v_action_required_codes,
        v_under_review_codes,
        v_draft_codes
    from commerce.offer_workflow_states state;

    if v_status not in (
        'all', 'online', 'paused', 'archived', 'rejected',
        'action_required', 'under_review', 'draft'
    ) then
        return jsonb_build_object(
            'seller_exists', true,
            'status_valid', false,
            'rows', '[]'::jsonb,
            'total', 0,
            'workflow_states', v_workflow_states,
            'media', '[]'::jsonb,
            'active_price_proposals', '[]'::jsonb
        );
    end if;

    if p_product_id is not null then
        v_product_id := p_product_id::bigint;
    end if;
    if p_variant_id is not null then
        v_variant_id := p_variant_id::bigint;
    end if;

    v_status_codes := case v_status
        when 'rejected' then v_rejected_codes
        when 'action_required' then v_action_required_codes
        when 'under_review' then v_under_review_codes
        when 'draft' then v_draft_codes
        else array[]::text[]
    end;

    with filtered as materialized (
        select offer.id, offer.updated_at
        from commerce.offers offer
        where offer.seller_id = v_seller_id
          and case v_status
              when 'online' then offer.publication_status = 'active'
              when 'paused' then offer.publication_status = 'paused'
              else p_publication_status is null
                or offer.publication_status = p_publication_status
          end
          and case when v_status in ('rejected', 'action_required', 'under_review', 'draft')
              then offer.workflow_state = any(v_status_codes)
              else p_workflow_state is null or offer.workflow_state = p_workflow_state
          end
          and (
              v_status <> 'archived'
              or p_query is not null
              or offer.publication_status = 'archived'
              or offer.workflow_state = any(v_archived_codes)
          )
          and (p_condition_code is null or offer.condition_code = p_condition_code)
          and (v_product_id is null or offer.product_id = v_product_id)
          and (v_variant_id is null or offer.variant_id = v_variant_id)
          and (
              p_query is null
              or offer.title ilike '%' || p_query || '%'
              or offer.slug ilike '%' || p_query || '%'
          )
    ), page_ids as materialized (
        select filtered.id, filtered.updated_at
        from filtered
        order by filtered.updated_at desc, filtered.id desc
        limit v_limit
        offset v_offset
    )
    select jsonb_build_object(
        'seller_exists', true,
        'status_valid', true,
        'rows', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', offer.id,
                'seller_id', offer.seller_id,
                'product_id', offer.product_id,
                'variant_id', offer.variant_id,
                'slug', offer.slug,
                'title', offer.title,
                'description', offer.description,
                'condition_code', offer.condition_code,
                'publication_status', offer.publication_status,
                'workflow_state', offer.workflow_state,
                'accepted_price_amount', offer.accepted_price_amount,
                'currency', offer.currency,
                'availability', offer.availability,
                'quantity_available', offer.quantity_available,
                'metadata', offer.metadata,
                'version', offer.version,
                'created_at', offer.created_at,
                'updated_at', offer.updated_at
            ) order by page.updated_at desc, page.id desc)
            from page_ids page
            join commerce.offers offer on offer.id = page.id
        ), '[]'::jsonb),
        'total', (select count(*) from filtered),
        'workflow_states', v_workflow_states,
        'media', coalesce((
            select jsonb_agg(jsonb_build_object(
                'offer_id', media.offer_id,
                'media_id', media.media_id,
                'sort_order', media.sort_order,
                'is_main', media.is_main
            ) order by media.sort_order, media.id)
            from page_ids page
            join commerce.offer_media media on media.offer_id = page.id
        ), '[]'::jsonb),
        'active_price_proposals', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', proposal.id,
                'offer_id', proposal.offer_id,
                'amount', proposal.amount,
                'status', proposal.status,
                'created_at', proposal.created_at
            ) order by proposal.created_at desc, proposal.id desc)
            from page_ids page
            join commerce.offer_price_proposals proposal on proposal.offer_id = page.id
            where proposal.status in ('pending', 'accepted')
        ), '[]'::jsonb)
    )
    into v_result;

    return v_result;
end;
$$;

revoke execute on function commerce.list_seller_offers_read_model(
    text, text, text, text, text, text, text, text, integer, bigint
) from public, anon, authenticated;
grant execute on function commerce.list_seller_offers_read_model(
    text, text, text, text, text, text, text, text, integer, bigint
) to service_role;

create or replace function commerce.get_public_offer_read_model(
    p_offer_id bigint default null,
    p_slug text default null
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with settings_state as materialized (
        select settings.require_verified_seller
        from commerce.settings settings
        where settings.id = 'default'
    ), offer_keys as materialized (
        select coalesce(array_agg(definition.key order by definition.key), array[]::text[]) keys
        from commerce.custom_field_definitions definition
        where definition.entity_type = 'offer'
          and definition.public_readable
          and definition.enabled
    ), product_keys as materialized (
        select coalesce(array_agg(definition.key order by definition.key), array[]::text[]) keys
        from commerce.custom_field_definitions definition
        where definition.entity_type = 'product'
          and definition.public_readable
          and definition.enabled
    ), candidate_offer as materialized (
        select offer.*
        from commerce.offers offer
        where offer.publication_status = 'active'
          and ((p_offer_id is not null and offer.id = p_offer_id)
            or (p_offer_id is null and p_slug is not null and offer.slug = p_slug))
        limit 1
    ), eligible_offer as materialized (
        select offer.*
        from candidate_offer offer
        join commerce.sellers seller on seller.id = offer.seller_id
        cross join settings_state settings
        where seller.verification_status in ('pending', 'verified')
          and (not settings.require_verified_seller or seller.verification_status = 'verified')
    ), media_rollup as (
        select link.offer_id,
               jsonb_agg(jsonb_build_object(
                   'id', link.id,
                   'media_id', link.media_id,
                   'sort_order', link.sort_order,
                   'is_main', link.is_main,
                   'media', jsonb_build_object(
                       'id', media.id,
                       'storage_bucket', media.storage_bucket,
                       'storage_path', media.storage_path,
                       'mime_type', media.mime_type,
                       'file_size', media.file_size,
                       'original_filename', media.original_filename,
                       'alt', media.alt,
                       'created_at', media.created_at,
                       'updated_at', media.updated_at,
                       'url', ''
                   )
               ) order by link.sort_order, link.id) media,
               (array_agg(link.media_id order by link.is_main desc, link.sort_order, link.id))[1]::text
                   main_image_media_id
        from eligible_offer offer
        join commerce.offer_media link on link.offer_id = offer.id
        join commerce.media media on media.id = link.media_id
        group by link.offer_id
    ), item as (
        select (to_jsonb(offer) - 'seller_id' - 'inventory_revision')
               || jsonb_build_object(
                   'metadata', commerce.public_metadata_subset(offer.metadata, offer_keys.keys),
                   'product', case when product.id is null then null else jsonb_build_object(
                       'id', product.id,
                       'slug', product.slug,
                       'title', product.title,
                       'brand_id', product.brand_id,
                       'status', product.status,
                       'visibility', product.visibility,
                       'metadata', commerce.public_metadata_subset(product.metadata, product_keys.keys),
                       'brand', case when brand.id is null then null else jsonb_build_object(
                           'id', brand.id,
                           'slug', brand.slug,
                           'name', brand.name,
                           'status', brand.status
                       ) end,
                       'primary_category_id', primary_link.category_id,
                       'primary_category', case when category.id is null then null else jsonb_build_object(
                           'id', category.id,
                           'parent_id', category.parent_id,
                           'slug', category.slug,
                           'full_slug', category.full_slug,
                           'label', category.label,
                           'status', category.status,
                           'position', category.position
                       ) end
                   ) end,
                   'variant', case when variant.id is null then null else jsonb_build_object(
                       'id', variant.id,
                       'sku', variant.sku,
                       'title', variant.title,
                       'status', variant.status
                   ) end,
                   'price_rule', null,
                   'price_proposals', '[]'::jsonb,
                   'media', coalesce(media_rollup.media, '[]'::jsonb),
                   'main_image_media_id', media_rollup.main_image_media_id
               ) value
        from eligible_offer offer
        cross join offer_keys
        cross join product_keys
        left join commerce.products product on product.id = offer.product_id
        left join commerce.product_variants variant
          on variant.product_id = offer.product_id
         and variant.id = offer.variant_id
        left join commerce.brands brand on brand.id = product.brand_id
        left join commerce.product_categories primary_link
          on primary_link.product_id = product.id
         and primary_link.is_primary
        left join commerce.categories category on category.id = primary_link.category_id
        left join media_rollup on media_rollup.offer_id = offer.id
    )
    select jsonb_build_object(
        'candidate_exists', exists(select 1 from candidate_offer),
        'settings_available', (select count(*) = 1 from settings_state),
        'offer', (select item.value from item)
    );
$$;

create or replace function commerce.get_managed_offer_read_model(
    p_scope text,
    p_offer_id bigint default null,
    p_slug text default null,
    p_cms_user_id text default null
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with candidate as materialized (
        select offer.*,
               seller.id as resolved_seller_id,
               seller.cms_user_id as owner_cms_user_id,
               seller.kind as seller_kind,
               seller.slug as seller_slug,
               seller.display_name as seller_display_name,
               seller.verification_status as seller_verification_status
        from commerce.offers offer
        left join commerce.sellers seller on seller.id = offer.seller_id
        where (p_offer_id is not null and offer.id = p_offer_id)
           or (p_offer_id is null and p_slug is not null and offer.slug = p_slug)
        limit 1
    ), access_state as materialized (
        select case
            when p_scope is null or p_scope not in ('self', 'admin') then 'invalid_scope'
            when not exists(select 1 from candidate) then 'not_found'
            when p_scope = 'admin' then 'ok'
            when candidate.resolved_seller_id is null then 'not_found'
            when nullif(btrim(p_cms_user_id), '') is null then 'identity_required'
            when candidate.owner_cms_user_id is distinct from btrim(p_cms_user_id) then 'not_found'
            else 'ok'
        end state
        from (values (true)) singleton(value)
        left join candidate on true
    ), authorized_offer as materialized (
        select candidate.*
        from candidate
        cross join access_state
        where access_state.state = 'ok'
    ), product_keys as materialized (
        select coalesce(array_agg(definition.key order by definition.key), array[]::text[]) keys
        from commerce.custom_field_definitions definition
        where p_scope = 'self'
          and exists(select 1 from authorized_offer)
          and definition.entity_type = 'product'
          and definition.public_readable
          and definition.enabled
    ), item as (
        select jsonb_build_object(
            'id', offer.id,
            'seller_id', offer.seller_id,
            'product_id', offer.product_id,
            'variant_id', offer.variant_id,
            'slug', offer.slug,
            'title', offer.title,
            'description', offer.description,
            'condition_code', offer.condition_code,
            'publication_status', offer.publication_status,
            'workflow_state', offer.workflow_state,
            'accepted_price_amount', offer.accepted_price_amount,
            'currency', offer.currency,
            'availability', offer.availability,
            'quantity_available', offer.quantity_available,
            'metadata', offer.metadata,
            'version', offer.version,
            'created_at', offer.created_at,
            'updated_at', offer.updated_at,
            'seller', case when offer.resolved_seller_id is null then null else jsonb_build_object(
                'id', offer.resolved_seller_id,
                'kind', offer.seller_kind,
                'slug', offer.seller_slug,
                'display_name', offer.seller_display_name,
                'verification_status', offer.seller_verification_status
            ) end,
            'product', case when product.id is null then null else jsonb_build_object(
                'id', product.id,
                'slug', product.slug,
                'title', product.title,
                'brand_id', product.brand_id,
                'status', product.status,
                'visibility', product.visibility,
                'metadata', case when p_scope = 'self'
                    then commerce.public_metadata_subset(product.metadata, product_keys.keys)
                    else product.metadata
                end,
                'brand', case when brand.id is null then null else jsonb_build_object(
                    'id', brand.id,
                    'slug', brand.slug,
                    'name', brand.name,
                    'status', brand.status
                ) end,
                'primary_category_id', primary_category.category_id,
                'primary_category', case when primary_category.id is null then null else jsonb_build_object(
                    'id', primary_category.id,
                    'parent_id', primary_category.parent_id,
                    'slug', primary_category.slug,
                    'full_slug', primary_category.full_slug,
                    'label', primary_category.label,
                    'status', primary_category.status,
                    'position', primary_category.category_position
                ) end
            ) end,
            'variant', case when variant.id is null then null else jsonb_build_object(
                'id', variant.id,
                'sku', variant.sku,
                'title', variant.title,
                'status', variant.status
            ) end,
            'price_rule', price_rule.value,
            'price_proposals', coalesce(proposals.value, '[]'::jsonb),
            'media', coalesce(media.value, '[]'::jsonb),
            'main_image_media_id', media.main_image_media_id
        ) value
        from authorized_offer offer
        cross join product_keys
        left join commerce.products product on product.id = offer.product_id
        left join commerce.product_variants variant
          on variant.id = offer.variant_id
         and offer.variant_id <> 0
        left join commerce.brands brand
          on brand.id = product.brand_id
         and product.brand_id <> 0
        left join lateral (
            select link.category_id,
                   category.id,
                   category.parent_id,
                   category.slug,
                   category.full_slug,
                   category.label,
                   category.status,
                   category.position as category_position
            from commerce.product_categories link
            left join commerce.categories category on category.id = link.category_id
            where link.product_id = product.id
              and link.is_primary
            order by link.position
            limit 1
        ) primary_category on true
        left join lateral (
            select case when p_scope = 'admin' then jsonb_build_object(
                'offer_id', rule.offer_id,
                'minimum_amount', rule.minimum_amount,
                'maximum_amount', rule.maximum_amount,
                'currency', rule.currency,
                'configured_by', rule.configured_by,
                'version', rule.version,
                'created_at', rule.created_at,
                'updated_at', rule.updated_at
            ) else jsonb_build_object(
                'offer_id', rule.offer_id,
                'minimum_amount', rule.minimum_amount,
                'maximum_amount', rule.maximum_amount,
                'currency', rule.currency,
                'version', rule.version,
                'created_at', rule.created_at,
                'updated_at', rule.updated_at
            ) end value
            from commerce.offer_price_rules rule
            where rule.offer_id = offer.id
            limit 1
        ) price_rule on true
        left join lateral (
            select jsonb_agg(proposal.value order by proposal.created_at desc) value
            from (
                select proposal.created_at,
                       case when p_scope = 'admin' then jsonb_build_object(
                           'id', proposal.id,
                           'offer_id', proposal.offer_id,
                           'amount', proposal.amount,
                           'currency', proposal.currency,
                           'status', proposal.status,
                           'proposed_by', proposal.proposed_by,
                           'decided_by', proposal.decided_by,
                           'decision_reason', proposal.decision_reason,
                           'decided_at', proposal.decided_at,
                           'created_at', proposal.created_at
                       ) else jsonb_build_object(
                           'id', proposal.id,
                           'offer_id', proposal.offer_id,
                           'amount', proposal.amount,
                           'currency', proposal.currency,
                           'status', proposal.status,
                           'decision_reason', proposal.decision_reason,
                           'decided_at', proposal.decided_at,
                           'created_at', proposal.created_at
                       ) end value
                from commerce.offer_price_proposals proposal
                where proposal.offer_id = offer.id
                order by proposal.created_at desc
                limit 20
            ) proposal
        ) proposals on true
        left join lateral (
            select jsonb_agg(media_item.value order by media_item.sort_order, media_item.id) value,
                   (array_agg(
                       media_item.media_id
                       order by media_item.is_main desc, media_item.sort_order, media_item.id
                   ))[1]::text main_image_media_id
            from (
                select link.id,
                       link.media_id,
                       link.sort_order,
                       link.is_main,
                       jsonb_build_object(
                           'id', link.id,
                           'media_id', link.media_id,
                           'sort_order', link.sort_order,
                           'is_main', link.is_main,
                           'media', case when stored.id is null then null else jsonb_build_object(
                               'id', stored.id,
                               'storage_bucket', stored.storage_bucket,
                               'storage_path', stored.storage_path,
                               'mime_type', stored.mime_type,
                               'file_size', stored.file_size,
                               'original_filename', stored.original_filename,
                               'alt', stored.alt,
                               'created_at', stored.created_at,
                               'updated_at', stored.updated_at,
                               'url', ''
                           ) end
                       ) value
                from commerce.offer_media link
                left join commerce.media stored on stored.id = link.media_id
                where link.offer_id = offer.id
            ) media_item
        ) media on true
    )
    select case when access_state.state = 'ok'
        then jsonb_build_object('state', 'ok', 'offer', item.value)
        else jsonb_build_object('state', access_state.state)
    end
    from access_state
    left join item on true;
$$;

create or replace function commerce.get_offer_negotiation_context(
    p_offer_id bigint
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    select coalesce((
        select case
            when seller.id is null then jsonb_build_object('state', 'seller_not_found')
            else jsonb_build_object(
                'state', 'ok',
                'context', jsonb_build_object(
                    'offer_id', offer.id,
                    'offer_slug', offer.slug,
                    'offer_title', offer.title,
                    'seller_cms_user_id', seller.cms_user_id,
                    'seller_display_name', seller.display_name,
                    'reference_amount', offer.accepted_price_amount,
                    'currency', offer.currency,
                    'publication_status', offer.publication_status,
                    'availability', offer.availability
                )
            )
        end
        from commerce.offers offer
        left join commerce.sellers seller on seller.id = offer.seller_id
        where offer.id = p_offer_id
    ), jsonb_build_object('state', 'not_found'));
$$;

revoke execute on function commerce.get_offer_negotiation_context(bigint)
    from public, anon, authenticated;
grant execute on function commerce.get_offer_negotiation_context(bigint)
    to service_role;

