create or replace function commerce.effective_variant_metadata(
    p_product_id bigint,
    p_variant_id bigint default null
)
returns jsonb
language sql
stable
set search_path = ''
as $$
    select coalesce(product.metadata, '{}'::jsonb)
        || coalesce(variant.metadata, '{}'::jsonb)
        || coalesce((
            select jsonb_object_agg(axis.field_key, axis_value.value)
            from commerce.product_variant_selections selection
            join commerce.product_variant_axes axis
              on axis.product_id = selection.product_id and axis.id = selection.axis_id
            join commerce.product_variant_axis_values axis_value
              on axis_value.product_id = selection.product_id
             and axis_value.axis_id = selection.axis_id and axis_value.id = selection.value_id
            where selection.product_id = p_product_id
              and selection.variant_id = p_variant_id
              and axis.field_key is not null
        ), '{}'::jsonb)
    from commerce.products product
    left join commerce.product_variants variant
      on variant.product_id = product.id and variant.id = p_variant_id
    where product.id = p_product_id;
$$;

create or replace function commerce.search_public_offers(
    p_category_full_slug text default null,
    p_brand_slug text default null,
    p_filters jsonb default '{}'::jsonb,
    p_query text default null,
    p_condition_code text default null,
    p_price_min bigint default null,
    p_price_max bigint default null,
    p_sort text default null,
    p_limit integer default 50,
    p_offset integer default 0
)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
    v_schema jsonb;
    v_key text;
    v_conditions jsonb;
    v_operator text;
    v_value jsonb;
    v_field jsonb;
begin
    p_filters := coalesce(p_filters, '{}'::jsonb);
    if jsonb_typeof(p_filters) <> 'object' or pg_column_size(p_filters) > 16384 then
        raise exception 'validation: offer filters must be a small object';
    end if;
    if p_category_full_slug is null and p_filters <> '{}'::jsonb then
        raise exception 'validation: category is required for custom filters';
    end if;
    if p_category_full_slug is not null then
        v_schema := commerce.offer_filter_schema(p_category_full_slug);
        if v_schema is null then raise exception 'validation: public category does not exist'; end if;
    end if;
    for v_key, v_conditions in select key, value from jsonb_each(p_filters)
    loop
        select field into v_field
        from jsonb_array_elements(v_schema->'fields') field
        where field->>'key' = v_key and (field->>'filterable')::boolean;
        if v_field is null then raise exception 'validation: unsupported filter %', v_key; end if;
        if jsonb_typeof(v_conditions) <> 'object' then
            raise exception 'validation: filter % conditions must be an object', v_key;
        end if;
        for v_operator, v_value in select key, value from jsonb_each(v_conditions)
        loop
            if not ((v_field->'operators') ? v_operator) then
                raise exception 'validation: unsupported operator % for filter %', v_operator, v_key;
            end if;
            if v_operator = 'in' and jsonb_typeof(v_value) <> 'array' then
                raise exception 'validation: in filter % must be an array', v_key;
            end if;
            if v_operator in ('gte', 'lte') and jsonb_typeof(v_value) <> 'number' then
                raise exception 'validation: numeric filter % must be a number', v_key;
            end if;
        end loop;
    end loop;

    return (
        with recursive selected_category as (
            select id from commerce.categories
            where p_category_full_slug is not null and full_slug = p_category_full_slug and status = 'active'
        ), category_scope as (
            select id from selected_category
            union all
            select child.id from commerce.categories child
            join category_scope parent on child.parent_id = parent.id
            where child.status = 'active'
        ), filtered as (
            select offer.*
            from commerce.offers offer
            join commerce.sellers seller on seller.id = offer.seller_id
            join commerce.settings settings on settings.id = 'default'
            join commerce.products product on product.id = offer.product_id
            left join commerce.brands brand on brand.id = product.brand_id
            left join commerce.product_categories category_link
              on category_link.product_id = product.id and category_link.is_primary
            cross join lateral (
                select commerce.effective_variant_metadata(product.id, offer.variant_id) value
            ) effective
            where offer.publication_status = 'active'
              and offer.availability = 'available'
              and seller.verification_status not in ('rejected', 'suspended')
              and (not settings.require_verified_seller or seller.verification_status = 'verified')
              and product.status = 'active' and product.visibility = 'public'
              and (p_category_full_slug is null or category_link.category_id in (select id from category_scope))
              and (p_brand_slug is null or brand.slug = p_brand_slug)
              and (p_condition_code is null or offer.condition_code = p_condition_code)
              and (p_price_min is null or offer.accepted_price_amount >= p_price_min)
              and (p_price_max is null or offer.accepted_price_amount <= p_price_max)
              and (p_query is null or offer.title ilike '%' || p_query || '%' or offer.slug ilike '%' || p_query || '%'
                   or product.title ilike '%' || p_query || '%' or brand.name ilike '%' || p_query || '%')
              and not exists (
                  select 1
                  from jsonb_each(p_filters) filter
                  cross join lateral jsonb_each(filter.value) condition
                  where not case condition.key
                      when 'eq' then effective.value->filter.key = condition.value
                      when 'in' then condition.value @> jsonb_build_array(effective.value->filter.key)
                      when 'gte' then (effective.value->>filter.key)::numeric >= (condition.value#>>'{}')::numeric
                      when 'lte' then (effective.value->>filter.key)::numeric <= (condition.value#>>'{}')::numeric
                      else false
                  end
              )
        ), page as (
            select filtered.*, row_number() over (order by
                case when p_sort = 'price-asc' then accepted_price_amount end asc nulls last,
                case when p_sort = 'price-desc' then accepted_price_amount end desc nulls last,
                updated_at desc, id desc
            ) sort_ordinal
            from filtered
            order by
                case when p_sort = 'price-asc' then accepted_price_amount end asc nulls last,
                case when p_sort = 'price-desc' then accepted_price_amount end desc nulls last,
                updated_at desc, id desc
            limit least(greatest(coalesce(p_limit, 50), 1), 100)
            offset greatest(coalesce(p_offset, 0), 0)
        )
        select jsonb_build_object(
            'items', coalesce((select jsonb_agg(to_jsonb(page) - 'sort_ordinal' order by sort_ordinal) from page), '[]'::jsonb),
            'total', (select count(*) from filtered),
            'limit', least(greatest(coalesce(p_limit, 50), 1), 100),
            'offset', greatest(coalesce(p_offset, 0), 0)
        )
    );
end;
$$;

create or replace function commerce.search_public_offers_read_model(
    p_category_full_slug text default null,
    p_brand_slug text default null,
    p_filters jsonb default '{}'::jsonb,
    p_query text default null,
    p_condition_code text default null,
    p_price_min bigint default null,
    p_price_max bigint default null,
    p_sort text default null,
    p_limit integer default 50,
    p_offset integer default 0
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with searched as materialized (
        select commerce.search_public_offers(
            p_category_full_slug,
            p_brand_slug,
            p_filters,
            p_query,
            p_condition_code,
            p_price_min,
            p_price_max,
            p_sort,
            p_limit,
            p_offset
        ) value
    ), offer_ids as (
        select coalesce(
            array_agg((entry.item->>'id')::bigint order by entry.ordinality),
            array[]::bigint[]
        ) value
        from searched
        cross join lateral jsonb_array_elements(searched.value->'items')
            with ordinality as entry(item, ordinality)
    )
    select (searched.value - 'items') || jsonb_build_object(
        'items', commerce.public_offer_items_read_model(offer_ids.value, true)
    )
    from searched
    cross join offer_ids;
$$;

revoke execute on function commerce.search_public_offers_read_model(
    text, text, jsonb, text, text, bigint, bigint, text, integer, integer
) from public, anon, authenticated;
grant execute on function commerce.search_public_offers_read_model(
    text, text, jsonb, text, text, bigint, bigint, text, integer, integer
) to service_role;

create or replace function commerce.attach_product_media(
    p_product_id bigint,
    p_storage_bucket text,
    p_storage_path text,
    p_mime_type text,
    p_file_size bigint,
    p_original_filename text,
    p_replace_media_id bigint default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_media commerce.media%rowtype;
    v_previous commerce.media%rowtype;
    v_link commerce.product_media%rowtype;
    v_position integer;
    v_is_main boolean;
begin
    perform id from commerce.products where id = p_product_id for update;
    if not found then raise exception 'not_found: product'; end if;

    insert into commerce.media (
        storage_bucket, storage_path, mime_type, file_size, original_filename
    ) values (
        p_storage_bucket, p_storage_path, lower(p_mime_type), p_file_size,
        coalesce(nullif(btrim(p_original_filename), ''), 'image')
    ) returning * into v_media;

    if p_replace_media_id is null then
        select coalesce(max(sort_order) + 1, 0), count(*) = 0
        into v_position, v_is_main
        from commerce.product_media
        where product_id = p_product_id;
        insert into commerce.product_media (product_id, media_id, sort_order, is_main)
        values (p_product_id, v_media.id, v_position, v_is_main)
        returning * into v_link;
    else
        select * into v_link
        from commerce.product_media
        where product_id = p_product_id and media_id = p_replace_media_id
        for update;
        if not found then raise exception 'not_found: product image'; end if;
        select * into v_previous from commerce.media where id = v_link.media_id for update;
        update commerce.product_media set media_id = v_media.id where id = v_link.id
        returning * into v_link;
        delete from commerce.media where id = v_previous.id;
    end if;

    return to_jsonb(v_media) || jsonb_build_object(
        'product_media_id', v_link.id,
        'media_id', v_media.id,
        'sort_order', v_link.sort_order,
        'is_main', v_link.is_main,
        'replaced_storage_bucket', v_previous.storage_bucket,
        'replaced_storage_path', v_previous.storage_path
    );
end;
$$;

create or replace function commerce.remove_product_media(
    p_product_id bigint,
    p_media_id bigint
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_link commerce.product_media%rowtype;
    v_media commerce.media%rowtype;
begin
    perform id from commerce.products where id = p_product_id for update;
    if not found then raise exception 'not_found: product'; end if;
    select * into v_link
    from commerce.product_media
    where product_id = p_product_id and media_id = p_media_id
    for update;
    if not found then raise exception 'not_found: product image'; end if;
    select * into v_media from commerce.media where id = v_link.media_id for update;
    delete from commerce.product_media where id = v_link.id;
    delete from commerce.media where id = v_media.id;
    if v_link.is_main then
        update commerce.product_media
        set is_main = true
        where id = (
            select id from commerce.product_media
            where product_id = p_product_id
            order by sort_order, id limit 1
        );
    end if;
    return jsonb_build_object(
        'media_id', v_media.id,
        'storage_bucket', v_media.storage_bucket,
        'storage_path', v_media.storage_path
    );
end;
$$;

create or replace function commerce.reorder_product_media(
    p_product_id bigint,
    p_media_ids jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_count integer;
begin
    perform id from commerce.products where id = p_product_id for update;
    if not found then raise exception 'not_found: product'; end if;
    if jsonb_typeof(p_media_ids) <> 'array' or exists (
        select 1 from jsonb_array_elements(p_media_ids) item
        where (item #>> '{}') !~ '^[1-9][0-9]{0,17}$'
    ) then raise exception 'validation: mediaIds must be an array of positive ids'; end if;
    perform id from commerce.product_media
    where product_id = p_product_id order by id for update;
    select count(*) into v_count from commerce.product_media where product_id = p_product_id;
    if jsonb_array_length(p_media_ids) <> v_count
        or (select count(distinct item #>> '{}') from jsonb_array_elements(p_media_ids) item) <> v_count
        or exists (
            select 1 from jsonb_array_elements_text(p_media_ids) item
            where not exists (
                select 1 from commerce.product_media
                where product_id = p_product_id and media_id = item::bigint
            )
        ) then raise exception 'validation: mediaIds must contain every product image exactly once'; end if;

    update commerce.product_media set is_main = false where product_id = p_product_id;
    update commerce.product_media link
    set sort_order = ordered.position - 1,
        is_main = ordered.position = 1
    from jsonb_array_elements_text(p_media_ids) with ordinality ordered(media_id, position)
    where link.product_id = p_product_id and link.media_id = ordered.media_id::bigint;
    return jsonb_build_object('media_ids', p_media_ids);
end;
$$;

create or replace function commerce.attach_offer_media(
    p_offer_id bigint,
    p_storage_bucket text,
    p_storage_path text,
    p_mime_type text,
    p_file_size bigint,
    p_original_filename text,
    p_replace_media_id bigint default null,
    p_cms_user_id text default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_media commerce.media%rowtype;
    v_previous commerce.media%rowtype;
    v_link commerce.offer_media%rowtype;
    v_position integer;
    v_is_main boolean;
begin
    perform offer.id
    from commerce.offers offer
    join commerce.sellers seller on seller.id = offer.seller_id
    where offer.id = p_offer_id
      and (p_cms_user_id is null or seller.cms_user_id = p_cms_user_id)
    for update of offer;
    if not found then raise exception 'not_found: offer'; end if;

    insert into commerce.media (
        storage_bucket, storage_path, mime_type, file_size, original_filename
    ) values (
        p_storage_bucket, p_storage_path, lower(p_mime_type), p_file_size,
        coalesce(nullif(btrim(p_original_filename), ''), 'image')
    ) returning * into v_media;

    if p_replace_media_id is null then
        select coalesce(max(sort_order) + 1, 0), count(*) = 0
        into v_position, v_is_main
        from commerce.offer_media
        where offer_id = p_offer_id;
        insert into commerce.offer_media (offer_id, media_id, sort_order, is_main)
        values (p_offer_id, v_media.id, v_position, v_is_main)
        returning * into v_link;
    else
        select * into v_link
        from commerce.offer_media
        where offer_id = p_offer_id and media_id = p_replace_media_id
        for update;
        if not found then raise exception 'not_found: offer image'; end if;
        select * into v_previous from commerce.media where id = v_link.media_id for update;
        update commerce.offer_media set media_id = v_media.id where id = v_link.id
        returning * into v_link;
        delete from commerce.media where id = v_previous.id;
    end if;

    return to_jsonb(v_media) || jsonb_build_object(
        'offer_media_id', v_link.id,
        'media_id', v_media.id,
        'sort_order', v_link.sort_order,
        'is_main', v_link.is_main,
        'replaced_storage_bucket', v_previous.storage_bucket,
        'replaced_storage_path', v_previous.storage_path
    );
end;
$$;

