create or replace function commerce.upsert_offer(
    p_offer_id bigint,
    p_payload jsonb,
    p_expected_version integer default null,
    p_admin_id text default 'cms-admin'
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_offer commerce.offers%rowtype;
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
    v_metadata jsonb;
    v_metadata_patch jsonb;
    v_seller_id bigint;
    v_product_id bigint;
    v_variant_id bigint;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    if p_offer_id is null then
        v_seller_id := nullif(p_payload->>'sellerId', '')::bigint;
        if v_seller_id is null then
            select id into v_seller_id from commerce.sellers where kind = 'merchant' and slug = 'default';
        end if;
        perform id from commerce.sellers where id = v_seller_id for share;
        if not found then raise exception 'not_found: seller'; end if;
        v_product_id := nullif(p_payload->>'productId', '')::bigint;
        v_variant_id := nullif(p_payload->>'variantId', '')::bigint;
        perform id from commerce.products where id = v_product_id for share;
        if not found then raise exception 'not_found: product'; end if;
        perform commerce.assert_product_variant_ready(v_product_id, v_variant_id);
        perform code from commerce.offer_workflow_states
        where code = coalesce(nullif(p_payload->>'workflowState', ''), 'draft')
        for share;
        if not found then raise exception 'validation: unsupported workflow state'; end if;
        if not exists (
            select 1 from commerce.offer_conditions
            where code = coalesce(nullif(p_payload->>'conditionCode', ''), 'good') and enabled
        ) then
            raise exception 'validation: unsupported offer condition';
        end if;
        if coalesce(nullif(p_payload->>'publicationStatus', ''), 'draft') = 'active'
            and not exists (
                select 1 from commerce.products
                where id = v_product_id and status = 'active' and visibility = 'public'
            ) then
            raise exception 'validation: an active public product is required to publish an offer';
        end if;
        if coalesce(nullif(p_payload->>'publicationStatus', ''), 'draft') = 'active'
            and not exists (
                select 1 from commerce.offer_workflow_states
                where code = coalesce(nullif(p_payload->>'workflowState', ''), 'draft')
                  and phase = 'ready' and enabled
            ) then
            raise exception 'validation: an offer must be in a ready workflow state before publication';
        end if;
        if coalesce(nullif(p_payload->>'publicationStatus', ''), 'draft') = 'active' then
            perform commerce.assert_offer_publication_ready(
                v_seller_id,
                v_product_id,
                v_variant_id,
                coalesce(nullif(p_payload->>'workflowState', ''), 'draft'),
                nullif(p_payload->>'acceptedPriceAmount', '')::bigint
            );
        end if;
        v_metadata := coalesce(p_payload->'metadata', '{}'::jsonb);
        perform commerce.assert_custom_fields('offer', v_metadata, 'admin');
        insert into commerce.offers (
            seller_id, product_id, variant_id, slug, title, description, condition_code,
            publication_status, workflow_state, accepted_price_amount, currency,
            availability, quantity_available, metadata
        ) values (
            v_seller_id, v_product_id, v_variant_id, lower(btrim(p_payload->>'slug')),
            btrim(p_payload->>'title'), nullif(btrim(p_payload->>'description'), ''),
            coalesce(nullif(p_payload->>'conditionCode', ''), 'good'),
            coalesce(nullif(p_payload->>'publicationStatus', ''), 'draft'),
            coalesce(nullif(p_payload->>'workflowState', ''), 'draft'),
            nullif(p_payload->>'acceptedPriceAmount', '')::bigint,
            lower(coalesce(nullif(p_payload->>'currency', ''), v_settings.default_currency)),
            coalesce(nullif(p_payload->>'availability', ''), 'available'),
            nullif(p_payload->>'quantityAvailable', '')::integer,
            v_metadata
        ) returning * into v_offer;
        insert into commerce.offer_events (
            offer_id, event_type, actor_kind, actor_id, previous_workflow_state, next_workflow_state
        ) values (
            v_offer.id, 'created', 'admin', coalesce(nullif(p_admin_id, ''), 'cms-admin'),
            null, v_offer.workflow_state
        );
    else
        if p_expected_version is null then raise exception 'validation: expected offer version is required'; end if;
        select * into v_offer from commerce.offers where id = p_offer_id for update;
        if not found then raise exception 'not_found: offer'; end if;
        if v_offer.version is distinct from p_expected_version then
            raise exception 'conflict: stale offer version';
        end if;
        if exists (
            select 1 from commerce.offer_price_rules where offer_id = v_offer.id
            union all
            select 1 from commerce.offer_price_proposals where offer_id = v_offer.id
        ) and (
            (p_payload ? 'acceptedPriceAmount' and nullif(p_payload->>'acceptedPriceAmount', '')::bigint is distinct from v_offer.accepted_price_amount)
            or (p_payload ? 'currency' and lower(p_payload->>'currency') is distinct from v_offer.currency)
        ) then
            raise exception 'conflict: reviewed price and currency must be changed through the price workflow';
        end if;
        if p_payload ? 'metadata' then
            v_metadata_patch := p_payload->'metadata';
            perform commerce.assert_custom_field_patch('offer', v_metadata_patch, 'admin');
            v_metadata := v_offer.metadata || v_metadata_patch;
        else
            v_metadata := v_offer.metadata;
        end if;
        perform commerce.assert_custom_fields('offer', v_metadata, 'system');
        if not exists (
            select 1 from commerce.offer_conditions
            where code = coalesce(nullif(p_payload->>'conditionCode', ''), v_offer.condition_code) and enabled
        ) then
            raise exception 'validation: unsupported offer condition';
        end if;
        if coalesce(nullif(p_payload->>'publicationStatus', ''), v_offer.publication_status) = 'active'
            and not exists (
                select 1 from commerce.products
                where id = v_offer.product_id and status = 'active' and visibility = 'public'
            ) then
            raise exception 'validation: an active public product is required to publish an offer';
        end if;
        if coalesce(nullif(p_payload->>'publicationStatus', ''), v_offer.publication_status) = 'active'
            and not exists (
                select 1 from commerce.offer_workflow_states
                where code = coalesce(nullif(p_payload->>'workflowState', ''), v_offer.workflow_state)
                  and phase = 'ready' and enabled
            ) then
            raise exception 'validation: an offer must be in a ready workflow state before publication';
        end if;
        if coalesce(nullif(p_payload->>'publicationStatus', ''), v_offer.publication_status) = 'active' then
            perform commerce.assert_offer_publication_ready(
                v_offer.seller_id,
                v_offer.product_id,
                v_offer.variant_id,
                coalesce(nullif(p_payload->>'workflowState', ''), v_offer.workflow_state),
                case when p_payload ? 'acceptedPriceAmount'
                    then nullif(p_payload->>'acceptedPriceAmount', '')::bigint
                    else v_offer.accepted_price_amount
                end
            );
        end if;
        update commerce.offers
        set slug = coalesce(nullif(lower(btrim(p_payload->>'slug')), ''), slug),
            title = coalesce(nullif(btrim(p_payload->>'title'), ''), title),
            description = case when p_payload ? 'description' then nullif(btrim(p_payload->>'description'), '') else description end,
            condition_code = coalesce(nullif(p_payload->>'conditionCode', ''), condition_code),
            publication_status = coalesce(nullif(p_payload->>'publicationStatus', ''), publication_status),
            workflow_state = coalesce(nullif(p_payload->>'workflowState', ''), workflow_state),
            accepted_price_amount = case when p_payload ? 'acceptedPriceAmount' then nullif(p_payload->>'acceptedPriceAmount', '')::bigint else accepted_price_amount end,
            currency = coalesce(nullif(lower(p_payload->>'currency'), ''), currency),
            availability = coalesce(nullif(p_payload->>'availability', ''), availability),
            quantity_available = case when p_payload ? 'quantityAvailable' then nullif(p_payload->>'quantityAvailable', '')::integer else quantity_available end,
            inventory_revision = case
                when p_payload ? 'availability' or p_payload ? 'quantityAvailable' then inventory_revision + 1
                else inventory_revision
            end,
            metadata = v_metadata
        where id = p_offer_id
        returning * into v_offer;
        insert into commerce.offer_events (offer_id, event_type, actor_kind, actor_id)
        values (v_offer.id, 'details_updated', 'admin', coalesce(nullif(p_admin_id, ''), 'cms-admin'));
    end if;
    return to_jsonb(v_offer);
end;
$$;

create or replace function commerce.create_my_offer(
    p_cms_user_id text,
    p_payload jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_seller commerce.sellers%rowtype;
    v_product commerce.products%rowtype;
    v_offer commerce.offers%rowtype;
    v_metadata jsonb := coalesce(p_payload->'metadata', '{}'::jsonb);
    v_product_id bigint;
    v_variant_id bigint;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    if v_settings.mode = 'ecommerce' then
        raise exception 'forbidden: marketplace offers are disabled';
    end if;
    select * into v_seller from commerce.sellers where cms_user_id = p_cms_user_id for share;
    if not found then raise exception 'forbidden: register as a seller first'; end if;
    if v_seller.verification_status in ('rejected', 'suspended') then
        raise exception 'forbidden: seller is not allowed to sell';
    end if;

    v_product_id := nullif(p_payload->>'productId', '')::bigint;
    v_variant_id := nullif(p_payload->>'variantId', '')::bigint;
    select * into v_product from commerce.products
    where id = v_product_id and status = 'active' and visibility = 'public';
    if not found then
        raise exception 'validation: an active public product is required';
    end if;
    perform commerce.assert_product_variant_ready(v_product_id, v_variant_id);
    if not exists (
        select 1 from commerce.offer_conditions
        where code = coalesce(nullif(p_payload->>'conditionCode', ''), 'good') and enabled
    ) then
        raise exception 'validation: unsupported offer condition';
    end if;
    perform commerce.assert_custom_fields('offer', v_metadata, 'self');

    insert into commerce.offers (
        seller_id, product_id, variant_id, slug, title, description,
        condition_code, currency, availability, quantity_available, metadata
    ) values (
        v_seller.id,
        v_product_id,
        v_variant_id,
        lower(btrim(p_payload->>'slug')),
        coalesce(nullif(btrim(p_payload->>'title'), ''), v_product.title),
        nullif(btrim(p_payload->>'description'), ''),
        coalesce(nullif(p_payload->>'conditionCode', ''), 'good'),
        lower(coalesce(nullif(p_payload->>'currency', ''), v_settings.default_currency)),
        coalesce(nullif(p_payload->>'availability', ''), 'available'),
        nullif(p_payload->>'quantityAvailable', '')::integer,
        v_metadata
    ) returning * into v_offer;

    insert into commerce.offer_events (
        offer_id, event_type, actor_kind, actor_id, previous_workflow_state, next_workflow_state
    ) values (v_offer.id, 'created', 'seller', p_cms_user_id, null, v_offer.workflow_state);
    return to_jsonb(v_offer);
end;
$$;

create or replace function commerce.update_my_offer(
    p_offer_id bigint,
    p_cms_user_id text,
    p_expected_version integer,
    p_payload jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_offer commerce.offers%rowtype;
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
    v_metadata jsonb;
    v_metadata_patch jsonb;
    v_details_editable boolean;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    if v_settings.mode = 'ecommerce' then raise exception 'forbidden: marketplace offers are disabled'; end if;
    select * into v_seller from commerce.sellers where cms_user_id = p_cms_user_id for share;
    if not found then raise exception 'not_found: seller'; end if;
    if v_seller.verification_status in ('rejected', 'suspended') then raise exception 'forbidden: seller is not allowed to sell'; end if;
    select * into v_offer from commerce.offers
    where id = p_offer_id and seller_id = v_seller.id
    for update;
    if not found then raise exception 'not_found: offer'; end if;
    if v_offer.version is distinct from p_expected_version then
        raise exception 'conflict: stale offer version';
    end if;
    if v_offer.publication_status = 'archived' then
        raise exception 'conflict: archived offers cannot be edited';
    end if;
    v_details_editable := v_offer.workflow_state in ('draft', 'changes_requested', 'awaiting_seller_price');
    if not v_details_editable and exists (
        select 1 from jsonb_object_keys(p_payload) key
        where key not in ('availability', 'quantityAvailable', 'publicationStatus')
    ) then
        raise exception 'conflict: only inventory and pause can be changed in the current workflow state';
    end if;
    if p_payload ? 'publicationStatus' and (
        p_payload->>'publicationStatus' <> 'paused' or v_offer.publication_status <> 'active'
    ) then
        raise exception 'conflict: a seller can only pause an active offer';
    end if;
    if p_payload ? 'metadata' then
        v_metadata_patch := p_payload->'metadata';
        perform commerce.assert_custom_field_patch('offer', v_metadata_patch, 'self');
        v_metadata := v_offer.metadata || v_metadata_patch;
    else
        v_metadata := v_offer.metadata;
    end if;
    perform commerce.assert_custom_fields('offer', v_metadata, 'system');
    if not exists (
        select 1 from commerce.offer_conditions
        where code = coalesce(nullif(p_payload->>'conditionCode', ''), v_offer.condition_code) and enabled
    ) then
        raise exception 'validation: unsupported offer condition';
    end if;

    update commerce.offers
    set slug = coalesce(nullif(lower(btrim(p_payload->>'slug')), ''), slug),
        title = coalesce(nullif(btrim(p_payload->>'title'), ''), title),
        description = case when p_payload ? 'description' then nullif(btrim(p_payload->>'description'), '') else description end,
        condition_code = coalesce(nullif(p_payload->>'conditionCode', ''), condition_code),
        publication_status = case
            when p_payload->>'publicationStatus' = 'paused' then 'paused'
            else publication_status
        end,
        availability = case
            when p_payload ? 'quantityAvailable'
                and nullif(p_payload->>'quantityAvailable', '')::integer = 0 then 'unavailable'
            else coalesce(nullif(p_payload->>'availability', ''), availability)
        end,
        quantity_available = case when p_payload ? 'quantityAvailable' then nullif(p_payload->>'quantityAvailable', '')::integer else quantity_available end,
        inventory_revision = case
            when p_payload ? 'availability' or p_payload ? 'quantityAvailable' then inventory_revision + 1
            else inventory_revision
        end,
        metadata = v_metadata
    where id = p_offer_id
    returning * into v_offer;

    insert into commerce.offer_events (offer_id, event_type, actor_kind, actor_id, data)
    values (
        v_offer.id,
        case
            when p_payload->>'publicationStatus' = 'paused' then 'paused'
            when not v_details_editable then 'inventory_updated'
            else 'details_updated'
        end,
        'seller', p_cms_user_id, '{}'::jsonb
    );
    return to_jsonb(v_offer);
end;
$$;

create or replace function commerce.submit_my_offer(
    p_offer_id bigint,
    p_cms_user_id text,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_offer commerce.offers%rowtype;
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
    v_previous_state text;
    v_next_state text;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    if v_settings.mode = 'ecommerce' then raise exception 'forbidden: marketplace offers are disabled'; end if;
    select * into v_seller from commerce.sellers where cms_user_id = p_cms_user_id for share;
    if not found then raise exception 'not_found: seller'; end if;
    select * into v_offer from commerce.offers
    where id = p_offer_id and seller_id = v_seller.id
    for update;
    if not found then raise exception 'not_found: offer'; end if;
    if v_offer.version is distinct from p_expected_version then raise exception 'conflict: stale offer version'; end if;
    perform commerce.assert_custom_fields('offer', v_offer.metadata, 'system');
    if v_seller.verification_status in ('rejected', 'suspended') then raise exception 'forbidden: seller is not allowed to sell'; end if;

    if v_settings.price_policy = 'free' and not exists (
        select 1 from commerce.offer_price_proposals
        where offer_id = v_offer.id and status in ('pending', 'accepted')
    ) and v_offer.accepted_price_amount is null then
        raise exception 'validation: submit a price before submitting this offer';
    end if;

    select to_state into v_next_state
    from commerce.offer_workflow_transitions
    where from_state = v_offer.workflow_state and action = 'submit' and actor_kind = 'seller';
    if not found then raise exception 'conflict: offer cannot be submitted from the current state'; end if;

    v_previous_state := v_offer.workflow_state;
    update commerce.offers set workflow_state = v_next_state where id = v_offer.id returning * into v_offer;
    insert into commerce.offer_events (
        offer_id, event_type, actor_kind, actor_id, previous_workflow_state, next_workflow_state
    ) values (v_offer.id, 'submitted', 'seller', p_cms_user_id, v_previous_state, v_next_state);
    return to_jsonb(v_offer);
end;
$$;

create or replace function commerce.submit_offer_price(
    p_offer_id bigint,
    p_cms_user_id text,
    p_amount bigint,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_offer commerce.offers%rowtype;
    v_seller commerce.sellers%rowtype;
    v_rule commerce.offer_price_rules%rowtype;
    v_proposal commerce.offer_price_proposals%rowtype;
    v_previous_state text;
    v_next_state text;
    v_transition_state text;
    v_rule_exists boolean;
    v_accept boolean;
begin
    if p_amount is null or p_amount < 0 then raise exception 'validation: price must be non-negative'; end if;
    select * into v_settings from commerce.settings where id = 'default' for share;
    if v_settings.mode = 'ecommerce' then raise exception 'forbidden: marketplace offers are disabled'; end if;
    select * into v_seller from commerce.sellers where cms_user_id = p_cms_user_id for share;
    if not found then raise exception 'not_found: seller'; end if;
    if v_seller.verification_status in ('rejected', 'suspended') then raise exception 'forbidden: seller is not allowed to sell'; end if;
    select * into v_offer from commerce.offers
    where id = p_offer_id and seller_id = v_seller.id
    for update;
    if not found then raise exception 'not_found: offer'; end if;
    if v_offer.version is distinct from p_expected_version then raise exception 'conflict: stale offer version'; end if;
    if not exists (
        select 1 from commerce.products
        where id = v_offer.product_id and status = 'active' and visibility = 'public'
    ) then raise exception 'conflict: offer product is not sellable'; end if;
    if v_offer.variant_id is not null and not exists (
        select 1 from commerce.product_variants
        where id = v_offer.variant_id and product_id = v_offer.product_id and status = 'active'
    ) then raise exception 'conflict: offer variant is not sellable'; end if;

    select * into v_rule from commerce.offer_price_rules where offer_id = v_offer.id for update;
    v_rule_exists := found;
    if v_rule_exists then
        select to_state into v_transition_state
        from commerce.offer_workflow_transitions
        where from_state = v_offer.workflow_state and action = 'submit_price' and actor_kind = 'seller';
        if not found then raise exception 'conflict: offer is not awaiting a seller price'; end if;
        if p_amount < v_rule.minimum_amount or p_amount > v_rule.maximum_amount then
            raise exception 'validation: price must be between % and %', v_rule.minimum_amount, v_rule.maximum_amount;
        end if;
    elsif v_settings.price_policy = 'admin_range' then
        raise exception 'conflict: administrator price range is missing';
    elsif v_offer.workflow_state not in ('draft', 'changes_requested', 'awaiting_seller_price') then
        raise exception 'conflict: price cannot be submitted in the current state';
    end if;

    update commerce.offer_price_proposals
    set status = 'superseded'
    where offer_id = v_offer.id and status = 'pending';

    v_accept := v_settings.auto_approve_price_in_range
        and not v_settings.require_final_price_approval
        and (v_rule_exists or v_settings.offer_moderation = 'none');
    if v_accept then
        update commerce.offer_price_proposals
        set status = 'superseded'
        where offer_id = v_offer.id and status = 'accepted';
    end if;
    insert into commerce.offer_price_proposals (
        offer_id, amount, currency, status, proposed_by, decided_by, decided_at
    ) values (
        v_offer.id,
        p_amount,
        v_offer.currency,
        case when v_accept then 'accepted' else 'pending' end,
        p_cms_user_id,
        case when v_accept then 'system' else null end,
        case when v_accept then now() else null end
    ) returning * into v_proposal;

    v_previous_state := v_offer.workflow_state;
    v_next_state := case
        when v_accept then 'approved'
        when v_rule_exists then v_transition_state
        when v_settings.offer_moderation = 'none' then 'awaiting_final_approval'
        else v_offer.workflow_state
    end;
    if v_accept and v_settings.seller_can_publish then
        perform commerce.assert_offer_publication_ready(
            v_offer.seller_id,
            v_offer.product_id,
            v_offer.variant_id,
            v_next_state,
            p_amount
        );
    end if;
    update commerce.offers
    set accepted_price_amount = case when v_accept then p_amount else accepted_price_amount end,
        workflow_state = v_next_state,
        publication_status = case
            when v_accept and v_settings.seller_can_publish then 'active'
            else publication_status
        end
    where id = v_offer.id
    returning * into v_offer;

    insert into commerce.offer_events (
        offer_id, event_type, actor_kind, actor_id, previous_workflow_state, next_workflow_state, data
    ) values (
        v_offer.id, 'price_submitted', 'seller', p_cms_user_id, v_previous_state, v_next_state,
        jsonb_build_object('proposalId', v_proposal.id, 'amount', p_amount, 'accepted', v_accept)
    );
    return jsonb_build_object('offer', to_jsonb(v_offer), 'proposal', to_jsonb(v_proposal));
end;
$$;

create or replace function commerce.review_offer(
    p_offer_id bigint,
    p_action text,
    p_admin_id text,
    p_expected_version integer,
    p_minimum_amount bigint default null,
    p_maximum_amount bigint default null,
    p_reason text default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_offer commerce.offers%rowtype;
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
    v_proposal commerce.offer_price_proposals%rowtype;
    v_previous_state text;
    v_next_state text;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    select seller.* into v_seller
    from commerce.sellers seller
    join commerce.offers offer on offer.seller_id = seller.id
    where offer.id = p_offer_id
    for share of seller;
    if not found then raise exception 'not_found: offer'; end if;
    select * into v_offer from commerce.offers where id = p_offer_id for update;
    if not found then raise exception 'not_found: offer'; end if;
    if v_offer.version is distinct from p_expected_version then raise exception 'conflict: stale offer version'; end if;
    if p_action not in ('pause', 'archive', 'reject') then
        if v_seller.verification_status in ('rejected', 'suspended') then raise exception 'forbidden: seller is not allowed to sell'; end if;
        if v_settings.mode = 'ecommerce' and v_seller.kind = 'user' then
            raise exception 'forbidden: marketplace offers are disabled';
        end if;
        perform commerce.assert_custom_fields('offer', v_offer.metadata, 'system');
    end if;
    v_previous_state := v_offer.workflow_state;

    if p_action in ('request_price', 'request_changes', 'approve', 'reject') then
        select to_state into v_next_state
        from commerce.offer_workflow_transitions
        where from_state = v_offer.workflow_state
          and action = p_action
          and actor_kind = 'admin';
        if not found then raise exception 'conflict: offer action is not allowed from the current state'; end if;
    elsif p_action = 'publish' then
        if exists (
            select 1 from commerce.offer_workflow_states
            where code = v_offer.workflow_state and phase = 'ready' and enabled
        ) then
            v_next_state := v_offer.workflow_state;
        else
            select to_state into v_next_state
            from commerce.offer_workflow_transitions
            where from_state = v_offer.workflow_state
              and action = 'approve'
              and actor_kind = 'admin';
            if not found then raise exception 'conflict: offer cannot be published from the current state'; end if;
        end if;
    elsif p_action not in ('pause', 'archive') then
        select to_state into v_next_state
        from commerce.offer_workflow_transitions
        where from_state = v_offer.workflow_state
          and action = p_action
          and actor_kind = 'admin';
        if not found then raise exception 'validation: unsupported offer review action'; end if;
    end if;

    if p_action <> 'pause' and not exists (
        select 1 from commerce.offer_workflow_states
        where code = v_next_state and enabled
    ) then raise exception 'conflict: target workflow state is disabled'; end if;

    if p_action = 'request_price' then
        if p_minimum_amount is null or p_maximum_amount is null
            or p_minimum_amount < 0 or p_maximum_amount < p_minimum_amount then
            raise exception 'validation: a valid minimum and maximum price are required';
        end if;
        if v_offer.workflow_state <> 'pending_review' then
            raise exception 'conflict: price can only be requested during review';
        end if;
        insert into commerce.offer_price_rules (
            offer_id, minimum_amount, maximum_amount, currency, configured_by
        ) values (
            v_offer.id, p_minimum_amount, p_maximum_amount, v_offer.currency,
            coalesce(nullif(p_admin_id, ''), 'cms-admin')
        ) on conflict (offer_id) do update
        set minimum_amount = excluded.minimum_amount,
            maximum_amount = excluded.maximum_amount,
            currency = excluded.currency,
            configured_by = excluded.configured_by;
    elsif p_action = 'request_changes' then
        null;
    elsif p_action in ('approve', 'publish') then
        select * into v_proposal
        from commerce.offer_price_proposals
        where offer_id = v_offer.id and status in ('pending', 'accepted')
        order by case when status = 'pending' then 0 else 1 end, created_at desc
        limit 1 for update;
        if v_offer.accepted_price_amount is null and not found then
            raise exception 'validation: an offer price must be approved first';
        end if;
        if found and v_proposal.status = 'pending' then
            update commerce.offer_price_proposals
            set status = 'superseded'
            where offer_id = v_offer.id and status = 'accepted' and id <> v_proposal.id;
            update commerce.offer_price_proposals
            set status = 'accepted', decided_by = coalesce(nullif(p_admin_id, ''), 'cms-admin'),
                decision_reason = p_reason, decided_at = now()
            where id = v_proposal.id;
            v_offer.accepted_price_amount := v_proposal.amount;
        end if;
    elsif p_action = 'reject' then
        update commerce.offer_price_proposals
        set status = 'rejected', decided_by = coalesce(nullif(p_admin_id, ''), 'cms-admin'),
            decision_reason = p_reason, decided_at = now()
        where offer_id = v_offer.id and status = 'pending';
    elsif p_action = 'pause' then
        update commerce.offers set publication_status = 'paused' where id = v_offer.id returning * into v_offer;
        v_next_state := v_offer.workflow_state;
    elsif p_action = 'archive' then
        v_next_state := 'archived';
    else
        -- Custom administrator actions use their configured transition.
        null;
    end if;

    if p_action <> 'pause' then
        if p_action in ('approve', 'publish') and not exists (
            select 1 from commerce.products
            where id = v_offer.product_id and status = 'active' and visibility = 'public'
        ) then
            raise exception 'validation: an active public product is required to publish an offer';
        end if;
        if p_action in ('approve', 'publish') and not exists (
            select 1 from commerce.offer_workflow_states
            where code = v_next_state and phase = 'ready' and enabled
        ) then
            raise exception 'validation: publication requires a ready workflow state';
        end if;
        if p_action in ('approve', 'publish') then
            perform commerce.assert_offer_publication_ready(
                v_offer.seller_id,
                v_offer.product_id,
                v_offer.variant_id,
                v_next_state,
                v_offer.accepted_price_amount
            );
        end if;
        update commerce.offers
        set workflow_state = v_next_state,
            accepted_price_amount = v_offer.accepted_price_amount,
            publication_status = case
                when p_action in ('approve', 'publish') then 'active'
                when p_action = 'reject' and publication_status = 'active' then 'paused'
                when p_action = 'archive' then 'archived'
                when publication_status = 'active' and not exists (
                    select 1 from commerce.offer_workflow_states
                    where code = v_next_state and phase = 'ready' and enabled
                ) then 'paused'
                else publication_status
            end
        where id = v_offer.id
        returning * into v_offer;
    end if;

    insert into commerce.offer_events (
        offer_id, event_type, actor_kind, actor_id, previous_workflow_state, next_workflow_state, data
    ) values (
        v_offer.id, p_action, 'admin', coalesce(nullif(p_admin_id, ''), 'cms-admin'),
        v_previous_state, v_next_state,
        jsonb_strip_nulls(jsonb_build_object(
            'minimumAmount', p_minimum_amount,
            'maximumAmount', p_maximum_amount,
            'reason', p_reason
        ))
    );
    return to_jsonb(v_offer);
end;
$$;

create or replace function commerce.upsert_offer_condition(
    p_code text,
    p_label text,
    p_description text default null,
    p_position integer default 0,
    p_enabled boolean default true
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_condition commerce.offer_conditions%rowtype;
begin
    perform pg_advisory_xact_lock(hashtextextended('commerce-offer-conditions', 0));
    if not exists (select 1 from commerce.offer_conditions where code = p_code)
        and (select count(*) from commerce.offer_conditions) >= 32 then
        raise exception 'validation: at most 32 offer conditions are allowed';
    end if;
    insert into commerce.offer_conditions (code, label, description, position, enabled)
    values (p_code, p_label, p_description, p_position, p_enabled)
    on conflict (code) do update
    set label = excluded.label, description = excluded.description,
        position = excluded.position, enabled = excluded.enabled
    returning * into v_condition;
    return to_jsonb(v_condition);
end;
$$;

create or replace function commerce.upsert_workflow_state(
    p_code text,
    p_label text,
    p_phase text,
    p_position integer default 0,
    p_enabled boolean default true,
    p_terminal boolean default false
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_state commerce.offer_workflow_states%rowtype;
begin
    perform pg_advisory_xact_lock(hashtextextended('commerce-offer-workflow', 0));
    select * into v_state from commerce.offer_workflow_states where code = p_code for update;
    if found and p_code in (
        'draft', 'pending_review', 'changes_requested', 'awaiting_seller_price',
        'awaiting_final_approval', 'approved', 'rejected', 'archived'
    ) and (
        v_state.phase is distinct from p_phase
        or v_state.enabled is distinct from p_enabled
        or v_state.terminal is distinct from p_terminal
    ) then raise exception 'conflict: reserved workflow state behavior is immutable'; end if;
    perform id from commerce.offers
    where workflow_state = p_code
    order by id
    for update;
    if not exists (select 1 from commerce.offer_workflow_states where code = p_code)
        and (select count(*) from commerce.offer_workflow_states) >= 16 then
        raise exception 'validation: at most 16 workflow states are allowed';
    end if;
    if p_code in (
        'draft', 'pending_review', 'changes_requested', 'awaiting_seller_price',
        'awaiting_final_approval', 'approved', 'rejected', 'archived'
    ) then
        update commerce.offer_workflow_states
        set label = p_label, position = p_position
        where code = p_code
        returning * into v_state;
        if not found then raise exception 'conflict: reserved workflow state is missing'; end if;
    else
        insert into commerce.offer_workflow_states (code, label, phase, position, enabled, terminal)
        values (p_code, p_label, p_phase, p_position, p_enabled, p_terminal)
        on conflict (code) do update
        set label = excluded.label, phase = excluded.phase, position = excluded.position,
            enabled = excluded.enabled, terminal = excluded.terminal
        returning * into v_state;
    end if;
    if not v_state.enabled or v_state.phase <> 'ready' then
        update commerce.offers
        set publication_status = 'paused'
        where workflow_state = v_state.code and publication_status = 'active';
    end if;
    return to_jsonb(v_state);
end;
$$;

create or replace function commerce.upsert_workflow_transition(
    p_from_state text,
    p_action text,
    p_actor_kind text,
    p_to_state text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_transition commerce.offer_workflow_transitions%rowtype;
begin
    perform pg_advisory_xact_lock(hashtextextended('commerce-offer-workflow', 0));
    if p_actor_kind not in ('seller', 'admin') then
        raise exception 'validation: configurable transitions support seller or admin actors';
    end if;
    if p_actor_kind = 'seller' and p_action not in ('submit', 'submit_price') then
        raise exception 'conflict: custom seller transitions are not executable';
    end if;
    if p_action in ('pause', 'archive', 'publish') then
        raise exception 'conflict: commerce command names cannot be configured as transitions';
    end if;
    if p_action in ('submit', 'submit_price', 'request_price', 'request_changes', 'approve', 'reject')
        and (p_from_state, p_action, p_actor_kind, p_to_state) not in (
            ('draft', 'submit', 'seller', 'pending_review'),
            ('changes_requested', 'submit', 'seller', 'pending_review'),
            ('pending_review', 'request_changes', 'admin', 'changes_requested'),
            ('pending_review', 'request_price', 'admin', 'awaiting_seller_price'),
            ('pending_review', 'approve', 'admin', 'approved'),
            ('awaiting_seller_price', 'submit_price', 'seller', 'awaiting_final_approval'),
            ('awaiting_final_approval', 'approve', 'admin', 'approved'),
            ('pending_review', 'reject', 'admin', 'rejected'),
            ('awaiting_final_approval', 'reject', 'admin', 'rejected')
        ) then
        raise exception 'conflict: commerce side-effect transitions are reserved';
    end if;
    if not exists (
        select 1 from commerce.offer_workflow_transitions
        where from_state = p_from_state and action = p_action and actor_kind = p_actor_kind
    ) and (select count(*) from commerce.offer_workflow_transitions) >= 64 then
        raise exception 'validation: at most 64 workflow transitions are allowed';
    end if;
    select * into v_transition
    from commerce.offer_workflow_transitions
    where from_state = p_from_state and action = p_action and actor_kind = p_actor_kind
    for update;
    if found and p_action in ('submit', 'submit_price', 'request_price', 'request_changes', 'approve', 'reject')
        and v_transition.to_state <> p_to_state then
        raise exception 'conflict: transitions with commerce side effects are immutable';
    end if;
    insert into commerce.offer_workflow_transitions (from_state, action, actor_kind, to_state)
    values (p_from_state, p_action, p_actor_kind, p_to_state)
    on conflict (from_state, action, actor_kind) do update set to_state = excluded.to_state
    returning * into v_transition;
    return to_jsonb(v_transition);
end;
$$;

create or replace function commerce.cart_payload(p_cart_id bigint)
returns jsonb
language sql
stable
set search_path = ''
as $$
with selected_cart as (
    select * from commerce.carts where id = p_cart_id
), details as (
    select
        item.*, offer.accepted_price_amount as current_unit_amount,
        offer.currency, offer.availability, offer.quantity_available,
        offer.title, offer.seller_id, seller.slug as seller_slug,
        seller.display_name as seller_name,
        product.id as product_id, product.slug as product_slug,
        product.title as product_title,
        variant.id as variant_id, variant.sku as variant_sku,
        variant.title as variant_title,
        array_remove(array[
            case when offer.publication_status <> 'active'
                or state.phase <> 'ready' or not state.enabled
                or offer.accepted_price_amount is null
                or offer.availability = 'unavailable' then 'offer_unavailable' end,
            case when offer.accepted_price_amount is distinct from item.unit_amount_at_add
                then 'price_changed' end,
            case when offer.quantity_available is not null
                and offer.quantity_available < item.quantity then 'insufficient_stock' end,
            case when seller.verification_status in ('rejected', 'suspended')
                or (settings.require_verified_seller and seller.verification_status <> 'verified')
                then 'seller_unavailable' end,
            case when product.status <> 'active' or product.visibility <> 'public'
                then 'product_unavailable' end,
            case when cart.currency is distinct from offer.currency then 'currency_mismatch' end
        ], null)::text[] as issues
    from selected_cart cart
    join commerce.cart_items item on item.cart_id = cart.id
    join commerce.offers offer on offer.id = item.offer_id
    join commerce.products product on product.id = offer.product_id
    left join commerce.product_variants variant on variant.id = offer.variant_id
    join commerce.sellers seller on seller.id = offer.seller_id
    join commerce.offer_workflow_states state on state.code = offer.workflow_state
    join commerce.settings settings on settings.id = 'default'
)
select coalesce((
    select jsonb_build_object(
        'exists', true,
        'id', cart.id,
        'public_id', cart.public_id,
        'buyer_cms_user_id', cart.buyer_cms_user_id,
        'status', cart.status,
        'currency', cart.currency,
        'version', cart.version,
        'subtotal_amount', coalesce((
            select sum(coalesce(current_unit_amount, 0) * quantity) from details
        ), 0),
        'items', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', id,
                'offer_id', offer_id,
                'quantity', quantity,
                'unit_amount_at_add', unit_amount_at_add,
                'offer_version_at_add', offer_version_at_add,
                'current_unit_amount', current_unit_amount,
                'currency', currency,
                'availability', availability,
                'quantity_available', quantity_available,
                'title', title,
                'issues', to_jsonb(issues),
                'seller', jsonb_build_object(
                    'id', seller_id, 'slug', seller_slug, 'display_name', seller_name
                ),
                'product', jsonb_build_object(
                    'id', product_id, 'slug', product_slug, 'title', product_title
                ),
                'variant', case when variant_id is null then null else jsonb_build_object(
                    'id', variant_id, 'sku', variant_sku, 'title', variant_title
                ) end
            ) order by id) from details
        ), '[]'::jsonb),
        'seller_groups', coalesce((
            select jsonb_agg(jsonb_build_object(
                'seller', jsonb_build_object(
                    'id', seller_id, 'slug', seller_slug, 'display_name', seller_name
                ),
                'currency', currency,
                'subtotal_amount', subtotal_amount,
                'item_ids', item_ids,
                'issues', issues
            ) order by seller_id)
            from (
                select
                    seller_id, min(seller_slug) as seller_slug,
                    min(seller_name) as seller_name, min(currency) as currency,
                    sum(coalesce(current_unit_amount, 0) * quantity) as subtotal_amount,
                    jsonb_agg(id order by id) as item_ids,
                    to_jsonb(array(
                        select distinct issue
                        from details issue_detail,
                        unnest(issue_detail.issues) issue
                        where issue_detail.seller_id = grouped.seller_id
                        order by issue
                    )) as issues
                from details grouped
                group by seller_id
            ) grouped_sellers
        ), '[]'::jsonb),
        'issues', to_jsonb(array(
            select distinct issue from details, unnest(issues) issue order by issue
        )),
        'created_at', cart.created_at,
        'updated_at', cart.updated_at
    )
    from selected_cart cart
), jsonb_build_object(
    'exists', false,
    'subtotal_amount', 0,
    'items', '[]'::jsonb,
    'seller_groups', '[]'::jsonb,
    'issues', '[]'::jsonb
));
$$;

create or replace function commerce.get_cart(p_buyer_cms_user_id text)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare v_cart_id bigint;
begin
    if p_buyer_cms_user_id is null or length(btrim(p_buyer_cms_user_id)) = 0 then
        raise exception 'forbidden: missing CMS user id';
    end if;
    select id into v_cart_id from commerce.carts
    where buyer_cms_user_id = p_buyer_cms_user_id and status = 'open';
    return commerce.cart_payload(v_cart_id);
end;
$$;

create or replace function commerce.assert_cart_offer_sellable(
    p_offer_id bigint,
    p_quantity integer
)
returns commerce.offers
language plpgsql
set search_path = ''
as $$
declare
    v_offer commerce.offers%rowtype;
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
begin
    select * into v_settings from commerce.settings where id = 'default' for share;
    select * into v_offer from commerce.offers where id = p_offer_id;
    if not found then raise exception 'not_found: offer'; end if;
    if v_offer.publication_status <> 'active'
        or not exists (
            select 1 from commerce.offer_workflow_states
            where code = v_offer.workflow_state and phase = 'ready' and enabled
        )
        or v_offer.availability = 'unavailable'
        or v_offer.accepted_price_amount is null then
        raise exception 'conflict: offer % is not sellable', v_offer.id;
    end if;
    if v_offer.quantity_available is not null and v_offer.quantity_available < p_quantity then
        raise exception 'conflict: insufficient quantity for offer %', v_offer.id;
    end if;
    if not exists (
        select 1 from commerce.products
        where id = v_offer.product_id and status = 'active' and visibility = 'public'
    ) then raise exception 'conflict: product for offer % is not sellable', v_offer.id; end if;
    perform commerce.assert_product_variant_ready(v_offer.product_id, v_offer.variant_id);
    select * into v_seller from commerce.sellers where id = v_offer.seller_id;
    if v_seller.verification_status in ('rejected', 'suspended')
        or (v_settings.require_verified_seller and v_seller.verification_status <> 'verified') then
        raise exception 'conflict: seller for offer % is not allowed to sell', v_offer.id;
    end if;
    if v_settings.mode = 'ecommerce' and v_seller.kind = 'user' then
        raise exception 'conflict: marketplace offers are disabled';
    end if;
    return v_offer;
end;
$$;

create or replace function commerce.upsert_cart_item(
    p_buyer_cms_user_id text,
    p_offer_id bigint,
    p_quantity integer,
    p_expected_version integer default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_cart commerce.carts%rowtype;
    v_offer commerce.offers%rowtype;
    v_cart_exists boolean;
begin
    if p_buyer_cms_user_id is null or length(btrim(p_buyer_cms_user_id)) = 0 then
        raise exception 'forbidden: missing CMS user id';
    end if;
    if p_quantity is null or p_quantity not between 1 and 1000 then
        raise exception 'validation: quantity must be between 1 and 1000';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('commerce-cart:' || p_buyer_cms_user_id, 0));
    select * into v_cart from commerce.carts
    where buyer_cms_user_id = p_buyer_cms_user_id and status = 'open'
    for update;
    v_cart_exists := found;
    perform id from commerce.offers where id = p_offer_id for share;
    v_offer := commerce.assert_cart_offer_sellable(p_offer_id, p_quantity);
    if not v_cart_exists then
        if p_expected_version is not null and p_expected_version <> 0 then
            raise exception 'conflict: stale cart version';
        end if;
        insert into commerce.carts (buyer_cms_user_id, currency)
        values (p_buyer_cms_user_id, v_offer.currency)
        returning * into v_cart;
    else
        if p_expected_version is null then
            raise exception 'validation: expected cart version is required';
        end if;
        if v_cart.version is distinct from p_expected_version then
            raise exception 'conflict: stale cart version';
        end if;
        if v_cart.currency is not null and v_cart.currency <> v_offer.currency then
            raise exception 'conflict: one cart cannot contain multiple currencies';
        end if;
        if not exists (
            select 1 from commerce.cart_items where cart_id = v_cart.id and offer_id = p_offer_id
        ) and (select count(*) from commerce.cart_items where cart_id = v_cart.id) >= 100 then
            raise exception 'validation: a cart cannot contain more than 100 items';
        end if;
    end if;
    insert into commerce.cart_items (
        cart_id, offer_id, quantity, unit_amount_at_add, offer_version_at_add
    ) values (
        v_cart.id, v_offer.id, p_quantity,
        v_offer.accepted_price_amount, v_offer.version
    ) on conflict (cart_id, offer_id) do update set
        quantity = excluded.quantity,
        unit_amount_at_add = excluded.unit_amount_at_add,
        offer_version_at_add = excluded.offer_version_at_add;
    if v_cart_exists then
        update commerce.carts
        set currency = coalesce(currency, v_offer.currency)
        where id = v_cart.id;
    end if;
    return commerce.cart_payload(v_cart.id);
end;
$$;

create or replace function commerce.remove_cart_item(
    p_buyer_cms_user_id text,
    p_offer_id bigint,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_cart commerce.carts%rowtype;
begin
    select * into v_cart from commerce.carts
    where buyer_cms_user_id = p_buyer_cms_user_id and status = 'open' for update;
    if not found then raise exception 'not_found: cart'; end if;
    if p_expected_version is null or v_cart.version is distinct from p_expected_version then
        raise exception 'conflict: stale cart version';
    end if;
    delete from commerce.cart_items where cart_id = v_cart.id and offer_id = p_offer_id;
    if not found then raise exception 'not_found: cart item'; end if;
    update commerce.carts
    set currency = case when exists (
        select 1 from commerce.cart_items where cart_id = v_cart.id
    ) then currency else null end
    where id = v_cart.id;
    return commerce.cart_payload(v_cart.id);
end;
$$;

create or replace function commerce.clear_cart(
    p_buyer_cms_user_id text,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_cart commerce.carts%rowtype;
begin
    select * into v_cart from commerce.carts
    where buyer_cms_user_id = p_buyer_cms_user_id and status = 'open' for update;
    if not found then raise exception 'not_found: cart'; end if;
    if p_expected_version is null or v_cart.version is distinct from p_expected_version then
        raise exception 'conflict: stale cart version';
    end if;
    delete from commerce.cart_items where cart_id = v_cart.id;
    update commerce.carts set currency = null where id = v_cart.id;
    return commerce.cart_payload(v_cart.id);
end;
$$;

create or replace function commerce.checkout_group_result(
    p_checkout_group_id uuid,
    p_idempotent_replay boolean
)
returns jsonb
language sql
stable
set search_path = ''
as $$
select jsonb_build_object(
    'checkout_group_id', p_checkout_group_id,
    'orders', coalesce(jsonb_agg((to_jsonb(orders) - 'request_hash') order by orders.id)
        filter (where orders.id is not null), '[]'::jsonb),
    'idempotent_replay', p_idempotent_replay
)
from commerce.orders
where checkout_group_id = p_checkout_group_id;
$$;

create or replace function commerce.create_order_from_offers(
    p_buyer_cms_user_id text,
    p_idempotency_key text,
    p_items jsonb,
    p_shipping_address jsonb default '{}'::jsonb,
    p_billing_address jsonb default '{}'::jsonb,
    p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_existing commerce.orders%rowtype;
    v_order commerce.orders%rowtype;
    v_offer commerce.offers%rowtype;
    v_product commerce.products%rowtype;
    v_variant commerce.product_variants%rowtype;
    v_seller commerce.sellers%rowtype;
    v_proposal_id bigint;
    v_item jsonb;
    v_canonical_items jsonb;
    v_request_hash text;
    v_offer_ids bigint[];
    v_quantity integer;
    v_seller_id bigint;
    v_currency text;
    v_subtotal numeric := 0;
begin
    if p_buyer_cms_user_id is null or length(btrim(p_buyer_cms_user_id)) = 0 then
        raise exception 'forbidden: missing CMS user id';
    end if;
    if p_idempotency_key is null or length(btrim(p_idempotency_key)) = 0 then
        raise exception 'validation: idempotency key is required';
    end if;
    perform pg_advisory_xact_lock(hashtextextended(p_buyer_cms_user_id || ':' || p_idempotency_key, 0));
    select * into v_settings from commerce.settings where id = 'default' for share;
    if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 100 then
        raise exception 'validation: order items must contain between 1 and 100 entries';
    end if;
    if exists (
        select 1
        from jsonb_array_elements(p_items) item
        where jsonb_typeof(item) <> 'object'
           or coalesce(item->>'offerId', '') !~ '^[1-9][0-9]{0,17}$'
           or coalesce(item->>'quantity', '') !~ '^[1-9][0-9]{0,3}$'
           or (item->>'quantity')::integer > 1000
    ) then raise exception 'validation: every order item needs a valid offerId and quantity'; end if;
    if exists (
        select 1
        from jsonb_array_elements(p_items) item
        group by item->>'offerId'
        having count(*) > 1
    ) then raise exception 'validation: duplicate offer entries are not allowed'; end if;
    if jsonb_typeof(coalesce(p_shipping_address, '{}'::jsonb)) <> 'object'
        or jsonb_typeof(coalesce(p_billing_address, '{}'::jsonb)) <> 'object' then
        raise exception 'validation: addresses must be objects';
    end if;
    select jsonb_agg(item order by (item->>'offerId')::bigint)
    into v_canonical_items
    from jsonb_array_elements(p_items) item;
    v_request_hash := md5(jsonb_build_object(
        'items', v_canonical_items,
        'shippingAddress', coalesce(p_shipping_address, '{}'::jsonb),
        'billingAddress', coalesce(p_billing_address, '{}'::jsonb),
        'metadata', coalesce(p_metadata, '{}'::jsonb)
    )::text);
    select * into v_existing from commerce.orders
    where buyer_cms_user_id = p_buyer_cms_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_existing.request_hash <> v_request_hash then
            raise exception 'conflict: idempotency key was already used for a different order';
        end if;
        return to_jsonb(v_existing) || jsonb_build_object('idempotent_replay', true);
    end if;
    perform commerce.assert_custom_fields('order', coalesce(p_metadata, '{}'::jsonb), 'self');

    select array_agg(distinct (item->>'offerId')::bigint order by (item->>'offerId')::bigint)
    into v_offer_ids
    from jsonb_array_elements(p_items) item;
    if v_offer_ids is null then raise exception 'validation: every order item needs an offerId'; end if;
    perform seller.id
    from commerce.sellers seller
    join commerce.offers offer on offer.seller_id = seller.id
    where offer.id = any(v_offer_ids)
    order by seller.id
    for share of seller;
    perform product.id
    from commerce.products product
    join commerce.offers offer on offer.product_id = product.id
    where offer.id = any(v_offer_ids)
    order by product.id
    for share of product;
    perform variant.id
    from commerce.product_variants variant
    join commerce.offers offer on offer.variant_id = variant.id
    where offer.id = any(v_offer_ids)
    order by variant.id
    for share of variant;
    perform state.code
    from commerce.offer_workflow_states state
    join commerce.offers offer on offer.workflow_state = state.code
    where offer.id = any(v_offer_ids)
    order by state.code
    for share of state;
    perform id from commerce.offers where id = any(v_offer_ids) order by id for update;
    if (select count(*) from commerce.offers where id = any(v_offer_ids)) <> cardinality(v_offer_ids) then
        raise exception 'not_found: offer';
    end if;

    for v_item in select value from jsonb_array_elements(p_items)
    loop
        v_quantity := nullif(v_item->>'quantity', '')::integer;
        if v_quantity is null or v_quantity <= 0 then raise exception 'validation: quantity must be positive'; end if;
        select * into v_offer from commerce.offers where id = (v_item->>'offerId')::bigint;
        if v_offer.publication_status <> 'active'
            or not exists (
                select 1 from commerce.offer_workflow_states
                where code = v_offer.workflow_state and phase = 'ready' and enabled
            )
            or v_offer.availability = 'unavailable' or v_offer.accepted_price_amount is null then
            raise exception 'conflict: offer % is not sellable', v_offer.id;
        end if;
        if v_offer.quantity_available is not null and v_offer.quantity_available < v_quantity then
            raise exception 'conflict: insufficient quantity for offer %', v_offer.id;
        end if;
        if not exists (
            select 1 from commerce.products
            where id = v_offer.product_id and status = 'active' and visibility = 'public'
        ) then
            raise exception 'conflict: product for offer % is not sellable', v_offer.id;
        end if;
        perform commerce.assert_product_variant_ready(v_offer.product_id, v_offer.variant_id);
        select * into v_seller from commerce.sellers where id = v_offer.seller_id;
        if v_seller.cms_user_id = p_buyer_cms_user_id then
            raise exception 'forbidden: buyers cannot purchase their own offer';
        end if;
        if v_seller.verification_status in ('rejected', 'suspended')
            or (v_settings.require_verified_seller and v_seller.verification_status <> 'verified') then
            raise exception 'conflict: seller for offer % is not allowed to sell', v_offer.id;
        end if;
        if v_settings.mode = 'ecommerce' and v_seller.kind = 'user' then
            raise exception 'conflict: marketplace offers are disabled';
        end if;
        if v_seller_id is null then
            v_seller_id := v_offer.seller_id;
            v_currency := v_offer.currency;
        elsif v_seller_id <> v_offer.seller_id then
            raise exception 'conflict: one order cannot contain multiple sellers';
        elsif v_currency <> v_offer.currency then
            raise exception 'conflict: one order cannot contain multiple currencies';
        end if;
        v_subtotal := v_subtotal + (v_offer.accepted_price_amount * v_quantity);
        if v_subtotal > 9007199254740991 then
            raise exception 'validation: order total exceeds the supported maximum';
        end if;
    end loop;

    insert into commerce.orders (
        order_number, seller_id, buyer_cms_user_id, currency,
        subtotal_amount, total_amount, shipping_address, billing_address,
        metadata, idempotency_key, request_hash
    ) values (
        'CO-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 24)),
        v_seller_id, p_buyer_cms_user_id, v_currency,
        v_subtotal, v_subtotal, coalesce(p_shipping_address, '{}'::jsonb),
        coalesce(p_billing_address, '{}'::jsonb), coalesce(p_metadata, '{}'::jsonb),
        p_idempotency_key, v_request_hash
    ) returning * into v_order;

    for v_item in select value from jsonb_array_elements(p_items)
    loop
        v_quantity := (v_item->>'quantity')::integer;
        select * into v_offer from commerce.offers where id = (v_item->>'offerId')::bigint;
        select * into v_product from commerce.products where id = v_offer.product_id;
        if v_offer.variant_id is not null then
            select * into v_variant from commerce.product_variants where id = v_offer.variant_id;
        else
            v_variant := null;
        end if;
        select * into v_seller from commerce.sellers where id = v_offer.seller_id;
        select id into v_proposal_id from commerce.offer_price_proposals
        where offer_id = v_offer.id and status = 'accepted'
        order by decided_at desc nulls last, id desc limit 1;

        insert into commerce.order_lines (
            order_id, seller_id, offer_id, product_id, variant_id, accepted_proposal_id,
            title, sku, quantity, inventory_reserved, availability_before, inventory_revision_before,
            unit_amount, total_amount,
            product_snapshot, variant_snapshot, offer_snapshot, seller_snapshot
        ) values (
            v_order.id, v_offer.seller_id, v_offer.id, v_product.id, v_offer.variant_id, v_proposal_id,
            v_offer.title, v_variant.sku, v_quantity,
            case when v_offer.quantity_available is null then 0 else v_quantity end,
            case when v_offer.quantity_available is null then null else v_offer.availability end,
            case when v_offer.quantity_available is null then null else v_offer.inventory_revision end,
            v_offer.accepted_price_amount,
            v_offer.accepted_price_amount * v_quantity,
            jsonb_build_object(
                'id', v_product.id,
                'slug', v_product.slug,
                'title', v_product.title
            ),
            case when v_offer.variant_id is null then null else jsonb_build_object(
                'id', v_variant.id,
                'sku', v_variant.sku,
                'title', v_variant.title,
                'combinationKey', v_variant.combination_key,
                'options', coalesce((
                    select jsonb_agg(jsonb_build_object(
                        'axisKey', axis.key,
                        'axisLabel', axis.label,
                        'valueKey', axis_value.key,
                        'valueLabel', axis_value.label
                    ) order by axis.position, axis.id)
                    from commerce.product_variant_selections selection
                    join commerce.product_variant_axes axis
                      on axis.product_id = selection.product_id and axis.id = selection.axis_id
                    join commerce.product_variant_axis_values axis_value
                      on axis_value.product_id = selection.product_id
                     and axis_value.axis_id = selection.axis_id
                     and axis_value.id = selection.value_id
                    where selection.product_id = v_product.id
                      and selection.variant_id = v_variant.id
                ), '[]'::jsonb)
            ) end,
            jsonb_build_object(
                'id', v_offer.id,
                'slug', v_offer.slug,
                'title', v_offer.title,
                'conditionCode', v_offer.condition_code,
                'acceptedPriceAmount', v_offer.accepted_price_amount,
                'currency', v_offer.currency
            ),
            jsonb_build_object(
                'id', v_seller.id,
                'kind', v_seller.kind,
                'slug', v_seller.slug,
                'displayName', v_seller.display_name
            )
        );
        if v_offer.quantity_available is not null then
            update commerce.offers
            set quantity_available = quantity_available - v_quantity,
                availability = case when quantity_available - v_quantity = 0 then 'unavailable' else availability end
            where id = v_offer.id;
        end if;
    end loop;

    insert into commerce.order_events (
        order_id, event_type, actor_kind, actor_id, previous_status, next_status
    ) values (v_order.id, 'order_created', 'buyer', p_buyer_cms_user_id, null, 'awaiting_quote');
    return to_jsonb(v_order) || jsonb_build_object('idempotent_replay', false);
end;
$$;

create or replace function commerce.checkout_cart(
    p_buyer_cms_user_id text,
    p_idempotency_key text,
    p_expected_version integer,
    p_shipping_address jsonb default '{}'::jsonb,
    p_billing_address jsonb default '{}'::jsonb,
    p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_cart commerce.carts%rowtype;
    v_group commerce.checkout_groups%rowtype;
    v_items jsonb;
    v_request_hash text;
    v_seller_id bigint;
    v_seller_items jsonb;
    v_order_result jsonb;
    v_order_id bigint;
    v_temporary_group_id uuid;
    v_currency_count integer;
begin
    if p_buyer_cms_user_id is null or length(btrim(p_buyer_cms_user_id)) = 0 then
        raise exception 'forbidden: missing CMS user id';
    end if;
    if p_idempotency_key is null or length(btrim(p_idempotency_key)) = 0 then
        raise exception 'validation: idempotency key is required';
    end if;
    if jsonb_typeof(coalesce(p_shipping_address, '{}'::jsonb)) <> 'object'
        or jsonb_typeof(coalesce(p_billing_address, '{}'::jsonb)) <> 'object'
        or jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object' then
        raise exception 'validation: checkout objects are invalid';
    end if;
    perform pg_advisory_xact_lock(hashtextextended(
        p_buyer_cms_user_id || ':' || p_idempotency_key, 0
    ));
    select * into v_group from commerce.checkout_groups
    where buyer_cms_user_id = p_buyer_cms_user_id
      and idempotency_key = p_idempotency_key;
    if found then
        if v_group.source_cart_id is null then
            raise exception 'conflict: idempotency key was already used outside this cart';
        end if;
        select * into v_cart from commerce.carts
        where id = v_group.source_cart_id and buyer_cms_user_id = p_buyer_cms_user_id;
    else
        select * into v_cart from commerce.carts
        where buyer_cms_user_id = p_buyer_cms_user_id and status = 'open'
        for update;
        if not found then raise exception 'not_found: cart'; end if;
        if p_expected_version is null or v_cart.version is distinct from p_expected_version then
            raise exception 'conflict: stale cart version';
        end if;
    end if;
    select jsonb_agg(jsonb_build_object(
        'offerId', offer_id,
        'quantity', quantity
    ) order by offer_id)
    into v_items
    from commerce.cart_items
    where cart_id = v_cart.id;
    if v_items is null or jsonb_array_length(v_items) = 0 then
        raise exception 'validation: cart is empty';
    end if;
    v_request_hash := md5(jsonb_build_object(
        'sourceCartId', v_cart.id,
        'items', v_items,
        'shippingAddress', coalesce(p_shipping_address, '{}'::jsonb),
        'billingAddress', coalesce(p_billing_address, '{}'::jsonb),
        'metadata', coalesce(p_metadata, '{}'::jsonb)
    )::text);
    if v_group.id is not null then
        if v_group.request_hash <> v_request_hash then
            raise exception 'conflict: idempotency key was already used for a different checkout';
        end if;
        return commerce.checkout_group_result(v_group.id, true);
    end if;
    perform offer.id
    from commerce.offers offer
    join commerce.cart_items item on item.offer_id = offer.id
    where item.cart_id = v_cart.id
    order by offer.id
    for update of offer;
    select count(distinct offer.currency) into v_currency_count
    from commerce.offers offer
    join commerce.cart_items item on item.offer_id = offer.id
    where item.cart_id = v_cart.id;
    if v_currency_count <> 1 then
        raise exception 'conflict: one cart cannot contain multiple currencies';
    end if;
    insert into commerce.checkout_groups (
        buyer_cms_user_id, source_cart_id, idempotency_key, request_hash
    ) values (
        p_buyer_cms_user_id, v_cart.id, p_idempotency_key, v_request_hash
    ) returning * into v_group;
    for v_seller_id in
        select distinct offer.seller_id
        from commerce.offers offer
        join commerce.cart_items item on item.offer_id = offer.id
        where item.cart_id = v_cart.id
        order by offer.seller_id
    loop
        select jsonb_agg(jsonb_build_object(
            'offerId', item.offer_id,
            'quantity', item.quantity
        ) order by item.offer_id)
        into v_seller_items
        from commerce.cart_items item
        join commerce.offers offer on offer.id = item.offer_id
        where item.cart_id = v_cart.id and offer.seller_id = v_seller_id;
        v_order_result := commerce.create_order_from_offers(
            p_buyer_cms_user_id,
            'cart:' || v_group.id::text || ':' || v_seller_id::text,
            v_seller_items,
            coalesce(p_shipping_address, '{}'::jsonb),
            coalesce(p_billing_address, '{}'::jsonb),
            coalesce(p_metadata, '{}'::jsonb)
        );
        v_order_id := (v_order_result->>'id')::bigint;
        v_temporary_group_id := (v_order_result->>'checkout_group_id')::uuid;
        update commerce.orders
        set checkout_group_id = v_group.id,
            idempotency_key = p_idempotency_key,
            request_hash = v_request_hash
        where id = v_order_id;
        delete from commerce.checkout_groups
        where id = v_temporary_group_id and id <> v_group.id;
    end loop;
    update commerce.carts
    set status = 'converted', converted_at = now()
    where id = v_cart.id;
    return commerce.checkout_group_result(v_group.id, false);
end;
$$;

create or replace function commerce.transition_order(
    p_order_id bigint,
    p_next_status text,
    p_admin_id text,
    p_expected_version integer,
    p_message text default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_order commerce.orders%rowtype; v_previous text;
begin
    raise exception 'conflict: generic order transitions were removed; use an explicit protected command';
    select * into v_order from commerce.orders where id = p_order_id for update;
    if not found then raise exception 'not_found: order'; end if;
    if v_order.version is distinct from p_expected_version then raise exception 'conflict: stale order version'; end if;
    if not (
        (v_order.status = 'placed' and p_next_status in ('cancelled', 'completed'))
        or (v_order.status in ('cancelled', 'completed') and p_next_status = 'archived')
    ) then raise exception 'conflict: order transition is not allowed'; end if;
    v_previous := v_order.status;
    if v_previous = 'placed' and p_next_status = 'cancelled' then
        perform offer.id
        from commerce.offers offer
        join commerce.order_lines line on line.offer_id = offer.id
        where line.order_id = v_order.id
        order by offer.id
        for update of offer;
        update commerce.offers offer
        set quantity_available = offer.quantity_available + restored.quantity,
            availability = case
                when offer.availability = 'unavailable' and offer.quantity_available = 0
                    and offer.inventory_revision = restored.inventory_revision_before
                    then restored.availability_before
                else offer.availability
            end
        from (
            select
                offer_id,
                sum(inventory_reserved)::integer as quantity,
                min(availability_before) as availability_before,
                min(inventory_revision_before) as inventory_revision_before
            from commerce.order_lines
            where order_id = v_order.id
              and inventory_reserved > 0
            group by offer_id
        ) restored
        where offer.id = restored.offer_id
          and offer.quantity_available is not null;
    end if;
    update commerce.orders set status = p_next_status where id = p_order_id returning * into v_order;
    insert into commerce.order_events (
        order_id, event_type, actor_kind, actor_id, previous_status, next_status, message
    ) values (
        v_order.id, 'status_changed', 'admin', coalesce(nullif(p_admin_id, ''), 'cms-admin'),
        v_previous, p_next_status, p_message
    );
    return to_jsonb(v_order);
end;
$$;

drop function if exists commerce.apply_delivery_quote(uuid, text, bigint, text, integer);

create or replace function commerce.estimate_offer_price(
    p_product_id bigint,
    p_variant_id bigint default null,
    p_condition_code text default null
)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
    v_scope text;
    v_scope_index integer;
    v_sample_size integer;
    v_currency text;
    v_observed_minimum bigint;
    v_observed_maximum bigint;
    v_median bigint;
    v_typical_minimum bigint;
    v_typical_maximum bigint;
begin
    if not exists (
        select 1 from commerce.products
        where id = p_product_id and status = 'active' and visibility = 'public'
    ) then
        raise exception 'not_found: product';
    end if;
    if p_variant_id is not null and not exists (
        select 1 from commerce.product_variants
        where id = p_variant_id and product_id = p_product_id and status = 'active'
    ) then
        raise exception 'validation: variant does not belong to product';
    end if;
    if p_condition_code is not null and not exists (
        select 1 from commerce.offer_conditions where code = p_condition_code and enabled
    ) then
        raise exception 'validation: unsupported offer condition';
    end if;

    for v_scope_index in 1..3 loop
        v_scope := case v_scope_index
            when 1 then 'variant_and_condition'
            when 2 then 'product_and_condition'
            else 'product'
        end;
        if v_scope_index = 1 and (p_variant_id is null or p_condition_code is null) then continue; end if;
        if v_scope_index = 2 and p_condition_code is null then continue; end if;

        with comparable as (
            select line.unit_amount as amount, order_row.currency, line.created_at
            from commerce.order_lines line
            join commerce.orders order_row on order_row.id = line.order_id
            where line.product_id = p_product_id
              and line.created_at >= now() - interval '18 months'
              and (v_scope_index <> 1 or line.variant_id = p_variant_id)
              and (v_scope_index = 3 or line.offer_snapshot->>'conditionCode' = p_condition_code)
            union all
            select offer.accepted_price_amount, offer.currency, offer.updated_at
            from commerce.offers offer
            where offer.product_id = p_product_id
              and offer.accepted_price_amount is not null
              and offer.updated_at >= now() - interval '18 months'
              and offer.workflow_state <> 'rejected'
              and (v_scope_index <> 1 or offer.variant_id = p_variant_id)
              and (v_scope_index = 3 or offer.condition_code = p_condition_code)
              and not exists (select 1 from commerce.order_lines line where line.offer_id = offer.id)
        ), recent as (
            select amount, currency
            from comparable
            order by created_at desc
            limit 20
        )
        select count(*)::integer,
               case when count(distinct currency) = 1 then min(currency) end,
               min(amount), max(amount),
               percentile_cont(0.5) within group (order by amount)::bigint,
               percentile_cont(0.25) within group (order by amount)::bigint,
               percentile_cont(0.75) within group (order by amount)::bigint
        into v_sample_size, v_currency, v_observed_minimum, v_observed_maximum,
             v_median, v_typical_minimum, v_typical_maximum
        from recent;

        if v_sample_size >= 3 and v_currency is not null then
            return jsonb_build_object(
                'available', true,
                'currency', v_currency,
                'scope', v_scope,
                'sampleSize', v_sample_size,
                'observedMinimumAmount', v_observed_minimum,
                'observedMaximumAmount', v_observed_maximum,
                'medianAmount', v_median,
                'estimatedMinimumAmount', v_typical_minimum,
                'estimatedMaximumAmount', v_typical_maximum
            );
        end if;
    end loop;

    return jsonb_build_object(
        'available', false,
        'currency', null,
        'scope', 'insufficient_data',
        'sampleSize', coalesce(v_sample_size, 0),
        'observedMinimumAmount', null,
        'observedMaximumAmount', null,
        'medianAmount', null,
        'estimatedMinimumAmount', null,
        'estimatedMaximumAmount', null
    );
end;
$$;

create or replace function commerce.round_half_up_fee(
    p_basis_amount bigint,
    p_rate_bps integer,
    p_fixed_amount bigint,
    p_minimum_amount bigint default null,
    p_maximum_amount bigint default null
)
returns bigint
language plpgsql
immutable
set search_path = ''
as $$
declare v_amount numeric;
begin
    if p_basis_amount < 0 or p_rate_bps not between 0 and 10000 or p_fixed_amount < 0 then
        raise exception 'validation: invalid fee component';
    end if;
    v_amount := floor((p_basis_amount::numeric * p_rate_bps::numeric + 5000) / 10000)
        + p_fixed_amount;
    if p_minimum_amount is not null then v_amount := greatest(v_amount, p_minimum_amount); end if;
    if p_maximum_amount is not null then v_amount := least(v_amount, p_maximum_amount); end if;
    if v_amount < 0 or v_amount > 9007199254740991 then
        raise exception 'validation: calculated fee exceeds supported amount';
    end if;
    return v_amount::bigint;
end;
$$;

create or replace function commerce.append_financial_event(
    p_order_id bigint,
    p_aggregate_type text,
    p_aggregate_id text,
    p_event_type text,
    p_actor_kind text,
    p_actor_id text,
    p_reason text,
    p_data jsonb,
    p_topic text,
    p_event_key text
)
returns void
language plpgsql
set search_path = ''
as $$
begin
    insert into commerce.audit_events (
        order_id, aggregate_type, aggregate_id, event_type,
        actor_kind, actor_id, reason, data
    ) values (
        p_order_id, p_aggregate_type, p_aggregate_id, p_event_type,
        p_actor_kind, p_actor_id, p_reason, coalesce(p_data, '{}'::jsonb)
    );
    insert into commerce.outbox_events (order_id, topic, event_key, payload)
    values (
        p_order_id, p_topic, p_event_key,
        jsonb_build_object(
            'orderId', p_order_id,
            'aggregateType', p_aggregate_type,
            'aggregateId', p_aggregate_id,
            'eventType', p_event_type,
            'data', coalesce(p_data, '{}'::jsonb)
        )
    ) on conflict (event_key) do nothing;
end;
$$;

create or replace function commerce.claim_provider_projection_event(
    p_authority text,
    p_provider_event_id text,
    p_order_id bigint,
    p_event_type text,
    p_occurred_at timestamptz,
    p_payload jsonb
)
returns bigint
language plpgsql
set search_path = ''
as $$
declare
    v_id bigint;
    v_existing commerce.provider_projection_events%rowtype;
begin
    insert into commerce.provider_projection_events (
        authority, provider_event_id, order_id, event_type, occurred_at, payload
    ) values (
        p_authority, p_provider_event_id, p_order_id, p_event_type,
        p_occurred_at, coalesce(p_payload, '{}'::jsonb)
    ) on conflict (authority, provider_event_id) do nothing returning id into v_id;
    if v_id is not null then return v_id; end if;
    select * into v_existing from commerce.provider_projection_events
    where authority = p_authority and provider_event_id = p_provider_event_id;
    if v_existing.order_id is distinct from p_order_id
        or v_existing.event_type is distinct from p_event_type
        or v_existing.occurred_at is distinct from p_occurred_at
        or v_existing.payload is distinct from coalesce(p_payload, '{}'::jsonb) then
        raise exception 'conflict: provider event replay changed canonical payload';
    end if;
    return null;
end;
$$;

create or replace function commerce.get_c2c_policy_configuration_read_model()
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    select coalesce((
        select jsonb_build_object(
            'state', 'ok',
            'settings', jsonb_build_object(
                'id', settings.id,
                'mode', settings.mode,
                'default_currency', settings.default_currency,
                'active_c2c_fee_policy_id', settings.active_c2c_fee_policy_id,
                'active_c2c_protection_policy_id', settings.active_c2c_protection_policy_id,
                'active_c2c_seller_risk_policy_id', settings.active_c2c_seller_risk_policy_id,
                'version', settings.version,
                'updated_at', settings.updated_at
            ),
            'fee_policy', (
                select jsonb_build_object(
                    'id', fee.id,
                    'policy_key', fee.policy_key,
                    'version', fee.version,
                    'name', fee.name,
                    'status', fee.status,
                    'currency', fee.currency,
                    'shipping_beneficiary', fee.shipping_beneficiary,
                    'estimated_stripe_cost_amount', fee.estimated_stripe_cost_amount,
                    'estimated_carrier_cost_amount', fee.estimated_carrier_cost_amount,
                    'platform_risk_reserve_contribution_amount',
                        fee.platform_risk_reserve_contribution_amount,
                    'configured_minimum_margin_amount', fee.configured_minimum_margin_amount,
                    'cost_estimates_configured', fee.cost_estimates_configured,
                    'subsidy_override', fee.subsidy_override,
                    'subsidy_reason', fee.subsidy_reason,
                    'published_at', fee.published_at,
                    'created_by', fee.created_by,
                    'created_at', fee.created_at
                )
                from commerce.fee_policies fee
                where fee.id = settings.active_c2c_fee_policy_id
            ),
            'protection_policy', (
                select jsonb_build_object(
                    'id', protection.id,
                    'policy_key', protection.policy_key,
                    'version', protection.version,
                    'name', protection.name,
                    'status', protection.status,
                    'currency', protection.currency,
                    'payment_window_minutes', protection.payment_window_minutes,
                    'seller_handoff_hours', protection.seller_handoff_hours,
                    'scan_grace_hours', protection.scan_grace_hours,
                    'claim_window_hours', protection.claim_window_hours,
                    'seller_response_hours', protection.seller_response_hours,
                    'return_ship_hours', protection.return_ship_hours,
                    'finance_review_threshold_amount',
                        protection.finance_review_threshold_amount,
                    'dual_approval_threshold_amount', protection.dual_approval_threshold_amount,
                    'published_at', protection.published_at,
                    'created_by', protection.created_by,
                    'created_at', protection.created_at
                )
                from commerce.protection_policies protection
                where protection.id = settings.active_c2c_protection_policy_id
            ),
            'seller_risk_policy', (
                select jsonb_build_object(
                    'id', risk.id,
                    'policy_key', risk.policy_key,
                    'version', risk.version,
                    'name', risk.name,
                    'status', risk.status,
                    'currency', risk.currency,
                    'reserve_rate_bps', risk.reserve_rate_bps,
                    'payout_delay_days', risk.payout_delay_days,
                    'reserve_liability_days', risk.reserve_liability_days,
                    'order_transfer_limit_amount', risk.order_transfer_limit_amount,
                    'velocity_limit_amount', risk.velocity_limit_amount,
                    'high_value_review_amount', risk.high_value_review_amount,
                    'claim_ratio_review_bps', risk.claim_ratio_review_bps,
                    'chargeback_ratio_review_bps', risk.chargeback_ratio_review_bps,
                    'published_at', risk.published_at,
                    'created_by', risk.created_by,
                    'created_at', risk.created_at
                )
                from commerce.seller_risk_policies risk
                where risk.id = settings.active_c2c_seller_risk_policy_id
            ),
            'components', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', component.id,
                    'fee_policy_id', component.fee_policy_id,
                    'component_key', component.component_key,
                    'payer', component.payer,
                    'basis', component.basis,
                    'rate_bps', component.rate_bps,
                    'fixed_amount', component.fixed_amount,
                    'minimum_amount', component.minimum_amount,
                    'maximum_amount', component.maximum_amount,
                    'rounding_mode', component.rounding_mode,
                    'refund_policy', component.refund_policy,
                    'position', component.position,
                    'created_at', component.created_at
                ) order by component.position, component.id)
                from commerce.fee_policy_components component
                where component.fee_policy_id = settings.active_c2c_fee_policy_id
            ), '[]'::jsonb),
            'subsidy_overrides', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', subsidy.id,
                    'fee_policy_id', subsidy.fee_policy_id,
                    'maximum_deficit_amount', subsidy.maximum_deficit_amount,
                    'reason', subsidy.reason,
                    'approved_by', subsidy.approved_by,
                    'expires_at', subsidy.expires_at,
                    'created_at', subsidy.created_at
                ) order by subsidy.created_at desc)
                from commerce.financial_subsidy_overrides subsidy
                where subsidy.fee_policy_id = settings.active_c2c_fee_policy_id
            ), '[]'::jsonb)
        )
        from commerce.settings settings
        where settings.id = 'default'
    ), jsonb_build_object('state', 'settings_missing'));
$$;

revoke execute on function commerce.get_c2c_policy_configuration_read_model()
from public, anon, authenticated;
grant execute on function commerce.get_c2c_policy_configuration_read_model()
to service_role;

create or replace function commerce.create_c2c_policy_revision(
    p_payload jsonb,
    p_actor_id text,
    p_expected_settings_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_settings commerce.settings%rowtype;
    v_fee commerce.fee_policies%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_risk commerce.seller_risk_policies%rowtype;
    v_version integer;
    v_subsidy_amount bigint;
    v_subsidy_reason text;
    v_guaranteed_fee_floor bigint;
    v_required_revenue_floor bigint;
    v_policy_deficit bigint;
begin
    if p_actor_id is null or length(btrim(p_actor_id)) = 0 then
        raise exception 'forbidden: admin actor is required';
    end if;
    if jsonb_typeof(p_payload) <> 'object' then
        raise exception 'validation: policy payload must be an object';
    end if;
    if coalesce(nullif(p_payload->>'sellerFeeRefundPolicy', ''), 'never') <> 'never' then
        raise exception 'validation: seller commission refund policy is not implemented; use never';
    end if;
    if not coalesce((p_payload->>'costEstimatesConfigured')::boolean, false)
        and not coalesce((p_payload->>'subsidyOverride')::boolean, false) then
        raise exception 'validation: unconfigured cost estimates require an audited subsidy override';
    end if;
    if coalesce((p_payload->>'costEstimatesConfigured')::boolean, false)
        and coalesce((p_payload->>'estimatedStripeCostAmount')::bigint, 0) <= 0 then
        raise exception 'validation: configured provider costs require a positive Stripe cost estimate';
    end if;
    if (nullif(p_payload->>'buyerFeeMaximumAmount', '') is not null
            and coalesce((p_payload->>'buyerFeeFixedAmount')::bigint, 0)
                > (p_payload->>'buyerFeeMaximumAmount')::bigint)
        or (nullif(p_payload->>'sellerFeeMaximumAmount', '') is not null
            and coalesce((p_payload->>'sellerFeeFixedAmount')::bigint, 0)
                > (p_payload->>'sellerFeeMaximumAmount')::bigint) then
        raise exception 'validation: fee fixed amount cannot exceed its maximum amount';
    end if;
    v_subsidy_amount := nullif(p_payload->>'subsidyMaximumDeficitAmount', '')::bigint;
    v_subsidy_reason := nullif(p_payload->>'subsidyReason', '');
    v_guaranteed_fee_floor :=
        least(
            greatest(
                coalesce((p_payload->>'buyerFeeFixedAmount')::bigint, 0),
                coalesce((p_payload->>'buyerFeeMinimumAmount')::bigint, 0)
            ),
            coalesce((p_payload->>'buyerFeeMaximumAmount')::bigint, 9007199254740991)
        )
        + least(
            greatest(
                coalesce((p_payload->>'sellerFeeFixedAmount')::bigint, 0),
                coalesce((p_payload->>'sellerFeeMinimumAmount')::bigint, 0)
            ),
            coalesce((p_payload->>'sellerFeeMaximumAmount')::bigint, 9007199254740991)
        );
    v_required_revenue_floor :=
        coalesce((p_payload->>'estimatedStripeCostAmount')::bigint, 0)
        + coalesce((p_payload->>'estimatedCarrierCostAmount')::bigint, 0)
        + coalesce((p_payload->>'platformRiskReserveContributionAmount')::bigint, 0)
        + coalesce((p_payload->>'configuredMinimumMarginAmount')::bigint, 0);
    v_policy_deficit := greatest(0, v_required_revenue_floor - v_guaranteed_fee_floor);
    if coalesce((p_payload->>'costEstimatesConfigured')::boolean, false)
        and v_policy_deficit > 0
        and not coalesce((p_payload->>'subsidyOverride')::boolean, false) then
        raise exception 'validation: guaranteed fee floor does not cover configured costs and minimum margin';
    end if;
    if coalesce((p_payload->>'subsidyOverride')::boolean, false)
        and (v_subsidy_amount is null or v_subsidy_reason is null) then
        raise exception 'validation: an audited subsidy amount and reason are required';
    end if;
    if coalesce((p_payload->>'subsidyOverride')::boolean, false)
        and v_subsidy_amount < v_policy_deficit then
        raise exception 'validation: audited subsidy maximum does not cover the configured policy deficit';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('commerce-c2c-policy', 0));
    select * into v_settings from commerce.settings where id = 'default' for update;
    if v_settings.version is distinct from p_expected_settings_version then
        raise exception 'conflict: stale settings version';
    end if;
    select greatest(
        coalesce((select max(version) from commerce.fee_policies where policy_key = 'c2c-default'), 0),
        coalesce((select max(version) from commerce.protection_policies where policy_key = 'c2c-default'), 0),
        coalesce((select max(version) from commerce.seller_risk_policies where policy_key = 'c2c-default'), 0)
    ) + 1 into v_version;

    insert into commerce.fee_policies (
        policy_key, version, name, status, currency, shipping_beneficiary,
        estimated_stripe_cost_amount, estimated_carrier_cost_amount,
        platform_risk_reserve_contribution_amount, configured_minimum_margin_amount,
        cost_estimates_configured, subsidy_override, subsidy_reason, published_at, created_by
    ) values (
        'c2c-default', v_version,
        coalesce(nullif(p_payload->>'name', ''), 'Protected C2C revision ' || v_version),
        'published', 'eur', coalesce(nullif(p_payload->>'shippingBeneficiary', ''), 'platform'),
        coalesce((p_payload->>'estimatedStripeCostAmount')::bigint, 0),
        coalesce((p_payload->>'estimatedCarrierCostAmount')::bigint, 0),
        coalesce((p_payload->>'platformRiskReserveContributionAmount')::bigint, 0),
        coalesce((p_payload->>'configuredMinimumMarginAmount')::bigint, 0),
        coalesce((p_payload->>'costEstimatesConfigured')::boolean, false),
        coalesce((p_payload->>'subsidyOverride')::boolean, false),
        nullif(p_payload->>'subsidyReason', ''), now(), p_actor_id
    ) returning * into v_fee;

    insert into commerce.fee_policy_components (
        fee_policy_id, component_key, payer, basis, rate_bps, fixed_amount,
        minimum_amount, maximum_amount, refund_policy, position
    ) values
    (
        v_fee.id, 'buyer_protection', 'buyer',
        coalesce(nullif(p_payload->>'buyerFeeBasis', ''), 'merchandise'),
        coalesce((p_payload->>'buyerFeeRateBps')::integer, 0),
        coalesce((p_payload->>'buyerFeeFixedAmount')::bigint, 0),
        nullif(p_payload->>'buyerFeeMinimumAmount', '')::bigint,
        nullif(p_payload->>'buyerFeeMaximumAmount', '')::bigint,
        coalesce(nullif(p_payload->>'buyerFeeRefundPolicy', ''), 'resolution_defined'), 10
    ),
    (
        v_fee.id, 'seller_commission', 'seller',
        coalesce(nullif(p_payload->>'sellerFeeBasis', ''), 'merchandise'),
        coalesce((p_payload->>'sellerFeeRateBps')::integer, 0),
        coalesce((p_payload->>'sellerFeeFixedAmount')::bigint, 0),
        nullif(p_payload->>'sellerFeeMinimumAmount', '')::bigint,
        nullif(p_payload->>'sellerFeeMaximumAmount', '')::bigint,
        'never', 20
    );

    insert into commerce.protection_policies (
        policy_key, version, name, status, currency, payment_window_minutes,
        seller_handoff_hours, scan_grace_hours, claim_window_hours,
        seller_response_hours, return_ship_hours, finance_review_threshold_amount,
        dual_approval_threshold_amount, published_at, created_by
    ) values (
        'c2c-default', v_version, v_fee.name, 'published', 'eur',
        coalesce((p_payload->>'paymentWindowMinutes')::integer, 30),
        coalesce((p_payload->>'sellerHandoffHours')::integer, 72),
        coalesce((p_payload->>'scanGraceHours')::integer, 48),
        coalesce((p_payload->>'claimWindowHours')::integer, 48),
        coalesce((p_payload->>'sellerResponseHours')::integer, 72),
        coalesce((p_payload->>'returnShipHours')::integer, 168),
        coalesce((p_payload->>'financeReviewThresholdAmount')::bigint, 50000),
        coalesce((p_payload->>'dualApprovalThresholdAmount')::bigint, 100000),
        now(), p_actor_id
    ) returning * into v_protection;

    insert into commerce.seller_risk_policies (
        policy_key, version, name, status, currency, reserve_rate_bps,
        payout_delay_days, reserve_liability_days, order_transfer_limit_amount, velocity_limit_amount,
        high_value_review_amount, claim_ratio_review_bps,
        chargeback_ratio_review_bps, published_at, created_by
    ) values (
        'c2c-default', v_version, v_fee.name, 'published', 'eur',
        coalesce((p_payload->>'sellerReserveRateBps')::integer, 1000),
        coalesce((p_payload->>'payoutDelayDays')::integer, 14),
        coalesce((p_payload->>'sellerReserveLiabilityDays')::integer, 120),
        coalesce((p_payload->>'orderTransferLimitAmount')::bigint, 500000),
        coalesce((p_payload->>'velocityLimitAmount')::bigint, 1000000),
        coalesce((p_payload->>'highValueReviewAmount')::bigint, 50000),
        coalesce((p_payload->>'claimRatioReviewBps')::integer, 1000),
        coalesce((p_payload->>'chargebackRatioReviewBps')::integer, 200),
        now(), p_actor_id
    ) returning * into v_risk;

    if v_fee.subsidy_override then
        insert into commerce.financial_subsidy_overrides (
            fee_policy_id, maximum_deficit_amount, reason, approved_by
        ) values (v_fee.id, v_subsidy_amount, v_subsidy_reason, p_actor_id);
    end if;

    update commerce.settings set
        active_c2c_fee_policy_id = v_fee.id,
        active_c2c_protection_policy_id = v_protection.id,
        active_c2c_seller_risk_policy_id = v_risk.id
    where id = 'default';
    return jsonb_build_object(
        'feePolicyId', v_fee.id,
        'protectionPolicyId', v_protection.id,
        'sellerRiskPolicyId', v_risk.id,
        'policyVersion', v_version,
        'settingsVersion', v_settings.version + 1
    );
end;
$$;

create or replace function commerce.refresh_seller_risk_state(p_seller_id bigint)
returns commerce.seller_risk_states
language plpgsql
set search_path = ''
as $$
declare
    v_reserve bigint;
    v_at_risk bigint;
    v_debt bigint;
    v_state commerce.seller_risk_states%rowtype;
begin
    select coalesce(sum(settlement.seller_reserve_liability_remaining_amount), 0)
    into v_reserve
    from commerce.order_settlements settlement
    join commerce.orders order_row on order_row.id = settlement.order_id
    where order_row.seller_id = p_seller_id
      and settlement.seller_reserve_liability_remaining_amount > 0
      and settlement.status not in ('refunded', 'reversed');

    select
        coalesce(sum(amount - recovered_amount) filter (where status = 'at_risk'), 0),
        coalesce(sum(amount - recovered_amount) filter (where status = 'debt'), 0)
    into v_at_risk, v_debt
    from commerce.seller_financial_exposures
    where seller_id = p_seller_id;

    insert into commerce.seller_risk_states (
        seller_id, status, reserve_liability_amount, at_risk_exposure_amount,
        outstanding_debt_amount, hold_reason, updated_at
    ) values (
        p_seller_id,
        case when v_debt > 0 then 'blocked'
            when v_at_risk > 0 then 'restricted'
            when v_reserve > 0 then 'monitored'
            else 'standard' end,
        v_reserve, v_at_risk, v_debt,
        case when v_debt > 0 then 'Unrecovered seller debt'
            when v_at_risk > 0 then 'Open seller financial exposure'
            else null end,
        now()
    ) on conflict (seller_id) do update set
        status = excluded.status,
        reserve_liability_amount = excluded.reserve_liability_amount,
        at_risk_exposure_amount = excluded.at_risk_exposure_amount,
        outstanding_debt_amount = excluded.outstanding_debt_amount,
        hold_reason = excluded.hold_reason,
        updated_at = excluded.updated_at
    returning * into v_state;
    return v_state;
end;
$$;

create or replace function commerce.record_seller_financial_exposure(
    p_order_id bigint,
    p_exposure_key text,
    p_exposure_type text,
    p_status text,
    p_amount bigint,
    p_recovered_amount bigint,
    p_reason text,
    p_details jsonb default '{}'::jsonb
)
returns commerce.seller_financial_exposures
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_exposure commerce.seller_financial_exposures%rowtype;
begin
    select * into v_order from commerce.orders where id = p_order_id;
    if not found then raise exception 'not_found: order'; end if;
    if p_exposure_key is null or length(btrim(p_exposure_key)) = 0 then
        raise exception 'validation: seller exposure key is required';
    end if;
    insert into commerce.seller_financial_exposures (
        seller_id, order_id, exposure_key, exposure_type, status, amount,
        recovered_amount, currency, reason, details
    ) values (
        v_order.seller_id, v_order.id, p_exposure_key, p_exposure_type, p_status,
        p_amount, p_recovered_amount, 'eur', p_reason, coalesce(p_details, '{}'::jsonb)
    ) on conflict (exposure_key) do update set
        status = excluded.status,
        amount = greatest(commerce.seller_financial_exposures.amount, excluded.amount),
        recovered_amount = greatest(commerce.seller_financial_exposures.recovered_amount, excluded.recovered_amount),
        reason = excluded.reason,
        details = commerce.seller_financial_exposures.details || excluded.details,
        updated_at = now()
    returning * into v_exposure;
    perform commerce.refresh_seller_risk_state(v_order.seller_id);
    if p_status = 'debt' then
        insert into commerce.financial_exceptions (order_id, kind, severity, reason, details)
        values (
            v_order.id, 'seller_debt', 'critical', p_reason,
            jsonb_build_object('exposureKey', p_exposure_key, 'amount', p_amount)
                || coalesce(p_details, '{}'::jsonb)
        );
    end if;
    return v_exposure;
end;
$$;

create or replace function commerce.assert_order_seller_risk(
    p_order_id bigint,
    p_stage text
)
returns void
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_risk commerce.seller_risk_policies%rowtype;
    v_state commerce.seller_risk_states%rowtype;
    v_velocity bigint;
    v_sales bigint;
    v_claims bigint;
    v_chargebacks bigint;
    v_claim_ratio integer;
    v_chargeback_ratio integer;
begin
    select * into v_order from commerce.orders where id = p_order_id;
    select * into v_terms from commerce.order_financial_terms where order_id = p_order_id;
    select * into v_risk from commerce.seller_risk_policies where id = v_terms.seller_risk_policy_id;
    if v_order.id is null or v_terms.order_id is null or v_risk.id is null then
        raise exception 'conflict: seller risk facts are unavailable';
    end if;
    perform pg_advisory_xact_lock(
        hashtextextended('commerce-seller-risk:' || v_order.seller_id::text, 0)
    );
    select * into v_state from commerce.refresh_seller_risk_state(v_order.seller_id);
    if v_state.status in ('restricted', 'blocked', 'manual_review')
        or v_state.outstanding_debt_amount > 0 then
        raise exception 'conflict: seller account is blocked by financial risk or debt';
    end if;
    select coalesce(sum(prior_terms.seller_proceeds_amount), 0)
    into v_velocity
    from commerce.order_financial_terms prior_terms
    join commerce.orders prior_order on prior_order.id = prior_terms.order_id
    where prior_order.seller_id = v_order.seller_id
      and (
          exists (
              select 1 from commerce.order_payment_attempts attempt
              where attempt.order_id = prior_order.id and attempt.status = 'succeeded'
                and attempt.succeeded_at >= now() - interval '24 hours'
          )
          or (prior_order.status = 'awaiting_payment' and prior_terms.pay_by_at > now())
          or exists (
              select 1 from commerce.order_payment_attempts attempt
              where attempt.order_id = prior_order.id
                and attempt.status in ('created', 'requires_action', 'processing')
          )
      );
    select coalesce(sum(prior_terms.buyer_total_amount), 0)
    into v_sales
    from commerce.order_financial_terms prior_terms
    join commerce.orders prior_order on prior_order.id = prior_terms.order_id
    where prior_order.seller_id = v_order.seller_id
      and exists (
          select 1 from commerce.order_payment_attempts attempt
          where attempt.order_id = prior_order.id and attempt.status = 'succeeded'
            and attempt.succeeded_at >= now() - interval '90 days'
      );
    select coalesce(sum(coalesce(claim.resolution_buyer_refund_amount, claim.buyer_requested_amount, 0)), 0)
    into v_claims
    from commerce.marketplace_claims claim
    join commerce.orders prior_order on prior_order.id = claim.order_id
    where prior_order.seller_id = v_order.seller_id
      and claim.created_at >= now() - interval '90 days'
      and claim.status <> 'resolved_seller';
    select coalesce(sum(dispute.amount), 0)
    into v_chargebacks
    from commerce.stripe_dispute_projections dispute
    join commerce.orders prior_order on prior_order.id = dispute.order_id
    where prior_order.seller_id = v_order.seller_id
      and dispute.opened_at >= now() - interval '90 days'
      and dispute.status not in ('won', 'prevented', 'warning_closed');
    v_claim_ratio := case when v_sales = 0
        then case when v_claims > 0 then 10000 else 0 end
        else least(10000, floor(v_claims::numeric * 10000 / v_sales)::integer) end;
    v_chargeback_ratio := case when v_sales = 0
        then case when v_chargebacks > 0 then 10000 else 0 end
        else least(10000, floor(v_chargebacks::numeric * 10000 / v_sales)::integer) end;
    if v_terms.seller_proceeds_amount > v_risk.order_transfer_limit_amount
        or v_terms.buyer_total_amount >= v_risk.high_value_review_amount then
        raise exception 'conflict: seller high-value risk review blocks %', p_stage;
    end if;
    if v_velocity > v_risk.velocity_limit_amount then
        raise exception 'conflict: seller velocity limit blocks %', p_stage;
    end if;
    if v_claims > 0 and v_claim_ratio >= v_risk.claim_ratio_review_bps then
        raise exception 'conflict: seller claim ratio blocks %', p_stage;
    end if;
    if v_chargebacks > 0 and v_chargeback_ratio >= v_risk.chargeback_ratio_review_bps then
        raise exception 'conflict: seller chargeback ratio blocks %', p_stage;
    end if;
end;
$$;

create or replace function commerce.get_order_delivery_quote_authorization(
    p_public_id uuid,
    p_buyer_cms_user_id text
)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_seller commerce.sellers%rowtype;
begin
    select * into v_order from commerce.orders
    where public_id = p_public_id and buyer_cms_user_id = p_buyer_cms_user_id;
    if not found then raise exception 'not_found: order'; end if;
    if v_order.status <> 'awaiting_quote' then
        raise exception 'conflict: order is not awaiting a delivery quote';
    end if;
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    if not found or v_seller.kind <> 'user' or v_seller.cms_user_id is null then
        raise exception 'conflict: protected delivery requires a C2C user seller';
    end if;
    return jsonb_build_object(
        'orderId', v_order.id,
        'orderPublicId', v_order.public_id,
        'orderVersion', v_order.version,
        'status', v_order.status,
        'buyerCmsUserId', v_order.buyer_cms_user_id,
        'sellerCmsUserId', v_seller.cms_user_id,
        'currency', v_order.currency,
        'merchandiseSubtotalMinorAmount', v_order.subtotal_amount,
        'shippingAddress', v_order.shipping_address
    );
end;
$$;

create or replace function commerce.lock_order_financial_terms(
    p_public_id uuid,
    p_buyer_cms_user_id text,
    p_delivery_quote_id text,
    p_shipping_amount bigint,
    p_currency text,
    p_expected_version integer,
    p_actor_id text default 'commerce-delivery'
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_seller commerce.sellers%rowtype;
    v_settings commerce.settings%rowtype;
    v_fee commerce.fee_policies%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_risk commerce.seller_risk_policies%rowtype;
    v_buyer_component commerce.fee_policy_components%rowtype;
    v_seller_component commerce.fee_policy_components%rowtype;
    v_existing commerce.order_financial_terms%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_buyer_basis bigint;
    v_seller_basis bigint;
    v_buyer_fee bigint;
    v_seller_fee bigint;
    v_platform_shipping bigint;
    v_seller_shipping bigint;
    v_seller_proceeds bigint;
    v_seller_reserve bigint;
    v_platform_retained bigint;
    v_expected_margin bigint;
    v_subsidy commerce.financial_subsidy_overrides%rowtype;
    v_risk_state commerce.seller_risk_states%rowtype;
    v_recent_velocity_amount bigint;
    v_historical_sales_amount bigint;
    v_claim_exposure_amount bigint;
    v_chargeback_exposure_amount bigint;
    v_claim_ratio_bps integer;
    v_chargeback_ratio_bps integer;
    v_hash text;
begin
    if p_shipping_amount is null or p_shipping_amount < 0 or p_shipping_amount > 9007199254740991 then
        raise exception 'validation: trusted shipping amount is invalid';
    end if;
    if lower(p_currency) <> 'eur' then
        raise exception 'validation: protected C2C currently supports EUR only';
    end if;
    if p_delivery_quote_id is null or length(btrim(p_delivery_quote_id)) = 0 then
        raise exception 'validation: a trusted delivery quote id is required';
    end if;
    select * into v_order from commerce.orders
    where public_id = p_public_id and buyer_cms_user_id = p_buyer_cms_user_id
    for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_existing from commerce.order_financial_terms where order_id = v_order.id;
    if found then
        if v_existing.delivery_quote_id <> p_delivery_quote_id
            or v_existing.shipping_amount <> p_shipping_amount
            or v_existing.currency <> lower(p_currency) then
            raise exception 'conflict: locked financial terms do not match the trusted quote';
        end if;
        return to_jsonb(v_existing) || jsonb_build_object('idempotent_replay', true);
    end if;
    if v_order.status <> 'awaiting_quote' then
        raise exception 'conflict: order is not awaiting a delivery quote';
    end if;
    if v_order.version is distinct from p_expected_version then
        raise exception 'conflict: stale order version';
    end if;
    select * into v_seller from commerce.sellers where id = v_order.seller_id for update;
    if not found or v_seller.kind <> 'user' then
        raise exception 'conflict: protected payment requires a C2C user seller';
    end if;
    perform pg_advisory_xact_lock(
        hashtextextended('commerce-seller-risk:' || v_order.seller_id::text, 0)
    );
    select * into v_settings from commerce.settings where id = 'default' for share;
    select * into v_fee from commerce.fee_policies
    where id = v_settings.active_c2c_fee_policy_id and status = 'published';
    select * into v_protection from commerce.protection_policies
    where id = v_settings.active_c2c_protection_policy_id and status = 'published';
    select * into v_risk from commerce.seller_risk_policies
    where id = v_settings.active_c2c_seller_risk_policy_id and status = 'published';
    if v_fee.id is null or v_protection.id is null or v_risk.id is null then
        raise exception 'conflict: protected C2C policies are unavailable';
    end if;
    if v_fee.currency <> lower(p_currency) or v_protection.currency <> lower(p_currency)
        or v_risk.currency <> lower(p_currency) then
        raise exception 'conflict: policy currency does not match order currency';
    end if;
    select * into v_buyer_component from commerce.fee_policy_components
    where fee_policy_id = v_fee.id and component_key = 'buyer_protection';
    select * into v_seller_component from commerce.fee_policy_components
    where fee_policy_id = v_fee.id and component_key = 'seller_commission';
    if v_buyer_component.id is null or v_seller_component.id is null then
        raise exception 'conflict: fee policy components are incomplete';
    end if;
    v_platform_shipping := case when v_fee.shipping_beneficiary = 'platform' then p_shipping_amount else 0 end;
    v_seller_shipping := p_shipping_amount - v_platform_shipping;
    v_buyer_basis := v_order.subtotal_amount + case
        when v_buyer_component.basis = 'merchandise_and_shipping' then p_shipping_amount else 0 end;
    v_seller_basis := v_order.subtotal_amount + case
        when v_seller_component.basis = 'merchandise_and_shipping' then p_shipping_amount else 0 end;
    v_buyer_fee := commerce.round_half_up_fee(
        v_buyer_basis, v_buyer_component.rate_bps, v_buyer_component.fixed_amount,
        v_buyer_component.minimum_amount, v_buyer_component.maximum_amount
    );
    v_seller_fee := commerce.round_half_up_fee(
        v_seller_basis, v_seller_component.rate_bps, v_seller_component.fixed_amount,
        v_seller_component.minimum_amount, v_seller_component.maximum_amount
    );
    if v_seller_fee >= v_order.subtotal_amount + v_seller_shipping then
        raise exception 'validation: seller commission must remain below seller gross entitlement';
    end if;
    v_seller_proceeds := v_order.subtotal_amount + v_seller_shipping - v_seller_fee;
    v_seller_reserve := least(
        greatest(0, v_seller_proceeds - 1),
        floor((v_seller_proceeds::numeric * v_risk.reserve_rate_bps + 5000) / 10000)::bigint
    );
    v_platform_retained := v_buyer_fee + v_seller_fee + v_platform_shipping;
    v_expected_margin := v_platform_retained - v_fee.estimated_stripe_cost_amount
        - v_fee.estimated_carrier_cost_amount - v_fee.platform_risk_reserve_contribution_amount;
    if not v_fee.cost_estimates_configured or v_expected_margin < v_fee.configured_minimum_margin_amount then
        select * into v_subsidy from commerce.financial_subsidy_overrides
        where fee_policy_id = v_fee.id
          and (expires_at is null or expires_at > now())
          and maximum_deficit_amount >= greatest(0, v_fee.configured_minimum_margin_amount - v_expected_margin)
        order by created_at desc limit 1;
        if not found then
            raise exception 'conflict: protected order margin is below policy minimum without subsidy approval';
        end if;
    end if;
    select * into v_risk_state from commerce.refresh_seller_risk_state(v_order.seller_id);
    if v_risk_state.status in ('restricted', 'blocked', 'manual_review')
        or v_risk_state.outstanding_debt_amount > 0 then
        raise exception 'conflict: seller account is blocked by financial risk or debt';
    end if;
    select coalesce(sum(terms.seller_proceeds_amount), 0)
    into v_recent_velocity_amount
    from commerce.order_financial_terms terms
    join commerce.orders prior_order on prior_order.id = terms.order_id
    where prior_order.seller_id = v_order.seller_id
      and (
          exists (
              select 1 from commerce.order_payment_attempts attempt
              where attempt.order_id = prior_order.id and attempt.status = 'succeeded'
                and attempt.succeeded_at >= now() - interval '24 hours'
          )
          or (prior_order.status = 'awaiting_payment' and terms.pay_by_at > now())
          or exists (
              select 1 from commerce.order_payment_attempts attempt
              where attempt.order_id = prior_order.id
                and attempt.status in ('created', 'requires_action', 'processing')
          )
      );
    select coalesce(sum(terms.buyer_total_amount), 0)
    into v_historical_sales_amount
    from commerce.order_financial_terms terms
    join commerce.orders prior_order on prior_order.id = terms.order_id
    join commerce.order_payment_attempts attempt on attempt.order_id = prior_order.id
    where prior_order.seller_id = v_order.seller_id
      and attempt.status = 'succeeded'
      and attempt.succeeded_at >= now() - interval '90 days';
    select coalesce(sum(coalesce(claim.resolution_buyer_refund_amount, claim.buyer_requested_amount, 0)), 0)
    into v_claim_exposure_amount
    from commerce.marketplace_claims claim
    join commerce.orders prior_order on prior_order.id = claim.order_id
    where prior_order.seller_id = v_order.seller_id
      and claim.created_at >= now() - interval '90 days'
      and claim.status not in ('resolved_seller');
    select coalesce(sum(dispute.amount), 0)
    into v_chargeback_exposure_amount
    from commerce.stripe_dispute_projections dispute
    join commerce.orders prior_order on prior_order.id = dispute.order_id
    where prior_order.seller_id = v_order.seller_id
      and dispute.opened_at >= now() - interval '90 days'
      and dispute.status not in ('won', 'prevented', 'warning_closed');
    v_claim_ratio_bps := case when v_historical_sales_amount = 0
        then case when v_claim_exposure_amount > 0 then 10000 else 0 end
        else least(10000, floor(v_claim_exposure_amount::numeric * 10000 / v_historical_sales_amount)::integer) end;
    v_chargeback_ratio_bps := case when v_historical_sales_amount = 0
        then case when v_chargeback_exposure_amount > 0 then 10000 else 0 end
        else least(10000, floor(v_chargeback_exposure_amount::numeric * 10000 / v_historical_sales_amount)::integer) end;
    if v_seller_proceeds > v_risk.order_transfer_limit_amount
        or v_order.subtotal_amount + p_shipping_amount + v_buyer_fee
            >= v_risk.high_value_review_amount then
        raise exception 'conflict: seller risk policy requires manual review before payment';
    end if;
    if v_recent_velocity_amount + v_seller_proceeds > v_risk.velocity_limit_amount then
        raise exception 'conflict: seller velocity limit requires manual review before payment';
    end if;
    if v_claim_exposure_amount > 0 and v_claim_ratio_bps >= v_risk.claim_ratio_review_bps then
        raise exception 'conflict: seller claim ratio requires manual review before payment';
    end if;
    if v_chargeback_exposure_amount > 0
        and v_chargeback_ratio_bps >= v_risk.chargeback_ratio_review_bps then
        raise exception 'conflict: seller chargeback ratio requires manual review before payment';
    end if;
    v_hash := encode(extensions.digest(jsonb_build_object(
        'orderPublicId', v_order.public_id,
        'buyerCmsUserId', v_order.buyer_cms_user_id,
        'sellerId', v_order.seller_id,
        'deliveryQuoteId', p_delivery_quote_id,
        'feePolicyId', v_fee.id,
        'protectionPolicyId', v_protection.id,
        'sellerRiskPolicyId', v_risk.id,
        'merchandiseSubtotalAmount', v_order.subtotal_amount,
        'shippingAmount', p_shipping_amount,
        'buyerProtectionFeeAmount', v_buyer_fee,
        'sellerCommissionAmount', v_seller_fee,
        'sellerProceedsAmount', v_seller_proceeds,
        'currency', lower(p_currency)
    )::text, 'sha256'), 'hex');
    insert into commerce.order_financial_terms (
        order_id, fee_policy_id, fee_policy_version, fee_policy_snapshot,
        protection_policy_id, protection_policy_version, protection_policy_snapshot,
        seller_risk_policy_id, seller_risk_policy_version, seller_risk_policy_snapshot,
        delivery_quote_id, merchandise_subtotal_amount, shipping_amount,
        buyer_protection_fee_amount, seller_commission_amount,
        platform_shipping_share_amount, seller_shipping_share_amount,
        buyer_total_amount, seller_proceeds_amount, seller_transfer_release_amount,
        seller_reserve_liability_amount, platform_retained_amount,
        estimated_stripe_cost_amount, estimated_carrier_cost_amount,
        platform_risk_reserve_contribution_amount, configured_minimum_margin_amount,
        expected_platform_margin_amount, subsidy_override_id, currency,
        financial_terms_hash, pricing_locked_at, pay_by_at
    ) values (
        v_order.id, v_fee.id, v_fee.version,
        to_jsonb(v_fee) || jsonb_build_object('components', (
            select jsonb_agg(to_jsonb(component) order by component.position, component.id)
            from commerce.fee_policy_components component where component.fee_policy_id = v_fee.id
        )),
        v_protection.id, v_protection.version, to_jsonb(v_protection),
        v_risk.id, v_risk.version, to_jsonb(v_risk),
        p_delivery_quote_id, v_order.subtotal_amount, p_shipping_amount,
        v_buyer_fee, v_seller_fee, v_platform_shipping, v_seller_shipping,
        v_order.subtotal_amount + p_shipping_amount + v_buyer_fee,
        v_seller_proceeds, v_seller_proceeds - v_seller_reserve, v_seller_reserve,
        v_platform_retained, v_fee.estimated_stripe_cost_amount,
        v_fee.estimated_carrier_cost_amount, v_fee.platform_risk_reserve_contribution_amount,
        v_fee.configured_minimum_margin_amount, v_expected_margin, v_subsidy.id,
        lower(p_currency), v_hash, now(), now() + make_interval(mins => v_protection.payment_window_minutes)
    ) returning * into v_terms;
    insert into commerce.order_fulfillments (
        order_id, seller_handoff_deadline, scan_grace_deadline
    ) values (
        v_order.id,
        now() + make_interval(hours => v_protection.seller_handoff_hours),
        now() + make_interval(hours => v_protection.seller_handoff_hours + v_protection.scan_grace_hours)
    );
    insert into commerce.order_settlements (
        order_id, authorized_seller_amount, seller_reserve_liability_remaining_amount,
        platform_gross_remainder_amount
    ) values (
        v_order.id, v_terms.seller_proceeds_amount,
        v_terms.seller_reserve_liability_amount, v_terms.platform_retained_amount
    );
    if v_terms.seller_reserve_liability_amount > 0 then
        perform commerce.record_seller_financial_exposure(
            v_order.id, 'reserve:' || v_order.id, 'reserve', 'held',
            v_terms.seller_reserve_liability_amount, 0,
            'Versioned seller rolling reserve',
            jsonb_build_object('sellerRiskPolicyId', v_terms.seller_risk_policy_id,
                'releaseAfter', now() + make_interval(days => v_risk.reserve_liability_days))
        );
    end if;
    update commerce.orders set
        status = 'awaiting_payment', shipping_amount = p_shipping_amount,
        delivery_quoted_at = now(), total_amount = v_terms.buyer_total_amount
    where id = v_order.id;
    perform commerce.append_financial_event(
        v_order.id, 'order', v_order.id::text, 'financial_terms_locked',
        'system', coalesce(nullif(p_actor_id, ''), 'commerce-delivery'), null,
        jsonb_build_object('financialTermsHash', v_hash, 'deliveryQuoteId', p_delivery_quote_id),
        'commerce.order.financial_terms_locked', 'order:' || v_order.id || ':financial-terms:' || v_hash
    );
    return to_jsonb(v_terms) || jsonb_build_object('idempotent_replay', false);
end;
$$;

create or replace function commerce.refresh_platform_payout_liability(
    p_calculation_reason text,
    p_included_prospective_order_id bigint default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_control commerce.platform_payout_liability_controls%rowtype;
    v_required_amount bigint;
    v_direction text;
begin
    if p_calculation_reason is null or length(btrim(p_calculation_reason)) = 0 then
        raise exception 'validation: platform payout liability calculation reason is required';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('commerce:platform-payout-liability', 0)
    );
    select coalesce(sum(
        case when liability.lifecycle_status in ('provisional', 'active') then
            greatest(
                0,
                settlement.authorized_seller_amount
                    - settlement.total_transferred_amount
                    + settlement.total_reversed_amount
            )
        else 0 end
        + case when liability.lifecycle_status = 'provisional'
            or (liability.lifecycle_status = 'active' and (
                liability.risk_release_at > now()
                or exists (
                    select 1
                    from commerce.stripe_dispute_projections dispute
                    where dispute.order_id = liability.order_id
                      and (
                          dispute.status not in ('won', 'prevented', 'warning_closed')
                          or dispute.funds_withdrawn
                      )
                )
            )) then terms.platform_risk_reserve_contribution_amount
            else 0 end
    ), 0)
    into v_required_amount
    from commerce.platform_payout_order_liabilities liability
    join commerce.order_settlements settlement on settlement.order_id = liability.order_id
    join commerce.order_financial_terms terms on terms.order_id = liability.order_id
    where liability.lifecycle_status <> 'released';

    select * into v_control
    from commerce.platform_payout_liability_controls
    where control_key = 'default'
    for update;
    if not found then
        raise exception 'configuration: platform payout liability control is unavailable';
    end if;
    v_direction := case
        when v_required_amount > v_control.last_provider_applied_amount then 'increase'
        when v_required_amount < v_control.last_provider_applied_amount then 'decrease'
        else 'unchanged'
    end;
    if v_required_amount is distinct from v_control.required_minimum_amount then
        update commerce.platform_payout_liability_controls set
            liability_revision = liability_revision + 1,
            previous_required_minimum_amount = required_minimum_amount,
            required_minimum_amount = v_required_amount,
            change_direction = v_direction,
            decrease_authorization_id = null,
            decrease_authorized_by = null,
            decrease_authorized_reason = null,
            decrease_authorized_at = null,
            calculated_at = now(),
            updated_at = now()
        where control_key = 'default'
        returning * into v_control;
        insert into commerce.platform_payout_liability_revisions (
            liability_revision, required_minimum_amount,
            previous_required_minimum_amount, change_direction,
            calculation_reason, included_prospective_order_id
        ) values (
            v_control.liability_revision, v_control.required_minimum_amount,
            v_control.previous_required_minimum_amount, v_control.change_direction,
            p_calculation_reason, p_included_prospective_order_id
        );
    else
        update commerce.platform_payout_liability_controls set
            change_direction = v_direction,
            calculated_at = now(),
            updated_at = now()
        where control_key = 'default'
        returning * into v_control;
    end if;
    return jsonb_build_object(
        'liabilityRevision', v_control.liability_revision,
        'requiredMinimumAmount', v_control.required_minimum_amount,
        'lastProviderAppliedRevision', v_control.last_provider_applied_revision,
        'lastProviderAppliedAmount', v_control.last_provider_applied_amount,
        'changeDirection', v_control.change_direction,
        'decreaseAuthorizationId', v_control.decrease_authorization_id,
        'decreaseAuthorizedAt', v_control.decrease_authorized_at,
        'calculatedAt', v_control.calculated_at
    );
end;
$$;

create or replace function commerce.authorize_platform_payout_liability_decrease(
    p_expected_liability_revision bigint,
    p_actor_id text,
    p_reason text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_control commerce.platform_payout_liability_controls%rowtype;
begin
    if p_actor_id is null or length(btrim(p_actor_id)) = 0
        or p_reason is null or length(btrim(p_reason)) = 0 then
        raise exception 'validation: Admin actor and reason are required';
    end if;
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('commerce:platform-payout-liability', 0)
    );
    select * into v_control
    from commerce.platform_payout_liability_controls
    where control_key = 'default'
    for update;
    if v_control.liability_revision is distinct from p_expected_liability_revision then
        raise exception 'conflict: stale platform payout liability revision';
    end if;
    if v_control.required_minimum_amount >= v_control.last_provider_applied_amount then
        raise exception 'conflict: current platform payout liability is not a provider decrease';
    end if;
    if v_control.decrease_authorization_id is null then
        update commerce.platform_payout_liability_controls set
            change_direction = 'decrease',
            decrease_authorization_id = gen_random_uuid(),
            decrease_authorized_by = p_actor_id,
            decrease_authorized_reason = p_reason,
            decrease_authorized_at = now(),
            updated_at = now()
        where control_key = 'default'
        returning * into v_control;
        update commerce.platform_payout_liability_revisions set
            decrease_authorization_id = v_control.decrease_authorization_id,
            decrease_authorized_by = p_actor_id,
            decrease_authorized_reason = p_reason,
            decrease_authorized_at = v_control.decrease_authorized_at
        where liability_revision = v_control.liability_revision;
    end if;
    perform commerce.append_financial_event(
        null, 'platform_payout_liability', v_control.liability_revision::text,
        'platform_payout_decrease_authorized', 'admin', p_actor_id, p_reason,
        jsonb_build_object('requiredMinimumAmount', v_control.required_minimum_amount,
            'previousProviderAmount', v_control.last_provider_applied_amount,
            'decreaseAuthorizationId', v_control.decrease_authorization_id),
        'commerce.platform_payout.decrease_authorized',
        'platform-payout-decrease:' || v_control.liability_revision
    );
    return commerce.refresh_platform_payout_liability(
        'Admin decrease authorization CAS confirmation', null
    );
end;
$$;

create or replace function commerce.record_platform_payout_liability_applied(
    p_liability_revision bigint,
    p_applied_minimum_amount bigint,
    p_decrease_authorization_id uuid default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_control commerce.platform_payout_liability_controls%rowtype;
begin
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('commerce:platform-payout-liability', 0)
    );
    select * into v_control
    from commerce.platform_payout_liability_controls
    where control_key = 'default'
    for update;
    if v_control.liability_revision is distinct from p_liability_revision then
        return jsonb_build_object(
            'accepted', false, 'needsReapply', true,
            'control', commerce.refresh_platform_payout_liability(
                'Provider completion observed a newer Commerce revision', null
            )
        );
    end if;
    if p_applied_minimum_amount < v_control.required_minimum_amount then
        raise exception 'conflict: provider applied amount is below the Commerce aggregate';
    end if;
    if v_control.decrease_authorization_id is not null then
        if v_control.decrease_authorization_id is distinct from p_decrease_authorization_id then
            raise exception 'forbidden: exact Admin decrease authorization does not match';
        end if;
        if p_applied_minimum_amount is distinct from v_control.required_minimum_amount then
            raise exception 'conflict: Admin-authorized provider decrease must match the exact Commerce aggregate';
        end if;
    end if;
    if p_applied_minimum_amount < v_control.last_provider_applied_amount then
        if v_control.decrease_authorization_id is null
            or v_control.decrease_authorization_id is distinct from p_decrease_authorization_id then
            raise exception 'forbidden: exact Admin decrease authorization is required';
        end if;
    end if;
    update commerce.platform_payout_liability_revisions set
        provider_applied_amount = p_applied_minimum_amount,
        provider_applied_at = now()
    where liability_revision = v_control.liability_revision;
    update commerce.platform_payout_liability_controls set
        last_provider_applied_revision = v_control.liability_revision,
        last_provider_applied_amount = p_applied_minimum_amount,
        last_provider_applied_at = now(),
        change_direction = 'unchanged',
        decrease_authorization_id = null,
        decrease_authorized_by = null,
        decrease_authorized_reason = null,
        decrease_authorized_at = null,
        updated_at = now()
    where control_key = 'default'
    returning * into v_control;
    return jsonb_build_object(
        'accepted', true, 'needsReapply', false,
        'liabilityRevision', v_control.liability_revision,
        'requiredMinimumAmount', v_control.required_minimum_amount,
        'lastProviderAppliedAmount', v_control.last_provider_applied_amount
    );
end;
$$;

create or replace function commerce.pending_platform_payout_liability_authorizations(
    p_run_key text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_control jsonb;
    v_required bigint;
    v_applied bigint;
    v_authorization_id text;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0 then
        raise exception 'validation: platform payout liability run key is required';
    end if;
    v_control := commerce.refresh_platform_payout_liability(
        'Scheduled liability and terminal risk-window refresh: ' || p_run_key, null
    );
    v_required := (v_control->>'requiredMinimumAmount')::bigint;
    v_applied := (v_control->>'lastProviderAppliedAmount')::bigint;
    v_authorization_id := v_control->>'decreaseAuthorizationId';
    return jsonb_build_object(
        'runKey', p_run_key,
        'control', v_control,
        'authorizations', case
            when v_required > v_applied
                or (v_required < v_applied and v_authorization_id is not null)
            then jsonb_build_array(jsonb_build_object(
                'liabilityRevision', (v_control->>'liabilityRevision')::bigint,
                'requiredMinimumAmount', v_required,
                'decreaseAuthorizationId', v_authorization_id,
                'changeDirection', v_control->>'changeDirection'
            ))
            else '[]'::jsonb
        end
    );
end;
$$;

create or replace function commerce.prepare_protected_payment(
    p_order_id bigint,
    p_buyer_cms_user_id text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_seller commerce.sellers%rowtype;
    v_risk commerce.seller_risk_policies%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_seller_required_minimum_balance bigint;
    v_platform_required_minimum_balance bigint;
    v_platform_control jsonb;
begin
    select * into v_order from commerce.orders
    where id = p_order_id and buyer_cms_user_id = p_buyer_cms_user_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    if not found then raise exception 'conflict: immutable financial terms are not locked'; end if;
    perform commerce.assert_order_seller_risk(v_order.id, 'payment preparation');
    if v_order.status not in ('awaiting_payment', 'active') then
        raise exception 'conflict: order cannot enter protected payment';
    end if;
    if v_order.status = 'awaiting_payment' and now() >= v_terms.pay_by_at then
        raise exception 'conflict: protected payment window has expired';
    end if;
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    select * into v_risk from commerce.seller_risk_policies where id = v_terms.seller_risk_policy_id;
    select * into v_protection from commerce.protection_policies where id = v_terms.protection_policy_id;
    if v_seller.kind <> 'user' or v_seller.cms_user_id is null then
        raise exception 'conflict: protected payment requires a C2C user seller';
    end if;
    select coalesce(state.outstanding_debt_amount + state.at_risk_exposure_amount, 0)
    into v_seller_required_minimum_balance
    from commerce.seller_risk_states state
    where state.seller_id = v_order.seller_id;
    insert into commerce.platform_payout_order_liabilities (
        order_id, lifecycle_status, risk_release_at
    ) values (
        v_order.id, 'provisional', null
    ) on conflict (order_id) do update set
        lifecycle_status = case
            when commerce.platform_payout_order_liabilities.lifecycle_status = 'active'
                then 'active'
            else 'provisional' end,
        risk_release_at = case
            when commerce.platform_payout_order_liabilities.lifecycle_status = 'active'
                then commerce.platform_payout_order_liabilities.risk_release_at
            else null end,
        updated_at = now();
    v_platform_control := commerce.refresh_platform_payout_liability(
        'Protected payment preparation reserved prospective liability', v_order.id
    );
    v_platform_required_minimum_balance := (v_platform_control->>'requiredMinimumAmount')::bigint;
    return jsonb_build_object(
        'orderId', v_order.id,
        'orderPublicId', v_order.public_id,
        'orderNumber', v_order.order_number,
        'buyerCmsUserId', v_order.buyer_cms_user_id,
        'sellerId', v_seller.cms_user_id,
        'currency', upper(v_terms.currency),
        'deliveryQuoteId', v_terms.delivery_quote_id,
        'merchandiseSubtotalMinorAmount', v_terms.merchandise_subtotal_amount,
        'shippingAmount', v_terms.shipping_amount,
        'buyerTotalAmount', v_terms.buyer_total_amount,
        'sellerProceedsAmount', v_terms.seller_proceeds_amount,
        'sellerTransferReleaseAmount', v_terms.seller_transfer_release_amount,
        'sellerReserveLiabilityAmount', v_terms.seller_reserve_liability_amount,
        'payoutDelayDays', v_risk.payout_delay_days,
        'sellerReserveLiabilityDays', v_risk.reserve_liability_days,
        'dualApprovalThresholdAmount', v_protection.dual_approval_threshold_amount,
        'sellerRequiredMinimumBalanceAmount', v_seller_required_minimum_balance,
        'platformRequiredMinimumBalanceAmount', v_platform_required_minimum_balance,
        'platformLiabilityRevision', (v_platform_control->>'liabilityRevision')::bigint,
        'platformPayoutDecreaseAuthorizationId', v_platform_control->>'decreaseAuthorizationId',
        'platformPayoutChangeDirection', v_platform_control->>'changeDirection',
        'platformRetainedAmount', v_terms.platform_retained_amount,
        'financialTermsHash', v_terms.financial_terms_hash,
        'financialRevision', v_terms.financial_revision,
        'payByAt', v_terms.pay_by_at,
        'protectionRequired', true
    );
end;
$$;

create or replace function commerce.ensure_payment_cancellation_request(
    p_order_id bigint,
    p_target_order_status text,
    p_reason text,
    p_actor_id text,
    p_order_cancellation_request_id bigint default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_attempt commerce.order_payment_attempts%rowtype;
    v_request commerce.payment_cancellation_requests%rowtype;
    v_business_key text;
begin
    if p_target_order_status not in ('cancelled', 'expired') then
        raise exception 'validation: unsupported payment cancellation target';
    end if;
    select * into v_order from commerce.orders where id = p_order_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_attempt from commerce.order_payment_attempts
    where order_id = v_order.id order by created_at desc limit 1;
    v_business_key := case when p_order_cancellation_request_id is not null
        then 'payment-cancellation:order-cancellation:' || p_order_cancellation_request_id
        else 'payment-cancellation:deadline:' || v_order.id end;
    insert into commerce.payment_cancellation_requests (
        order_id, order_cancellation_request_id, business_key, target_order_status,
        reason, provider_payment_id, provider_payment_intent_id
    ) values (
        v_order.id, p_order_cancellation_request_id, v_business_key, p_target_order_status,
        p_reason, v_attempt.provider_payment_id, v_attempt.provider_payment_intent_id
    ) on conflict (business_key) do update set
        provider_payment_id = coalesce(commerce.payment_cancellation_requests.provider_payment_id, excluded.provider_payment_id),
        provider_payment_intent_id = coalesce(commerce.payment_cancellation_requests.provider_payment_intent_id, excluded.provider_payment_intent_id)
    returning * into v_request;
    insert into commerce.financial_operation_dispatch_claims (
        operation_kind, operation_id, order_id
    ) values (
        'payment_cancellation', v_request.id::text, v_order.id
    ) on conflict (operation_kind, operation_id) do nothing;
    update commerce.orders set status = 'cancellation_pending', version = version + 1
    where id = v_order.id and status in ('awaiting_payment', 'active');
    if p_order_cancellation_request_id is not null then
        update commerce.order_cancellation_requests set status = 'provider_cancellation_pending'
        where id = p_order_cancellation_request_id
          and status in ('approved', 'provider_cancellation_pending');
    end if;
    if v_attempt.status = 'cancelled' then
        update commerce.payment_cancellation_requests set status = 'completed'
        where id = v_request.id returning * into v_request;
        perform commerce.restore_order_inventory(v_order.id);
        update commerce.orders set status = p_target_order_status, version = version + 1
        where id = v_order.id and status = 'cancellation_pending';
        update commerce.order_fulfillments set
            status = 'cancelled', blocking_reason = case
                when p_target_order_status = 'expired' then 'payment_window_expired'
                else 'order_cancelled_before_payment' end,
            version = version + 1
        where order_id = v_order.id;
        update commerce.order_settlements set
            status = 'blocked', manual_review_reason = case
                when p_target_order_status = 'expired' then 'order_expired_without_payment'
                else 'order_cancelled_without_payment' end,
            version = version + 1
        where order_id = v_order.id;
        update commerce.order_cancellation_requests set status = 'completed'
        where id = p_order_cancellation_request_id;
    end if;
    perform commerce.append_financial_event(
        v_order.id, 'payment_cancellation', v_request.id::text, 'payment_cancellation_requested',
        'system', p_actor_id, p_reason,
        jsonb_build_object('targetOrderStatus', p_target_order_status,
            'providerPaymentId', v_attempt.provider_payment_id),
        'commerce.order.payment_cancellation_requested', v_business_key || ':requested'
    );
    return commerce.payment_cancellation_authorization_payload(v_request.id);
end;
$$;

create or replace function commerce.payment_cancellation_authorization_payload(p_request_id bigint)
returns jsonb
language sql
stable
set search_path = ''
as $$
select jsonb_build_object(
    'status', request.status,
    'paymentCancellationRequestId', request.id,
    'cancellationRequestId', request.business_key,
    'orderId', order_row.id,
    'orderPublicId', order_row.public_id,
    'clientReferenceId', order_row.public_id,
    'providerPaymentId', coalesce(request.provider_payment_id, payment.provider_payment_id),
    'providerPaymentIntentId', coalesce(request.provider_payment_intent_id, payment.provider_payment_intent_id),
    'targetOrderStatus', request.target_order_status,
    'reason', request.reason,
    'amount', terms.buyer_total_amount,
    'currency', upper(terms.currency),
    'financialTermsHash', terms.financial_terms_hash
)
from commerce.payment_cancellation_requests request
join commerce.orders order_row on order_row.id = request.order_id
join commerce.order_financial_terms terms on terms.order_id = order_row.id
left join lateral (
    select attempt.provider_payment_id, attempt.provider_payment_intent_id
    from commerce.order_payment_attempts attempt
    where attempt.order_id = order_row.id
    order by attempt.created_at desc limit 1
) payment on true
where request.id = p_request_id;
$$;

create or replace function commerce.pending_payment_cancellation_authorizations(
    p_run_key text,
    p_limit integer default 25
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_authorizations jsonb;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0 then
        raise exception 'validation: payment cancellation run key is required';
    end if;
    insert into commerce.financial_operation_dispatch_claims (operation_kind, operation_id, order_id)
    select 'payment_cancellation', request.id::text, request.order_id
    from commerce.payment_cancellation_requests request
    where request.status in ('requested', 'processing')
    on conflict (operation_kind, operation_id) do nothing;
    with candidates as (
        select dispatch.operation_kind, dispatch.operation_id
        from commerce.financial_operation_dispatch_claims dispatch
        join commerce.payment_cancellation_requests request on request.id::text = dispatch.operation_id
        where dispatch.operation_kind = 'payment_cancellation'
          and request.status in ('requested', 'processing')
          and dispatch.available_at <= now()
          and (dispatch.claimed_at is null or dispatch.claimed_at < now() - interval '5 minutes')
        order by dispatch.available_at, dispatch.created_at, dispatch.operation_id
        limit least(greatest(p_limit, 1), 100)
        for update of dispatch skip locked
    ), claimed as (
        update commerce.financial_operation_dispatch_claims dispatch set
            claimed_at = now(), claimed_by = 'payment-cancellation-worker:' || p_run_key,
            attempts = attempts + 1
        from candidates
        where dispatch.operation_kind = candidates.operation_kind
          and dispatch.operation_id = candidates.operation_id
        returning dispatch.operation_id
    ), marked as (
        update commerce.payment_cancellation_requests request set status = 'processing'
        from claimed where request.id::text = claimed.operation_id
        returning request.id
    )
    select coalesce(jsonb_agg(
        commerce.payment_cancellation_authorization_payload(marked.id)
        order by marked.id
    ), '[]'::jsonb) into v_authorizations from marked;
    return jsonb_build_object('runKey', p_run_key, 'authorizations', v_authorizations);
end;
$$;

create or replace function commerce.record_absent_order_payment_cancellation(
    p_order_public_id uuid,
    p_provider_event_id text,
    p_cancellation_request_id text,
    p_occurred_at timestamptz,
    p_provider_snapshot jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_cancellation commerce.payment_cancellation_requests%rowtype;
    v_event_id bigint;
begin
    if nullif(btrim(p_cancellation_request_id), '') is null then
        raise exception 'validation: cancellation request id is required';
    end if;
    select * into v_order
    from commerce.orders
    where public_id = p_order_public_id
    for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_cancellation
    from commerce.payment_cancellation_requests
    where order_id = v_order.id
      and business_key = p_cancellation_request_id
    for update;
    if not found then raise exception 'conflict: payment cancellation request does not match Commerce authority'; end if;
    v_event_id := commerce.claim_provider_projection_event(
        'stripe', p_provider_event_id, v_order.id, 'payment.absent', p_occurred_at,
        jsonb_build_object(
            'cancellationRequestId', p_cancellation_request_id,
            'providerPaymentAbsent', true,
            'snapshot', coalesce(p_provider_snapshot, '{}'::jsonb)
        )
    );
    if v_event_id is null then
        return jsonb_build_object(
            'orderId', v_order.id,
            'status', v_cancellation.status,
            'providerPaymentAbsent', true,
            'idempotentReplay', true
        );
    end if;
    if exists (
        select 1 from commerce.order_payment_attempts attempt
        where attempt.order_id = v_order.id
    ) then
        raise exception 'conflict: absent provider truth cannot finalize an order with a payment attempt';
    end if;
    if v_cancellation.status not in ('requested', 'processing', 'completed') then
        raise exception 'conflict: payment cancellation is not awaiting absent provider truth';
    end if;
    if v_cancellation.status <> 'completed' then
        update commerce.payment_cancellation_requests
        set status = 'completed',
            provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb)
                || jsonb_build_object('providerPaymentAbsent', true)
        where id = v_cancellation.id
        returning * into v_cancellation;
        perform commerce.restore_order_inventory(v_order.id);
        update commerce.orders
        set status = v_cancellation.target_order_status,
            version = version + 1,
            updated_at = now()
        where id = v_order.id and status = 'cancellation_pending';
        update commerce.order_fulfillments
        set status = 'cancelled',
            blocking_reason = case
                when v_cancellation.target_order_status = 'expired' then 'payment_window_expired'
                else 'order_cancelled_before_payment' end,
            version = version + 1,
            updated_at = now()
        where order_id = v_order.id;
        update commerce.order_settlements
        set status = 'blocked',
            manual_review_reason = case
                when v_cancellation.target_order_status = 'expired' then 'order_expired_without_provider_payment'
                else 'order_cancelled_without_provider_payment' end,
            version = version + 1,
            updated_at = now()
        where order_id = v_order.id;
        update commerce.order_cancellation_requests
        set status = 'completed'
        where id = v_cancellation.order_cancellation_request_id
          and status = 'provider_cancellation_pending';
        update commerce.financial_exceptions
        set status = 'resolved', resolved_at = now(), resolved_by = 'stripe-payment-absent'
        where deduplication_key = 'deadline:payment:' || v_order.id
          and status <> 'resolved';
        insert into commerce.platform_payout_order_liabilities (
            order_id, lifecycle_status, risk_release_at
        ) values (
            v_order.id, 'released', null
        ) on conflict (order_id) do update set
            lifecycle_status = 'released', risk_release_at = null, updated_at = now();
        perform commerce.refresh_platform_payout_liability(
            'Provider-absent payment cancellation released prospective liability', null
        );
        perform commerce.append_financial_event(
            v_order.id, 'payment_cancellation', v_cancellation.id::text,
            'payment_cancellation_provider_absent', 'provider', 'stripe', null,
            jsonb_build_object(
                'cancellationRequestId', p_cancellation_request_id,
                'targetOrderStatus', v_cancellation.target_order_status
            ),
            'commerce.order.payment_cancellation_absent',
            v_cancellation.business_key || ':provider-absent'
        );
    end if;
    return jsonb_build_object(
        'orderId', v_order.id,
        'status', v_cancellation.status,
        'providerPaymentAbsent', true,
        'idempotentReplay', false
    );
end;
$$;

create or replace function commerce.record_order_payment_projection(
    p_order_public_id uuid,
    p_provider_event_id text,
    p_provider_payment_id bigint,
    p_status text,
    p_amount bigint,
    p_currency text,
    p_financial_terms_hash text,
    p_occurred_at timestamptz,
    p_provider_snapshot jsonb default '{}'::jsonb,
    p_provider_charge_id text default null,
    p_provider_payment_intent_id text default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_attempt commerce.order_payment_attempts%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_review_exception commerce.financial_exceptions%rowtype;
    v_cancellation commerce.payment_cancellation_requests%rowtype;
    v_refund commerce.refund_requests%rowtype;
    v_refund_json jsonb;
    v_late_refund_key text;
    v_event_id bigint;
    v_provider_review_reason text;
    v_review_occurred_at timestamptz := 'infinity'::timestamptz;
    v_snapshot_updated_at timestamptz := 'infinity'::timestamptz;
    v_provider_review_recoverable boolean := false;
    v_payment_review_transition_safe boolean := false;
    v_payment_review_transition_applied boolean := false;
    v_recovered_ambiguous_payment boolean := false;
    v_transient_provider_review_reason constant text :=
        'Stripe payment provider truth mismatch: charge_balance_transaction_expansion';
begin
    if p_status not in ('created', 'requires_action', 'processing', 'succeeded', 'failed', 'cancelled', 'manual_review') then
        raise exception 'validation: unsupported payment projection status';
    end if;
    select * into v_order from commerce.orders where public_id = p_order_public_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    if not found then raise exception 'conflict: immutable financial terms are missing'; end if;
    select * into v_fulfillment from commerce.order_fulfillments
    where order_id = v_order.id for update;
    if not found then raise exception 'conflict: order fulfillment is not initialized'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = v_order.id for update;
    if not found then raise exception 'conflict: order settlement is missing'; end if;

    v_provider_review_reason := nullif(btrim(p_provider_snapshot->>'manualReviewReason'), '');
    if p_provider_snapshot->>'updatedAt'
        ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}'
    then
        v_snapshot_updated_at :=
            (p_provider_snapshot->>'updatedAt')::timestamptz;
    end if;
    v_provider_review_recoverable := coalesce(p_status = 'manual_review'
        and v_provider_review_reason = v_transient_provider_review_reason
        and p_provider_snapshot->>'paymentStatus' in ('failed', 'succeeded')
        and coalesce(p_provider_snapshot, '{}'::jsonb) @> jsonb_build_object(
            'commercePaymentStatus', 'manual_review',
            'settlementStatus', 'manual_review',
            'disputeStatus', 'none',
            'sellerTransferAmount', v_terms.seller_proceeds_amount,
            'platformRetainedAmount', v_terms.platform_retained_amount,
            'refundedAmount', 0,
            'transferredAmount', 0,
            'reversedAmount', 0
        )
        and p_provider_snapshot->>'paymentId' = p_provider_payment_id::text
        and p_provider_snapshot->>'clientReferenceId' = v_order.public_id::text
        and p_provider_snapshot @> jsonb_build_object('amountTotal', v_terms.buyer_total_amount)
        and lower(p_provider_snapshot->>'currency') = v_terms.currency
        and p_provider_snapshot->>'financialTermsHash' = v_terms.financial_terms_hash
        and p_provider_payment_intent_id is not null
        and p_provider_charge_id is not null
        and p_provider_snapshot->>'stripePaymentIntentId' = p_provider_payment_intent_id
        and p_provider_snapshot->>'stripeChargeId' = p_provider_charge_id
        and (
            coalesce(p_provider_snapshot->>'stripeChargeBalanceTransactionId', '') = ''
            or p_provider_snapshot->>'stripeChargeBalanceTransactionId' like 'txn_%'
        )
        and p_occurred_at = v_snapshot_updated_at, false);

    select
        v_order.status in ('awaiting_payment', 'active')
        and v_settlement.status = 'held'
        and v_settlement.manual_review_reason is null
        and v_settlement.total_transferred_amount = 0
        and v_settlement.total_reversed_amount = 0
        and v_settlement.total_refunded_amount = 0
        and v_settlement.provider_transfer_id is null
        and v_fulfillment.status in (
            'awaiting_shipment', 'shipment_creating', 'label_created',
            'seller_handoff_declared', 'carrier_accepted', 'in_transit',
            'arrived_at_pickup_point', 'available_for_pickup'
        )
        and v_fulfillment.blocking_reason is null
        and v_fulfillment.recipient_handoff_at is null
        and v_fulfillment.recipient_handoff_first_observed_at is null
        and v_fulfillment.claim_window_started_at is null
        and v_fulfillment.claim_by_at is null
        and v_fulfillment.release_eligible_at is null
        and not exists (
            select 1 from commerce.financial_exceptions financial_exception
            where financial_exception.order_id = v_order.id
              and financial_exception.status in ('open', 'investigating')
        )
        and not exists (
            select 1 from commerce.marketplace_claims claim
            where claim.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.stripe_dispute_projections dispute
            where dispute.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.refund_requests refund
            where refund.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.order_cancellation_requests cancellation
            where cancellation.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.payment_cancellation_requests cancellation
            where cancellation.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.settlement_release_authorizations release_authorization
            where release_authorization.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.financial_operation_dispatch_claims dispatch
            where dispatch.order_id = v_order.id
        )
        and not exists (
            select 1 from commerce.seller_financial_exposures exposure
            where exposure.order_id = v_order.id
              and exposure.status in ('at_risk', 'debt')
        )
    into v_payment_review_transition_safe;
    v_event_id := commerce.claim_provider_projection_event(
        'stripe', p_provider_event_id, v_order.id, 'payment.' || p_status, p_occurred_at,
        jsonb_strip_nulls(jsonb_build_object(
            'providerPaymentId', p_provider_payment_id,
            'providerPaymentIntentId', p_provider_payment_intent_id,
            'providerChargeId', p_provider_charge_id,
            'amount', p_amount, 'currency', lower(p_currency),
            'financialTermsHash', p_financial_terms_hash,
            'snapshot', coalesce(p_provider_snapshot, '{}'::jsonb)
        ))
    );
    select * into v_attempt from commerce.order_payment_attempts
    where provider = 'stripe' and client_reference_id = v_order.public_id::text
    for update;
    if v_event_id is null then
        if not found then raise exception 'conflict: duplicate provider event has no payment projection'; end if;
        return to_jsonb(v_attempt) || jsonb_build_object('idempotentReplay', true);
    end if;
    if p_amount <> v_terms.buyer_total_amount or lower(p_currency) <> v_terms.currency
        or p_financial_terms_hash <> v_terms.financial_terms_hash then
        insert into commerce.financial_exceptions (
            order_id, kind, severity, reason, details
        ) values (
            v_order.id, 'payment_mismatch', 'critical',
            'Stripe payment projection does not match immutable Commerce terms',
            jsonb_build_object(
                'providerPaymentId', p_provider_payment_id,
                'providerAmount', p_amount,
                'providerCurrency', lower(p_currency),
                'providerTermsHash', p_financial_terms_hash
            )
        );
        update commerce.order_settlements set
            status = 'manual_review', manual_review_reason = 'payment_projection_mismatch'
        where order_id = v_order.id
          and v_payment_review_transition_safe;
        perform commerce.append_financial_event(
            v_order.id, 'payment', p_provider_payment_id::text, 'payment_mismatch',
            'provider', 'stripe', 'Provider payment differs from immutable Commerce terms',
            jsonb_build_object('providerEventId', p_provider_event_id),
            'commerce.order.payment_mismatch', 'stripe:' || p_provider_event_id || ':mismatch'
        );
        return jsonb_build_object(
            'orderId', v_order.id, 'status', 'manual_review',
            'accepted', false, 'idempotentReplay', false,
            'reason', 'provider_payment_does_not_match_immutable_terms'
        );
    end if;
    if v_attempt.id is null then
        insert into commerce.order_payment_attempts (
            order_id, provider_payment_id, provider_payment_intent_id,
            provider_charge_id, client_reference_id, status,
            amount, currency, financial_terms_hash, provider_snapshot,
            succeeded_at, failed_at, cancelled_at
        ) values (
            v_order.id, p_provider_payment_id, p_provider_payment_intent_id,
            p_provider_charge_id, v_order.public_id::text, p_status,
            p_amount, lower(p_currency), p_financial_terms_hash,
            coalesce(p_provider_snapshot, '{}'::jsonb),
            case when p_status = 'succeeded' then p_occurred_at end,
            case when p_status = 'failed' then p_occurred_at end,
            case when p_status = 'cancelled' then p_occurred_at end
        ) returning * into v_attempt;
    else
        if v_attempt.provider_payment_id is distinct from p_provider_payment_id
            or (p_provider_payment_intent_id is not null and v_attempt.provider_payment_intent_id is not null
                and v_attempt.provider_payment_intent_id <> p_provider_payment_intent_id)
            or (p_provider_charge_id is not null and v_attempt.provider_charge_id is not null
                and v_attempt.provider_charge_id <> p_provider_charge_id)
            or v_attempt.amount <> p_amount or v_attempt.currency <> lower(p_currency)
            or v_attempt.financial_terms_hash <> p_financial_terms_hash then
            raise exception 'conflict: payment replay changed immutable provider terms';
        end if;
        if v_attempt.status = 'succeeded'
            and p_status not in ('succeeded', 'manual_review') then
            return to_jsonb(v_attempt) || jsonb_build_object('idempotentReplay', false, 'ignoredStaleEvent', true);
        end if;
        if v_attempt.status = 'cancelled' and p_status not in ('cancelled', 'succeeded') then
            raise exception 'conflict: cancelled provider payment cannot regress';
        end if;
        update commerce.order_payment_attempts set
            status = p_status,
            provider_payment_intent_id = coalesce(provider_payment_intent_id, p_provider_payment_intent_id),
            provider_charge_id = coalesce(provider_charge_id, p_provider_charge_id),
            provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
            succeeded_at = case when p_status = 'succeeded' then coalesce(succeeded_at, p_occurred_at) else succeeded_at end,
            failed_at = case when p_status = 'failed' then coalesce(failed_at, p_occurred_at) else failed_at end,
            cancelled_at = case when p_status = 'cancelled' then coalesce(cancelled_at, p_occurred_at) else cancelled_at end
        where id = v_attempt.id returning * into v_attempt;
    end if;
    update commerce.payment_cancellation_requests set
        provider_payment_id = coalesce(provider_payment_id, p_provider_payment_id),
        provider_payment_intent_id = coalesce(provider_payment_intent_id, p_provider_payment_intent_id),
        provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
        status = case when p_status in ('created', 'requires_action', 'processing', 'failed')
            and status = 'requested' then 'processing' else status end
    where order_id = v_order.id
      and status in ('requested', 'processing', 'provider_cancelled', 'completed', 'manual_review');

    select * into v_cancellation from commerce.payment_cancellation_requests
    where order_id = v_order.id
    order by created_at desc, id desc limit 1 for update;

    if p_status = 'cancelled' and v_cancellation.id is not null
        and v_cancellation.status not in ('refund_pending', 'completed') then
        update commerce.payment_cancellation_requests set
            status = 'completed', provider_payment_id = p_provider_payment_id,
            provider_payment_intent_id = coalesce(provider_payment_intent_id, p_provider_payment_intent_id),
            provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb)
        where id = v_cancellation.id returning * into v_cancellation;
        perform commerce.restore_order_inventory(v_order.id);
        update commerce.orders set
            status = v_cancellation.target_order_status,
            version = version + 1, updated_at = now()
        where id = v_order.id and status = 'cancellation_pending';
        update commerce.order_fulfillments set
            status = 'cancelled', blocking_reason = case
                when v_cancellation.target_order_status = 'expired' then 'payment_window_expired'
                else 'order_cancelled_before_payment' end,
            version = version + 1, updated_at = now()
        where order_id = v_order.id;
        update commerce.order_settlements set
            status = 'blocked', manual_review_reason = case
                when v_cancellation.target_order_status = 'expired' then 'order_expired_without_payment'
                else 'order_cancelled_without_payment' end,
            version = version + 1, updated_at = now()
        where order_id = v_order.id;
        update commerce.order_cancellation_requests set status = 'completed'
        where id = v_cancellation.order_cancellation_request_id
          and status = 'provider_cancellation_pending';
        update commerce.financial_exceptions set
            status = 'resolved', resolved_at = now(), resolved_by = 'stripe-payment-cancellation'
        where deduplication_key = 'deadline:payment:' || v_order.id and status <> 'resolved';
        perform commerce.append_financial_event(
            v_order.id, 'payment_cancellation', v_cancellation.id::text,
            'payment_cancellation_provider_confirmed', 'provider', 'stripe', null,
            jsonb_build_object('providerPaymentId', p_provider_payment_id,
                'targetOrderStatus', v_cancellation.target_order_status),
            'commerce.order.payment_cancellation_confirmed',
            v_cancellation.business_key || ':provider-cancelled'
        );
    elsif p_status = 'succeeded' and (
        v_order.status in ('cancellation_pending', 'cancelled', 'expired')
        or (v_cancellation.id is not null and v_cancellation.status in ('requested', 'processing', 'provider_cancelled', 'completed'))
    ) then
        v_late_refund_key := 'late-payment-success:' || v_order.id || ':' || p_provider_payment_id;
        select * into v_refund from commerce.refund_requests
        where business_key = v_late_refund_key for update;
        if not found then
            v_refund_json := commerce.create_cancellation_refund_request(
                v_order.id, v_late_refund_key,
                'Automatic policy-governed refund after Stripe succeeded during or after provider cancellation',
                'system', 'late-payment-compensation'
            );
            update commerce.refund_requests set
                status = 'approved', requires_finance_approval = false,
                dual_approval_required = false, approved_by = 'late-payment-compensation',
                decision_reason = 'Mandatory automatic compensation for a late provider success'
            where id = (v_refund_json->>'id')::bigint returning * into v_refund;
        end if;
        if v_cancellation.id is null then
            insert into commerce.payment_cancellation_requests (
                order_id, business_key, target_order_status, reason, status,
                provider_payment_id, provider_payment_intent_id, provider_snapshot
            ) values (
                v_order.id, 'payment-cancellation:late-success:' || v_order.id,
                case when v_order.status = 'expired' then 'expired' else 'cancelled' end,
                'Late Stripe success requires a full protected refund', 'refund_pending',
                p_provider_payment_id, p_provider_payment_intent_id,
                coalesce(p_provider_snapshot, '{}'::jsonb)
            ) returning * into v_cancellation;
        else
            update commerce.payment_cancellation_requests set
                status = 'refund_pending', provider_payment_id = p_provider_payment_id,
                provider_payment_intent_id = coalesce(provider_payment_intent_id, p_provider_payment_intent_id),
                provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb)
            where id = v_cancellation.id returning * into v_cancellation;
        end if;
        update commerce.order_cancellation_requests set status = 'refund_pending'
        where id = v_cancellation.order_cancellation_request_id
          and status in ('provider_cancellation_pending', 'completed', 'approved');
        insert into commerce.financial_exceptions (
            deduplication_key, order_id, kind, severity, reason, details
        ) values (
            v_late_refund_key, v_order.id, 'late_payment_success', 'critical',
            'Stripe succeeded after Commerce requested or finalized payment cancellation',
            jsonb_build_object('providerPaymentId', p_provider_payment_id,
                'providerPaymentIntentId', p_provider_payment_intent_id,
                'refundRequestId', v_refund.id)
        ) on conflict (deduplication_key) where deduplication_key is not null do update set
            status = 'open', details = excluded.details;
        perform commerce.append_financial_event(
            v_order.id, 'payment', v_attempt.id::text, 'late_payment_success_refund_authorized',
            'system', 'late-payment-compensation',
            'Provider success raced a Commerce cancellation; full refund authorized exactly once',
            jsonb_build_object('providerPaymentId', p_provider_payment_id,
                'refundRequestId', v_refund.id, 'businessKey', v_late_refund_key),
            'commerce.order.late_payment_success', v_late_refund_key
        );
    elsif p_status = 'succeeded' then
        select * into v_settlement
        from commerce.order_settlements
        where order_id = v_order.id
        for update;
        if not found then raise exception 'conflict: order settlement is missing'; end if;
        select * into v_fulfillment
        from commerce.order_fulfillments
        where order_id = v_order.id
        for update;
        if not found then raise exception 'conflict: order fulfillment is not initialized'; end if;

        select * into v_review_exception
        from commerce.financial_exceptions financial_exception
        where financial_exception.order_id = v_order.id
          and financial_exception.kind = 'payment_mismatch'
          and financial_exception.severity = 'critical'
          and financial_exception.status in ('open', 'investigating')
          and financial_exception.details->>'providerPaymentId' = p_provider_payment_id::text
          and financial_exception.details->>'providerPaymentIntentId' = p_provider_payment_intent_id
          and financial_exception.details->>'providerChargeId' = p_provider_charge_id
          and financial_exception.details->>'providerManualReviewReason' =
                v_transient_provider_review_reason
          and (
              (
                  financial_exception.deduplication_key =
                      'ambiguous-payment-state:' || v_order.id || ':' || p_provider_payment_id
                  and financial_exception.reason = 'Ambiguous provider payment state'
                  and financial_exception.details->>'recoverable' = 'true'
              )
              or (
                  financial_exception.deduplication_key =
                      'provider-payment-review:' || v_order.id || ':' || p_provider_payment_id
                  and financial_exception.reason =
                      'Provider payment requires non-automatic manual review'
                  and financial_exception.details->>'recoverable' = 'false'
              )
          )
          and length(btrim(coalesce(financial_exception.details->>'providerEventId', ''))) > 0
          and financial_exception.details->>'providerOccurredAt'
                ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}'
        order by (
            financial_exception.deduplication_key =
                'ambiguous-payment-state:' || v_order.id || ':' || p_provider_payment_id
        ) desc, financial_exception.id desc
        limit 1
        for update;

        if v_review_exception.id is not null
            and v_review_exception.details->>'providerOccurredAt'
                ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}'
        then
            v_review_occurred_at :=
                (v_review_exception.details->>'providerOccurredAt')::timestamptz;
        end if;
        if v_settlement.status = 'manual_review'
            and v_settlement.manual_review_reason in (
                'ambiguous_payment_state', 'provider_payment_manual_review_nonrecoverable'
            )
            and v_order.status in ('awaiting_payment', 'active')
            and v_review_exception.id is not null
            and p_occurred_at > v_review_occurred_at
            and v_settlement.total_transferred_amount = 0
            and v_settlement.total_reversed_amount = 0
            and v_settlement.total_refunded_amount = 0
            and v_settlement.provider_transfer_id is null
            and coalesce(p_provider_snapshot, '{}'::jsonb) @> jsonb_build_object(
                'paymentStatus', 'succeeded',
                'commercePaymentStatus', 'succeeded',
                'settlementStatus', 'held',
                'disputeStatus', 'none',
                'sellerTransferAmount', v_terms.seller_proceeds_amount,
                'platformRetainedAmount', v_terms.platform_retained_amount,
                'refundedAmount', 0,
                'transferredAmount', 0,
                'reversedAmount', 0
            )
            and p_provider_snapshot->>'clientReferenceId' = v_order.public_id::text
            and p_provider_snapshot @> jsonb_build_object(
                'amountTotal', v_terms.buyer_total_amount
            )
            and lower(p_provider_snapshot->>'currency') = v_terms.currency
            and p_provider_snapshot->>'financialTermsHash' = v_terms.financial_terms_hash
            and p_occurred_at = v_snapshot_updated_at
            and (
                not (coalesce(p_provider_snapshot, '{}'::jsonb) ? 'manualReviewReason')
                or p_provider_snapshot->'manualReviewReason' = 'null'::jsonb
            )
            and p_provider_snapshot->>'paymentId' = p_provider_payment_id::text
            and p_provider_payment_intent_id is not null
            and p_provider_charge_id is not null
            and p_provider_snapshot->>'stripePaymentIntentId' = p_provider_payment_intent_id
            and p_provider_snapshot->>'stripeChargeId' = p_provider_charge_id
            and coalesce(p_provider_snapshot->>'stripeChargeBalanceTransactionId', '') like 'txn_%'
            and (
                nullif(v_review_exception.details->>'providerBalanceTransactionId', '') is null
                or p_provider_snapshot->>'stripeChargeBalanceTransactionId' =
                    v_review_exception.details->>'providerBalanceTransactionId'
            )
            and v_attempt.provider_payment_intent_id = p_provider_payment_intent_id
            and v_attempt.provider_charge_id = p_provider_charge_id
            and v_fulfillment.status in (
                'awaiting_shipment', 'shipment_creating', 'label_created',
                'seller_handoff_declared', 'carrier_accepted', 'in_transit',
                'arrived_at_pickup_point', 'available_for_pickup'
            )
            and v_fulfillment.blocking_reason is null
            and v_fulfillment.recipient_handoff_at is null
            and v_fulfillment.recipient_handoff_first_observed_at is null
            and v_fulfillment.claim_window_started_at is null
            and v_fulfillment.claim_by_at is null
            and v_fulfillment.release_eligible_at is null
            and not exists (
                select 1
                from commerce.financial_exceptions financial_exception
                where financial_exception.order_id = v_order.id
                  and financial_exception.status in ('open', 'investigating')
                  and not (
                      financial_exception.kind = 'payment_mismatch'
                      and financial_exception.severity = 'critical'
                      and financial_exception.details->>'providerPaymentId' = p_provider_payment_id::text
                      and financial_exception.details->>'providerPaymentIntentId' = p_provider_payment_intent_id
                      and financial_exception.details->>'providerChargeId' = p_provider_charge_id
                      and financial_exception.details->>'providerManualReviewReason' =
                          v_transient_provider_review_reason
                      and (
                          (
                              financial_exception.deduplication_key =
                                  'ambiguous-payment-state:' || v_order.id || ':' || p_provider_payment_id
                              and financial_exception.reason = 'Ambiguous provider payment state'
                              and financial_exception.details->>'recoverable' = 'true'
                          )
                          or (
                              financial_exception.deduplication_key =
                                  'provider-payment-review:' || v_order.id || ':' || p_provider_payment_id
                              and financial_exception.reason =
                                  'Provider payment requires non-automatic manual review'
                              and financial_exception.details->>'recoverable' = 'false'
                          )
                      )
                  )
            )
            and not exists (
                select 1
                from commerce.provider_projection_events provider_event
                where provider_event.authority = 'stripe'
                  and provider_event.order_id = v_order.id
                  and provider_event.event_type like 'payment.%'
                  and provider_event.provider_event_id <> p_provider_event_id
                  and provider_event.occurred_at >= p_occurred_at
            )
            and not exists (
                select 1 from commerce.marketplace_claims claim
                where claim.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.stripe_dispute_projections dispute
                where dispute.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.refund_requests refund
                where refund.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.order_cancellation_requests cancellation
                where cancellation.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.payment_cancellation_requests cancellation
                where cancellation.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.settlement_release_authorizations release_authorization
                where release_authorization.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.financial_operation_dispatch_claims dispatch
                where dispatch.order_id = v_order.id
            )
            and not exists (
                select 1 from commerce.seller_financial_exposures exposure
                where exposure.order_id = v_order.id
                  and exposure.status in ('at_risk', 'debt')
            )
        then
            update commerce.order_settlements set
                status = 'held', manual_review_reason = null,
                version = version + 1, updated_at = now()
            where order_id = v_order.id
            returning * into v_settlement;
            update commerce.financial_exceptions set
                status = 'resolved', resolved_at = now(),
                resolved_by = 'stripe-provider-truth-revalidation'
            where order_id = v_order.id
              and status in ('open', 'investigating')
              and kind = 'payment_mismatch'
              and severity = 'critical'
              and details->>'providerPaymentId' = p_provider_payment_id::text
              and details->>'providerPaymentIntentId' = p_provider_payment_intent_id
              and details->>'providerChargeId' = p_provider_charge_id
              and details->>'providerManualReviewReason' = v_transient_provider_review_reason
              and deduplication_key in (
                  'ambiguous-payment-state:' || v_order.id || ':' || p_provider_payment_id,
                  'provider-payment-review:' || v_order.id || ':' || p_provider_payment_id
              );
            perform commerce.append_financial_event(
                v_order.id, 'payment', v_attempt.id::text,
                'ambiguous_payment_state_revalidated', 'provider', 'stripe',
                'Stripe provider truth was fully revalidated before restoring the held settlement',
                jsonb_build_object(
                    'providerPaymentId', p_provider_payment_id,
                    'providerPaymentIntentId', p_provider_payment_intent_id,
                    'providerChargeId', p_provider_charge_id,
                    'providerEventId', p_provider_event_id,
                    'reviewProviderEventId', v_review_exception.details->>'providerEventId',
                    'reviewProviderOccurredAt', v_review_exception.details->>'providerOccurredAt',
                    'previousSettlementStatus', 'manual_review',
                    'nextSettlementStatus', 'held'
                ),
                'commerce.order.payment_review_recovered',
                'stripe:' || p_provider_event_id || ':ambiguous-payment-recovered'
            );
            v_recovered_ambiguous_payment := true;
        end if;

        if (v_settlement.status = 'held' or v_recovered_ambiguous_payment)
            and (v_payment_review_transition_safe or v_recovered_ambiguous_payment)
            and v_settlement.manual_review_reason is null
            and v_fulfillment.status in (
                'awaiting_shipment', 'shipment_creating', 'label_created',
                'seller_handoff_declared', 'carrier_accepted', 'in_transit',
                'arrived_at_pickup_point', 'available_for_pickup'
            )
            and v_fulfillment.blocking_reason is null
            and v_fulfillment.recipient_handoff_at is null
            and v_fulfillment.recipient_handoff_first_observed_at is null
            and v_fulfillment.claim_window_started_at is null
            and v_fulfillment.claim_by_at is null
            and v_fulfillment.release_eligible_at is null
        then
            update commerce.orders set status = 'active'
            where id = v_order.id and status = 'awaiting_payment';
        end if;
    elsif p_status = 'manual_review' then
        if v_payment_review_transition_safe then
            update commerce.order_settlements set
                status = 'manual_review',
                manual_review_reason = case
                    when v_provider_review_recoverable then 'ambiguous_payment_state'
                    else 'provider_payment_manual_review_nonrecoverable'
                end,
                version = version + 1, updated_at = now()
            where order_id = v_order.id
              and status = 'held'
              and manual_review_reason is null
            returning * into v_settlement;
            v_payment_review_transition_applied := found;
        end if;
        insert into commerce.financial_exceptions as financial_exception (
            deduplication_key, order_id, kind, severity, reason, details
        ) values (
            case when v_provider_review_recoverable
                then 'ambiguous-payment-state:' || v_order.id || ':' || p_provider_payment_id
                else 'provider-payment-review:' || v_order.id || ':' || p_provider_payment_id
            end,
            v_order.id, 'payment_mismatch', 'critical',
            case when v_provider_review_recoverable
                then 'Ambiguous provider payment state'
                else 'Provider payment requires non-automatic manual review'
            end,
            jsonb_strip_nulls(jsonb_build_object(
                'providerPaymentId', p_provider_payment_id,
                'providerPaymentIntentId', p_provider_payment_intent_id,
                'providerChargeId', p_provider_charge_id,
                'providerBalanceTransactionId',
                    p_provider_snapshot->>'stripeChargeBalanceTransactionId',
                'providerManualReviewReason', v_provider_review_reason,
                'providerEventId', p_provider_event_id,
                'providerOccurredAt', p_occurred_at,
                'recoverable', v_provider_review_recoverable,
                'settlementTransitionApplied', v_payment_review_transition_applied,
                'observedSettlementStatus', v_settlement.status,
                'observedSettlementReason', v_settlement.manual_review_reason,
                'observedFulfillmentStatus', v_fulfillment.status,
                'observedFulfillmentBlockingReason', v_fulfillment.blocking_reason
            ))
        ) on conflict (deduplication_key) where deduplication_key is not null do update set
            status = 'open', severity = 'critical',
            reason = excluded.reason,
            details = excluded.details,
            detected_at = now(), resolved_at = null, resolved_by = null
        where case
                when financial_exception.details->>'providerOccurredAt'
                    ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}'
                then (financial_exception.details->>'providerOccurredAt')::timestamptz
                else 'infinity'::timestamptz
            end <= case
                when excluded.details->>'providerOccurredAt'
                    ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}'
                then (excluded.details->>'providerOccurredAt')::timestamptz
                else '-infinity'::timestamptz
            end;
    end if;
    perform commerce.append_financial_event(
        v_order.id, 'payment', v_attempt.id::text, 'payment_' || p_status,
        'provider', 'stripe', null,
        jsonb_strip_nulls(jsonb_build_object(
            'providerPaymentId', p_provider_payment_id,
            'providerEventId', p_provider_event_id,
            'providerManualReviewReason', v_provider_review_reason,
            'paymentReviewRecoverable', case when p_status = 'manual_review'
                then v_provider_review_recoverable else null end,
            'settlementTransitionApplied', case when p_status = 'manual_review'
                then v_payment_review_transition_applied else null end
        )),
        'commerce.order.payment_projection', 'stripe:' || p_provider_event_id
    );
    return to_jsonb(v_attempt) || jsonb_build_object(
        'idempotentReplay', false,
        'paymentReviewRecoverable', v_provider_review_recoverable,
        'paymentReviewSettlementTransitioned', v_payment_review_transition_applied,
        'paymentReviewRecovered', v_recovered_ambiguous_payment
    );
end;
$$;

create or replace function commerce.record_order_fulfillment_projection(
    p_order_public_id uuid,
    p_provider_event_id text,
    p_normalized_status text,
    p_occurred_at timestamptz,
    p_provider_reference text default null,
    p_recipient_handoff_at timestamptz default null,
    p_carrier_accepted_at timestamptz default null,
    p_seller_handoff_declared_at timestamptz default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_event_id bigint;
    v_current_rank integer;
    v_next_rank integer;
    v_blocking boolean;
    v_projection_observed_at timestamptz;
    v_handoff_timestamp_anomalous boolean;
    v_terminal_occurred_at timestamptz;
begin
    if p_normalized_status not in (
        'label_created', 'seller_handoff_declared', 'carrier_accepted', 'in_transit',
        'arrived_at_pickup_point', 'available_for_pickup', 'collected_by_recipient',
        'incident', 'lost', 'pickup_expired', 'returning_to_sender',
        'returned_to_sender', 'cancelled'
    ) then raise exception 'validation: unsupported normalized fulfillment status'; end if;
    select * into v_order from commerce.orders where public_id = p_order_public_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_fulfillment from commerce.order_fulfillments
    where order_id = v_order.id for update;
    if not found then raise exception 'conflict: order fulfillment is not initialized'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = v_order.id for update;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    select * into v_protection from commerce.protection_policies where id = v_terms.protection_policy_id;
    select * into v_settlement from commerce.order_settlements where order_id = v_order.id for update;
    v_event_id := commerce.claim_provider_projection_event(
        'delivery', p_provider_event_id, v_order.id,
        'fulfillment.' || p_normalized_status, p_occurred_at,
        jsonb_strip_nulls(jsonb_build_object(
            'providerReference', p_provider_reference,
            'recipientHandoffAt', p_recipient_handoff_at,
            'carrierAcceptedAt', p_carrier_accepted_at,
            'sellerHandoffDeclaredAt', p_seller_handoff_declared_at
        ))
    );
    if v_event_id is null then
        return to_jsonb(v_fulfillment) || jsonb_build_object('idempotentReplay', true);
    end if;
    if v_fulfillment.status = 'cancelled' and p_normalized_status in (
        'carrier_accepted', 'in_transit', 'arrived_at_pickup_point',
        'available_for_pickup', 'collected_by_recipient', 'lost',
        'pickup_expired', 'returning_to_sender', 'returned_to_sender'
    ) then
        update commerce.order_fulfillments set
            status = 'manual_review', blocking_reason = 'late_carrier_scan_after_cancellation',
            provider_reference = coalesce(nullif(p_provider_reference, ''), provider_reference),
            carrier_accepted_at = coalesce(carrier_accepted_at, p_carrier_accepted_at, p_occurred_at),
            version = version + 1, updated_at = now()
        where order_id = v_order.id returning * into v_fulfillment;
        update commerce.order_settlements set
            status = 'manual_review', manual_review_reason = 'late_carrier_scan_after_cancellation',
            version = version + 1, updated_at = now()
        where order_id = v_order.id and status not in ('refunded', 'reversed');
        insert into commerce.financial_exceptions (
            deduplication_key, order_id, kind, severity, reason, details
        ) values (
            'late-carrier-scan:' || p_provider_event_id, v_order.id,
            'fulfillment_ambiguity', 'critical',
            'Carrier accepted or advanced a shipment after local cancellation',
            jsonb_build_object('providerEventId', p_provider_event_id,
                'normalizedStatus', p_normalized_status, 'occurredAt', p_occurred_at)
        ) on conflict (deduplication_key) where deduplication_key is not null do update set
            status = 'open', details = excluded.details;
        return to_jsonb(v_fulfillment) || jsonb_build_object(
            'order_public_id', v_order.public_id, 'lateCarrierScan', true,
            'idempotentReplay', false
        );
    end if;
    if v_fulfillment.status in (
        'collected_by_recipient', 'lost', 'returned_to_sender', 'cancelled'
    ) and v_fulfillment.status <> p_normalized_status then
        select max(event.occurred_at) into v_terminal_occurred_at
        from commerce.provider_projection_events event
        where event.authority = 'delivery' and event.order_id = v_order.id
          and event.event_type = 'fulfillment.' || v_fulfillment.status;
        if v_terminal_occurred_at is not null and p_occurred_at <= v_terminal_occurred_at then
            perform commerce.append_financial_event(
                v_order.id, 'fulfillment', v_order.id::text,
                'fulfillment_stale_event_ignored', 'provider', 'delivery',
                'Older carrier event arrived after a terminal fulfillment projection',
                jsonb_build_object(
                    'providerEventId', p_provider_event_id,
                    'normalizedStatus', p_normalized_status,
                    'occurredAt', p_occurred_at,
                    'terminalStatus', v_fulfillment.status,
                    'terminalOccurredAt', v_terminal_occurred_at
                ),
                'commerce.order.fulfillment_stale_ignored',
                'delivery:' || p_provider_event_id || ':stale-ignored'
            );
            return to_jsonb(v_fulfillment) || jsonb_build_object(
                'order_public_id', v_order.public_id,
                'ignoredStaleEvent', true, 'idempotentReplay', false
            );
        end if;
        update commerce.order_fulfillments set
            status = 'manual_review',
            blocking_reason = 'contradictory_carrier_event_after_terminal',
            provider_reference = coalesce(nullif(p_provider_reference, ''), provider_reference),
            version = version + 1, updated_at = now()
        where order_id = v_order.id returning * into v_fulfillment;
        update commerce.order_settlements set
            status = 'manual_review',
            manual_review_reason = 'contradictory_carrier_event_after_terminal',
            version = version + 1, updated_at = now()
        where order_id = v_order.id and status not in ('refunded', 'reversed');
        insert into commerce.financial_exceptions (
            deduplication_key, order_id, kind, severity, reason, details
        ) values (
            'terminal-carrier-contradiction:' || p_provider_event_id,
            v_order.id, 'fulfillment_ambiguity', 'critical',
            'A newer or unanchored carrier event contradicted terminal fulfillment truth',
            jsonb_build_object(
                'providerEventId', p_provider_event_id,
                'normalizedStatus', p_normalized_status,
                'occurredAt', p_occurred_at,
                'terminalOccurredAt', v_terminal_occurred_at
            )
        ) on conflict (deduplication_key) where deduplication_key is not null do update set
            status = 'open', details = excluded.details;
        return to_jsonb(v_fulfillment) || jsonb_build_object(
            'order_public_id', v_order.public_id,
            'manualReview', true, 'idempotentReplay', false
        );
    end if;
    v_current_rank := case v_fulfillment.status
        when 'awaiting_shipment' then 0 when 'label_created' then 10
        when 'seller_handoff_declared' then 20 when 'carrier_accepted' then 30
        when 'in_transit' then 40 when 'arrived_at_pickup_point' then 50
        when 'available_for_pickup' then 60 when 'collected_by_recipient' then 70
        else 0 end;
    v_next_rank := case p_normalized_status
        when 'label_created' then 10 when 'seller_handoff_declared' then 20
        when 'carrier_accepted' then 30 when 'in_transit' then 40
        when 'arrived_at_pickup_point' then 50 when 'available_for_pickup' then 60
        when 'collected_by_recipient' then 70 else v_current_rank end;
    v_blocking := p_normalized_status in (
        'incident', 'lost', 'pickup_expired', 'returning_to_sender', 'returned_to_sender', 'cancelled'
    );
    if not v_blocking and v_next_rank < v_current_rank then
        raise exception 'conflict: fulfillment state cannot regress';
    end if;
    if p_normalized_status = 'label_created' and v_order.status <> 'active' then
        raise exception 'conflict: shipment label requires a confirmed protected payment';
    end if;
    if p_normalized_status = 'collected_by_recipient' and p_recipient_handoff_at is null then
        raise exception 'validation: trusted recipient handoff timestamp is required';
    end if;
    v_projection_observed_at := clock_timestamp();
    v_handoff_timestamp_anomalous := p_normalized_status = 'collected_by_recipient'
        and (
            p_recipient_handoff_at > v_projection_observed_at + interval '5 minutes'
            or p_occurred_at > v_projection_observed_at + interval '5 minutes'
            or p_recipient_handoff_at > p_occurred_at + interval '5 minutes'
            or v_fulfillment.blocking_reason = 'recipient_handoff_timestamp_anomaly'
        );
    update commerce.order_fulfillments set
        status = case when v_handoff_timestamp_anomalous
            then 'manual_review' else p_normalized_status end,
        provider_reference = coalesce(nullif(p_provider_reference, ''), provider_reference),
        seller_handoff_declared_at = case when p_normalized_status = 'seller_handoff_declared'
            then coalesce(p_seller_handoff_declared_at, p_occurred_at) else seller_handoff_declared_at end,
        carrier_accepted_at = case when v_next_rank >= 30
            then coalesce(carrier_accepted_at, p_carrier_accepted_at, p_occurred_at) else carrier_accepted_at end,
        arrived_at_pickup_point_at = case when v_next_rank >= 50
            then coalesce(arrived_at_pickup_point_at, p_occurred_at) else arrived_at_pickup_point_at end,
        available_for_pickup_at = case when v_next_rank >= 60
            then coalesce(available_for_pickup_at, p_occurred_at) else available_for_pickup_at end,
        recipient_handoff_at = case when p_normalized_status = 'collected_by_recipient'
            then coalesce(recipient_handoff_at, p_recipient_handoff_at) else recipient_handoff_at end,
        recipient_handoff_first_observed_at = case
            when p_normalized_status = 'collected_by_recipient'
            then coalesce(recipient_handoff_first_observed_at, v_projection_observed_at)
            else recipient_handoff_first_observed_at end,
        claim_window_started_at = case
            when p_normalized_status = 'collected_by_recipient'
            then coalesce(claim_window_started_at,
                greatest(p_recipient_handoff_at, v_projection_observed_at))
            else claim_window_started_at end,
        claim_by_at = case when p_normalized_status = 'collected_by_recipient'
            then coalesce(claim_by_at,
                greatest(p_recipient_handoff_at, v_projection_observed_at)
                    + make_interval(hours => v_protection.claim_window_hours))
            else claim_by_at end,
        release_eligible_at = case when p_normalized_status = 'collected_by_recipient'
            then coalesce(release_eligible_at,
                greatest(p_recipient_handoff_at, v_projection_observed_at)
                    + make_interval(hours => v_protection.claim_window_hours))
            else release_eligible_at end,
        blocking_reason = case
            when v_handoff_timestamp_anomalous then 'recipient_handoff_timestamp_anomaly'
            when v_blocking then p_normalized_status
            else null end,
        version = version + 1,
        updated_at = now()
    where order_id = v_order.id returning * into v_fulfillment;
    if v_blocking then
        update commerce.order_settlements set
            status = 'blocked', manual_review_reason = 'fulfillment_' || p_normalized_status
        where order_id = v_order.id and status not in ('released', 'refunded', 'reversed');
    end if;
    if v_handoff_timestamp_anomalous then
        update commerce.order_settlements set
            status = 'manual_review',
            manual_review_reason = 'recipient_handoff_timestamp_anomaly'
        where order_id = v_order.id and status not in ('released', 'refunded', 'reversed');
        insert into commerce.financial_exceptions (
            deduplication_key, order_id, kind, severity, reason, details
        ) values (
            'fulfillment-handoff-timestamp:' || p_provider_event_id,
            v_order.id, 'fulfillment_ambiguity', 'critical',
            'Recipient handoff timestamp is inconsistent with the provider event or database clock',
            jsonb_build_object(
                'providerEventId', p_provider_event_id,
                'providerOccurredAt', p_occurred_at,
                'recipientHandoffAt', p_recipient_handoff_at,
                'firstObservedAt', v_projection_observed_at
            )
        ) on conflict (deduplication_key) where deduplication_key is not null do update set
            status = 'open', details = excluded.details;
    end if;
    perform commerce.append_financial_event(
        v_order.id, 'fulfillment', v_order.id::text, 'fulfillment_' || p_normalized_status,
        'provider', 'delivery', null,
        jsonb_build_object('providerEventId', p_provider_event_id, 'occurredAt', p_occurred_at),
        'commerce.order.fulfillment_projection', 'delivery:' || p_provider_event_id
    );
    return to_jsonb(v_fulfillment) || jsonb_build_object('order_public_id', v_order.public_id, 'idempotentReplay', false);
end;
$$;

create or replace function commerce.get_order_fulfillment_authorization(p_order_public_id uuid)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_seller commerce.sellers%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_allowed boolean;
    v_reason text;
begin
    select * into v_order from commerce.orders where public_id = p_order_public_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id;
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id order by created_at desc limit 1;
    v_allowed := coalesce(v_terms.order_id is not null
        and v_order.status = 'active'
        and v_payment.status = 'succeeded'
        -- `shipment_creating` is retryable here. The durable reservation below
        -- remains the atomic authority: it serializes the seller/worker retry,
        -- rejects ambiguous/manual-review operations and preserves the exact
        -- immutable delivery quote.
        and v_fulfillment.status in ('awaiting_shipment', 'shipment_creating', 'label_created')
        and not exists (
            select 1 from commerce.refund_requests
            where order_id = v_order.id and status not in ('rejected', 'cancelled', 'failed')
        )
        and not exists (
            select 1 from commerce.stripe_dispute_projections
            where order_id = v_order.id and status not in ('won', 'prevented', 'warning_closed')
        ), false);
    v_reason := case
        when v_terms.order_id is null then 'financial_terms_missing'
        when v_payment.status is distinct from 'succeeded' then 'payment_not_confirmed'
        when v_order.status <> 'active' then 'order_not_active'
        when v_fulfillment.status not in ('awaiting_shipment', 'shipment_creating', 'label_created') then 'fulfillment_not_eligible'
        when exists (select 1 from commerce.refund_requests where order_id = v_order.id and status not in ('rejected', 'cancelled', 'failed')) then 'refund_open'
        when exists (select 1 from commerce.stripe_dispute_projections where order_id = v_order.id and status not in ('won', 'prevented', 'warning_closed')) then 'stripe_dispute_open'
        else null end;
    return jsonb_build_object(
        'allowed', v_allowed,
        'reason', v_reason,
        'orderId', v_order.id,
        'orderPublicId', v_order.public_id,
        'sellerId', v_seller.cms_user_id,
        'buyerCmsUserId', v_order.buyer_cms_user_id,
        'currency', upper(coalesce(v_terms.currency, '')),
        'deliveryQuoteId', coalesce(v_terms.delivery_quote_id, ''),
        'merchandiseSubtotalMinorAmount', coalesce(v_terms.merchandise_subtotal_amount, 0),
        'shippingAmount', coalesce(v_terms.shipping_amount, 0),
        'buyerTotalAmount', coalesce(v_terms.buyer_total_amount, 0),
        'financialTermsHash', v_terms.financial_terms_hash,
        'paymentStatus', coalesce(v_payment.status, 'created'),
        'fulfillmentStatus', coalesce(v_fulfillment.status, 'uninitialized')
    );
end;
$$;

create or replace function commerce.open_marketplace_claim(
    p_order_id bigint,
    p_buyer_cms_user_id text,
    p_reason text,
    p_description text,
    p_requested_amount bigint default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_claim commerce.marketplace_claims%rowtype;
begin
    select * into v_order from commerce.orders
    where id = p_order_id and buyer_cms_user_id = p_buyer_cms_user_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = v_order.id for update;
    select * into v_fulfillment from commerce.order_fulfillments
    where order_id = v_order.id for update;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    select * into v_protection from commerce.protection_policies where id = v_terms.protection_policy_id;
    if v_fulfillment.status <> 'collected_by_recipient' or v_fulfillment.recipient_handoff_at is null then
        raise exception 'conflict: a marketplace claim requires trusted recipient handoff';
    end if;
    if v_fulfillment.claim_by_at is null or now() >= v_fulfillment.claim_by_at then
        raise exception 'conflict: marketplace claim window has closed';
    end if;
    if v_settlement.status in ('release_pending', 'reserve_held', 'released', 'reversal_pending', 'reversed', 'refunded') then
        raise exception 'conflict: settlement can no longer accept a standard marketplace claim';
    end if;
    if p_requested_amount is not null and (p_requested_amount < 0 or p_requested_amount > v_terms.buyer_total_amount) then
        raise exception 'validation: requested claim amount exceeds buyer total';
    end if;
    insert into commerce.marketplace_claims (
        order_id, buyer_cms_user_id, seller_id, reason, status, description,
        buyer_requested_amount, seller_response_by_at
    ) values (
        v_order.id, p_buyer_cms_user_id, v_order.seller_id, p_reason,
        'awaiting_seller_response', p_description, p_requested_amount,
        now() + make_interval(hours => v_protection.seller_response_hours)
    ) returning * into v_claim;
    update commerce.order_settlements set
        status = 'blocked', manual_review_reason = 'marketplace_claim_open'
    where order_id = v_order.id;
    insert into commerce.marketplace_claim_events (
        claim_id, event_type, actor_kind, actor_id, message
    ) values (v_claim.id, 'opened', 'buyer', p_buyer_cms_user_id, p_description);
    perform commerce.append_financial_event(
        v_order.id, 'marketplace_claim', v_claim.id::text, 'claim_opened',
        'buyer', p_buyer_cms_user_id, p_reason,
        jsonb_build_object('claimPublicId', v_claim.public_id, 'requestedAmount', p_requested_amount),
        'commerce.claim.opened', 'claim:' || v_claim.id || ':opened'
    );
    return to_jsonb(v_claim);
end;
$$;

create or replace function commerce.respond_marketplace_claim(
    p_claim_id bigint,
    p_seller_cms_user_id text,
    p_message text,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_claim commerce.marketplace_claims%rowtype;
begin
    select claim.* into v_claim
    from commerce.marketplace_claims claim
    join commerce.sellers seller on seller.id = claim.seller_id
    where claim.id = p_claim_id and seller.cms_user_id = p_seller_cms_user_id
    for update of claim;
    if not found then raise exception 'not_found: claim'; end if;
    if v_claim.version is distinct from p_expected_version then raise exception 'conflict: stale claim version'; end if;
    if v_claim.status not in ('open', 'awaiting_seller_response') then
        raise exception 'conflict: claim no longer accepts a seller response';
    end if;
    update commerce.marketplace_claims set status = 'under_review'
    where id = v_claim.id returning * into v_claim;
    insert into commerce.marketplace_claim_events (
        claim_id, event_type, actor_kind, actor_id, message
    ) values (v_claim.id, 'seller_responded', 'seller', p_seller_cms_user_id, p_message);
    perform commerce.append_financial_event(
        v_claim.order_id, 'marketplace_claim', v_claim.id::text, 'claim_seller_responded',
        'seller', p_seller_cms_user_id, null, '{}'::jsonb,
        'commerce.claim.seller_responded', 'claim:' || v_claim.id || ':seller-response:' || v_claim.version
    );
    return to_jsonb(v_claim);
end;
$$;

create or replace function commerce.attach_marketplace_claim_evidence(
    p_claim_id bigint,
    p_submitted_by_kind text,
    p_submitted_by text,
    p_storage_bucket text,
    p_storage_path text,
    p_mime_type text,
    p_file_size bigint,
    p_original_filename text,
    p_sha256 text,
    p_description text default null,
    p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_claim commerce.marketplace_claims%rowtype;
    v_evidence commerce.marketplace_claim_evidence%rowtype;
begin
    select * into v_claim from commerce.marketplace_claims where id = p_claim_id for update;
    if not found then raise exception 'not_found: claim'; end if;
    if v_claim.status in ('resolved_buyer', 'resolved_seller', 'resolved_split') then
        raise exception 'conflict: resolved claim no longer accepts evidence';
    end if;
    if p_submitted_by_kind = 'buyer' then
        if v_claim.buyer_cms_user_id is distinct from p_submitted_by then
            raise exception 'not_found: claim';
        end if;
    elsif p_submitted_by_kind = 'seller' then
        if not exists (
            select 1 from commerce.sellers seller
            where seller.id = v_claim.seller_id and seller.cms_user_id = p_submitted_by
        ) then raise exception 'not_found: claim'; end if;
    else
        raise exception 'forbidden: claim evidence actor is not allowed';
    end if;
    if p_storage_bucket <> 'commerce-claim-evidence'
        or p_storage_path !~ ('^claims/' || v_claim.public_id::text || '/(buyer|seller)/[A-Za-z0-9._-]+$') then
        raise exception 'validation: invalid claim evidence storage location';
    end if;
    insert into commerce.marketplace_claim_evidence (
        claim_id, submitted_by_kind, submitted_by, storage_bucket, storage_path,
        mime_type, file_size, original_filename, sha256, description, metadata
    ) values (
        v_claim.id, p_submitted_by_kind, p_submitted_by, p_storage_bucket, p_storage_path,
        p_mime_type, p_file_size, p_original_filename, p_sha256, nullif(btrim(p_description), ''),
        coalesce(p_metadata, '{}'::jsonb)
    ) returning * into v_evidence;
    insert into commerce.marketplace_claim_events (
        claim_id, event_type, actor_kind, actor_id, message, data
    ) values (
        v_claim.id, 'evidence_submitted', p_submitted_by_kind, p_submitted_by,
        nullif(btrim(p_description), ''),
        jsonb_build_object('evidenceId', v_evidence.id, 'mimeType', v_evidence.mime_type,
            'fileSize', v_evidence.file_size, 'sha256', v_evidence.sha256)
    );
    return jsonb_build_object(
        'id', v_evidence.id, 'claimId', v_evidence.claim_id,
        'submittedByKind', v_evidence.submitted_by_kind,
        'mimeType', v_evidence.mime_type, 'fileSize', v_evidence.file_size,
        'originalFilename', v_evidence.original_filename, 'sha256', v_evidence.sha256,
        'description', v_evidence.description, 'metadata', v_evidence.metadata,
        'createdAt', v_evidence.created_at
    );
end;
$$;

create or replace function commerce.get_claim_evidence_upload_context(
    p_claim_id bigint,
    p_actor_kind text,
    p_actor_id text
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    select coalesce((
        select jsonb_build_object(
            'state', 'ok',
            'public_id', claim.public_id
        )
        from commerce.marketplace_claims claim
        where claim.id = p_claim_id
          and claim.status not in ('resolved_buyer', 'resolved_seller', 'resolved_split')
          and (
              (p_actor_kind = 'buyer' and claim.buyer_cms_user_id = p_actor_id)
              or (
                  p_actor_kind = 'seller'
                  and exists (
                      select 1
                      from commerce.sellers seller
                      where seller.id = claim.seller_id
                        and seller.cms_user_id = p_actor_id
                  )
              )
          )
    ), jsonb_build_object('state', 'not_found'));
$$;

revoke execute on function commerce.get_claim_evidence_upload_context(bigint, text, text)
from public, anon, authenticated;
grant execute on function commerce.get_claim_evidence_upload_context(bigint, text, text)
to service_role;

create or replace function commerce.get_claim_evidence_download_context(
    p_evidence_id bigint,
    p_scope text,
    p_actor_id text
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    with context as (
        select evidence.storage_bucket,
            evidence.storage_path,
            evidence.mime_type,
            evidence.claim_id
        from commerce.marketplace_claim_evidence evidence
        where evidence.id = p_evidence_id
    )
    select coalesce((
        select case
            when context.storage_bucket <> 'commerce-claim-evidence'
                then jsonb_build_object('state', 'evidence_not_found')
            when p_scope = 'admin'
                then jsonb_build_object(
                    'state', 'ok',
                    'evidence', jsonb_build_object(
                        'storage_bucket', context.storage_bucket,
                        'storage_path', context.storage_path,
                        'mime_type', context.mime_type
                    )
                )
            when p_actor_id is null or btrim(p_actor_id) = ''
                then jsonb_build_object('state', 'identity_required')
            when exists (
                select 1
                from commerce.marketplace_claims claim
                where claim.id = context.claim_id
                  and claim.status not in (
                      'resolved_buyer', 'resolved_seller', 'resolved_split'
                  )
                  and (
                      (p_scope = 'buyer' and claim.buyer_cms_user_id = p_actor_id)
                      or (
                          p_scope = 'seller'
                          and exists (
                              select 1
                              from commerce.sellers seller
                              where seller.id = claim.seller_id
                                and seller.cms_user_id = p_actor_id
                          )
                      )
                  )
            )
                then jsonb_build_object(
                    'state', 'ok',
                    'evidence', jsonb_build_object(
                        'storage_bucket', context.storage_bucket,
                        'storage_path', context.storage_path,
                        'mime_type', context.mime_type
                    )
                )
            else jsonb_build_object('state', 'claim_not_found')
        end
        from context
    ), jsonb_build_object('state', 'evidence_not_found'));
$$;

revoke execute on function commerce.get_claim_evidence_download_context(bigint, text, text)
from public, anon, authenticated;
grant execute on function commerce.get_claim_evidence_download_context(bigint, text, text)
to service_role;

create or replace function commerce.get_claim_return_authorization_context(
    p_claim_id bigint
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    select coalesce((
        select jsonb_build_object(
            'state', 'ok',
            'claim', jsonb_build_object(
                'id', claim.id,
                'public_id', claim.public_id,
                'buyer_cms_user_id', claim.buyer_cms_user_id,
                'status', claim.status,
                'resolution_outcome', claim.resolution_outcome,
                'return_ship_by_at', claim.return_ship_by_at,
                'return_delivery_status', claim.return_delivery_status,
                'return_recipient_handoff_at', claim.return_recipient_handoff_at,
                'version', claim.version
            ),
            'order', case when orders.id is null then null else jsonb_build_object(
                'id', orders.id,
                'public_id', orders.public_id,
                'order_number', orders.order_number
            ) end,
            'seller', case when seller.id is null then null else jsonb_build_object(
                'id', seller.id,
                'cms_user_id', seller.cms_user_id
            ) end,
            'financial_terms', case when terms.order_id is null then null
                else jsonb_build_object(
                    'delivery_quote_id', terms.delivery_quote_id,
                    'merchandise_subtotal_amount', terms.merchandise_subtotal_amount,
                    'currency', terms.currency
                )
            end
        )
        from commerce.marketplace_claims claim
        left join commerce.orders orders on orders.id = claim.order_id
        left join commerce.sellers seller on seller.id = claim.seller_id
        left join commerce.order_financial_terms terms on terms.order_id = claim.order_id
        where claim.id = p_claim_id
    ), jsonb_build_object('state', 'not_found'));
$$;

revoke execute on function commerce.get_claim_return_authorization_context(bigint)
from public, anon, authenticated;
grant execute on function commerce.get_claim_return_authorization_context(bigint)
to service_role;

create or replace function commerce.get_marketplace_claim_read_model(
    p_claim_id bigint
)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
    select coalesce((
        select jsonb_build_object(
            'state', 'ok',
            'claim', jsonb_build_object(
                'id', claim.id,
                'public_id', claim.public_id,
                'order_id', claim.order_id,
                'buyer_cms_user_id', claim.buyer_cms_user_id,
                'seller_id', claim.seller_id,
                'reason', claim.reason,
                'status', claim.status,
                'description', claim.description,
                'buyer_requested_amount', claim.buyer_requested_amount,
                'resolution_outcome', claim.resolution_outcome,
                'resolution_buyer_refund_amount', claim.resolution_buyer_refund_amount,
                'resolution_seller_transfer_amount', claim.resolution_seller_transfer_amount,
                'resolution_protection_fee_refund_amount', claim.resolution_protection_fee_refund_amount,
                'decision_reason', claim.decision_reason,
                'seller_response_by_at', claim.seller_response_by_at,
                'return_ship_by_at', claim.return_ship_by_at,
                'return_delivery_status', claim.return_delivery_status,
                'return_provider_reference', claim.return_provider_reference,
                'return_carrier_accepted_at', claim.return_carrier_accepted_at,
                'return_recipient_handoff_at', claim.return_recipient_handoff_at,
                'resolved_at', claim.resolved_at,
                'resolved_by', claim.resolved_by,
                'version', claim.version,
                'created_at', claim.created_at,
                'updated_at', claim.updated_at
            ),
            'events', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', event.id,
                    'claim_id', event.claim_id,
                    'event_type', event.event_type,
                    'actor_kind', event.actor_kind,
                    'actor_id', event.actor_id,
                    'message', event.message,
                    'data', event.data,
                    'created_at', event.created_at
                ) order by event.created_at, event.id)
                from commerce.marketplace_claim_events event
                where event.claim_id = claim.id
            ), '[]'::jsonb),
            'evidence', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', evidence.id,
                    'claim_id', evidence.claim_id,
                    'submitted_by_kind', evidence.submitted_by_kind,
                    'mime_type', evidence.mime_type,
                    'file_size', evidence.file_size,
                    'original_filename', evidence.original_filename,
                    'sha256', evidence.sha256,
                    'description', evidence.description,
                    'metadata', evidence.metadata,
                    'created_at', evidence.created_at
                ) order by evidence.created_at, evidence.id)
                from commerce.marketplace_claim_evidence evidence
                where evidence.claim_id = claim.id
            ), '[]'::jsonb),
            'return_events', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', event.id,
                    'provider_event_id', event.provider_event_id,
                    'provider_reference', event.provider_reference,
                    'normalized_status', event.normalized_status,
                    'occurred_at', event.occurred_at,
                    'created_at', event.created_at
                ) order by event.occurred_at, event.id)
                from commerce.marketplace_claim_return_events event
                where event.claim_id = claim.id
            ), '[]'::jsonb)
        )
        from commerce.marketplace_claims claim
        where claim.id = p_claim_id
    ), jsonb_build_object('state', 'not_found'));
$$;

revoke execute on function commerce.get_marketplace_claim_read_model(bigint)
from public, anon, authenticated;
grant execute on function commerce.get_marketplace_claim_read_model(bigint)
to service_role;

create or replace function commerce.calculate_protection_fee_refund(
    p_order_id bigint,
    p_requested_amount bigint,
    p_resolution_defined_amount bigint default null
)
returns bigint
language plpgsql
stable
set search_path = ''
as $$
declare
    v_terms commerce.order_financial_terms%rowtype;
    v_component commerce.fee_policy_components%rowtype;
    v_existing_amount bigint;
    v_existing_protection_refund bigint;
    v_remaining_fee bigint;
    v_result bigint;
begin
    if p_requested_amount is null or p_requested_amount <= 0 then
        raise exception 'validation: protection fee calculation requires a positive refund amount';
    end if;
    select * into v_terms
    from commerce.order_financial_terms
    where order_id = p_order_id;
    if not found then
        raise exception 'conflict: refund requires immutable financial terms';
    end if;
    select * into v_component
    from commerce.fee_policy_components
    where fee_policy_id = v_terms.fee_policy_id
      and component_key = 'buyer_protection';
    if not found then
        raise exception 'conflict: buyer protection refund policy is missing';
    end if;
    select coalesce(sum(requested_amount), 0),
        coalesce(sum(protection_fee_refund_amount), 0)
    into v_existing_amount, v_existing_protection_refund
    from commerce.refund_requests
    where order_id = p_order_id
      and status not in ('rejected', 'cancelled', 'failed');
    if v_existing_amount + p_requested_amount > v_terms.buyer_total_amount then
        raise exception 'validation: cumulative refund requests exceed captured buyer total';
    end if;
    v_remaining_fee := greatest(
        0,
        v_terms.buyer_protection_fee_amount - v_existing_protection_refund
    );
    v_result := case v_component.refund_policy
        when 'always' then least(p_requested_amount, v_remaining_fee)
        when 'never' then 0
        when 'proportional' then
            case when v_terms.buyer_total_amount = 0 then 0 else
                least(
                    p_requested_amount,
                    v_remaining_fee,
                    greatest(
                        0,
                        floor((v_terms.buyer_protection_fee_amount::numeric
                            * (v_existing_amount + p_requested_amount)
                            + v_terms.buyer_total_amount / 2)
                            / v_terms.buyer_total_amount)::bigint
                            - v_existing_protection_refund
                    )
                )
            end
        when 'resolution_defined' then coalesce(p_resolution_defined_amount, 0)
        else 0
    end;
    if v_component.refund_policy = 'resolution_defined'
        and (v_result < 0 or v_result > least(p_requested_amount, v_remaining_fee)) then
        raise exception 'validation: resolution-defined protection fee refund exceeds the remaining policy amount';
    end if;
    return v_result;
end;
$$;

create or replace function commerce.create_refund_request(
    p_order_id bigint,
    p_claim_id bigint,
    p_business_key text,
    p_reason text,
    p_requested_amount bigint,
    p_protection_fee_refund_amount bigint,
    p_seller_recovery_amount bigint,
    p_requested_by_kind text,
    p_requested_by text,
    p_auto_approve boolean default false
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_existing_amount bigint;
    v_existing_protection_refund bigint;
    v_existing_seller_recovery bigint;
    v_existing_platform_contribution bigint;
    v_platform_contribution bigint;
    v_platform_contribution_cap bigint;
    v_cumulative_amount bigint;
    v_expected_protection_refund bigint;
    v_requires_finance boolean;
    v_requires_dual boolean;
    v_request commerce.refund_requests%rowtype;
    v_business_key text;
begin
    if p_requested_by_kind is null
        or p_requested_by_kind not in ('buyer', 'seller', 'admin', 'system')
        or p_requested_by is null or length(btrim(p_requested_by)) = 0 then
        raise exception 'forbidden: refund request actor is not allowed';
    end if;
    select * into v_order from commerce.orders where id = p_order_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    if not found then raise exception 'conflict: refund requires immutable financial terms'; end if;
    if not exists (
        select 1 from commerce.order_payment_attempts attempt
        where attempt.order_id = v_order.id and attempt.status = 'succeeded'
    ) then raise exception 'conflict: refund requires confirmed payment'; end if;
    select * into v_protection from commerce.protection_policies where id = v_terms.protection_policy_id;
    select * into v_settlement from commerce.order_settlements where order_id = v_order.id for update;
    select coalesce(sum(requested_amount), 0),
        coalesce(sum(protection_fee_refund_amount), 0),
        coalesce(sum(seller_recovery_amount), 0),
        coalesce(sum(
            requested_amount - protection_fee_refund_amount - seller_recovery_amount
        ), 0)
    into v_existing_amount, v_existing_protection_refund, v_existing_seller_recovery,
        v_existing_platform_contribution
    from commerce.refund_requests
    where order_id = v_order.id and status not in ('rejected', 'cancelled', 'failed');
    if p_requested_amount <= 0 or p_requested_amount + v_existing_amount > v_terms.buyer_total_amount then
        raise exception 'validation: cumulative refund requests exceed captured buyer total';
    end if;
    v_expected_protection_refund := commerce.calculate_protection_fee_refund(
        v_order.id, p_requested_amount, p_protection_fee_refund_amount
    );
    if p_protection_fee_refund_amount is distinct from v_expected_protection_refund then
        raise exception 'validation: protection fee refund does not match the immutable fee policy';
    end if;
    if p_protection_fee_refund_amount < 0 or p_protection_fee_refund_amount > p_requested_amount
        or p_seller_recovery_amount < 0 or p_seller_recovery_amount > p_requested_amount then
        raise exception 'validation: invalid refund allocation';
    end if;
    if p_protection_fee_refund_amount + p_seller_recovery_amount > p_requested_amount
        or v_existing_protection_refund + p_protection_fee_refund_amount > v_terms.buyer_protection_fee_amount
        or v_existing_seller_recovery + p_seller_recovery_amount > v_terms.seller_proceeds_amount then
        raise exception 'validation: cumulative refund allocation exceeds immutable financial terms';
    end if;
    v_platform_contribution := p_requested_amount
        - p_protection_fee_refund_amount - p_seller_recovery_amount;
    v_platform_contribution_cap := greatest(
        0,
        v_terms.platform_retained_amount - v_terms.buyer_protection_fee_amount
    );
    if v_platform_contribution < 0
        or v_existing_platform_contribution + v_platform_contribution
            > v_platform_contribution_cap then
        raise exception 'validation: cumulative platform-funded refund exceeds immutable platform contribution';
    end if;
    v_cumulative_amount := v_existing_amount + p_requested_amount;
    v_requires_finance := v_cumulative_amount >= v_protection.finance_review_threshold_amount
        or p_requested_by_kind = 'admin';
    v_requires_dual := v_cumulative_amount >= v_protection.dual_approval_threshold_amount;
    v_business_key := coalesce(
        nullif(btrim(p_business_key), ''),
        'refund:' || v_order.id || ':' || gen_random_uuid()::text
    );
    insert into commerce.refund_requests (
        order_id, claim_id, business_key, reason, status, requested_amount,
        protection_fee_refund_amount, seller_recovery_amount, seller_reserve_offset_amount,
        requires_finance_approval, dual_approval_required, requested_by_kind, requested_by,
        approved_by, decision_reason
    ) values (
        v_order.id, p_claim_id, v_business_key, p_reason,
        case when p_auto_approve and not v_requires_finance then 'approved' else 'requested' end,
        p_requested_amount, p_protection_fee_refund_amount, p_seller_recovery_amount,
        least(p_seller_recovery_amount, v_settlement.seller_reserve_liability_remaining_amount),
        v_requires_finance, v_requires_dual, p_requested_by_kind, p_requested_by,
        case when p_auto_approve and not v_requires_finance then p_requested_by end,
        case when p_auto_approve and not v_requires_finance then 'Policy-authorized business resolution' end
    ) on conflict (business_key) do update set business_key = excluded.business_key
    returning * into v_request;
    update commerce.order_settlements set status = case
        when total_transferred_amount > total_reversed_amount
          and v_request.seller_recovery_amount > v_request.seller_reserve_offset_amount
            then 'reversal_pending'
        else 'refund_pending' end
    where order_id = v_order.id and status not in ('refunded', 'reversed', 'manual_review');
    perform commerce.append_financial_event(
        v_order.id, 'refund_request', v_request.id::text, 'refund_requested',
        p_requested_by_kind, p_requested_by, p_reason,
        jsonb_build_object('amount', p_requested_amount, 'requiresFinanceApproval', v_requires_finance),
        'commerce.refund.requested', 'refund:' || v_request.id || ':requested'
    );
    return to_jsonb(v_request);
end;
$$;

create or replace function commerce.refund_authorization_payload(p_refund_request_id bigint)
returns jsonb
language sql
stable
set search_path = ''
as $$
select jsonb_build_object(
    'status', request.status,
    'orderId', order_row.id,
    'orderPublicId', order_row.public_id,
    'providerPaymentId', payment.provider_payment_id,
    'refundRequestId', request.business_key,
    'commerceRefundRequestId', request.id,
    'businessKey', request.business_key,
    'amount', request.requested_amount,
    'authorizedSellerAmount', greatest(
        0, settlement.authorized_seller_amount - request.seller_recovery_amount
    ),
    'sellerEntitlementReductionAmount', request.seller_recovery_amount,
    'sellerRecoveryAmount', least(
        request.seller_recovery_amount - request.seller_reserve_offset_amount,
        greatest(0, settlement.total_transferred_amount - settlement.total_reversed_amount)
    ),
    'sellerReserveOffsetAmount', request.seller_reserve_offset_amount,
    'protectionFeeRefundAmount', request.protection_fee_refund_amount,
    'currency', upper(terms.currency),
    'financialTermsHash', terms.financial_terms_hash,
    'requiresFinanceApproval', request.requires_finance_approval,
    'requiresDualApproval', request.dual_approval_required
)
from commerce.refund_requests request
join commerce.orders order_row on order_row.id = request.order_id
join commerce.order_financial_terms terms on terms.order_id = order_row.id
join commerce.order_settlements settlement on settlement.order_id = order_row.id
left join lateral (
    select attempt.provider_payment_id
    from commerce.order_payment_attempts attempt
    where attempt.order_id = order_row.id and attempt.status = 'succeeded'
    order by attempt.created_at desc limit 1
) payment on true
where request.id = p_refund_request_id;
$$;

create or replace function commerce.record_claim_return_delivery(
    p_claim_id bigint,
    p_provider_event_id text,
    p_provider_reference text,
    p_normalized_status text,
    p_occurred_at timestamptz,
    p_provider_evidence jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_claim commerce.marketplace_claims%rowtype;
    v_existing commerce.marketplace_claim_return_events%rowtype;
begin
    if p_normalized_status not in (
        'carrier_accepted', 'in_transit', 'arrived_at_pickup_point', 'available_for_pickup',
        'recipient_handoff', 'pickup_expired', 'returning_to_sender', 'returned_to_sender',
        'incident', 'lost'
    ) then
        raise exception 'validation: unsupported claim return delivery status';
    end if;
    if p_occurred_at is null or p_occurred_at > now() + interval '5 minutes' then
        raise exception 'validation: invalid claim return event timestamp';
    end if;
    select * into v_existing from commerce.marketplace_claim_return_events
    where provider_event_id = p_provider_event_id;
    if found then
        if v_existing.claim_id is distinct from p_claim_id
            or v_existing.provider_reference is distinct from p_provider_reference
            or v_existing.normalized_status is distinct from p_normalized_status
            or v_existing.occurred_at is distinct from p_occurred_at
            or v_existing.provider_evidence is distinct from coalesce(p_provider_evidence, '{}'::jsonb) then
            raise exception 'conflict: claim return provider event replay mismatch';
        end if;
        select * into v_claim from commerce.marketplace_claims where id = p_claim_id;
        return to_jsonb(v_claim) || jsonb_build_object('idempotentReplay', true);
    end if;
    select * into v_claim from commerce.marketplace_claims where id = p_claim_id for update;
    if not found then raise exception 'not_found: claim'; end if;
    if v_claim.status not in ('return_required', 'under_review')
        or v_claim.resolution_outcome <> 'return_required' then
        raise exception 'conflict: claim is not awaiting a required return';
    end if;
    insert into commerce.marketplace_claim_return_events (
        claim_id, provider_event_id, provider_reference, normalized_status,
        occurred_at, provider_evidence
    ) values (
        v_claim.id, p_provider_event_id, p_provider_reference, p_normalized_status,
        p_occurred_at, coalesce(p_provider_evidence, '{}'::jsonb)
    );
    update commerce.marketplace_claims set
        return_delivery_status = case
            when p_normalized_status = 'recipient_handoff' then 'recipient_handoff'
            when return_delivery_status = 'recipient_handoff' then return_delivery_status
            else p_normalized_status end,
        return_provider_reference = p_provider_reference,
        return_carrier_accepted_at = coalesce(
            return_carrier_accepted_at,
            case when p_normalized_status in ('carrier_accepted', 'recipient_handoff') then p_occurred_at end
        ),
        return_recipient_handoff_at = coalesce(
            return_recipient_handoff_at,
            case when p_normalized_status = 'recipient_handoff' then p_occurred_at end
        )
    where id = v_claim.id returning * into v_claim;
    insert into commerce.marketplace_claim_events (
        claim_id, event_type, actor_kind, actor_id, data
    ) values (
        v_claim.id, 'return_delivery_' || p_normalized_status, 'system', 'delivery-provider',
        jsonb_build_object('providerEventId', p_provider_event_id,
            'providerReference', p_provider_reference, 'occurredAt', p_occurred_at)
    );
    perform commerce.append_financial_event(
        v_claim.order_id, 'marketplace_claim', v_claim.id::text,
        'claim_return_delivery_' || p_normalized_status,
        'system', 'delivery-provider', null,
        jsonb_build_object('providerEventId', p_provider_event_id,
            'providerReference', p_provider_reference, 'occurredAt', p_occurred_at),
        'commerce.claim.return_delivery', 'claim-return:' || p_provider_event_id
    );
    return to_jsonb(v_claim) || jsonb_build_object('idempotentReplay', false);
end;
$$;

create or replace function commerce.resolve_marketplace_claim(
    p_claim_id bigint,
    p_outcome text,
    p_buyer_refund_amount bigint,
    p_seller_transfer_amount bigint,
    p_protection_fee_refund_amount bigint,
    p_decision_reason text,
    p_actor_kind text,
    p_actor_id text,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_claim commerce.marketplace_claims%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_protection commerce.protection_policies%rowtype;
    v_expected_protection_refund bigint;
    v_seller_recovery bigint;
    v_existing_platform_contribution bigint;
    v_platform_contribution bigint;
    v_platform_contribution_cap bigint;
    v_refund jsonb;
begin
    if p_actor_kind is distinct from 'admin' then
        raise exception 'forbidden: admin claim resolution actor is required';
    end if;
    if p_outcome not in ('buyer', 'seller', 'split', 'return_required') then
        raise exception 'validation: unsupported claim outcome';
    end if;
    select * into v_claim from commerce.marketplace_claims where id = p_claim_id;
    if not found then raise exception 'not_found: claim'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = v_claim.order_id for update;
    select * into v_claim from commerce.marketplace_claims where id = p_claim_id for update;
    if v_claim.version is distinct from p_expected_version then raise exception 'conflict: stale claim version'; end if;
    if v_claim.status in ('resolved_buyer', 'resolved_seller', 'resolved_split') then
        raise exception 'conflict: claim is already resolved';
    end if;
    if v_claim.status = 'return_required' and p_outcome <> 'return_required'
        and v_claim.return_recipient_handoff_at is null then
        raise exception 'conflict: required return needs trusted recipient handoff before monetary resolution';
    end if;
    if v_claim.status = 'return_required' and p_outcome = 'return_required' then
        raise exception 'conflict: claim is already awaiting the required return';
    end if;
    select * into v_terms from commerce.order_financial_terms where order_id = v_claim.order_id;
    select * into v_protection from commerce.protection_policies where id = v_terms.protection_policy_id;
    if p_outcome = 'return_required' then
        if p_buyer_refund_amount <> 0 or p_seller_transfer_amount <> 0
            or p_protection_fee_refund_amount <> 0 then
            raise exception 'validation: return-required resolution cannot authorize money movement';
        end if;
        update commerce.marketplace_claims set
            status = 'return_required', resolution_outcome = 'return_required',
            decision_reason = p_decision_reason,
            return_ship_by_at = now() + make_interval(hours => v_protection.return_ship_hours),
            return_delivery_status = 'awaiting_carrier',
            resolved_by = p_actor_id
        where id = v_claim.id returning * into v_claim;
    else
        if p_buyer_refund_amount < 0 or p_buyer_refund_amount > v_terms.buyer_total_amount
            or p_seller_transfer_amount < 0
            or p_seller_transfer_amount > v_settlement.authorized_seller_amount
            or p_protection_fee_refund_amount < 0 or p_protection_fee_refund_amount > v_terms.buyer_protection_fee_amount then
            raise exception 'validation: claim resolution exceeds immutable financial terms';
        end if;
        if p_buyer_refund_amount > 0 then
            v_expected_protection_refund := commerce.calculate_protection_fee_refund(
                v_claim.order_id,
                p_buyer_refund_amount,
                p_protection_fee_refund_amount
            );
            if p_protection_fee_refund_amount is distinct from v_expected_protection_refund then
                raise exception 'validation: claim protection fee refund does not match the immutable fee policy';
            end if;
        end if;
        if p_outcome = 'buyer' and p_seller_transfer_amount <> 0 then
            raise exception 'validation: buyer resolution cannot authorize a seller transfer';
        end if;
        if p_protection_fee_refund_amount > p_buyer_refund_amount then
            raise exception 'validation: protection fee refund exceeds buyer refund';
        end if;
        if p_outcome = 'buyer' and p_buyer_refund_amount = 0 then
            raise exception 'validation: buyer resolution requires a refund';
        end if;
        if p_outcome = 'seller' and (
            p_buyer_refund_amount <> 0 or p_protection_fee_refund_amount <> 0
            or p_seller_transfer_amount <> v_settlement.authorized_seller_amount
        ) then
            raise exception 'validation: seller resolution must preserve the immutable seller entitlement';
        end if;
        if p_outcome = 'split' and (
            p_buyer_refund_amount = 0
            or p_seller_transfer_amount <= 0
            or p_seller_transfer_amount >= v_settlement.authorized_seller_amount
        ) then
            raise exception 'validation: split resolution requires both a refund and reduced seller release';
        end if;
        v_seller_recovery := greatest(
            0,
            v_settlement.authorized_seller_amount - p_seller_transfer_amount
        );
        v_platform_contribution := p_buyer_refund_amount
            - v_seller_recovery - p_protection_fee_refund_amount;
        select coalesce(sum(
            requested_amount - protection_fee_refund_amount - seller_recovery_amount
        ), 0)
        into v_existing_platform_contribution
        from commerce.refund_requests
        where order_id = v_claim.order_id
          and status not in ('rejected', 'cancelled', 'failed');
        v_platform_contribution_cap := greatest(
            0,
            v_terms.platform_retained_amount - v_terms.buyer_protection_fee_amount
        );
        if v_platform_contribution < 0 then
            raise exception 'validation: claim refund cannot be lower than seller recovery plus protection fee refund';
        end if;
        if v_existing_platform_contribution + v_platform_contribution
            > v_platform_contribution_cap then
            raise exception 'validation: claim refund exceeds immutable platform contribution';
        end if;
        update commerce.marketplace_claims set
            status = case when p_outcome = 'seller' then 'resolved_seller' else 'resolution_pending' end,
            resolution_outcome = p_outcome,
            resolution_buyer_refund_amount = p_buyer_refund_amount,
            resolution_seller_transfer_amount = p_seller_transfer_amount,
            resolution_protection_fee_refund_amount = p_protection_fee_refund_amount,
            decision_reason = p_decision_reason,
            resolved_at = case when p_outcome = 'seller' then now() else null end,
            resolved_by = p_actor_id
        where id = v_claim.id returning * into v_claim;
        -- The refund request carries the delta from the current locked seller
        -- entitlement. Keep that entitlement and reserve untouched until Stripe confirms
        -- that refund; record_order_settlement_projection then applies the
        -- recovery exactly once. Pre-applying p_seller_transfer_amount here
        -- would double-decrement split/buyer resolutions on provider success.
        update commerce.order_settlements set
            status = case when p_buyer_refund_amount > 0 then 'refund_pending' else 'held' end,
            manual_review_reason = null
        where order_id = v_claim.order_id;
        if p_buyer_refund_amount > 0 then
            v_refund := commerce.create_refund_request(
                v_claim.order_id, v_claim.id,
                'claim:' || v_claim.id || ':resolution:' || p_expected_version,
                'marketplace_claim_' || p_outcome, p_buyer_refund_amount,
                p_protection_fee_refund_amount,
                v_seller_recovery,
                p_actor_kind, p_actor_id, true
            );
        end if;
    end if;
    insert into commerce.marketplace_claim_events (
        claim_id, event_type, actor_kind, actor_id, message, data
    ) values (
        v_claim.id, 'resolution_decided', p_actor_kind, p_actor_id, p_decision_reason,
        jsonb_build_object('outcome', p_outcome, 'buyerRefundAmount', p_buyer_refund_amount,
            'sellerTransferAmount', p_seller_transfer_amount,
            'platformContributionAmount', coalesce(v_platform_contribution, 0))
    );
    perform commerce.append_financial_event(
        v_claim.order_id, 'marketplace_claim', v_claim.id::text, 'claim_resolution_decided',
        p_actor_kind, p_actor_id, p_decision_reason,
        jsonb_build_object('outcome', p_outcome, 'refund', v_refund),
        'commerce.claim.resolution_decided', 'claim:' || v_claim.id || ':resolution:' || p_expected_version
    );
    return to_jsonb(v_claim) || jsonb_build_object(
        'refundRequest', v_refund,
        'refundAuthorization', case
            when v_refund is null then null
            else commerce.refund_authorization_payload((v_refund->>'id')::bigint)
        end
    );
end;
$$;

create or replace function commerce.request_order_refund(
    p_order_id bigint,
    p_reason text,
    p_requested_amount bigint,
    p_actor_kind text,
    p_actor_id text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_terms commerce.order_financial_terms%rowtype;
    v_component commerce.fee_policy_components%rowtype;
    v_existing_amount bigint;
    v_existing_protection_refund bigint;
    v_existing_seller_recovery bigint;
    v_protection_refund bigint;
    v_seller_recovery bigint;
    v_remaining_non_fee bigint;
    v_request jsonb;
begin
    if p_actor_kind is distinct from 'admin' then
        raise exception 'forbidden: admin refund request actor is required';
    end if;
    select * into v_terms from commerce.order_financial_terms where order_id = p_order_id;
    if not found then raise exception 'conflict: refund requires immutable financial terms'; end if;
    select coalesce(sum(requested_amount), 0),
        coalesce(sum(protection_fee_refund_amount), 0),
        coalesce(sum(seller_recovery_amount), 0)
    into v_existing_amount, v_existing_protection_refund, v_existing_seller_recovery
    from commerce.refund_requests
    where order_id = p_order_id and status not in ('rejected', 'cancelled', 'failed');
    v_protection_refund := commerce.calculate_protection_fee_refund(
        p_order_id, p_requested_amount, 0
    );
    v_remaining_non_fee := greatest(
        0,
        v_terms.buyer_total_amount - v_terms.buyer_protection_fee_amount
            - (v_existing_amount - v_existing_protection_refund)
    );
    if p_requested_amount <= 0 or p_requested_amount > v_remaining_non_fee + v_protection_refund then
        raise exception 'validation: requested refund includes a non-refundable protection fee';
    end if;
    v_seller_recovery := least(
        p_requested_amount - v_protection_refund,
        greatest(0, v_terms.seller_proceeds_amount - v_existing_seller_recovery)
    );
    v_request := commerce.create_refund_request(
        p_order_id, null, null, p_reason, p_requested_amount,
        v_protection_refund, v_seller_recovery,
        p_actor_kind, p_actor_id, true
    );
    return v_request || jsonb_build_object(
        'refundAuthorization', commerce.refund_authorization_payload((v_request->>'id')::bigint)
    );
end;
$$;

create or replace function commerce.create_cancellation_refund_request(
    p_order_id bigint,
    p_business_key text,
    p_reason text,
    p_requested_by_kind text,
    p_requested_by text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_terms commerce.order_financial_terms%rowtype;
    v_component commerce.fee_policy_components%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_existing_amount bigint;
    v_existing_protection_refund bigint;
    v_remaining_captured bigint;
    v_remaining_fee bigint;
    v_requested_amount bigint;
    v_protection_refund bigint;
    v_seller_recovery bigint;
begin
    select * into v_terms
    from commerce.order_financial_terms
    where order_id = p_order_id;
    if not found then
        raise exception 'conflict: cancellation refund requires immutable financial terms';
    end if;
    select * into v_component
    from commerce.fee_policy_components
    where fee_policy_id = v_terms.fee_policy_id
      and component_key = 'buyer_protection';
    if not found then
        raise exception 'conflict: buyer protection refund policy is missing';
    end if;
    select * into v_settlement
    from commerce.order_settlements
    where order_id = p_order_id;
    if not found then
        raise exception 'conflict: cancellation refund requires a settlement';
    end if;
    select coalesce(sum(requested_amount), 0),
        coalesce(sum(protection_fee_refund_amount), 0)
    into v_existing_amount, v_existing_protection_refund
    from commerce.refund_requests
    where order_id = p_order_id
      and status not in ('rejected', 'cancelled', 'failed');
    v_remaining_captured := greatest(0, v_terms.buyer_total_amount - v_existing_amount);
    v_remaining_fee := greatest(
        0,
        v_terms.buyer_protection_fee_amount - v_existing_protection_refund
    );
    v_requested_amount := greatest(
        0,
        v_remaining_captured - case
            when v_component.refund_policy = 'never' then v_remaining_fee
            else 0
        end
    );
    if v_requested_amount = 0 then
        return null;
    end if;
    v_protection_refund := commerce.calculate_protection_fee_refund(
        p_order_id,
        v_requested_amount,
        case when v_component.refund_policy = 'resolution_defined'
            then least(v_requested_amount, v_remaining_fee)
            else null end
    );
    v_seller_recovery := least(
        v_settlement.authorized_seller_amount,
        greatest(0, v_requested_amount - v_protection_refund)
    );
    return commerce.create_refund_request(
        p_order_id, null, p_business_key, p_reason, v_requested_amount,
        v_protection_refund, v_seller_recovery,
        p_requested_by_kind, p_requested_by, true
    );
end;
$$;

create or replace function commerce.review_refund_request(
    p_refund_request_id bigint,
    p_decision text,
    p_actor_id text,
    p_reason text,
    p_expected_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_request commerce.refund_requests%rowtype;
begin
    if p_decision not in ('approved', 'rejected', 'cancelled') then
        raise exception 'validation: unsupported refund decision';
    end if;
    select * into v_request from commerce.refund_requests
    where id = p_refund_request_id for update;
    if not found then raise exception 'not_found: refund request'; end if;
    if v_request.version is distinct from p_expected_version then raise exception 'conflict: stale refund request version'; end if;
    if v_request.status <> 'requested' then raise exception 'conflict: refund request is no longer reviewable'; end if;
    if p_actor_id is null or length(btrim(p_actor_id)) = 0 then
        raise exception 'forbidden: admin actor is required';
    end if;
    if p_decision = 'approved' and v_request.dual_approval_required
        and v_request.first_approved_by is null then
        update commerce.refund_requests set
            first_approved_by = p_actor_id,
            first_approved_at = now(),
            decision_reason = p_reason
        where id = v_request.id returning * into v_request;
    else
        if p_decision = 'approved' and v_request.dual_approval_required
            and v_request.first_approved_by = p_actor_id then
            raise exception 'forbidden: dual approval requires a second admin actor';
        end if;
        update commerce.refund_requests set
            status = p_decision,
            approved_by = case when p_decision = 'approved' then p_actor_id else approved_by end,
            second_approved_by = case
                when p_decision = 'approved' and dual_approval_required then p_actor_id
                else second_approved_by end,
            second_approved_at = case
                when p_decision = 'approved' and dual_approval_required then now()
                else second_approved_at end,
            rejected_by = case when p_decision = 'rejected' then p_actor_id else rejected_by end,
            decision_reason = p_reason
        where id = v_request.id returning * into v_request;
    end if;
    if p_decision in ('rejected', 'cancelled') and not exists (
        select 1 from commerce.refund_requests
        where order_id = v_request.order_id and id <> v_request.id
          and status not in ('rejected', 'cancelled', 'failed')
    ) then
        update commerce.order_settlements set status = 'blocked', manual_review_reason = 'refund_request_' || p_decision
        where order_id = v_request.order_id and status = 'refund_pending';
    end if;
    perform commerce.append_financial_event(
        v_request.order_id, 'refund_request', v_request.id::text,
        case when p_decision = 'approved' and v_request.status = 'requested'
            then 'refund_first_approved' else 'refund_' || p_decision end,
        'admin', p_actor_id, p_reason, '{}'::jsonb,
        'commerce.refund.reviewed', 'refund:' || v_request.id || ':' || p_decision || ':' || p_expected_version
    );
    return to_jsonb(v_request) || jsonb_build_object(
        'refundAuthorization', commerce.refund_authorization_payload(v_request.id)
    );
end;
$$;

create or replace function commerce.authorize_order_release(
    p_order_id bigint,
    p_actor_kind text,
    p_actor_id text,
    p_reason text,
    p_expected_settlement_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_seller commerce.sellers%rowtype;
    v_risk commerce.seller_risk_policies%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_authorization commerce.settlement_release_authorizations%rowtype;
    v_seller_required_minimum_balance bigint;
begin
    if p_actor_kind is null or p_actor_kind not in ('admin', 'system') then
        raise exception 'forbidden: release actor is not allowed';
    end if;
    select * into v_order from commerce.orders where id = p_order_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = v_order.id for update;
    if v_settlement.version is distinct from p_expected_settlement_version then
        raise exception 'conflict: stale settlement version';
    end if;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    perform commerce.assert_order_seller_risk(v_order.id, 'settlement release');
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    select * into v_risk from commerce.seller_risk_policies where id = v_terms.seller_risk_policy_id;
    select coalesce(state.outstanding_debt_amount + state.at_risk_exposure_amount, 0)
    into v_seller_required_minimum_balance
    from commerce.seller_risk_states state
    where state.seller_id = v_order.seller_id;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id and status = 'succeeded' order by created_at desc limit 1;
    if v_payment.id is null then raise exception 'conflict: release requires confirmed payment'; end if;
    if not exists (
        select 1 from commerce.delivery_reconciliation_health health
        where health.id = 'mondial-relay'
          and health.checked_at >= now() - interval '30 minutes'
    ) then
        raise exception 'conflict: fresh Delivery reconciliation heartbeat is required for release';
    end if;
    if not exists (
        select 1 from commerce.delivery_order_reconciliation_health health
        where health.order_id = v_order.id
          and health.checked_at >= now() - interval '30 minutes'
          and health.shipment_id <> ''
          and health.provider_reference = v_fulfillment.provider_reference
          and health.shipment_status = 'collected_by_recipient'
          and health.pending_projection_count = 0
          and health.manual_review_count = 0
          and health.tracking_error_count = 0
          and health.tracking_checked_at is not null
    ) then
        raise exception 'conflict: fresh healthy Delivery reconciliation for this order is required for release';
    end if;
    if v_fulfillment.status <> 'collected_by_recipient' or v_fulfillment.recipient_handoff_at is null
        or v_fulfillment.release_eligible_at is null or now() < v_fulfillment.release_eligible_at then
        raise exception 'conflict: recipient handoff claim window has not expired';
    end if;
    if exists (select 1 from commerce.marketplace_claims where order_id = v_order.id
        and status not in ('resolved_buyer', 'resolved_seller', 'resolved_split')) then
        raise exception 'conflict: open marketplace claim blocks release';
    end if;
    if exists (select 1 from commerce.refund_requests where order_id = v_order.id
        and status not in ('rejected', 'cancelled', 'failed', 'succeeded')) then
        raise exception 'conflict: refund request blocks release';
    end if;
    if exists (select 1 from commerce.stripe_dispute_projections where order_id = v_order.id
        and status not in ('won', 'prevented', 'warning_closed')) then
        raise exception 'conflict: Stripe dispute blocks release';
    end if;
    if v_fulfillment.blocking_reason is not null or v_settlement.status in (
        'release_pending', 'reserve_held', 'released', 'refund_pending',
        'refunded', 'reversal_pending', 'reversed', 'manual_review'
    ) then
        raise exception 'conflict: settlement is blocked';
    end if;
    insert into commerce.settlement_release_authorizations (
        order_id, business_key, release_kind, authorized_amount, currency, financial_terms_hash,
        authorized_by_kind, authorized_by, reason
    ) values (
        v_order.id, 'settlement:' || v_order.id || ':initial:' || v_terms.financial_terms_hash,
        'initial', v_settlement.authorized_seller_amount
            - v_settlement.seller_reserve_liability_remaining_amount,
        v_terms.currency, v_terms.financial_terms_hash,
        p_actor_kind, p_actor_id, p_reason
    ) on conflict (business_key) do update set order_id = excluded.order_id
    returning * into v_authorization;
    update commerce.order_settlements set status = 'release_pending', manual_review_reason = null
    where order_id = v_order.id;
    perform commerce.append_financial_event(
        v_order.id, 'release_authorization', v_authorization.id::text, 'settlement_release_authorized',
        p_actor_kind, p_actor_id, p_reason,
        jsonb_build_object('authorizedAmount', v_authorization.authorized_amount),
        'commerce.settlement.release_authorized', 'release:' || v_authorization.id || ':authorized'
    );
    return jsonb_build_object(
        'status', 'authorized',
        'releaseAuthorizationId', v_authorization.id,
        'orderId', v_order.id,
        'orderPublicId', v_order.public_id,
        'paymentId', v_payment.provider_payment_id,
        'businessKey', v_authorization.business_key,
        'sellerId', v_seller.cms_user_id,
        'sellerRequiredMinimumBalanceAmount', v_seller_required_minimum_balance,
        'payoutDelayDays', v_risk.payout_delay_days,
        'amount', v_authorization.authorized_amount,
        'authorizedSellerTransferAmount', v_authorization.authorized_amount,
        'releaseKind', v_authorization.release_kind,
        'currency', upper(v_authorization.currency),
        'financialTermsHash', v_authorization.financial_terms_hash
    );
end;
$$;

create or replace function commerce.authorize_order_reserve_release(
    p_order_id bigint,
    p_actor_id text,
    p_reason text,
    p_expected_settlement_version integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_seller commerce.sellers%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_risk commerce.seller_risk_policies%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_authorization commerce.settlement_release_authorizations%rowtype;
    v_seller_required_minimum_balance bigint;
begin
    select * into v_order from commerce.orders where id = p_order_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = p_order_id for update;
    if v_settlement.version is distinct from p_expected_settlement_version then
        raise exception 'conflict: stale settlement version';
    end if;
    select * into v_terms from commerce.order_financial_terms where order_id = p_order_id;
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    select * into v_risk from commerce.seller_risk_policies where id = v_terms.seller_risk_policy_id;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = p_order_id;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = p_order_id and status = 'succeeded' order by created_at desc limit 1;
    perform commerce.assert_order_seller_risk(p_order_id, 'seller reserve release');
    select coalesce(state.outstanding_debt_amount + state.at_risk_exposure_amount, 0)
    into v_seller_required_minimum_balance
    from commerce.seller_risk_states state
    where state.seller_id = v_order.seller_id;
    if v_settlement.seller_reserve_liability_remaining_amount <= 0 then
        raise exception 'conflict: seller reserve has no releasable balance';
    end if;
    if v_settlement.total_transferred_amount - v_settlement.total_reversed_amount
        < v_settlement.authorized_seller_amount
            - v_settlement.seller_reserve_liability_remaining_amount then
        raise exception 'conflict: initial seller release is not confirmed';
    end if;
    if v_fulfillment.release_eligible_at is null
        or now() < v_fulfillment.release_eligible_at + make_interval(days => v_risk.reserve_liability_days) then
        raise exception 'conflict: seller reserve holding period has not expired';
    end if;
    if exists (select 1 from commerce.marketplace_claims where order_id = p_order_id
        and status not in ('resolved_buyer', 'resolved_seller', 'resolved_split'))
        or exists (select 1 from commerce.refund_requests where order_id = p_order_id
            and status not in ('rejected', 'cancelled', 'failed', 'succeeded'))
        or exists (select 1 from commerce.stripe_dispute_projections where order_id = p_order_id
            and status not in ('won', 'prevented', 'warning_closed')) then
        raise exception 'conflict: an open financial incident blocks seller reserve release';
    end if;
    insert into commerce.settlement_release_authorizations (
        order_id, business_key, release_kind, authorized_amount, currency,
        financial_terms_hash, authorized_by_kind, authorized_by, reason
    ) values (
        p_order_id, 'settlement:' || p_order_id || ':reserve:' || v_terms.financial_terms_hash,
        'reserve', v_settlement.seller_reserve_liability_remaining_amount,
        v_terms.currency, v_terms.financial_terms_hash, 'system', p_actor_id, p_reason
    ) on conflict (business_key) do update set order_id = excluded.order_id
    returning * into v_authorization;
    update commerce.order_settlements set status = 'release_pending', manual_review_reason = null
    where order_id = p_order_id;
    perform commerce.append_financial_event(
        p_order_id, 'release_authorization', v_authorization.id::text,
        'seller_reserve_release_authorized', 'system', p_actor_id, p_reason,
        jsonb_build_object('authorizedAmount', v_authorization.authorized_amount),
        'commerce.settlement.reserve_release_authorized',
        'release:' || v_authorization.id || ':authorized'
    );
    return jsonb_build_object(
        'status', 'authorized', 'releaseAuthorizationId', v_authorization.id,
        'releaseKind', 'reserve', 'orderId', p_order_id,
        'orderPublicId', v_order.public_id, 'paymentId', v_payment.provider_payment_id,
        'businessKey', v_authorization.business_key,
        'sellerId', v_seller.cms_user_id,
        'sellerRequiredMinimumBalanceAmount', v_seller_required_minimum_balance,
        'payoutDelayDays', v_risk.payout_delay_days,
        'amount', v_authorization.authorized_amount,
        'authorizedSellerTransferAmount', v_authorization.authorized_amount,
        'currency', upper(v_authorization.currency),
        'financialTermsHash', v_authorization.financial_terms_hash
    );
end;
$$;

create or replace function commerce.restore_order_inventory(p_order_id bigint)
returns void
language plpgsql
set search_path = ''
as $$
begin
    perform offer.id
    from commerce.offers offer
    join commerce.order_lines line on line.offer_id = offer.id
    where line.order_id = p_order_id
    order by offer.id
    for update of offer;
    update commerce.offers offer
    set quantity_available = offer.quantity_available + restored.quantity,
        availability = case
            when offer.availability = 'unavailable' and offer.quantity_available = 0
                and offer.inventory_revision = restored.inventory_revision_before
                then restored.availability_before
            else offer.availability
        end
    from (
        select offer_id, sum(inventory_reserved)::integer quantity,
            min(availability_before) availability_before,
            min(inventory_revision_before) inventory_revision_before
        from commerce.order_lines
        where order_id = p_order_id and inventory_reserved > 0
        group by offer_id
    ) restored
    where offer.id = restored.offer_id and offer.quantity_available is not null;
    update commerce.order_lines set
        inventory_reserved = 0,
        availability_before = null,
        inventory_revision_before = null
    where order_id = p_order_id and inventory_reserved > 0;
end;
$$;

create or replace function commerce.record_order_settlement_projection(
    p_order_public_id uuid,
    p_provider_event_id text,
    p_operation_type text,
    p_provider_operation_id bigint,
    p_status text,
    p_amount bigint,
    p_currency text,
    p_occurred_at timestamptz,
    p_release_authorization_id uuid default null,
    p_refund_request_id bigint default null,
    p_refund_business_key text default null,
    p_provider_snapshot jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_authorization commerce.settlement_release_authorizations%rowtype;
    v_refund commerce.refund_requests%rowtype;
    v_payment_cancellation commerce.payment_cancellation_requests%rowtype;
    v_event_id bigint;
    v_prior_event commerce.provider_projection_events%rowtype;
    v_prior_status text;
    v_gross_remainder bigint;
    v_required_recovery bigint;
begin
    if p_operation_type not in ('transfer', 'reversal', 'refund') then
        raise exception 'validation: unsupported settlement operation type';
    end if;
    if p_status not in ('reserved', 'processing', 'pending', 'succeeded', 'failed', 'cancelled', 'manual_review') then
        raise exception 'validation: unsupported settlement provider status';
    end if;
    if p_provider_operation_id is null or p_provider_operation_id <= 0 then
        raise exception 'validation: provider operation id is required';
    end if;
    select * into v_order from commerce.orders where public_id = p_order_public_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_settlement from commerce.order_settlements
    where order_id = v_order.id for update;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    if lower(p_currency) <> v_terms.currency or p_amount <= 0 then
        raise exception 'conflict: provider settlement amount or currency is invalid';
    end if;
    v_event_id := commerce.claim_provider_projection_event(
        'stripe', p_provider_event_id, v_order.id,
        p_operation_type || '.' || p_status, p_occurred_at,
        jsonb_strip_nulls(jsonb_build_object(
            'providerOperationId', p_provider_operation_id,
            'amount', p_amount, 'currency', lower(p_currency),
            'releaseAuthorizationId', p_release_authorization_id,
            'commerceRefundRequestId', p_refund_request_id,
            'refundRequestId', p_refund_business_key,
            'snapshot', coalesce(p_provider_snapshot, '{}'::jsonb)
        ))
    );
    if v_event_id is null then
        return to_jsonb(v_settlement) || jsonb_build_object('idempotentReplay', true);
    end if;
    select * into v_prior_event from commerce.provider_projection_events event
    where event.authority = 'stripe' and event.id <> v_event_id
      and event.event_type like p_operation_type || '.%'
      and (event.payload->>'providerOperationId')::bigint = p_provider_operation_id
    order by event.occurred_at desc, event.id desc limit 1;
    if found then
        v_prior_status := split_part(v_prior_event.event_type, '.', 2);
        if v_prior_event.order_id <> v_order.id
            or (v_prior_event.payload->>'amount')::bigint <> p_amount
            or v_prior_event.payload->>'currency' <> lower(p_currency)
            or v_prior_event.payload->>'releaseAuthorizationId' is distinct from p_release_authorization_id::text
            or v_prior_event.payload->>'commerceRefundRequestId' is distinct from p_refund_request_id::text
            or v_prior_event.payload->>'refundRequestId' is distinct from p_refund_business_key then
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = p_operation_type || '_attach_once_mismatch'
            where order_id = v_order.id returning * into v_settlement;
            insert into commerce.financial_exceptions (order_id, kind, severity, reason, details)
            values (
                v_order.id, 'settlement_ambiguity', 'critical',
                'Provider operation changed attach-once settlement facts',
                jsonb_build_object('providerOperationId', p_provider_operation_id,
                    'operationType', p_operation_type)
            );
            perform commerce.append_financial_event(
                v_order.id, p_operation_type, p_provider_operation_id::text,
                p_operation_type || '_attach_once_mismatch', 'provider', 'stripe', null,
                jsonb_build_object('providerEventId', p_provider_event_id),
                'commerce.order.settlement_mismatch', 'stripe:' || p_provider_event_id || ':mismatch'
            );
            return to_jsonb(v_settlement) || jsonb_build_object(
                'orderPublicId', v_order.public_id, 'accepted', false,
                'idempotentReplay', false, 'reason', 'provider_operation_attach_once_mismatch'
            );
        end if;
        if v_prior_status = 'succeeded' then
            return to_jsonb(v_settlement) || jsonb_build_object(
                'orderPublicId', v_order.public_id,
                'idempotentReplay', false, 'idempotentOperationReplay', p_status = 'succeeded',
                'ignoredStaleEvent', p_status <> 'succeeded'
            );
        end if;
        if v_prior_status in ('failed', 'cancelled') and p_status <> v_prior_status then
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = p_operation_type || '_terminal_regression'
            where order_id = v_order.id returning * into v_settlement;
            insert into commerce.financial_exceptions (order_id, kind, severity, reason, details)
            values (
                v_order.id, 'settlement_ambiguity', 'critical',
                'Provider operation regressed from a terminal failure',
                jsonb_build_object('providerOperationId', p_provider_operation_id,
                    'previousStatus', v_prior_status, 'nextStatus', p_status)
            );
            perform commerce.append_financial_event(
                v_order.id, p_operation_type, p_provider_operation_id::text,
                p_operation_type || '_terminal_regression', 'provider', 'stripe', null,
                jsonb_build_object('providerEventId', p_provider_event_id),
                'commerce.order.settlement_regression', 'stripe:' || p_provider_event_id || ':regression'
            );
            return to_jsonb(v_settlement) || jsonb_build_object(
                'orderPublicId', v_order.public_id, 'accepted', false,
                'idempotentReplay', false, 'reason', 'provider_operation_terminal_regression'
            );
        end if;
    end if;

    if p_operation_type = 'transfer' then
        select * into v_authorization from commerce.settlement_release_authorizations
        where id = p_release_authorization_id and order_id = v_order.id for update;
        if not found then raise exception 'conflict: release authorization is missing'; end if;
        if p_amount <> v_authorization.authorized_amount then
            raise exception 'conflict: transfer exceeds Commerce release authorization';
        end if;
        if not exists (
            select 1 from commerce.order_payment_attempts
            where order_id = v_order.id and status = 'succeeded' and provider_charge_id is not null
        ) then raise exception 'conflict: transfer requires a confirmed source charge'; end if;
        update commerce.settlement_release_authorizations set
            status = case p_status
                when 'succeeded' then 'confirmed'
                when 'failed' then 'failed'
                when 'manual_review' then 'manual_review'
                else 'provider_pending' end
        where id = v_authorization.id;
        if p_status = 'succeeded' then
            if v_settlement.total_transferred_amount + p_amount - v_settlement.total_reversed_amount
                > v_settlement.authorized_seller_amount then
                raise exception 'conflict: cumulative transfers exceed authorized seller amount';
            end if;
            update commerce.order_settlements set
                total_transferred_amount = total_transferred_amount + p_amount,
                seller_reserve_liability_remaining_amount = case
                    when v_authorization.release_kind = 'reserve'
                        then greatest(0, seller_reserve_liability_remaining_amount - p_amount)
                    else seller_reserve_liability_remaining_amount end,
                provider_transfer_id = p_provider_operation_id,
                status = case
                    when total_transferred_amount + p_amount - total_reversed_amount
                        = authorized_seller_amount
                        and (v_authorization.release_kind = 'reserve'
                            or seller_reserve_liability_remaining_amount = 0)
                        then 'released'
                    when v_authorization.release_kind in ('initial', 'recovery')
                        and seller_reserve_liability_remaining_amount > 0 then 'reserve_held'
                    else 'held' end,
                manual_review_reason = null
            where order_id = v_order.id returning * into v_settlement;
            if v_authorization.release_kind = 'reserve' then
                perform commerce.record_seller_financial_exposure(
                    v_order.id, 'reserve:' || v_order.id, 'reserve', 'recovered',
                    v_terms.seller_reserve_liability_amount,
                    v_terms.seller_reserve_liability_amount,
                    'Seller reserve released after the holding period',
                    jsonb_build_object('providerOperationId', p_provider_operation_id)
                );
            end if;
            update commerce.orders set status = 'completed'
            where id = v_order.id and status = 'active'
              and v_settlement.status in ('reserve_held', 'released');
        elsif p_status in ('failed', 'cancelled', 'manual_review') then
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = 'transfer_' || p_status
            where order_id = v_order.id returning * into v_settlement;
        end if;
    elsif p_operation_type = 'reversal' then
        if p_amount + v_settlement.total_reversed_amount > v_settlement.total_transferred_amount then
            raise exception 'conflict: cumulative reversals exceed transferred amount';
        end if;
        if p_status = 'succeeded' then
            update commerce.order_settlements set
                total_reversed_amount = total_reversed_amount + p_amount,
                status = case when total_reversed_amount + p_amount = total_transferred_amount
                    then 'reversed' else 'reversal_pending' end
            where order_id = v_order.id returning * into v_settlement;
        elsif p_status in ('reserved', 'processing', 'pending') then
            update commerce.order_settlements set status = 'reversal_pending'
            where order_id = v_order.id returning * into v_settlement;
        else
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = 'reversal_' || p_status
            where order_id = v_order.id returning * into v_settlement;
            perform commerce.record_seller_financial_exposure(
                v_order.id, 'reversal:' || p_provider_operation_id,
                'reversal_failure', 'debt', p_amount, 0,
                'Provider could not recover a transferred seller balance',
                jsonb_build_object('providerOperationId', p_provider_operation_id,
                    'providerStatus', p_status)
            );
        end if;
    else
        select * into v_refund from commerce.refund_requests
        where id = p_refund_request_id
          and business_key = p_refund_business_key
          and order_id = v_order.id for update;
        if not found then raise exception 'conflict: refund request is missing'; end if;
        if p_amount <> v_refund.requested_amount then
            raise exception 'conflict: provider refund amount differs from Commerce request';
        end if;
        if v_refund.status not in ('approved', 'provider_operation_reserved', 'processing', 'manual_review')
            and p_status <> 'failed' then
            raise exception 'conflict: refund request is not provider-authorized';
        end if;
        update commerce.refund_requests set
            status = case p_status
                when 'reserved' then 'provider_operation_reserved'
                when 'processing' then 'processing'
                when 'pending' then 'processing'
                when 'succeeded' then 'succeeded'
                when 'failed' then 'failed'
                when 'cancelled' then 'failed'
                else 'manual_review' end,
            provider_refund_id = p_provider_operation_id,
            provider_operation_key = coalesce(provider_operation_key, business_key),
            provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb)
        where id = v_refund.id returning * into v_refund;
        if p_status = 'succeeded' then
            select least(
                v_settlement.total_transferred_amount,
                coalesce(sum(request.seller_recovery_amount - request.seller_reserve_offset_amount), 0)
            ) into v_required_recovery
            from commerce.refund_requests request
            where request.order_id = v_order.id and request.status = 'succeeded';
            if v_settlement.total_reversed_amount < v_required_recovery then
                raise exception 'conflict: refund requires confirmed seller recovery reversal';
            end if;
            if v_settlement.total_refunded_amount + p_amount > v_terms.buyer_total_amount then
                raise exception 'conflict: cumulative refunds exceed captured buyer total';
            end if;
            update commerce.order_settlements set
                total_refunded_amount = total_refunded_amount + p_amount,
                authorized_seller_amount = greatest(
                    total_transferred_amount - total_reversed_amount,
                    authorized_seller_amount - v_refund.seller_recovery_amount
                ),
                seller_reserve_liability_remaining_amount = greatest(
                    0, seller_reserve_liability_remaining_amount - v_refund.seller_reserve_offset_amount
                ),
                status = case
                    when total_refunded_amount + p_amount = v_terms.buyer_total_amount then 'refunded'
                    else 'held' end,
                manual_review_reason = null
            where order_id = v_order.id returning * into v_settlement;
            if v_refund.seller_reserve_offset_amount > 0 then
                update commerce.seller_financial_exposures set
                    recovered_amount = least(amount, recovered_amount + v_refund.seller_reserve_offset_amount),
                    status = case when recovered_amount + v_refund.seller_reserve_offset_amount >= amount
                        then 'recovered' else status end,
                    reason = 'Seller reserve offset against an authorized buyer refund',
                    updated_at = now()
                where exposure_key = 'reserve:' || v_order.id;
                perform commerce.refresh_seller_risk_state(v_order.seller_id);
            end if;
            update commerce.marketplace_claims set
                status = case resolution_outcome when 'buyer' then 'resolved_buyer' else 'resolved_split' end,
                resolved_at = now()
            where id = v_refund.claim_id and status = 'resolution_pending';
            if v_refund.claim_id is not null then
                update commerce.orders set status = 'completed'
                where id = v_order.id and status = 'active'
                  and exists (
                      select 1
                      from commerce.marketplace_claims claim
                      where claim.id = v_refund.claim_id
                        and claim.status in ('resolved_buyer', 'resolved_split')
                  );
            else
                select * into v_payment_cancellation
                from commerce.payment_cancellation_requests
                where order_id = v_order.id and status = 'refund_pending'
                order by created_at desc, id desc limit 1 for update;
                if found then
                    update commerce.payment_cancellation_requests set status = 'completed'
                    where id = v_payment_cancellation.id;
                    update commerce.order_cancellation_requests set status = 'completed'
                    where order_id = v_order.id and status = 'refund_pending';
                    perform commerce.restore_order_inventory(v_order.id);
                    update commerce.orders set status = v_payment_cancellation.target_order_status
                    where id = v_order.id and status = 'cancellation_pending';
                    update commerce.financial_exceptions set
                        status = 'resolved', resolved_at = now(), resolved_by = 'protected-refund'
                    where deduplication_key = v_refund.business_key and status <> 'resolved';
                elsif exists (
                    select 1 from commerce.order_cancellation_requests
                    where order_id = v_order.id and status = 'refund_pending'
                ) then
                    update commerce.order_cancellation_requests set status = 'completed'
                    where order_id = v_order.id and status = 'refund_pending';
                    perform commerce.restore_order_inventory(v_order.id);
                    update commerce.orders set status = 'cancelled' where id = v_order.id;
                end if;
            end if;
        elsif p_status in ('failed', 'cancelled', 'manual_review') then
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = 'refund_' || p_status
            where order_id = v_order.id returning * into v_settlement;
        end if;
    end if;
    v_gross_remainder := v_terms.buyer_total_amount - v_settlement.total_refunded_amount
        - (v_settlement.total_transferred_amount - v_settlement.total_reversed_amount)
        - v_settlement.seller_reserve_liability_remaining_amount;
    if v_gross_remainder < 0 then
        raise exception 'conflict: settlement projection violates gross conservation';
    end if;
    update commerce.order_settlements set platform_gross_remainder_amount = v_gross_remainder
    where order_id = v_order.id returning * into v_settlement;
    if p_status in ('failed', 'cancelled', 'manual_review') then
        insert into commerce.financial_exceptions (
            order_id, kind, severity, reason, details
        ) values (
            v_order.id,
            case p_operation_type when 'refund' then 'refund_failure' else 'settlement_ambiguity' end,
            'critical', p_operation_type || ' provider operation is ' || p_status,
            jsonb_build_object('providerOperationId', p_provider_operation_id, 'amount', p_amount)
        );
    end if;
    perform commerce.append_financial_event(
        v_order.id, p_operation_type, p_provider_operation_id::text,
        p_operation_type || '_' || p_status, 'provider', 'stripe', null,
        jsonb_build_object('providerEventId', p_provider_event_id, 'amount', p_amount),
        'commerce.order.settlement_projection', 'stripe:' || p_provider_event_id
    );
    return to_jsonb(v_settlement) || jsonb_build_object(
        'orderPublicId', v_order.public_id,
        'refundRequest', case when v_refund.id is null then null else to_jsonb(v_refund) end,
        'idempotentReplay', false
    );
end;
$$;

create or replace function commerce.record_order_stripe_dispute_projection(
    p_order_public_id uuid,
    p_provider_event_id text,
    p_provider_dispute_id text,
    p_status text,
    p_reason text,
    p_amount bigint,
    p_currency text,
    p_opened_at timestamptz,
    p_occurred_at timestamptz,
    p_evidence_due_by timestamptz default null,
    p_provider_snapshot jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_settlement commerce.order_settlements%rowtype;
    v_dispute commerce.stripe_dispute_projections%rowtype;
    v_recovery_authorization commerce.settlement_release_authorizations%rowtype;
    v_event_id bigint;
    v_open boolean;
    v_funds_withdrawn boolean;
    v_recovery_amount bigint;
    v_recovery_revision integer;
begin
    select * into v_order from commerce.orders where public_id = p_order_public_id;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_settlement from commerce.order_settlements where order_id = v_order.id for update;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    if p_amount <= 0 or p_amount > v_terms.buyer_total_amount or lower(p_currency) <> v_terms.currency then
        raise exception 'conflict: Stripe dispute does not match Commerce payment terms';
    end if;
    v_funds_withdrawn := coalesce((p_provider_snapshot->>'fundsWithdrawn')::boolean, false);
    v_event_id := commerce.claim_provider_projection_event(
        'stripe', p_provider_event_id, v_order.id,
        'stripe_dispute.' || p_status, p_occurred_at,
        jsonb_strip_nulls(jsonb_build_object(
            'providerDisputeId', p_provider_dispute_id,
            'reason', p_reason, 'amount', p_amount, 'currency', lower(p_currency),
            'openedAt', p_opened_at, 'evidenceDueBy', p_evidence_due_by,
            'fundsWithdrawn', v_funds_withdrawn,
            'snapshot', coalesce(p_provider_snapshot, '{}'::jsonb)
        ))
    );
    if v_event_id is null then
        select * into v_dispute from commerce.stripe_dispute_projections
        where provider_dispute_id = p_provider_dispute_id;
        return to_jsonb(v_dispute) || jsonb_build_object('idempotentReplay', true);
    end if;
    select * into v_dispute from commerce.stripe_dispute_projections
    where provider_dispute_id = p_provider_dispute_id for update;
    if found and (
        v_dispute.order_id <> v_order.id or v_dispute.amount <> p_amount
        or v_dispute.currency <> lower(p_currency)
        or (v_dispute.status in ('won', 'lost', 'prevented', 'warning_closed')
            and v_dispute.status <> p_status)
    ) then
        update commerce.order_settlements set
            status = 'manual_review', manual_review_reason = 'stripe_dispute_projection_regression'
        where order_id = v_order.id;
        insert into commerce.financial_exceptions (
            order_id, kind, severity, reason, details
        ) values (
            v_order.id, 'provider_dispute', 'critical',
            'Stripe dispute projection changed attach-once or terminal facts',
            jsonb_build_object('providerDisputeId', p_provider_dispute_id,
                'previousStatus', v_dispute.status, 'nextStatus', p_status)
        );
        perform commerce.append_financial_event(
            v_order.id, 'stripe_dispute', p_provider_dispute_id, 'stripe_dispute_regression',
            'provider', 'stripe', p_reason, jsonb_build_object('providerEventId', p_provider_event_id),
            'commerce.stripe_dispute.regression', 'stripe:' || p_provider_event_id || ':regression'
        );
        return to_jsonb(v_dispute) || jsonb_build_object(
            'accepted', false, 'idempotentReplay', false,
            'reason', 'provider_dispute_changed_terminal_or_attach_once_facts'
        );
    end if;
    insert into commerce.stripe_dispute_projections (
        order_id, provider_dispute_id, status, reason, amount, currency,
        evidence_due_by, funds_withdrawn, provider_snapshot, opened_at, closed_at
    ) values (
        v_order.id, p_provider_dispute_id, p_status, p_reason, p_amount,
        lower(p_currency), p_evidence_due_by, v_funds_withdrawn,
        coalesce(p_provider_snapshot, '{}'::jsonb), p_opened_at,
        case when p_status in ('won', 'lost', 'prevented', 'warning_closed')
            and not v_funds_withdrawn then p_occurred_at end
    ) on conflict (provider_dispute_id) do update set
        status = excluded.status, reason = excluded.reason, amount = excluded.amount,
        evidence_due_by = excluded.evidence_due_by,
        funds_withdrawn = excluded.funds_withdrawn,
        provider_snapshot = excluded.provider_snapshot,
        closed_at = excluded.closed_at, updated_at = now()
    returning * into v_dispute;
    v_open := p_status not in ('won', 'prevented', 'warning_closed') or v_funds_withdrawn;
    if v_open then
        update commerce.order_settlements set
            status = case
                when status = 'manual_review' then status
                when total_transferred_amount > total_reversed_amount then 'reversal_pending'
                else 'blocked'
            end,
            manual_review_reason = case
                when status = 'manual_review' then manual_review_reason
                else 'stripe_dispute_' || p_status
            end
        where order_id = v_order.id;
        insert into commerce.financial_exceptions (
            order_id, kind, severity, reason, details
        ) values (
            v_order.id, 'provider_dispute', 'critical',
            'Stripe dispute requires independent provider handling',
            jsonb_build_object('providerDisputeId', p_provider_dispute_id, 'status', p_status)
        );
        if v_settlement.total_transferred_amount > v_settlement.total_reversed_amount then
            perform commerce.record_seller_financial_exposure(
                v_order.id, 'chargeback:' || p_provider_dispute_id, 'chargeback',
                case when p_status = 'lost' then 'debt' else 'at_risk' end,
                least(p_amount, v_settlement.total_transferred_amount - v_settlement.total_reversed_amount),
                0, case when p_status = 'lost'
                    then 'Stripe chargeback was lost before seller funds were fully recovered'
                    else 'Open Stripe dispute exposes transferred seller funds' end,
                jsonb_build_object('providerDisputeId', p_provider_dispute_id, 'status', p_status)
            );
        end if;
    elsif p_status in ('won', 'prevented', 'warning_closed')
        and not exists (select 1 from commerce.marketplace_claims where order_id = v_order.id
            and status not in ('resolved_buyer', 'resolved_seller', 'resolved_split'))
        and not exists (select 1 from commerce.refund_requests where order_id = v_order.id
            and status not in ('rejected', 'cancelled', 'failed', 'succeeded')) then
        update commerce.order_settlements set
            status = case when total_transferred_amount > total_reversed_amount then 'released' else 'held' end,
            manual_review_reason = null
        where order_id = v_order.id
          and status <> 'manual_review'
          and (manual_review_reason is null or manual_review_reason like 'stripe_dispute_%');
    end if;
    if p_status in ('won', 'prevented', 'warning_closed') and not v_funds_withdrawn then
        update commerce.seller_financial_exposures set
            recovered_amount = amount, status = 'recovered',
            reason = 'Stripe dispute closed without seller debt', updated_at = now()
        where exposure_key = 'chargeback:' || p_provider_dispute_id
          and status in ('at_risk', 'debt');
        perform commerce.refresh_seller_risk_state(v_order.seller_id);
    end if;
    select * into v_settlement from commerce.order_settlements where order_id = v_order.id;
    if not v_open
        and v_settlement.status <> 'manual_review'
        and not exists (select 1 from commerce.marketplace_claims where order_id = v_order.id
            and status not in ('resolved_buyer', 'resolved_seller', 'resolved_split'))
        and not exists (select 1 from commerce.refund_requests where order_id = v_order.id
            and status not in ('rejected', 'cancelled', 'failed', 'succeeded'))
        and not exists (select 1 from commerce.stripe_dispute_projections
            where order_id = v_order.id
              and (status not in ('won', 'prevented', 'warning_closed') or funds_withdrawn)) then
        v_recovery_amount := greatest(
            0,
            v_settlement.authorized_seller_amount
                - v_settlement.seller_reserve_liability_remaining_amount
                - (v_settlement.total_transferred_amount - v_settlement.total_reversed_amount)
        );
        if v_recovery_amount > 0 then
            perform commerce.assert_order_seller_risk(v_order.id, 'dispute recovery release');
            select * into v_recovery_authorization
            from commerce.settlement_release_authorizations release_auth
            where release_auth.order_id = v_order.id
              and release_auth.release_kind = 'recovery'
              and release_auth.status in ('authorized', 'provider_pending')
            order by release_auth.recovery_revision desc limit 1;
            if not found then
                select coalesce(max(recovery_revision), 0) + 1 into v_recovery_revision
                from commerce.settlement_release_authorizations
                where order_id = v_order.id and release_kind = 'recovery';
                insert into commerce.settlement_release_authorizations (
                    order_id, business_key, release_kind, recovery_revision,
                    authorized_amount, currency, financial_terms_hash,
                    authorized_by_kind, authorized_by, reason
                ) values (
                    v_order.id,
                    'settlement:' || v_order.id || ':recovery:' || v_recovery_revision
                        || ':dispute:' || p_provider_dispute_id
                        || ':reversed:' || v_settlement.total_reversed_amount,
                    'recovery', v_recovery_revision, v_recovery_amount,
                    v_terms.currency, v_terms.financial_terms_hash,
                    'system', 'stripe-reconciliation',
                    'Stripe dispute closed safely after seller Transfer recovery'
                ) returning * into v_recovery_authorization;
                perform commerce.append_financial_event(
                    v_order.id, 'release_authorization', v_recovery_authorization.id::text,
                    'dispute_recovery_release_authorized', 'system', 'stripe-reconciliation', null,
                    jsonb_build_object('authorizedAmount', v_recovery_authorization.authorized_amount,
                        'providerDisputeId', p_provider_dispute_id,
                        'recoveryRevision', v_recovery_authorization.recovery_revision),
                    'commerce.settlement.recovery_release_authorized',
                    'release:' || v_recovery_authorization.id || ':authorized'
                );
            elsif v_recovery_authorization.authorized_amount <> v_recovery_amount then
                update commerce.order_settlements set
                    status = 'manual_review',
                    manual_review_reason = 'dispute_recovery_release_amount_mismatch'
                where order_id = v_order.id;
                raise exception 'conflict: active dispute recovery release amount changed';
            end if;
            update commerce.order_settlements set status = 'release_pending', manual_review_reason = null
            where order_id = v_order.id;
        end if;
    end if;
    perform commerce.append_financial_event(
        v_order.id, 'stripe_dispute', p_provider_dispute_id,
        'stripe_dispute_' || p_status, 'provider', 'stripe', p_reason,
        jsonb_build_object('providerEventId', p_provider_event_id, 'amount', p_amount),
        'commerce.stripe_dispute.projection', 'stripe:' || p_provider_event_id
    );
    return to_jsonb(v_dispute) || jsonb_build_object(
        'recoveryReleaseAuthorization', case when v_recovery_authorization.id is null then null
            else jsonb_build_object(
                'releaseAuthorizationId', v_recovery_authorization.id,
                'releaseKind', v_recovery_authorization.release_kind,
                'recoveryRevision', v_recovery_authorization.recovery_revision,
                'amount', v_recovery_authorization.authorized_amount,
                'businessKey', v_recovery_authorization.business_key
            ) end,
        'idempotentReplay', false
    );
end;
$$;

create or replace function commerce.reserve_order_shipment_creation(
    p_order_public_id uuid,
    p_seller_cms_user_id text,
    p_worker_id text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_seller commerce.sellers%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_operation commerce.shipment_creation_operations%rowtype;
    v_business_key text;
    v_idempotent_replay boolean := false;
begin
    if p_worker_id is null or length(btrim(p_worker_id)) = 0 then
        raise exception 'validation: shipment creation worker id is required';
    end if;
    select * into v_order from commerce.orders where public_id = p_order_public_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    if v_seller.cms_user_id is distinct from p_seller_cms_user_id then
        raise exception 'not_found: sale';
    end if;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id for update;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id and status = 'succeeded' order by created_at desc limit 1;
    if v_order.status <> 'active' or v_payment.id is null
        or v_fulfillment.status not in ('awaiting_shipment', 'shipment_creating', 'label_created')
        or exists (select 1 from commerce.refund_requests request
            where request.order_id = v_order.id and request.status not in ('rejected', 'cancelled', 'failed'))
        or exists (select 1 from commerce.order_cancellation_requests request
            where request.order_id = v_order.id and request.status not in ('rejected', 'completed'))
    then
        raise exception 'conflict: Commerce has not authorized shipment creation';
    end if;
    v_business_key := 'shipment-creation:' || v_order.id || ':' || v_terms.delivery_quote_id;
    insert into commerce.shipment_creation_operations (
        order_id, business_key, delivery_quote_id, financial_terms_hash, status,
        claim_token, claimed_at, claimed_by, attempts
    ) values (
        v_order.id, v_business_key, v_terms.delivery_quote_id, v_terms.financial_terms_hash,
        'processing', gen_random_uuid(), now(), p_worker_id, 1
    ) on conflict (order_id) do nothing;
    select * into v_operation from commerce.shipment_creation_operations
    where order_id = v_order.id for update;
    if v_operation.business_key <> v_business_key
        or v_operation.delivery_quote_id <> v_terms.delivery_quote_id
        or v_operation.financial_terms_hash <> v_terms.financial_terms_hash then
        raise exception 'conflict: shipment creation replay changed immutable terms';
    end if;
    if v_operation.status in ('failed', 'requested') then
        update commerce.shipment_creation_operations set
            status = 'processing', claim_token = gen_random_uuid(), claimed_at = now(),
            claimed_by = p_worker_id, attempts = attempts + 1, last_error = null,
            updated_at = now()
        where id = v_operation.id returning * into v_operation;
    elsif v_operation.status = 'processing'
        and v_operation.claimed_at < now() - interval '5 minutes' then
        update commerce.shipment_creation_operations set
            claim_token = gen_random_uuid(), claimed_at = now(), claimed_by = p_worker_id,
            attempts = attempts + 1, last_error = 'shipment creation lease expired before completion',
            updated_at = now()
        where id = v_operation.id returning * into v_operation;
    end if;
    v_idempotent_replay := v_operation.status = 'succeeded';
    if v_operation.status in ('unknown', 'manual_review', 'cancelled') then
        raise exception 'conflict: shipment creation requires manual reconciliation';
    end if;
    if v_fulfillment.status = 'awaiting_shipment' then
        update commerce.order_fulfillments set status = 'shipment_creating', version = version + 1,
            updated_at = now()
        where order_id = v_order.id and status = 'awaiting_shipment'
        returning * into v_fulfillment;
    end if;
    return jsonb_build_object(
        'operationId', v_operation.id,
        'claimToken', coalesce(v_operation.claim_token, gen_random_uuid()),
        'businessKey', v_operation.business_key,
        'status', v_operation.status,
        'orderId', v_order.id,
        'orderPublicId', v_order.public_id,
        'sellerId', v_seller.cms_user_id,
        'buyerCmsUserId', v_order.buyer_cms_user_id,
        'deliveryQuoteId', v_terms.delivery_quote_id,
        'merchandiseSubtotalMinorAmount', v_terms.merchandise_subtotal_amount,
        'currency', upper(v_terms.currency),
        'financialTermsHash', v_terms.financial_terms_hash,
        'fulfillmentStatus', coalesce(v_fulfillment.status, 'shipment_creating'),
        'idempotentReplay', v_idempotent_replay
    );
end;
$$;

create or replace function commerce.claim_pending_shipment_creations(
    p_worker_id text,
    p_limit integer default 5
)
returns setof jsonb
language plpgsql
set search_path = ''
as $$
begin
    if p_worker_id is null or length(btrim(p_worker_id)) = 0 then
        raise exception 'validation: worker id is required';
    end if;
    return query
    with candidates as (
        select operation.id
        from commerce.shipment_creation_operations operation
        join commerce.orders order_row on order_row.id = operation.order_id
        join commerce.order_fulfillments fulfillment on fulfillment.order_id = operation.order_id
        where operation.status in ('requested', 'failed', 'processing')
          and operation.available_at <= now()
          and operation.attempts < 12
          and order_row.status in ('active', 'cancellation_pending')
          and fulfillment.status in ('shipment_creating', 'awaiting_shipment')
          and (operation.status <> 'processing' or operation.claimed_at < now() - interval '5 minutes')
        order by operation.available_at, operation.created_at, operation.id
        for update of operation skip locked
        limit least(greatest(coalesce(p_limit, 5), 1), 12)
    ), claimed as (
        update commerce.shipment_creation_operations operation set
            status = 'processing', claim_token = gen_random_uuid(), claimed_at = now(),
            claimed_by = p_worker_id, attempts = operation.attempts + 1,
            last_error = null, updated_at = now()
        from candidates where operation.id = candidates.id returning operation.*
    )
    select jsonb_build_object(
        'operationId', operation.id, 'claimToken', operation.claim_token,
        'businessKey', operation.business_key, 'status', operation.status,
        'orderId', order_row.id, 'orderPublicId', order_row.public_id,
        'sellerId', seller.cms_user_id, 'buyerCmsUserId', order_row.buyer_cms_user_id,
        'deliveryQuoteId', terms.delivery_quote_id,
        'merchandiseSubtotalMinorAmount', terms.merchandise_subtotal_amount,
        'currency', upper(terms.currency), 'financialTermsHash', terms.financial_terms_hash,
        'fulfillmentStatus', fulfillment.status
    )
    from claimed operation
    join commerce.orders order_row on order_row.id = operation.order_id
    join commerce.sellers seller on seller.id = order_row.seller_id
    join commerce.order_financial_terms terms on terms.order_id = operation.order_id
    join commerce.order_fulfillments fulfillment on fulfillment.order_id = operation.order_id;
end;
$$;

create or replace function commerce.complete_order_shipment_creation(
    p_operation_id bigint,
    p_claim_token uuid,
    p_provider_reference text,
    p_provider_shipment_id text,
    p_provider_snapshot jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_operation commerce.shipment_creation_operations%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
begin
    select * into v_operation from commerce.shipment_creation_operations
    where id = p_operation_id for update;
    if not found then raise exception 'not_found: shipment creation operation'; end if;
    if v_operation.status = 'succeeded' then return to_jsonb(v_operation) || jsonb_build_object('idempotentReplay', true); end if;
    if v_operation.status <> 'processing' or v_operation.claim_token is distinct from p_claim_token then
        raise exception 'conflict: shipment creation lease mismatch';
    end if;
    if p_provider_reference is null or length(btrim(p_provider_reference)) = 0 then
        raise exception 'validation: provider reference is required';
    end if;
    select * into v_fulfillment from commerce.order_fulfillments
    where order_id = v_operation.order_id for update;
    if v_fulfillment.status not in ('shipment_creating', 'label_created') then
        raise exception 'conflict: fulfillment no longer accepts shipment creation completion';
    end if;
    update commerce.shipment_creation_operations set
        status = 'succeeded', provider_reference = p_provider_reference,
        provider_shipment_id = nullif(btrim(p_provider_shipment_id), ''),
        provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
        claim_token = null, claimed_at = null, claimed_by = null, last_error = null,
        updated_at = now()
    where id = v_operation.id returning * into v_operation;
    update commerce.order_fulfillments set
        status = 'label_created', provider_reference = p_provider_reference,
        version = version + 1, updated_at = now()
    where order_id = v_operation.order_id and status = 'shipment_creating'
    returning * into v_fulfillment;
    perform commerce.append_financial_event(
        v_operation.order_id, 'fulfillment', v_operation.order_id::text,
        'shipment_creation_succeeded', 'provider', 'mondial-relay', null,
        jsonb_build_object('operationId', v_operation.id, 'providerReference', p_provider_reference),
        'commerce.order.shipment_creation', v_operation.business_key || ':succeeded'
    );
    return to_jsonb(v_operation) || jsonb_build_object('fulfillment', to_jsonb(v_fulfillment), 'idempotentReplay', false);
end;
$$;

create or replace function commerce.recover_order_shipment_creation(
    p_order_public_id uuid,
    p_provider_reference text,
    p_provider_shipment_id text,
    p_provider_snapshot jsonb,
    p_actor_kind text,
    p_actor_id text,
    p_reason text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_operation commerce.shipment_creation_operations%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
begin
    if p_provider_reference is null or length(btrim(p_provider_reference)) = 0
        or p_provider_shipment_id is null or length(btrim(p_provider_shipment_id)) = 0
        or p_actor_kind is distinct from 'admin'
        or p_actor_id is null or length(btrim(p_actor_id)) = 0
        or p_reason is null or length(btrim(p_reason)) < 8 then
        raise exception 'validation: provider shipment and audited recovery reason are required';
    end if;
    select * into v_order from commerce.orders where public_id = p_order_public_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_operation from commerce.shipment_creation_operations
    where order_id = v_order.id for update;
    if not found then raise exception 'not_found: shipment creation operation'; end if;
    select * into v_fulfillment from commerce.order_fulfillments
    where order_id = v_order.id for update;
    if v_operation.status = 'succeeded' then
        if v_operation.provider_reference = btrim(p_provider_reference)
            and (v_operation.provider_shipment_id is null
                or v_operation.provider_shipment_id = btrim(p_provider_shipment_id)) then
            return to_jsonb(v_operation) || jsonb_build_object(
                'fulfillment', to_jsonb(v_fulfillment), 'idempotentReplay', true
            );
        end if;
        raise exception 'conflict: recovered shipment differs from the completed operation';
    end if;
    if v_operation.status not in ('processing', 'failed', 'unknown', 'manual_review') then
        raise exception 'conflict: shipment creation operation cannot be recovered';
    end if;
    if v_fulfillment.status not in ('awaiting_shipment', 'shipment_creating', 'label_created', 'manual_review')
        or (v_fulfillment.status = 'manual_review'
            and v_fulfillment.blocking_reason not in (
                'shipment_creation_unknown', 'shipment_creation_manual_review'
            )) then
        raise exception 'conflict: fulfillment cannot accept shipment creation recovery';
    end if;
    update commerce.shipment_creation_operations set
        status = 'succeeded',
        provider_reference = btrim(p_provider_reference),
        provider_shipment_id = btrim(p_provider_shipment_id),
        provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
        claim_token = null, claimed_at = null, claimed_by = null,
        last_error = null, updated_at = now()
    where id = v_operation.id returning * into v_operation;
    update commerce.order_fulfillments set
        status = 'label_created', provider_reference = btrim(p_provider_reference),
        blocking_reason = null, version = version + 1, updated_at = now()
    where order_id = v_order.id returning * into v_fulfillment;
    update commerce.order_settlements set
        status = 'held', manual_review_reason = null,
        version = version + 1, updated_at = now()
    where order_id = v_order.id and status = 'manual_review'
      and manual_review_reason in ('shipment_creation_unknown', 'shipment_creation_manual_review');
    update commerce.financial_exceptions set
        status = 'resolved', resolved_at = now(), resolved_by = p_actor_id
    where order_id = v_order.id and status <> 'resolved'
      and kind = 'fulfillment_ambiguity'
      and reason like 'Shipment creation%';
    perform commerce.append_financial_event(
        v_order.id, 'fulfillment', v_order.id::text,
        'shipment_creation_recovered', p_actor_kind, p_actor_id, p_reason,
        jsonb_build_object(
            'operationId', v_operation.id,
            'providerReference', v_operation.provider_reference,
            'providerShipmentId', v_operation.provider_shipment_id
        ),
        'commerce.order.shipment_creation_recovered',
        v_operation.business_key || ':recovered'
    );
    return to_jsonb(v_operation) || jsonb_build_object(
        'fulfillment', to_jsonb(v_fulfillment), 'idempotentReplay', false
    );
end;
$$;

create or replace function commerce.fail_order_shipment_creation(
    p_operation_id bigint,
    p_claim_token uuid,
    p_error text,
    p_unknown boolean default false
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_operation commerce.shipment_creation_operations%rowtype;
begin
    select * into v_operation from commerce.shipment_creation_operations where id = p_operation_id for update;
    if not found then raise exception 'not_found: shipment creation operation'; end if;
    if v_operation.status = 'succeeded' then return to_jsonb(v_operation); end if;
    if v_operation.status <> 'processing' or v_operation.claim_token is distinct from p_claim_token then
        raise exception 'conflict: shipment creation lease mismatch';
    end if;
    update commerce.shipment_creation_operations set
        status = case when p_unknown then 'unknown' when attempts >= 12 then 'manual_review' else 'failed' end,
        available_at = now() + interval '5 minutes', last_error = left(coalesce(nullif(btrim(p_error), ''), 'shipment creation failed'), 2000),
        claim_token = null, claimed_at = null, claimed_by = null, updated_at = now()
    where id = v_operation.id returning * into v_operation;
    if v_operation.status in ('unknown', 'manual_review') then
        update commerce.order_fulfillments set status = 'manual_review',
            blocking_reason = 'shipment_creation_' || v_operation.status,
            version = version + 1, updated_at = now()
        where order_id = v_operation.order_id;
        update commerce.order_settlements set status = 'manual_review',
            manual_review_reason = 'shipment_creation_' || v_operation.status,
            version = version + 1, updated_at = now()
        where order_id = v_operation.order_id and status not in ('refunded', 'reversed');
    end if;
    return to_jsonb(v_operation);
end;
$$;

create or replace function commerce.get_order_label_authorization(
    p_order_public_id uuid,
    p_seller_cms_user_id text
)
returns jsonb
language sql
stable
set search_path = ''
as $$
select jsonb_build_object(
    'allowed', order_row.status = 'active'
        and fulfillment.status in ('label_created', 'seller_handoff_declared')
        and creation.status = 'succeeded'
        and not exists (select 1 from commerce.order_cancellation_requests request
            where request.order_id = order_row.id and request.status not in ('rejected', 'completed'))
        and not exists (select 1 from commerce.refund_requests request
            where request.order_id = order_row.id and request.status not in ('rejected', 'cancelled', 'failed')),
    'orderId', order_row.id, 'orderPublicId', order_row.public_id,
    'sellerCmsUserId', seller.cms_user_id, 'fulfillmentStatus', fulfillment.status,
    'providerReference', fulfillment.provider_reference
)
from commerce.orders order_row
join commerce.sellers seller on seller.id = order_row.seller_id
join commerce.order_fulfillments fulfillment on fulfillment.order_id = order_row.id
join commerce.shipment_creation_operations creation on creation.order_id = order_row.id
where order_row.public_id = p_order_public_id and seller.cms_user_id = p_seller_cms_user_id;
$$;

create or replace function commerce.record_delivery_reconciliation_health(
    p_run_key text,
    p_checked_at timestamptz,
    p_pending_projection_count integer,
    p_manual_review_count integer,
    p_tracking_error_count integer
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_health commerce.delivery_reconciliation_health%rowtype;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0 or p_checked_at is null
        or p_checked_at > now() + interval '5 minutes'
        or p_pending_projection_count is null or p_pending_projection_count < 0
        or p_manual_review_count is null or p_manual_review_count < 0
        or p_tracking_error_count is null or p_tracking_error_count < 0 then
        raise exception 'validation: invalid delivery reconciliation health';
    end if;
    insert into commerce.delivery_reconciliation_health (
        id, run_key, checked_at, pending_projection_count, manual_review_count,
        tracking_error_count, updated_at
    ) values (
        'mondial-relay', p_run_key, p_checked_at, p_pending_projection_count,
        p_manual_review_count, p_tracking_error_count, now()
    ) on conflict (id) do update set
        run_key = case
            when excluded.checked_at >= commerce.delivery_reconciliation_health.checked_at
                then excluded.run_key
            else commerce.delivery_reconciliation_health.run_key end,
        checked_at = greatest(commerce.delivery_reconciliation_health.checked_at, excluded.checked_at),
        pending_projection_count = case
            when excluded.checked_at >= commerce.delivery_reconciliation_health.checked_at
                then excluded.pending_projection_count
            else commerce.delivery_reconciliation_health.pending_projection_count end,
        manual_review_count = case
            when excluded.checked_at >= commerce.delivery_reconciliation_health.checked_at
                then excluded.manual_review_count
            else commerce.delivery_reconciliation_health.manual_review_count end,
        tracking_error_count = case
            when excluded.checked_at >= commerce.delivery_reconciliation_health.checked_at
                then excluded.tracking_error_count
            else commerce.delivery_reconciliation_health.tracking_error_count end,
        updated_at = now()
    returning * into v_health;
    return to_jsonb(v_health);
end;
$$;

create or replace function commerce.record_delivery_order_reconciliation_health(
    p_run_key text,
    p_checked_at timestamptz,
    p_order_public_id uuid,
    p_shipment_id text,
    p_provider_reference text,
    p_shipment_status text,
    p_pending_projection_count integer,
    p_manual_review_count integer,
    p_tracking_error_count integer,
    p_tracking_checked_at timestamptz default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order_id bigint;
    v_health commerce.delivery_order_reconciliation_health%rowtype;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0
        or p_checked_at is null or p_checked_at > now() + interval '5 minutes'
        or p_shipment_id is null or length(btrim(p_shipment_id)) = 0
        or p_shipment_status is null or length(btrim(p_shipment_status)) = 0
        or p_pending_projection_count is null or p_pending_projection_count < 0
        or p_manual_review_count is null or p_manual_review_count < 0
        or p_tracking_error_count is null or p_tracking_error_count < 0 then
        raise exception 'validation: invalid order Delivery reconciliation health';
    end if;
    select id into v_order_id from commerce.orders where public_id = p_order_public_id;
    if v_order_id is null then
        return jsonb_build_object(
            'ignored', true, 'reason', 'order_not_found',
            'orderPublicId', p_order_public_id, 'checkedAt', p_checked_at
        );
    end if;
    insert into commerce.delivery_order_reconciliation_health (
        order_id, run_key, checked_at, shipment_id, provider_reference,
        shipment_status, pending_projection_count, manual_review_count,
        tracking_error_count, tracking_checked_at, updated_at
    ) values (
        v_order_id, btrim(p_run_key), p_checked_at, btrim(p_shipment_id),
        nullif(btrim(p_provider_reference), ''), btrim(p_shipment_status),
        p_pending_projection_count, p_manual_review_count,
        p_tracking_error_count, p_tracking_checked_at, now()
    ) on conflict (order_id) do update set
        run_key = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.run_key else commerce.delivery_order_reconciliation_health.run_key end,
        checked_at = greatest(commerce.delivery_order_reconciliation_health.checked_at, excluded.checked_at),
        shipment_id = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.shipment_id else commerce.delivery_order_reconciliation_health.shipment_id end,
        provider_reference = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.provider_reference else commerce.delivery_order_reconciliation_health.provider_reference end,
        shipment_status = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.shipment_status else commerce.delivery_order_reconciliation_health.shipment_status end,
        pending_projection_count = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.pending_projection_count else commerce.delivery_order_reconciliation_health.pending_projection_count end,
        manual_review_count = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.manual_review_count else commerce.delivery_order_reconciliation_health.manual_review_count end,
        tracking_error_count = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.tracking_error_count else commerce.delivery_order_reconciliation_health.tracking_error_count end,
        tracking_checked_at = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then excluded.tracking_checked_at else commerce.delivery_order_reconciliation_health.tracking_checked_at end,
        updated_at = case when excluded.checked_at >= commerce.delivery_order_reconciliation_health.checked_at
            then now() else commerce.delivery_order_reconciliation_health.updated_at end
    returning * into v_health;
    return to_jsonb(v_health);
end;
$$;

create or replace function commerce.claim_pending_shipment_cancellations(
    p_worker_id text,
    p_limit integer default 5
)
returns setof jsonb
language plpgsql
set search_path = ''
as $$
begin
    if p_worker_id is null or length(btrim(p_worker_id)) = 0 then
        raise exception 'validation: worker id is required';
    end if;
    return query
    with candidates as (
        select operation.id
        from commerce.shipment_cancellation_operations operation
        join commerce.shipment_creation_operations creation on creation.order_id = operation.order_id
        where operation.status in ('requested', 'failed', 'processing')
          and operation.available_at <= now() and operation.attempts < 12
          and creation.status = 'succeeded'
          and (operation.status <> 'processing' or operation.claimed_at < now() - interval '5 minutes')
        order by operation.available_at, operation.created_at, operation.id
        for update of operation skip locked
        limit least(greatest(coalesce(p_limit, 5), 1), 12)
    ), claimed as (
        update commerce.shipment_cancellation_operations operation set
            status = 'processing', claim_token = gen_random_uuid(), claimed_at = now(),
            claimed_by = p_worker_id, attempts = operation.attempts + 1,
            last_error = null, updated_at = now()
        from candidates where operation.id = candidates.id returning operation.*
    )
    select jsonb_build_object(
        'operationId', operation.id, 'claimToken', operation.claim_token,
        'businessKey', operation.business_key, 'status', operation.status,
        'orderId', order_row.id, 'orderPublicId', order_row.public_id,
        'providerReference', creation.provider_reference,
        'trackingUntil', operation.tracking_until,
        'cancellationRequestId', operation.order_cancellation_request_id
    )
    from claimed operation
    join commerce.orders order_row on order_row.id = operation.order_id
    join commerce.shipment_creation_operations creation on creation.order_id = operation.order_id;
end;
$$;

create or replace function commerce.complete_order_shipment_cancellation(
    p_operation_id bigint,
    p_claim_token uuid,
    p_provider_status text,
    p_provider_reference text,
    p_provider_snapshot jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_operation commerce.shipment_cancellation_operations%rowtype;
    v_order commerce.orders%rowtype;
    v_request commerce.order_cancellation_requests%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_refund jsonb;
    v_payment_cancellation jsonb;
begin
    select * into v_operation from commerce.shipment_cancellation_operations
    where id = p_operation_id for update;
    if not found then raise exception 'not_found: shipment cancellation operation'; end if;
    if v_operation.status = 'completed' then return to_jsonb(v_operation) || jsonb_build_object('idempotentReplay', true); end if;
    if v_operation.status <> 'processing' or v_operation.claim_token is distinct from p_claim_token then
        raise exception 'conflict: shipment cancellation lease mismatch';
    end if;
    select * into v_order from commerce.orders where id = v_operation.order_id for update;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id for update;
    select * into v_request from commerce.order_cancellation_requests
    where id = v_operation.order_cancellation_request_id for update;
    if p_provider_status = 'cancelled_unscanned'
        and v_fulfillment.status not in (
            'seller_handoff_declared', 'carrier_accepted', 'in_transit',
            'arrived_at_pickup_point', 'available_for_pickup',
            'collected_by_recipient', 'incident', 'lost', 'pickup_expired',
            'returning_to_sender', 'returned_to_sender', 'manual_review'
        ) then
        update commerce.shipment_cancellation_operations set
            status = 'requested', attempts = 0,
            available_at = now() + interval '5 minutes',
            provider_reference = nullif(btrim(p_provider_reference), ''),
            provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
            claim_token = null, claimed_at = null, claimed_by = null,
            last_error = 'awaiting terminal Delivery cancellation confirmation',
            updated_at = now()
        where id = v_operation.id returning * into v_operation;
        return to_jsonb(v_operation) || jsonb_build_object(
            'cancellationRequest', to_jsonb(v_request),
            'providerPending', true, 'idempotentReplay', false
        );
    end if;
    if p_provider_status is distinct from 'cancelled'
        or v_fulfillment.status in (
            'seller_handoff_declared', 'carrier_accepted', 'in_transit',
            'arrived_at_pickup_point', 'available_for_pickup',
            'collected_by_recipient', 'incident', 'lost', 'pickup_expired',
            'returning_to_sender', 'returned_to_sender', 'manual_review'
        ) then
        update commerce.shipment_cancellation_operations set
            status = 'manual_review',
            provider_reference = nullif(btrim(p_provider_reference), ''),
            provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
            claim_token = null, claimed_at = null, claimed_by = null,
            last_error = left('ambiguous Delivery cancellation status: '
                || coalesce(nullif(btrim(p_provider_status), ''), 'missing'), 2000),
            updated_at = now()
        where id = v_operation.id returning * into v_operation;
        update commerce.order_cancellation_requests set status = 'manual_review'
        where id = v_request.id returning * into v_request;
        update commerce.order_fulfillments set
            status = 'manual_review',
            blocking_reason = 'shipment_cancellation_carrier_ambiguity',
            version = version + 1, updated_at = now()
        where order_id = v_order.id returning * into v_fulfillment;
        update commerce.order_settlements set
            status = 'manual_review',
            manual_review_reason = 'shipment_cancellation_carrier_ambiguity',
            version = version + 1, updated_at = now()
        where order_id = v_order.id and status not in ('refunded', 'reversed');
        insert into commerce.financial_exceptions (
            deduplication_key, order_id, kind, severity, reason, details
        ) values (
            'shipment-cancellation-ambiguity:' || v_operation.id,
            v_order.id, 'fulfillment_ambiguity', 'critical',
            'Delivery did not confirm a terminal unscanned cancellation',
            jsonb_build_object(
                'operationId', v_operation.id,
                'providerStatus', p_provider_status,
                'providerReference', p_provider_reference,
                'fulfillmentStatus', v_fulfillment.status
            )
        ) on conflict (deduplication_key) where deduplication_key is not null do update set
            status = 'open', details = excluded.details;
        return to_jsonb(v_operation) || jsonb_build_object(
            'cancellationRequest', to_jsonb(v_request),
            'providerPending', false, 'manualReview', true,
            'idempotentReplay', false
        );
    end if;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id order by created_at desc limit 1;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    update commerce.shipment_cancellation_operations set
        status = 'completed', provider_reference = nullif(btrim(p_provider_reference), ''),
        provider_snapshot = coalesce(p_provider_snapshot, '{}'::jsonb),
        claim_token = null, claimed_at = null, claimed_by = null, last_error = null,
        updated_at = now()
    where id = v_operation.id returning * into v_operation;
    update commerce.order_fulfillments set status = 'cancelled',
        blocking_reason = 'shipment_cancelled_after_tracking_grace', version = version + 1,
        updated_at = now()
    where order_id = v_order.id;
    if v_payment.status = 'succeeded' then
        v_refund := commerce.create_cancellation_refund_request(
            v_order.id, 'cancellation:' || v_request.id,
            'order_cancellation', v_request.requested_by_kind, v_request.requested_by
        );
        update commerce.order_cancellation_requests set status = 'refund_pending'
        where id = v_request.id returning * into v_request;
    else
        v_payment_cancellation := commerce.ensure_payment_cancellation_request(
            v_order.id, 'cancelled', v_request.reason,
            'shipment-cancellation:' || v_request.id, v_request.id
        );
        select * into v_request from commerce.order_cancellation_requests where id = v_request.id;
    end if;
    perform commerce.append_financial_event(
        v_order.id, 'cancellation', v_request.id::text, 'shipment_cancellation_confirmed',
        'provider', 'mondial-relay', v_request.reason,
        jsonb_build_object('operationId', v_operation.id, 'providerStatus', p_provider_status),
        'commerce.order.shipment_cancellation', v_operation.business_key || ':completed'
    );
    return to_jsonb(v_operation) || jsonb_build_object(
        'cancellationRequest', to_jsonb(v_request), 'refundRequest', v_refund,
        'refundAuthorization', case when v_refund is null then null
            else commerce.refund_authorization_payload((v_refund->>'id')::bigint) end,
        'paymentCancellationAuthorization', v_payment_cancellation,
        'idempotentReplay', false
    );
end;
$$;

create or replace function commerce.fail_order_shipment_cancellation(
    p_operation_id bigint,
    p_claim_token uuid,
    p_error text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_operation commerce.shipment_cancellation_operations%rowtype;
begin
    select * into v_operation from commerce.shipment_cancellation_operations where id = p_operation_id for update;
    if not found then raise exception 'not_found: shipment cancellation operation'; end if;
    if v_operation.status = 'completed' then return to_jsonb(v_operation); end if;
    if v_operation.status <> 'processing' or v_operation.claim_token is distinct from p_claim_token then
        raise exception 'conflict: shipment cancellation lease mismatch';
    end if;
    update commerce.shipment_cancellation_operations set
        status = case when attempts >= 12 then 'manual_review' else 'failed' end,
        available_at = now() + interval '5 minutes',
        last_error = left(coalesce(nullif(btrim(p_error), ''), 'shipment cancellation failed'), 2000),
        claim_token = null, claimed_at = null, claimed_by = null, updated_at = now()
    where id = v_operation.id returning * into v_operation;
    if v_operation.status = 'manual_review' then
        update commerce.order_cancellation_requests set status = 'manual_review'
        where id = v_operation.order_cancellation_request_id;
        update commerce.order_fulfillments set status = 'manual_review',
            blocking_reason = 'shipment_cancellation_manual_review', version = version + 1,
            updated_at = now() where order_id = v_operation.order_id;
        update commerce.order_settlements set status = 'manual_review',
            manual_review_reason = 'shipment_cancellation_manual_review',
            version = version + 1, updated_at = now()
        where order_id = v_operation.order_id and status not in ('refunded', 'reversed');
    end if;
    return to_jsonb(v_operation);
end;
$$;

create or replace function commerce.request_order_cancellation(
    p_order_id bigint,
    p_actor_kind text,
    p_actor_id text,
    p_reason text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_order commerce.orders%rowtype;
    v_seller commerce.sellers%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_terms commerce.order_financial_terms%rowtype;
    v_request commerce.order_cancellation_requests%rowtype;
    v_refund jsonb;
    v_payment_cancellation jsonb;
begin
    select * into v_order from commerce.orders where id = p_order_id for update;
    if not found then raise exception 'not_found: order'; end if;
    select * into v_seller from commerce.sellers where id = v_order.seller_id;
    if p_actor_kind = 'buyer' and v_order.buyer_cms_user_id <> p_actor_id then
        raise exception 'not_found: order';
    elsif p_actor_kind = 'seller' and v_seller.cms_user_id <> p_actor_id then
        raise exception 'not_found: sale';
    elsif p_actor_kind is null or p_actor_kind not in ('buyer', 'seller', 'system') then
        raise exception 'forbidden: cancellation actor is not allowed';
    end if;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id for update;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id order by created_at desc limit 1;
    select * into v_terms from commerce.order_financial_terms where order_id = v_order.id;
    select * into v_request
    from commerce.order_cancellation_requests
    where order_id = v_order.id
      and requested_by_kind = p_actor_kind
      and requested_by = p_actor_id
      and reason = p_reason
      and status <> 'rejected'
    order by id desc
    limit 1;
    if found then
        select to_jsonb(refund) into v_refund
        from commerce.refund_requests refund
        where refund.business_key = 'cancellation:' || v_request.id;
        select commerce.payment_cancellation_authorization_payload(cancellation.id)
        into v_payment_cancellation
        from commerce.payment_cancellation_requests cancellation
        where cancellation.order_cancellation_request_id = v_request.id
        order by cancellation.id desc
        limit 1;
        return to_jsonb(v_request) || jsonb_build_object(
            'refundRequest', v_refund,
            'paymentCancellationAuthorization', v_payment_cancellation,
            'refundAuthorization', case when v_refund is null then null
                else commerce.refund_authorization_payload((v_refund->>'id')::bigint) end,
            'orderPublicId', v_order.public_id
        );
    end if;
    if v_order.status in ('completed', 'cancelled', 'expired') then
        raise exception 'conflict: order cannot be cancelled';
    end if;
    if v_fulfillment.status in ('seller_handoff_declared', 'carrier_accepted', 'in_transit',
        'arrived_at_pickup_point', 'available_for_pickup', 'collected_by_recipient') then
        raise exception 'conflict: carrier reconciliation or claim resolution is required';
    end if;
    insert into commerce.order_cancellation_requests (
        order_id, status, requested_by_kind, requested_by, reason
    ) values (
        v_order.id,
        case
            when v_order.status in ('awaiting_quote', 'awaiting_payment') and v_payment.status is distinct from 'succeeded' then 'approved'
            when p_actor_kind = 'seller' and v_fulfillment.status in ('shipment_creating', 'label_created') then 'provider_cancellation_pending'
            when p_actor_kind = 'seller' and v_fulfillment.status = 'awaiting_shipment' then 'approved'
            when p_actor_kind = 'buyer' and v_fulfillment.status = 'awaiting_shipment' then 'approved'
            else 'requested' end,
        p_actor_kind, p_actor_id, p_reason
    ) returning * into v_request;
    if v_request.status = 'provider_cancellation_pending' then
        insert into commerce.shipment_cancellation_operations (
            order_id, order_cancellation_request_id, business_key, tracking_until
        ) values (
            v_order.id, v_request.id, 'shipment-cancellation:' || v_request.id,
            greatest(v_fulfillment.scan_grace_deadline, now() + interval '24 hours')
        ) on conflict (order_cancellation_request_id) do nothing;
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    elsif v_request.status = 'approved' and v_payment.status = 'succeeded' then
        v_refund := commerce.create_cancellation_refund_request(
            v_order.id, 'cancellation:' || v_request.id,
            'order_cancellation', p_actor_kind, p_actor_id
        );
        update commerce.order_cancellation_requests set status = 'refund_pending'
        where id = v_request.id returning * into v_request;
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    elsif v_request.status = 'approved' and v_order.status = 'awaiting_quote' then
        perform commerce.restore_order_inventory(v_order.id);
        update commerce.orders set status = 'cancelled' where id = v_order.id;
        update commerce.order_cancellation_requests set status = 'completed'
        where id = v_request.id returning * into v_request;
    elsif v_request.status = 'approved' then
        v_payment_cancellation := commerce.ensure_payment_cancellation_request(
            v_order.id, 'cancelled', p_reason,
            'order-cancellation:' || v_request.id, v_request.id
        );
        select * into v_request from commerce.order_cancellation_requests where id = v_request.id;
    else
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    end if;
    perform commerce.append_financial_event(
        v_order.id, 'cancellation', v_request.id::text, 'cancellation_' || v_request.status,
        p_actor_kind, p_actor_id, p_reason,
        jsonb_build_object('refundRequest', v_refund),
        'commerce.order.cancellation', 'cancellation:' || v_request.id || ':' || v_request.status
    );
    return to_jsonb(v_request) || jsonb_build_object(
        'refundRequest', v_refund,
        'paymentCancellationAuthorization', v_payment_cancellation,
        'refundAuthorization', case when v_refund is null then null
            else commerce.refund_authorization_payload((v_refund->>'id')::bigint) end,
        'orderPublicId', v_order.public_id
    );
end;
$$;

create or replace function commerce.review_order_cancellation_as(
    p_request_id bigint,
    p_decision text,
    p_actor_kind text,
    p_actor_id text,
    p_reason text
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_request commerce.order_cancellation_requests%rowtype;
    v_order commerce.orders%rowtype;
    v_payment commerce.order_payment_attempts%rowtype;
    v_fulfillment commerce.order_fulfillments%rowtype;
    v_refund jsonb;
    v_payment_cancellation jsonb;
begin
    if p_decision not in ('approved', 'rejected') then raise exception 'validation: unsupported cancellation decision'; end if;
    if p_actor_kind is null or p_actor_kind not in ('admin', 'system')
        or p_actor_id is null or length(btrim(p_actor_id)) = 0 then
        raise exception 'forbidden: cancellation review actor is not allowed';
    end if;
    select * into v_request from commerce.order_cancellation_requests where id = p_request_id for update;
    if not found then raise exception 'not_found: cancellation request'; end if;
    if v_request.status <> 'requested' then raise exception 'conflict: cancellation request is no longer reviewable'; end if;
    if p_decision = 'rejected' then
        update commerce.order_cancellation_requests set status = 'rejected', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        update commerce.orders set status = 'active' where id = v_request.order_id and status = 'cancellation_pending';
        perform commerce.append_financial_event(
            v_request.order_id, 'cancellation', v_request.id::text, 'cancellation_rejected',
            p_actor_kind, p_actor_id, p_reason, '{}'::jsonb,
            'commerce.order.cancellation_reviewed', 'cancellation:' || v_request.id || ':rejected'
        );
        return to_jsonb(v_request);
    end if;
    select * into v_order from commerce.orders where id = v_request.order_id for update;
    select * into v_payment from commerce.order_payment_attempts
    where order_id = v_order.id order by created_at desc limit 1;
    select * into v_fulfillment from commerce.order_fulfillments where order_id = v_order.id for update;
    if v_fulfillment.status in ('shipment_creating', 'label_created') then
        update commerce.order_cancellation_requests set
            status = 'provider_cancellation_pending', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        insert into commerce.shipment_cancellation_operations (
            order_id, order_cancellation_request_id, business_key, tracking_until
        ) values (
            v_order.id, v_request.id, 'shipment-cancellation:' || v_request.id,
            greatest(v_fulfillment.scan_grace_deadline, now() + interval '24 hours')
        ) on conflict (order_cancellation_request_id) do nothing;
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    elsif v_payment.status = 'succeeded' then
        v_refund := commerce.create_cancellation_refund_request(
            v_order.id, 'cancellation:' || v_request.id,
            'order_cancellation', p_actor_kind, p_actor_id
        );
        update commerce.order_cancellation_requests set
            status = 'refund_pending', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        update commerce.orders set status = 'cancellation_pending' where id = v_order.id;
    else
        update commerce.order_cancellation_requests set
            status = 'approved', decision_reason = p_reason, decided_by = p_actor_id
        where id = v_request.id returning * into v_request;
        v_payment_cancellation := commerce.ensure_payment_cancellation_request(
            v_order.id, 'cancelled', p_reason,
            'cancellation-review:' || v_request.id, v_request.id
        );
        select * into v_request from commerce.order_cancellation_requests where id = v_request.id;
    end if;
    perform commerce.append_financial_event(
        v_request.order_id, 'cancellation', v_request.id::text,
        'cancellation_' || v_request.status, p_actor_kind, p_actor_id, p_reason,
        jsonb_build_object('refundRequest', v_refund),
        'commerce.order.cancellation_reviewed', 'cancellation:' || v_request.id || ':' || v_request.status
    );
    return to_jsonb(v_request) || jsonb_build_object(
        'refundRequest', v_refund,
        'paymentCancellationAuthorization', v_payment_cancellation,
        'refundAuthorization', case when v_refund is null then null
            else commerce.refund_authorization_payload((v_refund->>'id')::bigint) end,
        'orderPublicId', v_order.public_id
    );
end;
$$;

create or replace function commerce.review_order_cancellation(
    p_request_id bigint,
    p_decision text,
    p_actor_id text,
    p_reason text
)
returns jsonb
language sql
set search_path = ''
as $$
select commerce.review_order_cancellation_as(
    p_request_id, p_decision, 'admin', p_actor_id, p_reason
);
$$;

create or replace function commerce.process_due_order_deadlines(
    p_run_key text,
    p_limit integer default 25
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_candidate record;
    v_attempt commerce.order_payment_attempts%rowtype;
    v_review jsonb;
    v_payment_cancellation jsonb;
    v_events jsonb := '[]'::jsonb;
    v_limit integer;
    v_processed integer := 0;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0 then
        raise exception 'validation: deadline run key is required';
    end if;
    v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);

    -- Expiration is a provider cancellation saga. Missing, failed, created,
    -- requires-action, and processing attempts all retain inventory until a
    -- Stripe `canceled` projection is durably attached.
    for v_candidate in
        select order_row.id, order_row.public_id, settlement.status settlement_status,
               exception.detected_at exception_checked_at
        from commerce.orders order_row
        join commerce.order_financial_terms terms on terms.order_id = order_row.id
        join commerce.order_settlements settlement on settlement.order_id = order_row.id
        left join commerce.financial_exceptions exception
          on exception.deduplication_key = 'deadline:payment:' || order_row.id
        where order_row.status = 'awaiting_payment'
          and terms.pay_by_at <= now()
          and (
              settlement.status <> 'manual_review'
              or (
                  settlement.manual_review_reason = 'payment_deadline_provider_truth_required'
                  and (
                      exception.detected_at is null
                      or exception.detected_at <= now() - interval '5 minutes'
                  )
              )
          )
        order by coalesce(exception.detected_at, terms.pay_by_at), order_row.id
        limit v_limit - v_processed
        for update of order_row, settlement skip locked
    loop
        select * into v_attempt
        from commerce.order_payment_attempts attempt
        where attempt.order_id = v_candidate.id
        order by attempt.created_at desc
        limit 1;
        if v_attempt.status = 'succeeded' then
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = 'payment_deadline_late_success_projection',
                version = version + 1, updated_at = now()
            where order_id = v_candidate.id;
            insert into commerce.financial_exceptions (
                deduplication_key, order_id, kind, severity, reason, details
            ) values (
                'deadline:payment:' || v_candidate.id,
                v_candidate.id, 'payment_mismatch', 'critical',
                'Payment deadline worker found a succeeded attempt on an order not activated by its projection',
                jsonb_build_object('runKey', p_run_key, 'paymentStatus', v_attempt.status)
            ) on conflict (deduplication_key) where deduplication_key is not null do update set
                status = 'open', details = excluded.details;
            v_events := v_events || jsonb_build_array(jsonb_build_object(
                'kind', 'payment_deadline', 'orderId', v_candidate.id,
                'orderPublicId', v_candidate.public_id, 'outcome', 'manual_review'
            ));
        else
            v_payment_cancellation := commerce.ensure_payment_cancellation_request(
                v_candidate.id, 'expired', 'Protected payment window expired',
                'deadline-worker:' || p_run_key, null
            );
            if v_payment_cancellation->>'status' = 'completed' then
                update commerce.financial_exceptions set
                    status = 'resolved', resolved_at = now(), resolved_by = 'deadline-worker:' || p_run_key
                where deduplication_key = 'deadline:payment:' || v_candidate.id and status <> 'resolved';
            else
                update commerce.order_settlements set
                    status = 'blocked', manual_review_reason = 'payment_deadline_provider_cancellation_pending',
                    version = version + 1, updated_at = now()
                where order_id = v_candidate.id;
                insert into commerce.financial_exceptions (
                    deduplication_key, order_id, kind, severity, reason, details
                ) values (
                    'deadline:payment:' || v_candidate.id,
                    v_candidate.id, 'payment_mismatch', 'high',
                    'Payment deadline elapsed; provider cancellation must be confirmed before inventory restoration',
                    jsonb_build_object('runKey', p_run_key,
                        'paymentStatus', coalesce(v_attempt.status, 'missing'),
                        'paymentCancellationRequestId', v_payment_cancellation->>'paymentCancellationRequestId')
                ) on conflict (deduplication_key) where deduplication_key is not null do update set
                    status = 'open', detected_at = now(), resolved_at = null, resolved_by = null,
                    details = commerce.financial_exceptions.details || excluded.details;
            end if;
            v_events := v_events || jsonb_build_array(jsonb_build_object(
                'kind', 'payment_deadline', 'orderId', v_candidate.id,
                'orderPublicId', v_candidate.public_id,
                'outcome', case when v_payment_cancellation->>'status' = 'completed'
                    then 'expired' else 'provider_cancellation_pending' end,
                'paymentCancellationAuthorization', v_payment_cancellation
            ));
        end if;
        v_processed := v_processed + 1;
        exit when v_processed >= v_limit;
    end loop;

    -- A buyer cancellation after label creation may be auto-approved only
    -- after the scan grace period and only while both seller handoff and
    -- trusted carrier acceptance are still absent under the same row locks.
    if v_processed < v_limit then
        for v_candidate in
            select request.id, request.order_id
            from commerce.order_cancellation_requests request
            join commerce.orders order_row on order_row.id = request.order_id
            join commerce.order_fulfillments fulfillment on fulfillment.order_id = request.order_id
            where request.status = 'requested'
              and request.requested_by_kind = 'buyer'
              and fulfillment.status in ('awaiting_shipment', 'label_created')
              and fulfillment.scan_grace_deadline <= now()
              and fulfillment.seller_handoff_declared_at is null
              and fulfillment.carrier_accepted_at is null
            order by fulfillment.scan_grace_deadline, request.id
            limit v_limit - v_processed
            for update of request, order_row, fulfillment skip locked
        loop
            v_review := commerce.review_order_cancellation_as(
                v_candidate.id, 'approved', 'system', 'deadline-worker:' || p_run_key,
                'Buyer cancellation auto-approved after scan grace without seller handoff or carrier acceptance'
            );
            v_events := v_events || jsonb_build_array(jsonb_build_object(
                'kind', 'cancellation_scan_grace', 'orderId', v_candidate.order_id,
                'cancellationRequestId', v_candidate.id,
                'outcome', v_review->>'status'
            ));
            v_processed := v_processed + 1;
            exit when v_processed >= v_limit;
        end loop;
    end if;

    -- Missing scans without an eligible cancellation never imply a refund.
    -- They block release and enter the exception queue for carrier recovery.
    if v_processed < v_limit then
        for v_candidate in
            select order_row.id, order_row.public_id
            from commerce.orders order_row
            join commerce.order_fulfillments fulfillment on fulfillment.order_id = order_row.id
            join commerce.order_settlements settlement on settlement.order_id = order_row.id
            where order_row.status = 'active'
              and fulfillment.status in ('awaiting_shipment', 'label_created', 'seller_handoff_declared')
              and fulfillment.scan_grace_deadline <= now()
              and fulfillment.carrier_accepted_at is null
              and settlement.status not in ('manual_review', 'refunded', 'reversed')
              and not exists (
                  select 1 from commerce.order_cancellation_requests request
                  where request.order_id = order_row.id
                    and request.status in ('requested', 'approved', 'refund_pending', 'manual_review')
              )
            order by fulfillment.scan_grace_deadline, order_row.id
            limit v_limit - v_processed
            for update of order_row, fulfillment, settlement skip locked
        loop
            update commerce.order_fulfillments set
                status = 'manual_review', blocking_reason = 'scan_grace_elapsed_without_carrier_acceptance',
                version = version + 1, updated_at = now()
            where order_id = v_candidate.id;
            update commerce.order_settlements set
                status = 'manual_review', manual_review_reason = 'fulfillment_reconciliation_required',
                version = version + 1, updated_at = now()
            where order_id = v_candidate.id;
            insert into commerce.financial_exceptions (
                deduplication_key, order_id, kind, severity, reason, details
            ) values (
                'deadline:fulfillment:' || v_candidate.id,
                v_candidate.id, 'fulfillment_ambiguity', 'high',
                'Scan grace elapsed without trusted carrier acceptance',
                jsonb_build_object('runKey', p_run_key)
            ) on conflict (deduplication_key) where deduplication_key is not null do update set
                status = 'open', detected_at = now(), resolved_at = null, resolved_by = null,
                details = commerce.financial_exceptions.details || excluded.details;
            perform commerce.append_financial_event(
                v_candidate.id, 'fulfillment', v_candidate.id::text, 'scan_grace_manual_review',
                'system', 'deadline-worker:' || p_run_key, null, '{}'::jsonb,
                'commerce.order.fulfillment_deadline_review',
                'deadline:fulfillment:' || v_candidate.id || ':manual-review'
            );
            v_events := v_events || jsonb_build_array(jsonb_build_object(
                'kind', 'fulfillment_scan_grace', 'orderId', v_candidate.id,
                'orderPublicId', v_candidate.public_id, 'outcome', 'manual_review'
            ));
            v_processed := v_processed + 1;
            exit when v_processed >= v_limit;
        end loop;
    end if;

    -- Missing seller evidence or an expired return is a manual-review fact,
    -- never an automatic monetary decision or admission of fault.
    if v_processed < v_limit then
        for v_candidate in
            select claim.id, claim.order_id, claim.status, claim.version,
                   case
                       when claim.status = 'awaiting_seller_response' then 'seller_response_deadline'
                       else 'return_ship_deadline'
                   end deadline_kind
            from commerce.marketplace_claims claim
            where (claim.status = 'awaiting_seller_response' and claim.seller_response_by_at <= now())
               or (claim.status = 'return_required' and claim.return_ship_by_at <= now())
            order by least(claim.seller_response_by_at, coalesce(claim.return_ship_by_at, claim.seller_response_by_at)), claim.id
            limit v_limit - v_processed
            for update of claim skip locked
        loop
            update commerce.marketplace_claims set
                status = 'under_review', version = version + 1, updated_at = now()
            where id = v_candidate.id;
            insert into commerce.marketplace_claim_events (
                claim_id, event_type, actor_kind, actor_id, message,
                data
            ) values (
                v_candidate.id, v_candidate.deadline_kind, 'system',
                'deadline-worker:' || p_run_key,
                'Deadline elapsed; manual review is required before any financial decision',
                jsonb_build_object('previousStatus', v_candidate.status)
            );
            perform commerce.append_financial_event(
                v_candidate.order_id, 'marketplace_claim', v_candidate.id::text,
                'claim_' || v_candidate.deadline_kind,
                'system', 'deadline-worker:' || p_run_key, null,
                jsonb_build_object('previousStatus', v_candidate.status),
                'commerce.claim.deadline_review',
                'deadline:claim:' || v_candidate.id || ':' || v_candidate.deadline_kind
            );
            v_events := v_events || jsonb_build_array(jsonb_build_object(
                'kind', v_candidate.deadline_kind, 'orderId', v_candidate.order_id,
                'claimId', v_candidate.id, 'outcome', 'under_review'
            ));
            v_processed := v_processed + 1;
            exit when v_processed >= v_limit;
        end loop;
    end if;

    return jsonb_build_object(
        'runKey', p_run_key,
        'processed', v_processed,
        'events', v_events
    );
end;
$$;

create or replace function commerce.authorize_due_order_releases(
    p_run_key text,
    p_limit integer default 25
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_candidate record;
    v_authorizations jsonb := '[]'::jsonb;
    v_authorization jsonb;
    v_limit integer;
    v_claimed integer;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0 then
        raise exception 'validation: release run key is required';
    end if;
    v_limit := least(greatest(p_limit, 1), 100);
    insert into commerce.financial_operation_dispatch_claims (
        operation_kind, operation_id, order_id
    )
    select 'release', release_auth.id::text, release_auth.order_id
    from commerce.settlement_release_authorizations release_auth
    where release_auth.status in ('authorized', 'provider_pending')
    on conflict (operation_kind, operation_id) do nothing;
    with candidates as (
        select dispatch.operation_kind, dispatch.operation_id
        from commerce.financial_operation_dispatch_claims dispatch
        join commerce.settlement_release_authorizations release_auth
          on release_auth.id::text = dispatch.operation_id
        join commerce.order_settlements settlement on settlement.order_id = release_auth.order_id
        where dispatch.operation_kind = 'release'
          and release_auth.status in ('authorized', 'provider_pending')
          and settlement.status = 'release_pending'
          and dispatch.available_at <= now()
          and (dispatch.claimed_at is null
            or dispatch.claimed_at < now() - interval '5 minutes')
        order by dispatch.available_at, dispatch.created_at, dispatch.operation_id
        limit v_limit
        for update of dispatch skip locked
    ), claimed as (
        update commerce.financial_operation_dispatch_claims dispatch set
            claimed_at = now(),
            claimed_by = 'release-worker:' || p_run_key,
            attempts = attempts + 1
        from candidates
        where dispatch.operation_kind = candidates.operation_kind
          and dispatch.operation_id = candidates.operation_id
        returning dispatch.operation_id
    )
    select coalesce(jsonb_agg(jsonb_build_object(
        'status', 'authorized',
        'releaseAuthorizationId', release_auth.id,
        'orderId', order_row.id,
        'orderPublicId', order_row.public_id,
        'paymentId', payment.provider_payment_id,
        'businessKey', release_auth.business_key,
        'releaseKind', release_auth.release_kind,
        'sellerId', seller.cms_user_id,
        'sellerRequiredMinimumBalanceAmount', coalesce(
            risk_state.outstanding_debt_amount + risk_state.at_risk_exposure_amount, 0
        ),
        'payoutDelayDays', risk.payout_delay_days,
        'amount', release_auth.authorized_amount,
        'currency', upper(release_auth.currency),
        'financialTermsHash', release_auth.financial_terms_hash
    ) order by release_auth.created_at, release_auth.id), '[]'::jsonb)
    into v_authorizations
    from claimed dispatch
    join commerce.settlement_release_authorizations release_auth
      on release_auth.id::text = dispatch.operation_id
    join commerce.orders order_row on order_row.id = release_auth.order_id
    join commerce.sellers seller on seller.id = order_row.seller_id
    join commerce.order_financial_terms terms on terms.order_id = order_row.id
    join commerce.seller_risk_policies risk on risk.id = terms.seller_risk_policy_id
    left join commerce.seller_risk_states risk_state on risk_state.seller_id = seller.id
    join lateral (
        select attempt.provider_payment_id
        from commerce.order_payment_attempts attempt
        where attempt.order_id = release_auth.order_id and attempt.status = 'succeeded'
        order by attempt.created_at desc limit 1
    ) payment on true;
    v_claimed := jsonb_array_length(v_authorizations);
    for v_candidate in
        select settlement.order_id, settlement.version
        from commerce.order_settlements settlement
        join commerce.order_fulfillments fulfillment on fulfillment.order_id = settlement.order_id
        where settlement.status in ('reserve_held', 'held', 'eligible')
          and settlement.total_transferred_amount = 0
          and not exists (
              select 1 from commerce.settlement_release_authorizations existing
              where existing.order_id = settlement.order_id and existing.release_kind = 'initial'
          )
          and fulfillment.status = 'collected_by_recipient'
          and fulfillment.blocking_reason is null
          and fulfillment.release_eligible_at <= now()
          and exists (
              select 1 from commerce.delivery_reconciliation_health health
              where health.id = 'mondial-relay'
                and health.checked_at >= now() - interval '30 minutes'
          )
          and exists (
              select 1 from commerce.delivery_order_reconciliation_health health
              where health.order_id = settlement.order_id
                and health.checked_at >= now() - interval '30 minutes'
                and health.shipment_id <> ''
                and health.provider_reference = fulfillment.provider_reference
                and health.shipment_status = 'collected_by_recipient'
                and health.pending_projection_count = 0
                and health.manual_review_count = 0
                and health.tracking_error_count = 0
                and health.tracking_checked_at is not null
          )
        order by fulfillment.release_eligible_at, settlement.order_id
        limit greatest(v_limit - v_claimed, 0)
        for update of settlement skip locked
    loop
        begin
            v_authorization := commerce.authorize_order_release(
                v_candidate.order_id, 'system', 'release-worker:' || p_run_key,
                'Claim window expired without an open blocker', v_candidate.version
            );
            insert into commerce.financial_operation_dispatch_claims (
                operation_kind, operation_id, order_id, claimed_at, claimed_by, attempts
            ) values (
                'release', v_authorization->>'releaseAuthorizationId', v_candidate.order_id,
                now(), 'release-worker:' || p_run_key, 1
            ) on conflict (operation_kind, operation_id) do update set
                claimed_at = excluded.claimed_at,
                claimed_by = excluded.claimed_by,
                attempts = commerce.financial_operation_dispatch_claims.attempts + 1;
            v_authorizations := v_authorizations || jsonb_build_array(v_authorization);
        exception when others then
            insert into commerce.financial_exceptions (
                order_id, kind, severity, reason, details
            ) values (
                v_candidate.order_id, 'settlement_ambiguity', 'high',
                'Due release authorization failed closed',
                jsonb_build_object('runKey', p_run_key, 'error', sqlerrm)
            );
        end;
    end loop;
    v_claimed := jsonb_array_length(v_authorizations);
    for v_candidate in
        select settlement.order_id, settlement.version
        from commerce.order_settlements settlement
        join commerce.order_financial_terms terms on terms.order_id = settlement.order_id
        join commerce.seller_risk_policies risk on risk.id = terms.seller_risk_policy_id
        join commerce.order_fulfillments fulfillment on fulfillment.order_id = settlement.order_id
        where settlement.status in ('reserve_held', 'held', 'eligible')
          and settlement.seller_reserve_liability_remaining_amount > 0
          and settlement.total_transferred_amount - settlement.total_reversed_amount
              >= settlement.authorized_seller_amount
                  - settlement.seller_reserve_liability_remaining_amount
          and fulfillment.release_eligible_at + make_interval(days => risk.reserve_liability_days) <= now()
          and not exists (
              select 1 from commerce.settlement_release_authorizations existing
              where existing.order_id = settlement.order_id and existing.release_kind = 'reserve'
          )
        order by fulfillment.release_eligible_at, settlement.order_id
        limit greatest(v_limit - v_claimed, 0)
        for update of settlement skip locked
    loop
        begin
            v_authorization := commerce.authorize_order_reserve_release(
                v_candidate.order_id, 'reserve-worker:' || p_run_key,
                'Seller reserve holding period expired without an open blocker',
                v_candidate.version
            );
            insert into commerce.financial_operation_dispatch_claims (
                operation_kind, operation_id, order_id, claimed_at, claimed_by, attempts
            ) values (
                'release', v_authorization->>'releaseAuthorizationId', v_candidate.order_id,
                now(), 'release-worker:' || p_run_key, 1
            ) on conflict (operation_kind, operation_id) do update set
                claimed_at = excluded.claimed_at,
                claimed_by = excluded.claimed_by,
                attempts = commerce.financial_operation_dispatch_claims.attempts + 1;
            v_authorizations := v_authorizations || jsonb_build_array(v_authorization);
        exception when others then
            insert into commerce.financial_exceptions (
                order_id, kind, severity, reason, details
            ) values (
                v_candidate.order_id, 'risk_hold', 'high',
                'Seller reserve release failed closed',
                jsonb_build_object('runKey', p_run_key, 'error', sqlerrm)
            );
        end;
    end loop;
    return jsonb_build_object('runKey', p_run_key, 'authorizations', v_authorizations);
end;
$$;

create or replace function commerce.pending_order_refund_authorizations(
    p_run_key text,
    p_limit integer default 25
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_authorizations jsonb;
begin
    if p_run_key is null or length(btrim(p_run_key)) = 0 then
        raise exception 'validation: refund run key is required';
    end if;
    insert into commerce.financial_operation_dispatch_claims (
        operation_kind, operation_id, order_id
    )
    select 'refund', request.id::text, request.order_id
    from commerce.refund_requests request
    where request.status in ('approved', 'provider_operation_reserved', 'processing')
    on conflict (operation_kind, operation_id) do nothing;
    with candidates as (
        select dispatch.operation_kind, dispatch.operation_id
        from commerce.financial_operation_dispatch_claims dispatch
        join commerce.refund_requests request on request.id::text = dispatch.operation_id
        join commerce.order_settlements settlement on settlement.order_id = request.order_id
        where dispatch.operation_kind = 'refund'
          and request.status in ('approved', 'provider_operation_reserved', 'processing')
          and settlement.status in (
            'refund_pending', 'held', 'released', 'reversal_pending', 'reversed', 'manual_review'
          )
          and dispatch.available_at <= now()
          and (dispatch.claimed_at is null
            or dispatch.claimed_at < now() - interval '5 minutes')
        order by dispatch.available_at, dispatch.created_at, dispatch.operation_id
        limit least(greatest(p_limit, 1), 100)
        for update of dispatch skip locked
    ), claimed as (
        update commerce.financial_operation_dispatch_claims dispatch set
            claimed_at = now(),
            claimed_by = 'refund-worker:' || p_run_key,
            attempts = attempts + 1
        from candidates
        where dispatch.operation_kind = candidates.operation_kind
          and dispatch.operation_id = candidates.operation_id
        returning dispatch.operation_id
    )
    select coalesce(jsonb_agg(
        commerce.refund_authorization_payload(request.id)
        order by request.created_at, request.id
    ), '[]'::jsonb) into v_authorizations
    from claimed dispatch
    join commerce.refund_requests request on request.id::text = dispatch.operation_id;
    return jsonb_build_object('runKey', p_run_key, 'authorizations', v_authorizations);
end;
$$;

create or replace function commerce.claim_outbox_events(
    p_worker_id text,
    p_limit integer default 25
)
returns jsonb
language sql
set search_path = ''
as $$
with claimed as (
    select id from commerce.outbox_events
    where status in ('pending', 'failed') and available_at <= now()
    order by available_at, id
    limit least(greatest(p_limit, 1), 100)
    for update skip locked
), updated as (
    update commerce.outbox_events event set
        status = 'processing', claimed_at = now(), claimed_by = p_worker_id,
        attempts = attempts + 1
    from claimed where event.id = claimed.id
    returning event.*
)
select coalesce(jsonb_agg(to_jsonb(updated) order by id), '[]'::jsonb) from updated;
$$;

create or replace function commerce.complete_outbox_event(
    p_event_id bigint,
    p_worker_id text,
    p_succeeded boolean,
    p_error text default null
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_event commerce.outbox_events%rowtype;
begin
    update commerce.outbox_events set
        status = case when p_succeeded then 'delivered' else 'failed' end,
        delivered_at = case when p_succeeded then now() else null end,
        available_at = case when p_succeeded then available_at
            else now() + make_interval(secs => least(3600, attempts * attempts * 30)) end,
        last_error = case when p_succeeded then null else p_error end
    where id = p_event_id and status = 'processing' and claimed_by = p_worker_id
    returning * into v_event;
    if not found then raise exception 'conflict: outbox event is not owned by worker'; end if;
    return to_jsonb(v_event);
end;
$$;

create or replace view commerce.protected_order_operations
with (security_invoker = true)
as
select
    order_row.id as order_id,
    order_row.public_id as order_public_id,
    order_row.order_number,
    order_row.buyer_cms_user_id,
    order_row.seller_id,
    order_row.currency,
    terms.buyer_total_amount,
    terms.seller_proceeds_amount,
    terms.platform_retained_amount,
    terms.financial_terms_hash,
    coalesce(payment.status, 'created') as payment_status,
    fulfillment.status as fulfillment_status,
    settlement.status as settlement_status,
    claim.status as claim_status,
    coalesce(refunds.total_requested, 0) as total_refund_requested_amount,
    fulfillment.release_eligible_at,
    fulfillment.recipient_handoff_at,
    fulfillment.recipient_handoff_first_observed_at,
    fulfillment.claim_window_started_at,
    fulfillment.claim_by_at,
    greatest(order_row.updated_at, fulfillment.updated_at, settlement.updated_at) as updated_at
from commerce.orders order_row
join commerce.order_financial_terms terms on terms.order_id = order_row.id
join commerce.order_fulfillments fulfillment on fulfillment.order_id = order_row.id
join commerce.order_settlements settlement on settlement.order_id = order_row.id
left join lateral (
    select attempt.status from commerce.order_payment_attempts attempt
    where attempt.order_id = order_row.id order by attempt.created_at desc limit 1
) payment on true
left join lateral (
    select marketplace_claim.status from commerce.marketplace_claims marketplace_claim
    where marketplace_claim.order_id = order_row.id order by marketplace_claim.created_at desc limit 1
) claim on true
left join lateral (
    select sum(requested_amount) total_requested from commerce.refund_requests request
    where request.order_id = order_row.id and request.status not in ('rejected', 'cancelled', 'failed')
) refunds on true;

create or replace function commerce.get_order_detail_read_model(
    p_scope text,
    p_cms_user_id text default null,
    p_id bigint default null,
    p_public_id text default null
)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
    v_scope text := lower(nullif(btrim(p_scope), ''));
    v_cms_user_id text := nullif(btrim(p_cms_user_id), '');
    v_public_id text := nullif(btrim(p_public_id), '');
    v_public_uuid uuid;
    v_seller_id bigint;
    v_order_id bigint;
    v_order_public_id uuid;
    v_order_buyer_cms_user_id text;
    v_authorization jsonb;
    v_result jsonb;
begin
    if v_scope is null or v_scope not in ('buyer', 'seller', 'admin') then
        return jsonb_build_object('state', 'invalid_scope');
    end if;
    if p_id is null and v_public_id is null then
        return jsonb_build_object('state', 'selector_required');
    end if;
    if v_scope = 'seller' then
        if v_cms_user_id is null then
            return jsonb_build_object('state', 'identity_required');
        end if;
        select seller.id into v_seller_id
        from commerce.sellers seller
        where seller.cms_user_id = v_cms_user_id
        limit 1;
        if v_seller_id is null then
            return jsonb_build_object('state', 'not_found');
        end if;
    end if;
    if p_id is null then
        v_public_uuid := v_public_id::uuid;
    end if;

    if v_scope = 'seller' then
        if p_id is not null then
            select order_row.id, order_row.public_id, order_row.buyer_cms_user_id
            into v_order_id, v_order_public_id, v_order_buyer_cms_user_id
            from commerce.orders order_row
            where order_row.id = p_id and order_row.seller_id = v_seller_id;
        else
            select order_row.id, order_row.public_id, order_row.buyer_cms_user_id
            into v_order_id, v_order_public_id, v_order_buyer_cms_user_id
            from commerce.orders order_row
            where order_row.public_id = v_public_uuid and order_row.seller_id = v_seller_id;
        end if;
    elsif p_id is not null then
        select order_row.id, order_row.public_id, order_row.buyer_cms_user_id
        into v_order_id, v_order_public_id, v_order_buyer_cms_user_id
        from commerce.orders order_row
        where order_row.id = p_id;
    else
        select order_row.id, order_row.public_id, order_row.buyer_cms_user_id
        into v_order_id, v_order_public_id, v_order_buyer_cms_user_id
        from commerce.orders order_row
        where order_row.public_id = v_public_uuid;
    end if;

    if v_order_id is null then
        return jsonb_build_object('state', 'not_found');
    end if;
    if v_scope = 'buyer' then
        if v_cms_user_id is null then
            return jsonb_build_object('state', 'identity_required');
        end if;
        if v_order_buyer_cms_user_id is distinct from v_cms_user_id then
            return jsonb_build_object('state', 'not_found');
        end if;
    end if;

    if v_scope = 'seller' then
        v_authorization := commerce.get_order_fulfillment_authorization(v_order_public_id);
        select jsonb_build_object(
            'state', 'ok',
            'order', jsonb_build_object(
                'id', order_row.id,
                'public_id', order_row.public_id,
                'order_number', order_row.order_number,
                'checkout_group_id', order_row.checkout_group_id,
                'status', order_row.status,
                'currency', order_row.currency,
                'subtotal_amount', order_row.subtotal_amount,
                'shipping_amount', order_row.shipping_amount,
                'delivery_quoted_at', order_row.delivery_quoted_at,
                'total_amount', order_row.total_amount,
                'metadata', order_row.metadata,
                'version', order_row.version,
                'created_at', order_row.created_at,
                'updated_at', order_row.updated_at
            ),
            'lines', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', line.id,
                    'order_id', line.order_id,
                    'offer_id', line.offer_id,
                    'product_id', line.product_id,
                    'variant_id', line.variant_id,
                    'accepted_proposal_id', line.accepted_proposal_id,
                    'title', line.title,
                    'sku', line.sku,
                    'quantity', line.quantity,
                    'unit_amount', line.unit_amount,
                    'total_amount', line.total_amount,
                    'product_snapshot', line.product_snapshot,
                    'variant_snapshot', line.variant_snapshot,
                    'offer_snapshot', line.offer_snapshot,
                    'created_at', line.created_at
                ) order by line.id)
                from commerce.order_lines line
                where line.order_id = order_row.id and line.seller_id = v_seller_id
            ), '[]'::jsonb),
            'events', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', event.id,
                    'order_id', event.order_id,
                    'event_type', event.event_type,
                    'previous_status', event.previous_status,
                    'next_status', event.next_status,
                    'created_at', event.created_at
                ) order by event.created_at, event.id)
                from commerce.order_events event
                where event.order_id = order_row.id
            ), '[]'::jsonb),
            'seller', null,
            'operation', (
                select jsonb_build_object(
                    'order_id', operation.order_id,
                    'order_public_id', operation.order_public_id,
                    'order_number', operation.order_number,
                    'currency', operation.currency,
                    'payment_status', operation.payment_status,
                    'fulfillment_status', operation.fulfillment_status,
                    'settlement_status', operation.settlement_status,
                    'claim_status', operation.claim_status,
                    'recipient_handoff_at', operation.recipient_handoff_at,
                    'recipient_handoff_first_observed_at', operation.recipient_handoff_first_observed_at,
                    'claim_window_started_at', operation.claim_window_started_at,
                    'claim_by_at', operation.claim_by_at,
                    'release_eligible_at', operation.release_eligible_at,
                    'updated_at', operation.updated_at
                )
                from commerce.protected_order_operations operation
                where operation.order_id = order_row.id
            ),
            'financial_terms', (
                select jsonb_build_object(
                    'order_id', terms.order_id,
                    'merchandise_subtotal_amount', terms.merchandise_subtotal_amount,
                    'shipping_amount', terms.shipping_amount,
                    'seller_commission_amount', terms.seller_commission_amount,
                    'platform_shipping_share_amount', terms.platform_shipping_share_amount,
                    'seller_shipping_share_amount', terms.seller_shipping_share_amount,
                    'seller_proceeds_amount', terms.seller_proceeds_amount,
                    'seller_transfer_release_amount', terms.seller_transfer_release_amount,
                    'seller_reserve_liability_amount', terms.seller_reserve_liability_amount,
                    'currency', terms.currency,
                    'pricing_locked_at', terms.pricing_locked_at,
                    'pay_by_at', terms.pay_by_at,
                    'financial_revision', terms.financial_revision
                )
                from commerce.order_financial_terms terms
                where terms.order_id = order_row.id
            ),
            'fulfillment', (
                select jsonb_build_object(
                    'order_id', fulfillment.order_id,
                    'status', fulfillment.status,
                    'seller_handoff_deadline', fulfillment.seller_handoff_deadline,
                    'scan_grace_deadline', fulfillment.scan_grace_deadline,
                    'seller_handoff_declared_at', fulfillment.seller_handoff_declared_at,
                    'carrier_accepted_at', fulfillment.carrier_accepted_at,
                    'recipient_handoff_at', fulfillment.recipient_handoff_at,
                    'recipient_handoff_first_observed_at', fulfillment.recipient_handoff_first_observed_at,
                    'claim_window_started_at', fulfillment.claim_window_started_at,
                    'claim_by_at', fulfillment.claim_by_at,
                    'release_eligible_at', fulfillment.release_eligible_at,
                    'blocking_reason', fulfillment.blocking_reason,
                    'version', fulfillment.version
                )
                from commerce.order_fulfillments fulfillment
                where fulfillment.order_id = order_row.id
            ),
            'settlement', (
                select jsonb_build_object(
                    'order_id', settlement.order_id,
                    'status', settlement.status,
                    'authorized_seller_amount', settlement.authorized_seller_amount,
                    'total_transferred_amount', settlement.total_transferred_amount,
                    'total_reversed_amount', settlement.total_reversed_amount,
                    'seller_reserve_liability_remaining_amount', settlement.seller_reserve_liability_remaining_amount,
                    'version', settlement.version
                )
                from commerce.order_settlements settlement
                where settlement.order_id = order_row.id
            ),
            'claim', null,
            'authorization', case when v_authorization is null then null else jsonb_build_object(
                'allowed', v_authorization->'allowed',
                'reason', v_authorization->'reason',
                'order_id', v_authorization->'orderId',
                'order_public_id', v_authorization->'orderPublicId',
                'seller_id', v_authorization->'sellerId',
                'currency', v_authorization->'currency',
                'payment_status', v_authorization->'paymentStatus',
                'fulfillment_status', v_authorization->'fulfillmentStatus'
            ) end,
            'definitions', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'key', definition.key,
                    'label', definition.label,
                    'field_type', definition.field_type,
                    'unit', definition.unit
                ) order by definition.position, definition.key)
                from commerce.custom_field_definitions definition
                where definition.entity_type = 'order'
                  and definition.public_readable
                  and definition.enabled
            ), '[]'::jsonb)
        ) into v_result
        from commerce.orders order_row
        where order_row.id = v_order_id;
    else
        select jsonb_build_object(
            'state', 'ok',
            'order', jsonb_build_object(
                'id', order_row.id,
                'public_id', order_row.public_id,
                'order_number', order_row.order_number,
                'checkout_group_id', order_row.checkout_group_id,
                'seller_id', order_row.seller_id,
                'buyer_cms_user_id', order_row.buyer_cms_user_id,
                'status', order_row.status,
                'currency', order_row.currency,
                'subtotal_amount', order_row.subtotal_amount,
                'shipping_amount', order_row.shipping_amount,
                'delivery_quoted_at', order_row.delivery_quoted_at,
                'total_amount', order_row.total_amount,
                'shipping_address', order_row.shipping_address,
                'billing_address', order_row.billing_address,
                'metadata', order_row.metadata,
                'idempotency_key', order_row.idempotency_key,
                'archived_at', order_row.archived_at,
                'version', order_row.version,
                'created_at', order_row.created_at,
                'updated_at', order_row.updated_at
            ),
            'lines', coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', line.id,
                    'order_id', line.order_id,
                    'offer_id', line.offer_id,
                    'product_id', line.product_id,
                    'variant_id', line.variant_id,
                    'accepted_proposal_id', line.accepted_proposal_id,
                    'title', line.title,
                    'sku', line.sku,
                    'quantity', line.quantity,
                    'unit_amount', line.unit_amount,
                    'total_amount', line.total_amount,
                    'product_snapshot', line.product_snapshot,
                    'variant_snapshot', line.variant_snapshot,
                    'offer_snapshot', line.offer_snapshot,
                    'seller_snapshot', line.seller_snapshot,
                    'created_at', line.created_at
                ) order by line.id)
                from commerce.order_lines line
                where line.order_id = order_row.id
            ), '[]'::jsonb),
            'events', case when v_scope = 'admin' then coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', event.id,
                    'order_id', event.order_id,
                    'event_type', event.event_type,
                    'actor_kind', event.actor_kind,
                    'actor_id', event.actor_id,
                    'previous_status', event.previous_status,
                    'next_status', event.next_status,
                    'message', event.message,
                    'data', event.data,
                    'created_at', event.created_at
                ) order by event.created_at, event.id)
                from commerce.order_events event
                where event.order_id = order_row.id
            ), '[]'::jsonb) else coalesce((
                select jsonb_agg(jsonb_build_object(
                    'id', event.id,
                    'order_id', event.order_id,
                    'event_type', event.event_type,
                    'previous_status', event.previous_status,
                    'next_status', event.next_status,
                    'created_at', event.created_at
                ) order by event.created_at, event.id)
                from commerce.order_events event
                where event.order_id = order_row.id
            ), '[]'::jsonb) end,
            'seller', (
                select jsonb_build_object(
                    'id', seller.id,
                    'kind', seller.kind,
                    'slug', seller.slug,
                    'display_name', seller.display_name
                )
                from commerce.sellers seller
                where seller.id = order_row.seller_id
            ),
            'operation', (
                select jsonb_build_object(
                    'order_id', operation.order_id,
                    'order_public_id', operation.order_public_id,
                    'order_number', operation.order_number,
                    'buyer_cms_user_id', operation.buyer_cms_user_id,
                    'seller_id', operation.seller_id,
                    'currency', operation.currency,
                    'buyer_total_amount', operation.buyer_total_amount,
                    'seller_proceeds_amount', operation.seller_proceeds_amount,
                    'platform_retained_amount', operation.platform_retained_amount,
                    'financial_terms_hash', operation.financial_terms_hash,
                    'payment_status', operation.payment_status,
                    'fulfillment_status', operation.fulfillment_status,
                    'settlement_status', operation.settlement_status,
                    'claim_status', operation.claim_status,
                    'total_refund_requested_amount', operation.total_refund_requested_amount,
                    'release_eligible_at', operation.release_eligible_at,
                    'recipient_handoff_at', operation.recipient_handoff_at,
                    'recipient_handoff_first_observed_at', operation.recipient_handoff_first_observed_at,
                    'claim_window_started_at', operation.claim_window_started_at,
                    'claim_by_at', operation.claim_by_at,
                    'updated_at', operation.updated_at
                )
                from commerce.protected_order_operations operation
                where operation.order_id = order_row.id
            ),
            'financial_terms', (
                select jsonb_build_object(
                    'order_id', terms.order_id,
                    'delivery_quote_id', terms.delivery_quote_id,
                    'merchandise_subtotal_amount', terms.merchandise_subtotal_amount,
                    'shipping_amount', terms.shipping_amount,
                    'buyer_protection_fee_amount', terms.buyer_protection_fee_amount,
                    'seller_commission_amount', terms.seller_commission_amount,
                    'buyer_total_amount', terms.buyer_total_amount,
                    'seller_proceeds_amount', terms.seller_proceeds_amount,
                    'platform_retained_amount', terms.platform_retained_amount,
                    'currency', terms.currency,
                    'financial_terms_hash', terms.financial_terms_hash,
                    'pricing_locked_at', terms.pricing_locked_at,
                    'pay_by_at', terms.pay_by_at,
                    'financial_revision', terms.financial_revision
                )
                from commerce.order_financial_terms terms
                where terms.order_id = order_row.id
            ),
            'fulfillment', (
                select jsonb_build_object(
                    'order_id', fulfillment.order_id,
                    'status', fulfillment.status,
                    'seller_handoff_deadline', fulfillment.seller_handoff_deadline,
                    'scan_grace_deadline', fulfillment.scan_grace_deadline,
                    'carrier_accepted_at', fulfillment.carrier_accepted_at,
                    'arrived_at_pickup_point_at', fulfillment.arrived_at_pickup_point_at,
                    'available_for_pickup_at', fulfillment.available_for_pickup_at,
                    'recipient_handoff_at', fulfillment.recipient_handoff_at,
                    'recipient_handoff_first_observed_at', fulfillment.recipient_handoff_first_observed_at,
                    'claim_window_started_at', fulfillment.claim_window_started_at,
                    'claim_by_at', fulfillment.claim_by_at,
                    'release_eligible_at', fulfillment.release_eligible_at,
                    'blocking_reason', fulfillment.blocking_reason,
                    'version', fulfillment.version
                )
                from commerce.order_fulfillments fulfillment
                where fulfillment.order_id = order_row.id
            ),
            'settlement', (
                select jsonb_build_object(
                    'order_id', settlement.order_id,
                    'status', settlement.status,
                    'authorized_seller_amount', settlement.authorized_seller_amount,
                    'total_transferred_amount', settlement.total_transferred_amount,
                    'total_reversed_amount', settlement.total_reversed_amount,
                    'total_refunded_amount', settlement.total_refunded_amount,
                    'seller_reserve_liability_remaining_amount', settlement.seller_reserve_liability_remaining_amount,
                    'version', settlement.version
                )
                from commerce.order_settlements settlement
                where settlement.order_id = order_row.id
            ),
            'claim', (
                select jsonb_build_object(
                    'id', claim.id,
                    'public_id', claim.public_id,
                    'reason', claim.reason,
                    'status', claim.status,
                    'seller_response_by_at', claim.seller_response_by_at,
                    'return_ship_by_at', claim.return_ship_by_at,
                    'resolved_at', claim.resolved_at,
                    'version', claim.version,
                    'created_at', claim.created_at
                )
                from commerce.marketplace_claims claim
                where claim.order_id = order_row.id
                order by claim.created_at desc
                limit 1
            ),
            'authorization', null,
            'definitions', case when v_scope = 'buyer' then coalesce((
                select jsonb_agg(jsonb_build_object(
                    'key', definition.key,
                    'label', definition.label,
                    'field_type', definition.field_type,
                    'unit', definition.unit
                ) order by definition.position, definition.key)
                from commerce.custom_field_definitions definition
                where definition.entity_type = 'order'
                  and definition.public_readable
                  and definition.enabled
            ), '[]'::jsonb) else '[]'::jsonb end
        ) into v_result
        from commerce.orders order_row
        where order_row.id = v_order_id;
    end if;
    return v_result;
end;
$$;

revoke execute on function commerce.get_order_detail_read_model(
